  struct PaidTriggerFixture<T: Config> {
    actor_id: ActorId,
    owner: T::AccountId,
    source: T::AccountId,
    asset: T::AssetId,
    fee: T::Balance,
    payer_before: T::Balance,
    sink_before: T::Balance,
  }

  fn prepare_paid_trigger<T: Config>(
    family: TriggerFamily,
  ) -> Result<PaidTriggerFixture<T>, BenchmarkError> {
    let (owner, asset, trigger, funding) = large_header_fields::<T>();
    let (owner, asset, source, trigger, weight) = match family {
      TriggerFamily::Manual => {
        let caller: T::AccountId = whitelisted_caller();
        (
          caller.clone(),
          asset,
          caller,
          Trigger::Manual,
          T::WeightInfo::manual_trigger(),
        )
      }
      TriggerFamily::AddressEvent => {
        let Trigger::AddressEvent {
          source_filter: SourceFilter::Whitelist(sources),
          asset_filter: AssetFilter::Whitelist(assets),
        } = &trigger
        else {
          return Err(BenchmarkError::Stop(
            "maximum AddressEvent filters are required",
          ));
        };
        let source = sources
          .last()
          .expect("maximum source filter is nonempty")
          .clone();
        let asset = *assets.last().expect("maximum asset filter is nonempty");
        (
          owner,
          asset,
          source,
          trigger,
          T::WeightInfo::address_event_trigger_occurrence(),
        )
      }
      _ => {
        return Err(BenchmarkError::Stop(
          "only Manual and AddressEvent use this fixture",
        ));
      }
    };
    let trigger_width = trigger.encoded_size();
    ensure_creation_balance::<T>(&owner);
    let steps = maximum_temporal_control_steps::<T>(asset)?;
    prefund_active_user_creation::<T>(&owner, &steps);
    let mut contract = user_contract::<T>(
      Schedule {
        trigger,
        cooldown_blocks: 0,
      },
      steps,
    )
    .expect("maximum paid User Trigger Contract exists");
    contract.funding = funding;
    contract.parked_balance_activation = Some(maximum_parked_balance_activation::<T>(&owner)?);
    let start = frame_system::Pallet::<T>::block_number();
    contract.window = Some(ScheduleWindow {
      start,
      end: start.saturating_add(T::MinWindowLength::get()),
    });
    Pallet::<T>::create_user_actor(
      RawOrigin::Signed(owner.clone()).into(),
      Mutability::Mutable,
      Some(contract),
    )?;
    let actor_id = NextActorId::<T>::get() - 1;
    assert_max_contract_geometry::<T>(actor_id);
    if family == TriggerFamily::AddressEvent {
      assert_measured_actor_accounts::<T>(&[actor_id]);
    } else {
      let sovereign = Pallet::<T>::actor_identity(actor_id)
        .unwrap()
        .sovereign_account;
      assert_distinct_measured_accounts::<T>(&[&sovereign, &T::FeeSink::get()]);
      assert_ne!(owner, sovereign);
      assert_ne!(owner, T::FeeSink::get());
    }
    let head = ActorContractHeads::<T>::get(actor_id).expect("public Trigger head exists");
    assert_eq!(
      head.header.encoded_size(),
      ActorContractHeaderOf::<T>::max_encoded_len() - TriggerOf::<T>::max_encoded_len()
        + trigger_width
        - u64::max_encoded_len(),
      "paid Trigger header attains its legal ceiling without an incompatible nonce target"
    );
    seed_actor_for_cycle::<T>(actor_id);
    assert!(
      !benchmark_fixture_semantic_hot::<T>(actor_id)
        .unwrap()
        .pending_signal
    );
    let sovereign = Pallet::<T>::actor_identity(actor_id)
      .unwrap()
      .sovereign_account;
    let native = T::FeeNativeAssetId::get();
    let fee = Pallet::<T>::trigger_fee_for_weight(ActorType::User, family, weight).trigger_fee;
    Ok(PaidTriggerFixture {
      actor_id,
      owner,
      source,
      asset,
      fee,
      payer_before: T::AssetOps::balance(&sovereign, native),
      sink_before: T::AssetOps::balance(&T::FeeSink::get(), native),
    })
  }

  fn assert_paid_trigger<T: Config>(fixture: &PaidTriggerFixture<T>) {
    let identity =
      Pallet::<T>::actor_identity(fixture.actor_id).expect("paid Actor remains active");
    let native = T::FeeNativeAssetId::get();
    assert_eq!(
      T::AssetOps::balance(&identity.sovereign_account, native),
      fixture.payer_before - fixture.fee
    );
    assert_eq!(
      T::AssetOps::balance(&T::FeeSink::get(), native),
      fixture.sink_before + fixture.fee
    );
    assert_eq!(identity.cycle_nonce, 0);
    assert!(ActorRunStateStore::<T>::get(fixture.actor_id).is_none());
    assert_canonical_ingress_readiness::<T>(fixture.actor_id);
  }

  /// Paid maximum legal User Manual readiness; Pipeline and Actions execute later.
  #[benchmark]
  fn manual_trigger() -> Result<(), BenchmarkError> {
    let fixture = prepare_paid_trigger::<T>(TriggerFamily::Manual)?;
    let caller = fixture.owner.clone();
    let actor_id = fixture.actor_id;
    #[extrinsic_call]
    manual_trigger(RawOrigin::Signed(caller), actor_id);
    assert_paid_trigger::<T>(&fixture);
    Ok(())
  }

  /// Selected paid Manual placement from an initial window-expiry Deadline to a future
  /// window-start Deadline. This isolated zero-Step diagnostic is not a physical maximum.
  #[benchmark(extra)]
  fn manual_trigger_future_deadline() -> Result<(), BenchmarkError> {
    frame_system::Pallet::<T>::set_block_number(1u32.into());
    let owner: T::AccountId = whitelisted_caller();
    ensure_creation_balance::<T>(&owner);
    let mut contract = user_contract::<T>(
      Schedule {
        trigger: Trigger::manual(),
        cooldown_blocks: 0,
      },
      Default::default(),
    )
    .ok_or(BenchmarkError::Stop("Manual Contract is required"))?;
    prefund_active_user_creation::<T>(&owner, &contract.steps);
    let start: BlockNumberFor<T> = 100u32.into();
    let end = start
      .checked_add(&T::MinWindowLength::get())
      .ok_or(BenchmarkError::Stop("window endpoint must fit"))?;
    contract.window = Some(ScheduleWindow { start, end });
    Pallet::<T>::create_user_actor(
      RawOrigin::Signed(owner.clone()).into(),
      Mutability::Mutable,
      Some(contract),
    )?;
    let actor_id = NextActorId::<T>::get() - 1;
    let sovereign = Pallet::<T>::actor_identity(actor_id)
      .unwrap()
      .sovereign_account;
    let native = T::FeeNativeAssetId::get();
    let fee = Pallet::<T>::trigger_fee_for_weight(
      ActorType::User,
      TriggerFamily::Manual,
      T::WeightInfo::manual_trigger(),
    )
    .trigger_fee;
    T::AssetOps::mint(
      &sovereign,
      native,
      fee.saturating_add(T::MinUserBalance::get()),
    )
    .map_err(|failure| failure.error)?;
    assert_distinct_measured_accounts::<T>(&[&sovereign, &T::FeeSink::get()]);
    assert_eq!(
      DeadlineHandles::<T>::get(actor_id).unwrap().key,
      WakeupKey::Block(end.saturating_add(One::one()))
    );
    let payer_before = T::AssetOps::balance(&sovereign, native);
    let sink_before = T::AssetOps::balance(&T::FeeSink::get(), native);
    #[extrinsic_call]
    manual_trigger(RawOrigin::Signed(owner), actor_id);
    assert_eq!(T::AssetOps::balance(&sovereign, native), payer_before - fee);
    assert_eq!(
      T::AssetOps::balance(&T::FeeSink::get(), native),
      sink_before + fee
    );
    let deadline = DeadlineHandles::<T>::get(actor_id).unwrap();
    assert_eq!(deadline.key, WakeupKey::Block(start));
    assert_eq!(
      ActorProcesses::<T>::get(actor_id).unwrap().residence,
      Some(ProcessResidence::Deadline {
        key: deadline.key,
        page: deadline.page,
        slot: deadline.slot
      })
    );
    assert!(!ServiceNodes::<T>::contains_key(actor_id));
    assert!(benchmark_fixture_hot::<T>(actor_id).unwrap().pending_signal);
    assert!(!ActorRunStateStore::<T>::contains_key(actor_id));
    assert!(!ActorFinancialWaits::<T>::contains_key(actor_id));
    Ok(())
  }

  /// One paid maximum legal AddressEvent latch, matching the last entries of both filters.
  /// Producer publication and later Pipeline/Action work are outside this owner.
  #[benchmark(pov_mode = Measured)]
  fn address_event_trigger_occurrence() -> Result<(), BenchmarkError> {
    let fixture = prepare_paid_trigger::<T>(TriggerFamily::AddressEvent)?;
    #[block]
    {
      Pallet::<T>::notify_address_event(
        fixture.actor_id,
        fixture.asset,
        One::one(),
        &fixture.source,
      )?;
    }
    assert_paid_trigger::<T>(&fixture);
    Ok(())
  }

  /// Comparative lifecycle-only cleanup of an Idle User with a pending Pipeline.
  /// A one-Step Manual Contract is retained; temporal membership and Run state are absent.
  /// The direct finalizer does not qualify affordability or other Triggers and has no separate
  /// production Weight consumer. Complete admission refusal belongs to the Service benchmark.
  #[benchmark(extra)]
  fn pipeline_admission_apoptosis() {
    let owner: T::AccountId = account("pipeline-apoptosis-owner", 0, 0);
    let recipient: T::AccountId = account("pipeline-apoptosis-recipient", 0, 0);
    let contract_steps = make_contract_steps::<T>(recipient);
    ensure_creation_balance::<T>(&owner);
    prefund_active_user_creation::<T>(&owner, &contract_steps);
    Pallet::<T>::create_user_actor(
      RawOrigin::Signed(owner).into(),
      Mutability::Mutable,
      user_contract::<T>(
        Schedule {
          trigger: Trigger::Manual,
          cooldown_blocks: 0u32.into(),
        },
        contract_steps,
      ),
    )
    .expect("apoptosis benchmark Actor exists");
    let actor_id = NextActorId::<T>::get().saturating_sub(1);
    benchmark_latch_canonical_occurrence::<T>(actor_id);
    let instance = Pallet::<T>::active_actor_view(actor_id).expect("active Actor view exists");
    assert_eq!(instance.cycle_state, CycleState::Idle);
    assert!(instance.pending_signal);
    assert!(ActorRunStateStore::<T>::get(actor_id).is_none());
    #[block]
    {
      Pallet::<T>::finalize_actor(actor_id, &instance, CloseReason::CycleAdmissionInsufficient)
        .expect("minimal Pipeline-admission apoptosis must succeed");
    }
    assert!(!Pallet::<T>::active_actor_exists(actor_id));
  }

  struct CloseDestructionFixture<T: Config> {
    actor_id: ActorId,
    identity: ActorIdentityOf<T>,
    balances: Vec<(T::AssetId, T::Balance)>,
    owner_hold_after: T::Balance,
    owner_slots_after: [u8; 32],
    active_count_after: u32,
    identity_count_after: u32,
    sink_balance: T::Balance,
    committed_credit: Option<(T::AccountId, T::AssetId, T::Balance)>,
  }

  fn prepare_close_shape<T: Config>(
    actor_type: ActorType,
    shape: u32,
  ) -> Result<CloseDestructionFixture<T>, BenchmarkError> {
    match shape {
      0 | 1 => prepare_retry_close_header::<T>(actor_type, shape == 1),
      2 => prepare_temporal_close::<T>(actor_type, false, CycleState::Idle),
      3 => prepare_temporal_close::<T>(actor_type, true, CycleState::Idle),
      4 => prepare_temporal_close::<T>(actor_type, false, CycleState::Running),
      5 => prepare_temporal_close::<T>(actor_type, false, CycleState::Suspended),
      _ => Err(BenchmarkError::Stop("unsupported Close authority shape")),
    }
  }

  fn prepare_full_header_retry_close<T: Config>(
    actor_type: ActorType,
  ) -> Result<CloseDestructionFixture<T>, BenchmarkError> {
    prepare_retry_close_header::<T>(actor_type, false)
  }

  fn prepare_wide_idle_close<T: Config>(
    actor_type: ActorType,
  ) -> Result<CloseDestructionFixture<T>, BenchmarkError> {
    prepare_wide_idle_close_with_at_time::<T>(actor_type, None)
  }

  fn prepare_wide_idle_close_with_at_time<T: Config>(
    actor_type: ActorType,
    at_time: Option<u64>,
  ) -> Result<CloseDestructionFixture<T>, BenchmarkError> {
    if at_time.is_some() {
      T::BenchmarkHelper::advance_to_scheduler_tick(2)?;
    }
    let (owner, asset, trigger, funding) = large_header_fields::<T>();
    let steps = maximum_temporal_control_steps::<T>(asset)?;
    let first = steps.first().expect("wide Contract has a Step");
    assert!(
      steps.iter().all(|step| step == first),
      "wide Close retains every Step"
    );
    let owner_slot = if actor_type == ActorType::User {
      prefill_reachable_owner_slots::<T>(&owner)
    } else {
      0
    };
    let owner_slots_after = OwnerSlotBitmaps::<T>::get(&owner);
    if actor_type == ActorType::User {
      prefund_user_sovereign::<T>(&owner, owner_slot, &steps);
    }
    let mut contract = user_contract::<T>(
      Schedule {
        trigger,
        cooldown_blocks: 100,
      },
      steps,
    )
    .expect("wide Idle Contract exists");
    contract.funding = funding;
    contract.window = Some(ScheduleWindow {
      start: 1u32.into(),
      end: T::MinWindowLength::get().saturating_add(1_000u32.into()),
    });
    let mut activation = maximum_parked_balance_activation::<T>(&owner)?;
    let header_reduction = if let Some(after_ticks) = at_time {
      contract.trigger = Trigger::at_time(after_ticks);
      contract.cooldown_blocks = 0;
      contract.window = None;
      activation.watches.truncate(1);
      TriggerOf::<T>::max_encoded_len() - contract.trigger.encoded_size()
        + ScheduleWindow::<BlockNumberFor<T>>::max_encoded_len()
    } else {
      0
    };
    let watch_count = activation.watches.len();
    let activation_width = activation.encoded_size();
    contract.parked_balance_activation = Some(activation);
    let expected_steps = contract.steps.clone();
    let hold_reason: T::RuntimeHoldReason = HoldReason::ActorState.into();
    let owner_hold_before = T::StateHoldCurrency::balance_on_hold(&hold_reason, &owner);
    match actor_type {
      ActorType::User => Pallet::<T>::create_user_actor_at_slot(
        RawOrigin::Signed(owner.clone()).into(),
        owner_slot,
        Mutability::Mutable,
        Some(contract),
      )?,
      ActorType::System => Pallet::<T>::create_system_actor(
        RawOrigin::Root.into(),
        owner.clone(),
        Mutability::Mutable,
        Some(contract),
      )?,
    }
    let actor_id = NextActorId::<T>::get() - 1;
    assert_max_contract_geometry::<T>(actor_id);
    let head = ActorContractHeads::<T>::get(actor_id).unwrap();
    assert_eq!(
      head.header.encoded_size(),
      ActorContractHeaderOf::<T>::max_encoded_len()
        - ParkedBalanceActivationOf::<T>::max_encoded_len()
        + activation_width
        - u64::max_encoded_len()
        - header_reduction
    );
    assert_eq!(
      Pallet::<T>::load_actor_contract(actor_id).unwrap().steps,
      expected_steps
    );
    assert_eq!(
      benchmark_fixture_hot::<T>(actor_id).unwrap().cycle_state,
      CycleState::Idle
    );
    assert!(!ActorRunStateStore::<T>::contains_key(actor_id));
    assert_eq!(DependencyPlans::<T>::get(actor_id).len(), watch_count);
    assert_eq!(
      ParkedBalanceEpisodes::<T>::get(actor_id)
        .unwrap()
        .watches
        .len(),
      watch_count
    );
    assert!(matches!(
      ActorProcesses::<T>::get(actor_id).unwrap().residence,
      Some(ProcessResidence::Parked(_))
    ));
    assert_eq!(
      ActorStateHolds::<T>::contains_key(actor_id),
      actor_type == ActorType::User
    );
    let identity = Pallet::<T>::actor_identity(actor_id).unwrap();
    let mut assets = vec![asset, T::FeeNativeAssetId::get()];
    for rule in head
      .header
      .parked_balance_activation
      .as_ref()
      .unwrap()
      .watches
      .iter()
    {
      if !assets.contains(&rule.asset) {
        assets.push(rule.asset);
      }
    }
    let balances = assets
      .into_iter()
      .map(|asset| {
        (
          asset,
          T::AssetOps::balance(&identity.sovereign_account, asset),
        )
      })
      .collect();
    #[cfg(feature = "try-runtime")]
    Pallet::<T>::do_try_state().expect("wide Idle Close fixture is coherent");
    Ok(CloseDestructionFixture {
      actor_id,
      identity,
      balances,
      owner_hold_after: owner_hold_before,
      owner_slots_after,
      active_count_after: ActiveActorCount::<T>::get() - 1,
      identity_count_after: ActorIdentityCount::<T>::get() - 1,
      sink_balance: T::AssetOps::balance(&T::FeeSink::get(), T::FeeNativeAssetId::get()),
      committed_credit: None,
    })
  }

  fn prepare_retry_close_header<T: Config>(
    actor_type: ActorType,
    address_event: bool,
  ) -> Result<CloseDestructionFixture<T>, BenchmarkError> {
    prepare_retry_close_header_with_currency_peer::<T>(actor_type, address_event, false)
  }

  fn prepare_retry_close_header_with_currency_peer<T: Config>(
    actor_type: ActorType,
    address_event: bool,
    currency_peer: bool,
  ) -> Result<CloseDestructionFixture<T>, BenchmarkError> {
    let (owner, address_asset, address_trigger, funding) = large_header_fields::<T>();
    if currency_peer && !T::BenchmarkHelper::setup_close_currency_peer(&owner)? {
      return Err(BenchmarkError::Skip);
    }
    let owner_slot = if actor_type == ActorType::User {
      prefill_reachable_owner_slots::<T>(&owner)
    } else {
      0
    };
    let owner_slots_after = OwnerSlotBitmaps::<T>::get(&owner);
    let trigger = if address_event {
      address_trigger
    } else {
      Trigger::manual()
    };
    let trigger_width = trigger.encoded_size();
    let schedule = Schedule {
      trigger,
      cooldown_blocks: 100,
    };
    let (mut contract_steps, retry_funding) = reachable_retry_contract::<T>()?;
    let wide_tail = maximum_temporal_control_steps::<T>(address_asset)?[0].clone();
    for step in contract_steps.iter_mut().skip(1) {
      *step = wide_tail.clone();
    }
    retain_admitted_contract_geometry::<T>(actor_type, &mut contract_steps, &[0])?;
    if contract_steps.iter().skip(1).any(|step| step != &wide_tail) {
      return Err(BenchmarkError::Stop(
        "retry Close must retain every unvisited wide Step",
      ));
    }
    if actor_type == ActorType::User {
      prefund_user_sovereign::<T>(&owner, owner_slot, &contract_steps);
    }
    let mut contract = user_contract::<T>(schedule, contract_steps).unwrap();
    contract.funding = funding;
    contract.window = Some(ScheduleWindow {
      start: 1u32.into(),
      end: T::MinWindowLength::get().saturating_add(1_000u32.into()),
    });
    let activation = maximum_parked_balance_activation::<T>(&owner)?;
    let activation_width = activation.encoded_size();
    contract.parked_balance_activation = Some(activation);
    // Balance activation excludes outcome-driven and nonce-terminal closure.
    assert!(contract.auto_close_at_cycle_nonce.is_none());
    let hold_reason: T::RuntimeHoldReason = HoldReason::ActorState.into();
    let owner_hold_before = T::StateHoldCurrency::balance_on_hold(&hold_reason, &owner);
    match actor_type {
      ActorType::User => Pallet::<T>::create_user_actor_at_slot(
        RawOrigin::Signed(owner.clone()).into(),
        owner_slot,
        Mutability::Mutable,
        Some(contract),
      )?,
      ActorType::System => Pallet::<T>::create_system_actor(
        RawOrigin::Root.into(),
        owner.clone(),
        Mutability::Mutable,
        Some(contract),
      )?,
    }
    let actor_id = NextActorId::<T>::get().saturating_sub(1);
    open_reachable_retry::<T>(actor_id, retry_funding);
    assert_reachable_retry::<T>(actor_id);
    let head = ActorContractHeads::<T>::get(actor_id).unwrap();
    assert_eq!(
      head.header.encoded_size(),
      ActorContractHeaderOf::<T>::max_encoded_len() - TriggerOf::<T>::max_encoded_len()
        + trigger_width
        - ParkedBalanceActivationOf::<T>::max_encoded_len()
        + activation_width
        - u64::max_encoded_len()
    );
    assert!(DependencyPlans::<T>::get(actor_id).is_empty());
    assert!(!ParkedBalanceEpisodes::<T>::contains_key(actor_id));
    assert!(!TriggerDeadlineHandles::<T>::contains_key(actor_id));
    assert_eq!(
      ActorStateHolds::<T>::contains_key(actor_id),
      actor_type == ActorType::User
    );
    if actor_type == ActorType::User {
      assert!(T::StateHoldCurrency::balance_on_hold(&hold_reason, &owner) > owner_hold_before);
    }
    let identity = Pallet::<T>::actor_identity(actor_id).unwrap();
    let mut assets = vec![retry_funding.0, retry_funding.1, T::FeeNativeAssetId::get()];
    if address_event && !assets.contains(&address_asset) {
      assets.push(address_asset);
    }
    let balances = assets
      .into_iter()
      .map(|asset| {
        (
          asset,
          T::AssetOps::balance(&identity.sovereign_account, asset),
        )
      })
      .collect();
    #[cfg(feature = "try-runtime")]
    Pallet::<T>::do_try_state().expect("reachable close premeasurement state is valid");
    Ok(CloseDestructionFixture {
      actor_id,
      identity,
      balances,
      owner_hold_after: owner_hold_before,
      owner_slots_after,
      active_count_after: ActiveActorCount::<T>::get() - 1,
      identity_count_after: ActorIdentityCount::<T>::get() - 1,
      sink_balance: T::AssetOps::balance(&T::FeeSink::get(), T::FeeNativeAssetId::get()),
      committed_credit: None,
    })
  }

  fn prepare_temporal_close<T: Config>(
    actor_type: ActorType,
    one_shot: bool,
    phase: CycleState,
  ) -> Result<CloseDestructionFixture<T>, BenchmarkError> {
    prepare_temporal_close_with_prefix::<T>(actor_type, one_shot, phase, false)
  }

  #[derive(Clone, Copy)]
  enum PrefixCloseHeader {
    Temporal { one_shot: bool },
    AddressEvent,
    AddressEventCycleBalance,
    AddressEventDeadlinePage(CloseDeadlinePageGeometry),
  }

  fn prepare_temporal_close_with_prefix<T: Config>(
    actor_type: ActorType,
    one_shot: bool,
    phase: CycleState,
    maximum_prefix: bool,
  ) -> Result<CloseDestructionFixture<T>, BenchmarkError> {
    prepare_prefix_close::<T>(
      actor_type,
      PrefixCloseHeader::Temporal { one_shot },
      phase,
      maximum_prefix,
    )
  }

  #[derive(Clone, Copy)]
  struct PrefixCloseKey {
    geometry: CloseDeadlineKeyGeometry,
    tail_entries: u32,
    last_owner_slot: bool,
  }

  fn prepare_prefix_close<T: Config>(
    actor_type: ActorType,
    header: PrefixCloseHeader,
    phase: CycleState,
    maximum_prefix: bool,
  ) -> Result<CloseDestructionFixture<T>, BenchmarkError> {
    prepare_prefix_close_with_key::<T>(actor_type, header, phase, maximum_prefix, None)
      .map(|(fixture, _)| fixture)
  }

  fn prepare_prefix_close_with_key<T: Config>(
    actor_type: ActorType,
    header: PrefixCloseHeader,
    phase: CycleState,
    maximum_prefix: bool,
    key_shape: Option<PrefixCloseKey>,
  ) -> Result<
    (
      CloseDestructionFixture<T>,
      Option<CloseDeadlinePageFixture<T>>,
    ),
    BenchmarkError,
  > {
    let one_shot = matches!(header, PrefixCloseHeader::Temporal { one_shot: true });
    // Every maximum-prefix shape must retain the distribution field in the Run it closes.
    let capture_balance = maximum_prefix;
    let address_event = matches!(
      header,
      PrefixCloseHeader::AddressEvent
        | PrefixCloseHeader::AddressEventCycleBalance
        | PrefixCloseHeader::AddressEventDeadlinePage(_)
    );
    let deadline_page = match header {
      PrefixCloseHeader::AddressEventDeadlinePage(geometry) => {
        assert_eq!(phase, CycleState::Suspended);
        Some(geometry)
      }
      _ => None,
    };
    if let Some(shape) = key_shape {
      assert!(matches!(header, PrefixCloseHeader::AddressEvent));
      assert_eq!(phase, CycleState::Suspended);
      assert!(maximum_prefix);
      assert!(!shape.last_owner_slot || actor_type == ActorType::User);
    }
    let cooldown = if let Some(shape) = key_shape {
      close_deadline_key_spacing::<T>(shape.geometry)?
    } else if address_event {
      100
    } else {
      0
    };
    assert!(!address_event || maximum_prefix);
    assert!(!maximum_prefix || phase != CycleState::Idle);
    let (owner, wide_asset, address_trigger, funding) = large_header_fields::<T>();
    T::BenchmarkHelper::advance_to_scheduler_tick(2)?;
    let owner_slot = if actor_type == ActorType::User {
      prefill_reachable_owner_slots::<T>(&owner)
    } else {
      0
    };
    let mut owner_slots_after = OwnerSlotBitmaps::<T>::get(&owner);
    let hold_reason: T::RuntimeHoldReason = HoldReason::ActorState.into();
    let mut owner_hold_after = T::StateHoldCurrency::balance_on_hold(&hold_reason, &owner);
    let native = T::FeeNativeAssetId::get();
    let native_minimum = T::AssetOps::minimum_balance(native).max(One::one());
    let prefix_asset = if maximum_prefix { wide_asset } else { native };
    if capture_balance && prefix_asset == native {
      return Err(BenchmarkError::Stop(
        "cycle snapshot Close needs a maximum-width non-fee asset",
      ));
    }
    let recipient = measured_account::<T>("close-committed-prefix", 0);
    let amount = T::AssetOps::minimum_balance(prefix_asset).max(One::one());
    T::AssetOps::mint(&recipient, prefix_asset, amount).expect("prefix recipient is pre-endowed");
    let recipient_before = T::AssetOps::balance(&recipient, prefix_asset);
    let (mut steps, retry_funding) = reachable_retry_contract::<T>()?;
    let wide_tail = maximum_temporal_control_steps::<T>(wide_asset)?[0].clone();
    let required_steps = if phase == CycleState::Running { 3 } else { 2 };
    if steps.len() < required_steps {
      return Err(BenchmarkError::Stop(
        "temporal Close witness needs its retained authored suffix",
      ));
    }
    let mut retry_step = steps[0].clone();
    let expected_sovereign = match actor_type {
      ActorType::User => Pallet::<T>::sovereign_account_id(&owner, owner_slot),
      ActorType::System => Pallet::<T>::sovereign_account_id_system(NextActorId::<T>::get()),
    };
    let retry_asset = if phase == CycleState::Idle {
      None
    } else {
      let (asset, _, failed_recipient) =
        T::BenchmarkHelper::setup_temporary_transfer(&owner, &expected_sovereign)?;
      assert_distinct_measured_accounts::<T>(&[
        &owner,
        &expected_sovereign,
        &failed_recipient,
        &T::FeeSink::get(),
      ]);
      let total = One::one();
      T::AssetOps::mint(&expected_sovereign, asset, total).map_err(|failure| failure.error)?;
      // The attempted Transfer is narrower than the inert maximum-width suffix.
      retry_step.precondition = wide_tail.precondition.clone();
      for clause in &mut retry_step.precondition.as_mut().unwrap().clauses {
        for predicate in clause {
          if let Predicate::ObservationAbove { max_age_blocks, .. } = predicate {
            *max_age_blocks = u32::MAX;
          }
        }
      }
      retry_step.task = ActorTask::Transfer {
        asset,
        amount: AmountResolution::Fixed(total),
        to: failed_recipient,
      };
      assert!(retry_step.task.encoded_size() <= TaskOf::<T>::max_encoded_len());
      assert!(retry_step.encoded_size() <= wide_tail.encoded_size());
      Some(asset)
    };
    steps[0] = if maximum_prefix {
      let total = amount;
      let mut prefix = wide_tail.clone();
      prefix.precondition = retry_step.precondition.clone();
      prefix.task = ActorTask::Transfer {
        asset: prefix_asset,
        amount: if capture_balance {
          AmountResolution::CaptureCycleBalance {
            percent: Perbill::one(),
            share: Perbill::from_percent(50),
          }
        } else {
          AmountResolution::Fixed(total)
        },
        to: recipient.clone(),
      };
      let mut funding = total.checked_add(&amount).ok_or(BenchmarkError::Stop(
        "maximum committed prefix funding overflows",
      ))?;
      if capture_balance {
        funding = funding.checked_add(&amount).ok_or(BenchmarkError::Stop(
          "cycle snapshot prefix funding overflows",
        ))?;
      }
      T::AssetOps::mint(&expected_sovereign, prefix_asset, funding)
        .map_err(|failure| failure.error)?;
      assert!(prefix.task.encoded_size() <= TaskOf::<T>::max_encoded_len());
      assert!(prefix.encoded_size() <= wide_tail.encoded_size());
      prefix
    } else {
      Step {
        precondition: None,
        task: ActorTask::Transfer {
          to: recipient.clone(),
          asset: native,
          amount: AmountResolution::Fixed(amount),
        },
        on_error: StepErrorPolicy::AbortCycle,
      }
    };
    if phase == CycleState::Running {
      retry_step.on_error = StepErrorPolicy::ContinueNextStep;
    }
    steps[1] = if phase == CycleState::Idle {
      make_inert_contract_steps::<T>()[0].clone()
    } else {
      retry_step
    };
    for step in steps.iter_mut().skip(2) {
      *step = wide_tail.clone();
    }
    retain_admitted_contract_geometry::<T>(actor_type, &mut steps, &[0, 1])?;
    if steps.iter().skip(2).any(|step| step != &wide_tail) {
      return Err(BenchmarkError::Stop(
        "temporal Close must retain every unvisited wide Step",
      ));
    }
    let (trigger_family, trigger_weight) = if address_event {
      (
        TriggerFamily::AddressEvent,
        T::WeightInfo::address_event_trigger_occurrence(),
      )
    } else if one_shot {
      (
        TriggerFamily::AtTime,
        T::WeightInfo::at_time_trigger_occurrence(),
      )
    } else {
      (
        TriggerFamily::Cadenced,
        T::WeightInfo::cadenced_trigger_occurrence(),
      )
    };
    let reserve = full_attempt_fee::<T>(&steps)
      .checked_add(
        &Pallet::<T>::trigger_fee_for_weight(actor_type, trigger_family, trigger_weight)
          .trigger_fee,
      )
      .and_then(|value| value.checked_add(&native_minimum))
      .and_then(|value| value.checked_add(&native_minimum))
      .ok_or(BenchmarkError::Stop("completed Close prefunding overflow"))?;
    if actor_type == ActorType::User {
      prefund_user_sovereign::<T>(&owner, owner_slot, &steps);
    }
    let mut contract = system_contract::<T>(
      Schedule {
        trigger: if address_event {
          address_trigger
        } else if one_shot {
          Trigger::AtTime { after_ticks: 1_000 }
        } else {
          Trigger::cadenced(1_000)
        },
        cooldown_blocks: cooldown,
      },
      steps,
    )
    .unwrap();
    contract.funding = funding;
    if address_event {
      contract.window = Some(ScheduleWindow {
        start: 1u32.into(),
        end: T::MinWindowLength::get()
          .saturating_add(1_000u32.into())
          .saturating_add(if key_shape.is_some() {
            cooldown.into()
          } else {
            Zero::zero()
          }),
      });
      contract.parked_balance_activation = Some(maximum_parked_balance_activation::<T>(&owner)?);
      assert!(contract.auto_close_at_cycle_nonce.is_none());
    } else if T::MaxAutoCloseNonceHorizon::get() < 2 {
      return Err(BenchmarkError::Stop(
        "completed Close witness needs a retained future nonce",
      ));
    } else {
      contract.auto_close_at_cycle_nonce = Some(T::MaxAutoCloseNonceHorizon::get());
    }
    match actor_type {
      ActorType::User => Pallet::<T>::create_user_actor_at_slot(
        RawOrigin::Signed(owner.clone()).into(),
        owner_slot,
        Mutability::Mutable,
        Some(contract),
      )?,
      ActorType::System => Pallet::<T>::create_system_actor(
        RawOrigin::Root.into(),
        owner.clone(),
        Mutability::Mutable,
        Some(contract),
      )?,
    }
    let actor_id = NextActorId::<T>::get() - 1;
    let actor = Pallet::<T>::load_actor_ref(actor_id).unwrap();
    let sovereign = Pallet::<T>::actor_identity(actor_id)
      .unwrap()
      .sovereign_account;
    assert_eq!(sovereign, expected_sovereign);
    T::AssetOps::mint(&sovereign, native, reserve).expect("both authored Steps are funded");
    if phase != CycleState::Idle {
      T::AssetOps::mint(&sovereign, retry_funding.0, retry_funding.2)
        .map_err(|failure| failure.error)?;
      T::AssetOps::mint(&sovereign, retry_funding.1, retry_funding.3)
        .map_err(|failure| failure.error)?;
    }
    if address_event {
      let contract = Pallet::<T>::actor_contract(actor_id).unwrap();
      let Trigger::AddressEvent {
        source_filter: SourceFilter::Whitelist(sources),
        asset_filter: AssetFilter::Whitelist(assets),
      } = &contract.trigger
      else {
        panic!("wide prefix uses complete AddressEvent filters")
      };
      let source = sources.last().unwrap();
      let asset = *assets.last().unwrap();
      let amount = T::AssetOps::minimum_balance(asset).max(One::one());
      let source_funding = amount.checked_add(&amount).ok_or(BenchmarkError::Stop(
        "matched AddressEvent source prefunding overflows",
      ))?;
      T::AssetOps::mint(source, asset, source_funding).map_err(|failure| failure.error)?;
      let source_before = T::AssetOps::balance(source, asset);
      let custody_before = T::AssetOps::balance(&sovereign, asset);
      T::BenchmarkHelper::transfer_signed(source, &sovereign, asset, amount)?;
      assert_eq!(T::AssetOps::balance(source, asset), source_before - amount);
      if asset != native {
        assert_eq!(
          T::AssetOps::balance(&sovereign, asset),
          custody_before + amount
        );
      }
      assert!(benchmark_fixture_hot::<T>(actor_id).unwrap().pending_signal);
    } else {
      let WakeupKey::Tick(due) = TriggerDeadlineHandles::<T>::get(actor_id).unwrap().key else {
        panic!("temporal authority initially owns a Tick source")
      };
      T::BenchmarkHelper::finalize_scheduler_clock()?;
      T::BenchmarkHelper::advance_to_scheduler_tick(due)?;
      prepare_temporal_deadline_frontier::<T>(actor, due);
      Pallet::<T>::process_due_temporal_deadline(actor, due).unwrap();
    }
    let mut key_fixture = None;
    let mut committed_amount = amount;
    let mut captured_balance = None;
    for visit in 0..2 {
      let eligible = ServiceNodes::<T>::get(actor_id).unwrap().eligible_from;
      let eligible = ActorRunStateStore::<T>::get(actor_id)
        .map_or(eligible, |run| eligible.max(run.eligible_at));
      frame_system::Pallet::<T>::set_block_number(
        frame_system::Pallet::<T>::block_number().max(eligible),
      );
      if visit == 1 {
        if let Some(shape) = key_shape {
          if shape.last_owner_slot {
            let identity = Pallet::<T>::actor_identity(actor_id).unwrap();
            retire_close_owner_slot_peers::<T>(actor_id, &identity)?;
            owner_slots_after = [0; 32];
            owner_hold_after = Zero::zero();
          }
          // Fill the index before the real failed attempt publishes this Actor's retry.
          key_fixture = Some(prepare_close_deadline_key_remove_with_authority::<T>(
            CloseDeadlineOwner::Process,
            shape.tail_entries,
            shape.geometry,
            CloseDeadlineAuthority {
              actor,
              key: WakeupKey::Block(eligible.saturating_add(cooldown.into())),
              publish_at: eligible,
            },
          )?);
          continue;
        }
      }
      let guards = if visit == 1 {
        if let Some(geometry) = deadline_page {
          let due = eligible.saturating_add(100u32.into());
          Some(prepare_close_authority_page_prefix::<T>(
            WakeupKey::Block(due),
            geometry,
          )?)
        } else {
          None
        }
      } else {
        None
      };
      if visit == 0 && capture_balance {
        let balance = T::AssetOps::balance(&sovereign, prefix_asset)
          .saturating_sub(T::AssetOps::minimum_balance(prefix_asset));
        committed_amount = Perbill::from_percent(50).mul_floor(balance);
        assert!(committed_amount >= amount);
        captured_balance = Some(balance);
      }
      Pallet::<T>::execute_cycle(Weight::MAX);
      if let Some(guards) = guards {
        assert_deadline_process_authority_width::<T>(actor);
        let key = DeadlineHandles::<T>::get(actor_id).unwrap().key;
        finish_close_authority_page::<T>(
          CloseDeadlineOwner::Process,
          actor,
          key,
          guards,
          deadline_page.unwrap(),
        )?;
      }
    }
    if one_shot && actor_type == ActorType::System {
      let now = frame_system::Pallet::<T>::block_number();
      frame_system::Pallet::<T>::set_block_number(now.saturating_add(One::one()));
      Pallet::<T>::pause_actor(RawOrigin::Signed(owner.clone()).into(), actor_id)?;
      let process = ActorProcesses::<T>::get(actor_id).unwrap();
      assert!(process.residence.is_none());
      assert!(matches!(
        process.status,
        ProcessStatus::Disabled(ProcessDisablement {
          cause: ProcessDisableCause::OwnerPaused,
          basis: SuspendedProcessBasis::Idle,
          ..
        })
      ));
      assert!(!ServiceNodes::<T>::contains_key(actor_id));
      assert!(!TriggerDeadlineHandles::<T>::contains_key(actor_id));
    }
    if one_shot && actor_type == ActorType::User {
      assert_eq!(
        ActorProcesses::<T>::get(actor_id).unwrap().residence,
        Some(ProcessResidence::Service(ServiceResidenceKind::Live))
      );
      assert!(!TriggerDeadlineHandles::<T>::contains_key(actor_id));
      assert!(
        !Pallet::<T>::active_actor_view(actor_id)
          .unwrap()
          .lifecycle
          .is_paused()
      );
    }
    let record = benchmark_fixture_semantic_record::<T>(actor_id).unwrap();
    assert_eq!(
      record.identity.cycle_nonce,
      u64::from(phase == CycleState::Idle)
    );
    assert_eq!(record.hot.cycle_state, phase);
    if phase == CycleState::Idle {
      assert!(ActorRunStateStore::<T>::get(actor_id).is_none());
      assert_completed_temporal_authority_width::<T>(&record);
    } else {
      let run = ActorRunStateStore::<T>::get(actor_id).unwrap();
      assert_eq!(
        run.balance_snapshot,
        captured_balance.map(|balance| CycleBalanceSnapshot {
          asset: prefix_asset,
          balance,
        })
      );
      assert_eq!(run.cycle_nonce, 1);
      assert_eq!(run.cursor, if phase == CycleState::Running { 2 } else { 1 });
      assert!(run.last_committed_step_block.is_some());
      let Some(StepOutcome::Failed(ref failure)) = run.last_step_outcome else {
        panic!("the second actual attempt must retain its typed failure")
      };
      assert_eq!(failure.retry, RetryClass::Temporary);
      assert_eq!(
        failure.error,
        Error::<T>::RecipientDepositUnavailable.into()
      );
      assert_eq!(
        run.suspension,
        (phase == CycleState::Suspended).then_some(SuspensionReason::Temporary)
      );
      let absent_suspension =
        Option::<SuspensionReason>::max_encoded_len() - run.suspension.encoded_size();
      if maximum_prefix {
        assert!(run.balance_snapshot.is_some());
        assert_eq!(
          run.encoded_size(),
          ActorRunStateOf::<T>::max_encoded_len() - absent_suspension
        );
      }
      assert_eq!(
        run.encoded_size(),
        ActorRunStateOf::<T>::max_encoded_len()
          - absent_suspension
          - (Option::<CycleBalanceSnapshot<T::AssetId, T::Balance>>::max_encoded_len()
            - run.balance_snapshot.encoded_size())
      );
      assert_eq!(run.cumulative_outcomes.committed_effectful_tasks, 1);
      if address_event && phase == CycleState::Suspended {
        let handle = DeadlineHandles::<T>::get(actor_id).unwrap();
        assert_eq!(handle.key, WakeupKey::Block(run.eligible_at));
        assert_eq!(
          ActorProcesses::<T>::get(actor_id).unwrap().residence,
          Some(ProcessResidence::Deadline {
            key: handle.key,
            page: handle.page,
            slot: handle.slot,
          })
        );
        assert!(!ServiceNodes::<T>::contains_key(actor_id));
      } else {
        assert_eq!(
          ActorProcesses::<T>::get(actor_id).unwrap().residence,
          Some(ProcessResidence::Service(ServiceResidenceKind::Live))
        );
        assert!(!DeadlineHandles::<T>::contains_key(actor_id));
      }
      assert_eq!(
        TriggerDeadlineHandles::<T>::contains_key(actor_id),
        !address_event
      );
    }
    assert_max_contract_geometry::<T>(actor_id);
    assert_eq!(
      T::AssetOps::balance(&recipient, prefix_asset),
      recipient_before + committed_amount
    );
    if maximum_prefix {
      let contract = Pallet::<T>::actor_contract(actor_id).unwrap();
      let maximum = wide_tail.encoded_size();
      for (index, step) in contract.steps.iter().enumerate() {
        let error_gap = if index == 1 && phase == CycleState::Running {
          wide_tail.on_error.encoded_size() - StepErrorPolicy::ContinueNextStep.encoded_size()
        } else {
          0
        };
        let task_gap = wide_tail.task.encoded_size() - step.task.encoded_size();
        if index >= 2 {
          assert_eq!(task_gap, 0);
        } else {
          assert!(matches!(step.task, ActorTask::Transfer { .. }));
        }
        assert_eq!(step.encoded_size(), maximum - task_gap - error_gap);
      }
    }
    if address_event {
      let head = ActorContractHeads::<T>::get(actor_id).unwrap();
      let activation = head.header.parked_balance_activation.as_ref().unwrap();
      assert_eq!(
        activation.watches.len(),
        T::MaxParkedBalanceWatches::get() as usize
      );
      assert_eq!(
        head.header.encoded_size(),
        ActorContractHeaderOf::<T>::max_encoded_len()
          - ParkedBalanceActivationOf::<T>::max_encoded_len()
          + activation.encoded_size()
          - u64::max_encoded_len()
      );
      assert!(DependencyPlans::<T>::get(actor_id).is_empty());
      assert!(!ParkedBalanceEpisodes::<T>::contains_key(actor_id));
    }
    #[cfg(feature = "try-runtime")]
    Pallet::<T>::do_try_state().expect("temporal Close authority is coherent");
    let mut assets = if phase == CycleState::Idle {
      vec![native]
    } else {
      vec![native, retry_funding.0, retry_funding.1]
    };
    if let Some(asset) = retry_asset {
      if !assets.contains(&asset) {
        assets.push(asset);
      }
    }
    if !assets.contains(&prefix_asset) {
      assets.push(prefix_asset);
    }
    if address_event {
      for rule in Pallet::<T>::actor_contract(actor_id)
        .unwrap()
        .parked_balance_activation
        .as_ref()
        .unwrap()
        .watches
        .iter()
      {
        if !assets.contains(&rule.asset) {
          assets.push(rule.asset);
        }
      }
      let Trigger::AddressEvent {
        asset_filter: AssetFilter::Whitelist(filter),
        ..
      } = Pallet::<T>::actor_contract(actor_id).unwrap().trigger
      else {
        panic!("wide AddressEvent asset filter remains")
      };
      let ingress_asset = *filter.last().unwrap();
      if !assets.contains(&ingress_asset) {
        assets.push(ingress_asset);
      }
    }
    let balances = assets
      .into_iter()
      .map(|asset| (asset, T::AssetOps::balance(&sovereign, asset)))
      .collect();
    Ok((
      CloseDestructionFixture {
        actor_id,
        identity: record.identity,
        balances,
        owner_hold_after,
        owner_slots_after,
        active_count_after: ActiveActorCount::<T>::get() - 1,
        identity_count_after: ActorIdentityCount::<T>::get() - 1,
        sink_balance: T::AssetOps::balance(&T::FeeSink::get(), native),
        committed_credit: Some((recipient, prefix_asset, recipient_before + committed_amount)),
      },
      key_fixture,
    ))
  }

  fn retire_close_owner_slot_peers<T: Config>(
    actor_id: ActorId,
    identity: &ActorIdentityOf<T>,
  ) -> Result<(), BenchmarkError> {
    let ActorClass::User { owner_slot } = identity.actor_class else {
      panic!("last owner-slot release belongs to User destruction")
    };
    for slot in 0..T::MaxOwnerSlots::get() {
      if slot == owner_slot {
        continue;
      }
      let sovereign = Pallet::<T>::sovereign_account_id(&identity.owner, slot);
      let peer = SovereignIndex::<T>::get(sovereign).expect("ordinary Dormant peer exists");
      Pallet::<T>::close_actor(RawOrigin::Signed(identity.owner.clone()).into(), peer)?;
    }
    let bitmap = OwnerSlotBitmaps::<T>::get(&identity.owner);
    assert_eq!(bitmap.iter().map(|byte| byte.count_ones()).sum::<u32>(), 1);
    assert!(ActorStateHolds::<T>::contains_key(actor_id));
    #[cfg(feature = "try-runtime")]
    Pallet::<T>::do_try_state().expect("peer retirement preserves the target and last owner slot");
    Ok(())
  }

  fn leave_last_close_owner_slot<T: Config>(
    fixture: &mut CloseDestructionFixture<T>,
  ) -> Result<(), BenchmarkError> {
    retire_close_owner_slot_peers::<T>(fixture.actor_id, &fixture.identity)?;
    fixture.owner_slots_after = [0; 32];
    fixture.owner_hold_after = Zero::zero();
    fixture.identity_count_after = ActorIdentityCount::<T>::get() - 1;
    Ok(())
  }

  fn assert_close_destruction<T: Config>(fixture: &CloseDestructionFixture<T>) {
    let actor_id = fixture.actor_id;
    assert!(Pallet::<T>::actor_identity(actor_id).is_none());
    assert!(!ActorSemanticStates::<T>::contains_key(actor_id));
    assert!(!ActorIdentities::<T>::contains_key(actor_id));
    assert!(!ActorContractHeads::<T>::contains_key(actor_id));
    assert!(
      ActorContractTailChunks::<T>::iter_prefix(actor_id)
        .next()
        .is_none()
    );
    assert!(!ActorRunStateStore::<T>::contains_key(actor_id));
    assert!(!ActorControlLocators::<T>::contains_key(actor_id));
    assert!(!ActorProcesses::<T>::contains_key(actor_id));
    assert!(!DeadlineHandles::<T>::contains_key(actor_id));
    assert!(!ActorStateHolds::<T>::contains_key(actor_id));
    let hold_reason: T::RuntimeHoldReason = HoldReason::ActorState.into();
    assert_eq!(
      T::StateHoldCurrency::balance_on_hold(&hold_reason, &fixture.identity.owner),
      fixture.owner_hold_after
    );
    assert_eq!(
      OwnerSlotBitmaps::<T>::get(&fixture.identity.owner),
      fixture.owner_slots_after
    );
    assert_eq!(
      OwnerSlotBitmaps::<T>::contains_key(&fixture.identity.owner),
      fixture.owner_slots_after.iter().any(|byte| *byte != 0)
    );
    assert_eq!(ActiveActorCount::<T>::get(), fixture.active_count_after);
    assert_eq!(ActorIdentityCount::<T>::get(), fixture.identity_count_after);
    assert!(!SovereignIndex::<T>::contains_key(
      &fixture.identity.sovereign_account
    ));
    if let ActorClass::System { sovereign_id } = fixture.identity.actor_class {
      assert_eq!(
        SystemSovereigns::<T>::get(sovereign_id),
        Some(SystemSovereignState::Vacant)
      );
    }
    for &(asset, balance) in &fixture.balances {
      assert_eq!(
        T::AssetOps::balance(&fixture.identity.sovereign_account, asset),
        balance
      );
    }
    assert_eq!(
      T::AssetOps::balance(&T::FeeSink::get(), T::FeeNativeAssetId::get()),
      fixture.sink_balance
    );
    if let Some((recipient, asset, balance)) = &fixture.committed_credit {
      assert_eq!(T::AssetOps::balance(recipient, *asset), *balance);
    }
    #[cfg(feature = "try-runtime")]
    Pallet::<T>::do_try_state().expect("close leaves no orphan state");
  }

  #[benchmark]
  fn close_actor() -> Result<(), BenchmarkError> {
    // This complete Manual retry witness is not the Parked/temporal/residence union.
    let fixture = prepare_full_header_retry_close::<T>(ActorType::User)?;
    let actor_id = fixture.actor_id;
    let owner = fixture.identity.owner.clone();
    #[extrinsic_call]
    close_actor(RawOrigin::Signed(owner), actor_id);
    assert_close_destruction::<T>(&fixture);
    Ok(())
  }

  /// Complete public Close on a live policy-bearing Mutable User, whose optional policy and
  /// monitor destruction the plain `close_actor` owner excludes. The host must supply an
  /// admission authority that can price the policy Close (benchmarks bind a benchmark-only
  /// authority for exactly this reason), so the measurement covers the real work while no
  /// production coefficient is asserted.
  #[benchmark]
  fn close_actor_policy_bearing() -> Result<(), BenchmarkError> {
    let source = prepare_behavior_source_snapshot_in_domain::<T>(4, false, ActorType::User, false)?;
    let actor_id = source.actor_id;
    let fixture = source.destruction.expect("temporal destruction witness");
    let owner = benchmark_fixture_semantic_record::<T>(actor_id)
      .expect("policy-bearing source keeps authority")
      .identity
      .owner;
    #[extrinsic_call]
    close_actor(RawOrigin::Signed(owner), actor_id);
    assert_close_destruction::<T>(&fixture);
    Ok(())
  }

  fn detach_close_destruction<T: Config>(
    actor_id: ActorId,
  ) -> Result<(ActiveActorStateOf<T>, ActorAdmissionCertificateOf<T>), BenchmarkError> {
    let (LoadedActorStateOf::Active(state), Some(admission)) =
      Pallet::<T>::load_actor_state_with_admission(actor_id)
    else {
      panic!("finalization starts from complete Active authority")
    };
    let generation = benchmark_fixture_semantic_record::<T>(actor_id)
      .unwrap()
      .generation;
    let terminal = Pallet::<T>::detach_actor_publication(
      ActorRef {
        actor_id,
        generation,
      },
      state.clone(),
      state.run_state.as_ref(),
    )?;
    assert!(!ActorProcesses::<T>::contains_key(actor_id));
    assert!(!DeadlineHandles::<T>::contains_key(actor_id));
    assert!(!TriggerDeadlineHandles::<T>::contains_key(actor_id));
    assert_eq!(
      ActorRunStateStore::<T>::get(actor_id).encode(),
      state.run_state.encode()
    );
    assert_eq!(terminal.run_state.encode(), state.run_state.encode());
    Ok((terminal, admission))
  }

