  #[benchmark(extra, pov_mode = Measured)]
  fn close_dormant_event_root(c: Linear<0, 1>) -> Result<(), BenchmarkError> {
    let actor_type = if c == 0 {
      ActorType::User
    } else {
      ActorType::System
    };
    let mut fixture = prepare_dormant_close::<T>(actor_type)?;
    if actor_type == ActorType::User {
      leave_last_close_owner_slot::<T>(&mut fixture)?;
    }
    let expected_prefix: <T as frame_system::Config>::RuntimeEvent =
      frame_system::Event::<T>::Remarked {
        sender: fixture.identity.owner.clone(),
        hash: T::Hashing::hash(&[]),
      }
      .into();
    let measured_root: Vec<u8>;
    #[block]
    {
      // Reset and prefix belong to this complete fragment, after FRAME's setup commit.
      frame_system::Pallet::<T>::reset_events();
      frame_system::Pallet::<T>::note_finished_initialize();
      for _ in 0..63 {
        frame_system::Pallet::<T>::remark_with_event(
          RawOrigin::Signed(fixture.identity.owner.clone()).into(),
          Vec::new(),
        )?;
      }
      // Materialize count 63 so the Close suffix widens its compact prefix at the next root.
      let _ = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
      let origin = if actor_type == ActorType::User {
        RawOrigin::Signed(fixture.identity.owner.clone())
      } else {
        RawOrigin::Root
      };
      Pallet::<T>::close_actor(origin.into(), fixture.actor_id)?;
      measured_root =
        polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    }
    assert_eq!(
      polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
      measured_root,
    );
    let events = frame_system::Pallet::<T>::events();
    assert!(events.len() >= 64);
    assert_eq!(
      frame_system::Pallet::<T>::event_count() as usize,
      events.len()
    );
    for record in &events[..63] {
      assert_eq!(record.event.encode(), expected_prefix.encode());
      assert!(matches!(
        record.phase,
        frame_system::Phase::ApplyExtrinsic(0)
      ));
      assert!(record.topics.is_empty());
    }
    frame_system::Pallet::<T>::assert_last_event(
      Event::<T>::ActorClosed {
        actor_id: fixture.actor_id,
        reason: CloseReason::OwnerInitiated,
      }
      .into(),
    );
    assert_close_destruction::<T>(&fixture);
    Ok(())
  }

