  fn prepare_close_currency_shortfall<T: Config>(
    fixture: &CloseDestructionFixture<T>,
  ) -> Result<T::Balance, BenchmarkError> {
    use polkadot_sdk::frame_support::traits::{fungible::MutateHold, tokens::Precision};
    let reason: T::RuntimeHoldReason = HoldReason::ActorState.into();
    let held = T::StateHoldCurrency::balance_on_hold(&reason, &fixture.identity.owner);
    let required = held
      .checked_sub(&fixture.owner_hold_after)
      .ok_or(BenchmarkError::Stop(
        "late Close refusal requires the target's complete hold",
      ))?;
    if required <= One::one() {
      return Err(BenchmarkError::Stop(
        "late Close refusal requires a retained nonzero currency hold",
      ));
    }
    // Keep a real Holds entry one unit below the target release, including when peers remain.
    let released = fixture
      .owner_hold_after
      .checked_add(&One::one())
      .ok_or(BenchmarkError::Stop("late Close shortfall overflows"))?;
    T::StateHoldCurrency::release(&reason, &fixture.identity.owner, released, Precision::Exact)?;
    assert_eq!(
      T::StateHoldCurrency::balance_on_hold(&reason, &fixture.identity.owner),
      required - One::one()
    );
    Ok(released)
  }

  fn verify_close_currency_rollback<T: Config>(
    fixture: &CloseDestructionFixture<T>,
    released: T::Balance,
    root: &[u8],
    result: DispatchResult,
  ) -> Result<(), BenchmarkError> {
    use polkadot_sdk::frame_support::traits::fungible::MutateHold;
    assert_eq!(result, Err(Error::<T>::StateHoldInvariant.into()));
    assert_eq!(
      polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
      root
    );
    for &(asset, balance) in &fixture.balances {
      assert_eq!(
        T::AssetOps::balance(&fixture.identity.sovereign_account, asset),
        balance
      );
    }
    if let Some((recipient, asset, balance)) = &fixture.committed_credit {
      assert_eq!(T::AssetOps::balance(recipient, *asset), *balance);
    }
    assert_eq!(
      T::AssetOps::balance(&T::FeeSink::get(), T::FeeNativeAssetId::get()),
      fixture.sink_balance
    );
    let reason: T::RuntimeHoldReason = HoldReason::ActorState.into();
    assert!(!T::StateHoldCurrency::balance_on_hold(&reason, &fixture.identity.owner).is_zero());
    T::StateHoldCurrency::hold(&reason, &fixture.identity.owner, released)?;
    Pallet::<T>::close_actor(
      RawOrigin::Signed(fixture.identity.owner.clone()).into(),
      fixture.actor_id,
    )?;
    assert_close_destruction::<T>(fixture);
    Ok(())
  }

