  /// Host authority construction only; no Actor body, admission, cleanup or Task is invoked.
  /// Referenced Weight values remain inputs, not qualified by executing their identity owner.
  #[benchmark(extra, pov_mode = Measured)]
  fn admission_certificate_authority() -> Result<(), BenchmarkError> {
    let expected = T::AdmissionCertificateAuthority::current().ok_or(BenchmarkError::Stop(
      "host admission authority is unavailable",
    ))?;
    let actual;
    #[block]
    {
      actual = T::AdmissionCertificateAuthority::current();
      core::hint::black_box(&actual);
    }
    assert_eq!(actual, Some(expected));
    Ok(())
  }

