  fn prepare_breaker_resource_state<T: Config>()
  -> Result<BlockResourceState<BlockNumberFor<T>>, BenchmarkError> {
    GlobalCircuitBreaker::<T>::put(false);
    T::BenchmarkHelper::advance_to_scheduler_tick(2)?;
    T::BenchmarkHelper::prepare_actor_prepass_context()?;
    Pallet::<T>::actor_prepass(RawOrigin::None.into()).map_err(|error| error.error)?;
    let state = CurrentBlockResourceState::<T>::get()
      .expect("successful mandatory Prepass publishes its resource state");
    assert_eq!(
      state.block_number(),
      frame_system::Pallet::<T>::block_number()
    );
    assert_eq!(state.phase(), BlockResourcePhase::ExternalPhase);
    assert!(state.budget().is_ok());
    assert_eq!(state.outstanding_reservations(), 0);
    assert!(!state.optional_actor_work_halted());
    Ok(state)
  }

  // Componentless public setter witness; the categorical diagnostic retains the other states.
  // Dispatch admission and the governance enactment envelope require separate qualification.
  #[benchmark(extra)]
  fn set_user_creation_enabled() -> Result<(), BenchmarkError> {
    let mut resource_state = prepare_breaker_resource_state::<T>()?;
    UserCreationEnabled::<T>::put(false);
    let origin = T::GlobalBreakerOrigin::try_successful_origin()
      .map_err(|_| BenchmarkError::Stop("host must provide admission control authority"))?;
    Pallet::<T>::set_global_circuit_breaker(origin.clone(), true)?;
    resource_state.halt_optional_actor_work();
    assert_eq!(CurrentBlockResourceState::<T>::get(), Some(resource_state));
    let next_id = NextActorId::<T>::get();
    let active_count = ActiveActorCount::<T>::get();
    #[block]
    {
      Pallet::<T>::set_user_creation_enabled(origin, true)?;
    }
    assert!(UserCreationEnabled::<T>::get());
    assert!(GlobalCircuitBreaker::<T>::get());
    assert_eq!(CurrentBlockResourceState::<T>::get(), Some(resource_state));
    assert_eq!(NextActorId::<T>::get(), next_id);
    assert_eq!(ActiveActorCount::<T>::get(), active_count);
    frame_system::Pallet::<T>::assert_last_event(
      Event::<T>::UserCreationEnabledSet { enabled: true }.into(),
    );
    Ok(())
  }

