  #[benchmark]
  fn process_dependency_scan_unit() -> Result<(), BenchmarkError> {
    frame_system::Pallet::<T>::set_block_number(1u32.into());
    let owner_account: T::AccountId = account("dependency-scan-unit", 0, 0);
    let asset = T::BenchmarkHelper::setup_max_encoded_predicate_assets(&owner_account, 1)?
      .into_iter()
      .next()
      .expect("one maximum-width benchmark asset exists");
    let source = polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
      match Pallet::<T>::resolve_balance_dependency_source(asset) {
        Ok(
          DependencySourceMutation::Existing(source) | DependencySourceMutation::Allocated(source),
        ) => polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(Ok(source)),
        Err(_) => polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(Err(())),
      }
    })
    .map_err(|()| BenchmarkError::Stop("benchmark balance dependency source is missing"))?;
    for _ in 0..2 {
      let Some(target) = DependencyRevisions::<T>::get(source).scan_target else {
        break;
      };
      polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
        match Pallet::<T>::complete_dependency_scan(source, target, 0) {
          Ok(_) => polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(Ok(())),
          Err(error) => {
            polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(Err(error))
          }
        }
      })
      .map_err(|_| BenchmarkError::Stop("initial empty balance scan did not settle"))?;
    }
    let activation = ParkedBalanceActivationOf::<T>::try_from_rules(vec![ParkedBalanceRule {
      asset,
      authored_min_delta: 1u32.into(),
    }])
    .map_err(|_| BenchmarkError::Stop("one bounded balance watch certifies"))?;
    let mut contract = system_contract::<T>(
      Schedule {
        trigger: Trigger::Manual,
        cooldown_blocks: 0,
      },
      inert_contract_steps_of_len::<T>(1),
    )
    .expect("bounded active Contract");
    contract.parked_balance_activation = Some(activation);
    Pallet::<T>::create_system_actor(
      RawOrigin::Root.into(),
      owner_account,
      Mutability::Mutable,
      Some(contract),
    )
    .expect("public creation arms real parked-balance episode");
    let actor_id = NextActorId::<T>::get() - 1;
    polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
      match Pallet::<T>::publish_dependency_event_with_source_retention(source) {
        Ok(_) => polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(Ok(())),
        Err(error) => {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(Err(error))
        }
      }
    })
    .map_err(|_| BenchmarkError::Stop("dependency revision publication failed"))?;
    let mut meter = polkadot_sdk::sp_weights::WeightMeter::with_limit(Weight::MAX);

    #[block]
    {
      Pallet::<T>::process_next_dependency_scan_unit(&mut meter)
        .expect("dependency scan member advances")
        .expect("one source is active");
    }

    assert!(PendingDependencyEvents::<T>::contains_key(actor_id));
    assert_eq!(DependencyRevisions::<T>::get(source).scan_cursor, 1);
    Ok(())
  }

  #[benchmark]
  fn process_dependency_scan_completion_unit() -> Result<(), BenchmarkError> {
    let source = 1;
    DependencyRevisions::<T>::insert(
      source,
      DependencyRevisionState {
        revision: 1,
        scan_target: Some(1),
        scan_cursor: 0,
        scan_end: 0,
        exhausted: false,
      },
    );
    polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
      match Pallet::<T>::insert_dependency_scan_source(source) {
        Ok(_) => polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(Ok(())),
        Err(error) => {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(Err(error))
        }
      }
    })
    .map_err(|_| BenchmarkError::Stop("empty scan source did not enter selector"))?;
    let mut meter = polkadot_sdk::sp_weights::WeightMeter::with_limit(Weight::MAX);

    #[block]
    {
      Pallet::<T>::process_next_dependency_scan_unit(&mut meter)
        .expect("empty dependency scan completes")
        .expect("one source is active");
    }

    assert_eq!(DependencyScanSourceListState::<T>::get().count, 0);
    assert!(DependencyRevisions::<T>::get(source).scan_target.is_none());
    Ok(())
  }

  #[benchmark]
  fn complete_cycle_to_parked_balance() -> Result<(), BenchmarkError> {
    frame_system::Pallet::<T>::set_block_number(1u32.into());
    let owner_account: T::AccountId = account("complete-balance-park", 0, 0);
    Pallet::<T>::create_system_actor(
      RawOrigin::Root.into(),
      owner_account,
      Mutability::Mutable,
      system_contract::<T>(
        Schedule {
          trigger: Trigger::Manual,
          cooldown_blocks: 0,
        },
        make_inert_contract_steps::<T>(),
      ),
    )?;
    let actor_id = NextActorId::<T>::get().saturating_sub(1);
    let ActorSemanticState::Active(record) =
      ActorSemanticStates::<T>::get(actor_id).expect("benchmark Actor owns semantic state")
    else {
      panic!("benchmark Actor is active")
    };
    let actor = ActorRef {
      actor_id,
      generation: record.generation,
    };
    ActorControlLocators::<T>::remove(actor_id);
    ActorUnsignaledControlCells::<T>::remove(actor_id);
    ActorProcesses::<T>::remove(actor_id);
    Pallet::<T>::publish_service_member(actor, ServiceResidenceKind::Live, 1u32.into())
      .expect("benchmark Actor enters canonical Service");
    let maximum = T::MaxParkedBalanceWatches::get();
    let assets = T::BenchmarkHelper::setup_max_encoded_predicate_assets(
      &record.identity.sovereign_account,
      maximum,
    )
    .map_err(|_| BenchmarkError::Stop("host cannot prepare maximum parked-balance assets"))?;
    if maximum == 0 || assets.len() != maximum as usize {
      return Err(BenchmarkError::Stop(
        "host did not fill the maximum parked-balance watch set",
      ));
    }
    let rules = assets
      .into_iter()
      .map(|asset| ParkedBalanceRule {
        asset,
        authored_min_delta: T::AssetOps::minimum_balance(asset).max(One::one()),
      })
      .collect();
    let activation = ParkedBalanceActivationOf::<T>::try_from_rules(rules)
      .map_err(|_| BenchmarkError::Stop("maximum parked-balance plan is invalid"))?;

    #[block]
    {
      Pallet::<T>::transfer_service_member_to_parked_balance(
        actor,
        ServiceResidenceKind::Live,
        1,
        &activation,
        WakeupKey::Block(2u32.into()),
      )
      .expect("completion enters balance Park");
    }

    assert!(ParkedBalanceEpisodes::<T>::contains_key(actor_id));
    assert!(!ServiceNodes::<T>::contains_key(actor_id));
    Ok(())
  }

  #[benchmark]
  fn process_pending_parked_balance_event() -> Result<(), BenchmarkError> {
    let actor = prepare_due_parked_balance_review::<T>("pending-balance-event")?;
    let actor_id = actor.actor_id;
    let sovereign = Pallet::<T>::actor_identity(actor_id)
      .unwrap()
      .sovereign_account;
    let first = ParkedBalanceEpisodes::<T>::get(actor_id).unwrap().watches[0].asset;
    let threshold = T::AssetOps::minimum_balance(first)
      .max(One::one())
      .saturating_mul(100u32.into());
    T::AssetOps::mint(&sovereign, first, threshold)
      .map_err(|_| BenchmarkError::Stop("host cannot qualify parked-balance asset"))?;
    let source = BalanceDependencySources::<T>::get(first)
      .ok_or(BenchmarkError::Stop("balance source is missing"))?;
    if DependencyRevisions::<T>::get(source).revision == 0 {
      polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
        polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(
          Pallet::<T>::publish_balance_dependency_event(first),
        )
      })
      .map_err(|_| BenchmarkError::Stop("balance event publication failed"))?;
    }
    let target = DependencyRevisions::<T>::get(source).revision;
    polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
      let result = (|| {
        Pallet::<T>::process_dependency_scan_member(source, target, 0)?;
        Pallet::<T>::complete_dependency_scan(source, target, 1)?;
        Ok::<(), DependencyScanError>(())
      })();
      match result {
        Ok(()) => polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(Ok(())),
        Err(error) => {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(Err(error))
        }
      }
    })
    .map_err(|_| BenchmarkError::Stop("balance scan failed to publish Pending"))?;
    let expected = PendingDependencyEvents::<T>::get(actor_id)
      .ok_or(BenchmarkError::Stop("balance Pending event is missing"))?;
    let Some(ProcessResidence::Parked(evidence)) =
      ActorProcesses::<T>::get(actor_id).and_then(|process| process.residence)
    else {
      return Err(BenchmarkError::Stop(
        "benchmark Actor left Park prematurely",
      ));
    };
    let mut meter = polkadot_sdk::sp_weights::WeightMeter::with_limit(Weight::MAX);

    #[block]
    {
      Pallet::<T>::process_pending_parked_balance_event(
        &mut meter,
        expected,
        ServiceResidenceKind::Pending,
        evidence,
        1u32.into(),
        None,
      )
      .expect("qualified current balance wakes benchmark Actor");
    }

    assert!(!ParkedBalanceEpisodes::<T>::contains_key(actor_id));
    assert_eq!(
      ServiceNodes::<T>::get(actor_id).unwrap().kind,
      ServiceResidenceKind::Pending
    );
    assert!(
      Pallet::<T>::active_actor_state(actor_id)
        .unwrap()
        .hot
        .pending_signal
    );
    Ok(())
  }

  fn prepare_due_parked_balance_review<T: Config>(
    label: &'static str,
  ) -> Result<ActorRef, BenchmarkError> {
    frame_system::Pallet::<T>::set_block_number(0u32.into());
    let owner_account: T::AccountId = account(label, 0, 0);
    Pallet::<T>::create_system_actor(
      RawOrigin::Root.into(),
      owner_account,
      Mutability::Mutable,
      system_contract::<T>(
        Schedule {
          trigger: Trigger::Manual,
          cooldown_blocks: 0,
        },
        make_inert_contract_steps::<T>(),
      ),
    )?;
    let actor_id = NextActorId::<T>::get().saturating_sub(1);
    let ActorSemanticState::Active(record) =
      ActorSemanticStates::<T>::get(actor_id).expect("benchmark Actor owns semantic state")
    else {
      panic!("benchmark Actor is active")
    };
    let maximum = T::MaxParkedBalanceWatches::get();
    if maximum == 0 {
      return Err(BenchmarkError::Stop(
        "host cannot represent a parked-balance watch",
      ));
    }
    let assets = T::BenchmarkHelper::setup_max_encoded_predicate_assets(
      &record.identity.sovereign_account,
      maximum,
    )
    .map_err(|_| BenchmarkError::Stop("host cannot prepare maximum parked-balance assets"))?;
    if assets.len() != maximum as usize {
      return Err(BenchmarkError::Stop(
        "host did not fill the maximum parked-balance watch set",
      ));
    }
    let mut rules = Vec::with_capacity(assets.len());
    for asset in assets
      .iter(/* deos-bypass: bounded-iter -- MaxWhitelistSize benchmark fixture. */)
      .copied()
    {
      let amount = T::AssetOps::minimum_balance(asset).max(One::one());
      T::AssetOps::mint(&record.identity.sovereign_account, asset, amount)
        .map_err(|_| BenchmarkError::Stop("host cannot fund parked-balance asset"))?;
      rules.push(ParkedBalanceRule {
        asset,
        authored_min_delta: amount,
      });
    }
    let activation = ParkedBalanceActivationOf::<T>::try_from_rules(rules)
      .map_err(|_| BenchmarkError::Stop("maximum parked-balance plan is invalid"))?;
    let mut contract = system_contract::<T>(
      Schedule {
        trigger: Trigger::Manual,
        cooldown_blocks: 0,
      },
      make_inert_contract_steps::<T>(),
    )
    .ok_or(BenchmarkError::Stop(
      "parked balance requires an active Contract",
    ))?;
    contract.parked_balance_activation = Some(activation);
    frame_system::Pallet::<T>::set_block_number(1u32.into());
    Pallet::<T>::update_contract(RawOrigin::Root.into(), actor_id, contract)?;
    let actor = Pallet::<T>::load_actor_ref(actor_id).ok_or(BenchmarkError::Stop(
      "replacement did not retain Actor identity",
    ))?;
    if !ParkedBalanceEpisodes::<T>::contains_key(actor_id) {
      return Err(BenchmarkError::Stop("replacement did not arm balance Park"));
    }
    Ok(actor)
  }

  // Fixed corners cover class/causal, shared clocks, full bodies and joined Tick unlink owners.
  // Real committed Actions and maximum-length Contracts retain original full Close authority.
  #[benchmark(extra, pov_mode = Measured)]
  fn park_review_namespace_terminal(c: Linear<0, 21>) -> Result<(), BenchmarkError> {
    use polkadot_sdk::frame_support::traits::{fungible::MutateHold, tokens::Precision};
    let actor_type = if c == 1 || c == 3 {
      ActorType::System
    } else {
      ActorType::User
    };
    let causal = c == 2 || c == 3 || c == 5;
    let late = c == 4
      || c == 5
      || c == 7
      || c == 9
      || c == 11
      || c == 13
      || c == 15
      || c == 17
      || c == 19
      || c == 21;
    let interior_tick = c >= 20;
    let vacancy_neighbor = c >= 16;
    let vacancy_live: u8 = if c >= 18 { 31 } else { 1 };
    let retained_front = c >= 14;
    let address_header = (12..20).contains(&c);
    let shared_temporal = (6..12).contains(&c) || interior_tick;
    let shared_watches = c >= 6;
    let wide_deep = c >= 8;
    let full_body = c >= 10;
    let (owner, wide_header) = if wide_deep {
      let (owner, asset, trigger, funding) = large_header_fields::<T>();
      (owner, Some((asset, trigger, funding)))
    } else {
      (measured_account::<T>("park-terminal-owner", 0), None)
    };
    let recipient = measured_account::<T>("park-terminal-credit", 0);
    T::BenchmarkHelper::advance_to_scheduler_tick(2)?;
    ensure_creation_balance::<T>(&owner);
    let native = T::FeeNativeAssetId::get();
    let credit_asset = if full_body {
      wide_header.as_ref().unwrap().0
    } else {
      native
    };
    let amount = T::AssetOps::minimum_balance(credit_asset).max(One::one());
    T::AssetOps::mint(&recipient, credit_asset, amount).map_err(|failure| failure.error)?;
    let credit_before = T::AssetOps::balance(&recipient, credit_asset);
    let mut steps = if let Some((asset, ..)) = &wide_header {
      maximum_temporal_control_steps::<T>(*asset)?
    } else {
      make_max_contract_steps::<T>(recipient.clone())
    };
    if steps.len() < 3 {
      return Err(BenchmarkError::Stop(
        "Park terminal requires two economic Steps and authored StopCycle",
      ));
    }
    for (index, step) in steps.iter_mut().enumerate() {
      if full_body {
        if step.precondition.as_ref().map(|p| p.predicate_count())
          != Some(benchmark_predicate_capacity::<T>())
        {
          return Err(BenchmarkError::Stop(
            "host cannot admit the named full body payload",
          ));
        }
        step.task = ActorTask::Transfer {
          asset: credit_asset,
          amount: AmountResolution::Fixed(amount),
          to: recipient.clone(),
        };
        for predicate in step
          .precondition
          .as_mut()
          .unwrap()
          .clauses
          .iter_mut()
          .flat_map(|clause| clause.iter_mut())
        {
          let Predicate::ObservationAbove { max_age_blocks, .. } = predicate else {
            return Err(BenchmarkError::Stop(
              "full body requires prepared fresh Observation predicates",
            ));
          };
          // Fixed-width age keeps the admitted body width while spanning the actual full Q1 plan.
          *max_age_blocks = u32::MAX;
        }
      } else if !wide_deep || index < 3 {
        *step = Step {
          precondition: None,
          task: ActorTask::Transfer {
            to: recipient.clone(),
            asset: native,
            amount: AmountResolution::Fixed(amount),
          },
          on_error: StepErrorPolicy::AbortCycle,
        };
      } else {
        // Refuse an unsupported full-tail profile instead of relabeling admitted filler as maximum.
        if step.task.encoded_size() != TaskOf::<T>::max_encoded_len()
          || step.precondition.as_ref().map(|p| p.predicate_count())
            != Some(benchmark_predicate_capacity::<T>())
        {
          return Err(BenchmarkError::Stop(
            "host cannot admit the named full tail payload",
          ));
        }
      }
    }
    if !full_body {
      steps[2].task = ActorTask::StopCycle;
    }
    let action_count = if full_body { steps.len() as u32 } else { 2 };
    let credit_after = credit_before
      .checked_add(
        &amount
          .checked_mul(&action_count.into())
          .ok_or(BenchmarkError::Stop("committed full-plan credit overflows"))?,
      )
      .ok_or(BenchmarkError::Stop(
        "recipient full-plan balance overflows",
      ))?;
    let mut activation = maximum_parked_balance_activation::<T>(&owner)?;
    for rule in &mut activation.watches {
      rule.authored_min_delta = rule
        .authored_min_delta
        .checked_add(&rule.authored_min_delta)
        .ok_or(BenchmarkError::Stop(
          "subthreshold causal witness overflows",
        ))?;
    }
    let causal_asset = activation.watches[0].asset;
    let watch_assets = activation
      .watches
      .iter()
      .map(|rule| rule.asset)
      .collect::<Vec<_>>();
    let watch_count = activation.watches.len();
    let mut contract = user_contract::<T>(
      Schedule {
        trigger: if address_header {
          wide_header.as_ref().unwrap().1.clone()
        } else {
          Trigger::manual()
        },
        cooldown_blocks: 0,
      },
      steps.clone(),
    )
    .unwrap();
    contract.parked_balance_activation = Some(activation);
    if let Some((_, _, funding)) = wide_header {
      assert_eq!(
        funding.encoded_size(),
        FundingSourcePolicyOf::<T>::max_encoded_len()
      );
      contract.funding = funding;
    }
    let first = T::MinWindowLength::get()
      .checked_add(&1u32.into())
      .ok_or(BenchmarkError::Stop(
        "public window guards require Block space",
      ))?;
    if address_header {
      assert_eq!(
        contract.trigger.encoded_size(),
        TriggerOf::<T>::max_encoded_len()
      );
      contract.window = Some(ScheduleWindow {
        start: first,
        end: first
          .checked_add(&T::MaxExecutionDelayBlocks::get())
          .ok_or(BenchmarkError::Stop(
            "AddressEvent window requires Block space",
          ))?,
      });
      assert_eq!(
        contract.window.unwrap().encoded_size(),
        ScheduleWindow::<BlockNumberFor<T>>::max_encoded_len()
      );
    }
    frame_system::Pallet::<T>::set_block_number(first);
    let hold_reason: T::RuntimeHoldReason = HoldReason::ActorState.into();
    let owner_hold_before = T::StateHoldCurrency::balance_on_hold(&hold_reason, &owner);
    let owner_slots_before = OwnerSlotBitmaps::<T>::get(&owner);
    if actor_type == ActorType::User {
      prefund_active_user_creation::<T>(&owner, &steps);
      Pallet::<T>::create_user_actor(
        RawOrigin::Signed(owner.clone()).into(),
        Mutability::Mutable,
        Some(contract),
      )?;
    } else {
      Pallet::<T>::create_system_actor(
        RawOrigin::Root.into(),
        owner.clone(),
        Mutability::Mutable,
        Some(contract),
      )?;
    }
    let actor_id = NextActorId::<T>::get() - 1;
    let mut actor = Pallet::<T>::load_actor_ref(actor_id).unwrap();
    let identity = Pallet::<T>::actor_identity(actor_id).unwrap();
    if wide_deep {
      let stored = Pallet::<T>::load_actor_contract(actor_id).unwrap();
      assert_eq!(
        stored.funding.encoded_size(),
        FundingSourcePolicyOf::<T>::max_encoded_len()
      );
      if address_header {
        assert_eq!(
          stored.trigger.encoded_size(),
          TriggerOf::<T>::max_encoded_len()
        );
        assert_eq!(
          stored.window.unwrap().encoded_size(),
          ScheduleWindow::<BlockNumberFor<T>>::max_encoded_len()
        );
        assert!(!TriggerDeadlineHandles::<T>::contains_key(actor_id));
      }
      for step in stored.steps.iter().skip(if full_body { 0 } else { 3 }) {
        if full_body {
          assert!(step.task.encoded_size() <= TaskOf::<T>::max_encoded_len());
        } else {
          assert_eq!(step.task.encoded_size(), TaskOf::<T>::max_encoded_len());
        }
        let precondition = step.precondition.as_ref().unwrap();
        assert_eq!(
          precondition.predicate_count(),
          benchmark_predicate_capacity::<T>()
        );
        for predicate in precondition.clauses.iter().flat_map(|clause| clause.iter()) {
          assert_eq!(
            predicate.encoded_size(),
            Predicate::<T::AssetId, T::Balance, BlockNumberFor<T>, T::ObservationFeedId>::max_encoded_len()
          );
        }
      }
    }
    T::AssetOps::mint(
      &identity.sovereign_account,
      native,
      (u64::MAX / 4).saturated_into(),
    )
    .map_err(|failure| failure.error)?;
    if full_body {
      let ActorTask::Transfer {
        amount: AmountResolution::Fixed(input),
        ..
      } = &steps[0].task
      else {
        unreachable!()
      };
      // Ordinary authored spend retains the protected minimum even for a non-native asset.
      let balance = input
        .checked_mul(&action_count.into())
        .and_then(|total| total.checked_add(&T::AssetOps::minimum_balance(credit_asset)))
        .ok_or(BenchmarkError::Stop("complete plan funding overflows"))?;
      if address_header {
        assert!(
          !benchmark_fixture_semantic_hot::<T>(actor_id)
            .unwrap()
            .pending_signal
        );
        assert!(!ServiceNodes::<T>::contains_key(actor_id));
        T::AssetOps::mint(&owner, credit_asset, balance).map_err(|failure| failure.error)?;
        let before = T::AssetOps::balance(&identity.sovereign_account, credit_asset);
        T::BenchmarkHelper::transfer_signed(
          &owner,
          &identity.sovereign_account,
          credit_asset,
          balance,
        )?;
        assert_eq!(
          T::AssetOps::balance(&identity.sovereign_account, credit_asset),
          before + balance
        );
        assert_canonical_ingress_readiness::<T>(actor_id);
      } else {
        T::AssetOps::mint(&identity.sovereign_account, credit_asset, balance)
          .map_err(|failure| failure.error)?;
      }
    }
    if !address_header {
      Pallet::<T>::manual_trigger(RawOrigin::Signed(owner.clone()).into(), actor_id)
        .map_err(|failure| failure.error)?;
    }
    let opening = ServiceNodes::<T>::get(actor_id)
      .expect("real occurrence publishes B+1 Service readiness")
      .eligible_from;
    let mut tick_guards = Vec::new();
    let mut tick_members = Vec::new();
    if interior_tick {
      let due = Pallet::<T>::current_scheduler_tick()
        .map_err(|_| BenchmarkError::Stop("joined Tick needs actual clock authority"))?
        .checked_add(1_000)
        .ok_or(BenchmarkError::Stop("joined Tick needs rearm space"))?;
      let key = WakeupKey::Tick(due);
      let keys = DeadlineIndexLen::<T>::get(WakeupClock::Tick);
      if keys > 47
        || DeadlineHeaders::<T>::contains_key(key)
        || DeadlineIndexPages::<T>::iter_prefix(WakeupClock::Tick)
          .flat_map(|(_, page)| page.into_iter())
          .any(|existing| existing >= key)
      {
        return Err(BenchmarkError::Stop(
          "host cannot admit the named joined Tick prefix",
        ));
      }
      for offset in 0..47 - keys {
        let smaller = WakeupKey::Tick(due - 500 + u64::from(offset));
        if DeadlineHeaders::<T>::contains_key(smaller) {
          return Err(BenchmarkError::Stop(
            "host occupies the named joined Tick guard key",
          ));
        }
        tick_guards.push(create_close_deadline_guard::<T>(70_000 + offset, smaller)?);
      }
      for seed in 0..96 {
        tick_members.push(create_close_deadline_guard::<T>(71_000 + seed, key)?);
      }
      assert_eq!(DeadlineIndexPositions::<T>::get(key), Some(47));
    }
    for offset in 0u32..if full_body { action_count } else { 3 } {
      let now = opening
        .checked_add(&offset.into())
        .ok_or(BenchmarkError::Stop(
          "committed prefix requires Block space",
        ))?;
      frame_system::Pallet::<T>::set_block_number(now);
      Pallet::<T>::execute_cycle(Weight::MAX);
      if full_body {
        assert_eq!(
          T::AssetOps::balance(&recipient, credit_asset),
          credit_before + amount * (offset + 1).into()
        );
        if offset + 1 < action_count {
          let run =
            ActorRunStateStore::<T>::get(actor_id).expect("full plan retains its next Step");
          assert_eq!(run.cursor, offset + 1);
          assert_eq!(
            run.cumulative_outcomes,
            OutcomeTotals {
              executed_steps: offset + 1,
              committed_effectful_tasks: offset + 1,
              ..OutcomeTotals::default()
            }
          );
        }
      }
    }
    assert_eq!(T::AssetOps::balance(&recipient, credit_asset), credit_after);
    if shared_temporal {
      // Preserve a committed Manual Cycle, then install an unconsumed one-shot with the same plan.
      // Cadenced/ParkedBalance is forbidden; ordinary replacement supplies both clock owners.
      let mut replacement = Pallet::<T>::load_actor_contract(actor_id).unwrap();
      let after_ticks = if interior_tick {
        let WakeupKey::Tick(due) = TriggerDeadlineHandles::<T>::get(tick_members[0])
          .unwrap()
          .key
        else {
          unreachable!()
        };
        due
          .checked_sub(Pallet::<T>::current_scheduler_tick().unwrap())
          .ok_or(BenchmarkError::Stop(
            "joined one-shot must remain in the future",
          ))?
      } else {
        12
      };
      replacement.trigger = Trigger::at_time(after_ticks);
      Pallet::<T>::update_contract(
        RawOrigin::Signed(owner.clone()).into(),
        actor_id,
        replacement,
      )?;
      actor = Pallet::<T>::load_actor_ref(actor_id).unwrap();
      if interior_tick {
        let handle = TriggerDeadlineHandles::<T>::get(actor_id).unwrap();
        if (handle.page, handle.slot) != (3, 0)
          || DeadlineIndexPositions::<T>::get(handle.key) != Some(47)
        {
          return Err(BenchmarkError::Stop(
            "host replacement cannot retain the named joined Tick geometry",
          ));
        }
        tick_members.push(actor_id);
        for seed in 0..191 {
          tick_members.push(create_close_deadline_guard::<T>(72_000 + seed, handle.key)?);
        }
        let WakeupKey::Tick(due) = handle.key else {
          unreachable!()
        };
        for offset in 1..=80 {
          tick_guards.push(create_close_deadline_guard::<T>(
            73_000 + offset,
            WakeupKey::Tick(due + u64::from(offset)),
          )?);
        }
        assert_eq!(DeadlineIndexLen::<T>::get(WakeupClock::Tick), 128);
        for page in 0..4 {
          assert_eq!(
            DeadlineIndexPages::<T>::get(WakeupClock::Tick, page)
              .unwrap()
              .len(),
            32
          );
        }
      }
    }
    let identity = Pallet::<T>::actor_identity(actor_id).unwrap();
    assert_eq!(identity.cycle_nonce, 1);
    assert!(ActorRunStateStore::<T>::get(actor_id).is_none());
    assert_eq!(
      assert_contract_geometry_encoding::<T>(actor_id),
      T::MaxContractSteps::get()
    );
    assert_eq!(
      ParkedBalanceEpisodes::<T>::get(actor_id)
        .unwrap()
        .watches
        .len(),
      watch_count
    );
    let front_guards = if retained_front {
      let handle = DeadlineHandles::<T>::get(actor_id).unwrap();
      let WakeupKey::Block(due) = handle.key else {
        unreachable!()
      };
      if due <= frame_system::Pallet::<T>::block_number() {
        return Err(BenchmarkError::Stop(
          "retained front guards require a real future review",
        ));
      }
      let header = DeadlineHeaders::<T>::get(handle.key).unwrap();
      let page = DeadlinePages::<T>::get(handle.key, header.first_page).unwrap();
      assert_eq!(handle.page, header.first_page);
      assert_eq!(page.entries.iter().find_map(|entry| *entry), Some(actor));
      if page.live_entries != 1 {
        return Err(BenchmarkError::Stop(
          "retained front profile requires the original source-only page",
        ));
      }
      let guards = (0..31 + u32::from(vacancy_neighbor) * u32::from(vacancy_live))
        .map(|seed| create_close_deadline_guard::<T>(62_000 + seed, handle.key))
        .collect::<Result<Vec<_>, _>>()?;
      assert_eq!(
        DeadlinePages::<T>::get(handle.key, handle.page)
          .unwrap()
          .live_entries,
        32
      );
      if vacancy_neighbor {
        let header = DeadlineHeaders::<T>::get(handle.key).unwrap();
        let tail = DeadlineHandles::<T>::get(*guards.last().unwrap()).unwrap();
        let front = DeadlinePages::<T>::get(handle.key, handle.page).unwrap();
        let page = DeadlinePages::<T>::get(handle.key, tail.page).unwrap();
        assert_ne!(tail.page, handle.page);
        assert_eq!(
          (header.count, header.page_count),
          (32 + u32::from(vacancy_live), 2)
        );
        assert_eq!(header.first_vacant_page, Some(tail.page));
        assert_eq!(front.next_page, Some(tail.page));
        assert_eq!(page.previous_page, Some(handle.page));
        assert!(page.next_page.is_none());
        assert!(page.previous_vacant_page.is_none() && page.next_vacant_page.is_none());
        assert_eq!(
          page.entries[tail.slot as usize],
          Pallet::<T>::load_actor_ref(*guards.last().unwrap())
        );
        assert_close_deadline_page_width(&page, vacancy_live, 3);
      }
      guards
        .into_iter()
        .map(|id| (id, parked_close_peer_snapshot::<T>(id)))
        .collect::<Vec<_>>()
    } else {
      Vec::new()
    };
    let shared_peers = if shared_watches {
      populate_shared_parked_balance_peers::<T>(actor_id)?
    } else {
      Vec::new()
    };
    let shared_authority = shared_peers
      .iter()
      .map(|peer| (*peer, parked_close_peer_snapshot::<T>(*peer)))
      .collect::<Vec<_>>();
    let registrations = if shared_watches {
      DependencyPlans::<T>::get(actor_id)
        .into_iter()
        .map(|entry| {
          let position = DependencyRegistrationPositions::<T>::get(entry.source, actor_id)
            .expect("target owns its shared registration position");
          let page = DependencyRegistrationPages::<T>::get(entry.source, position.page)
            .expect("target shared registration page exists");
          assert_eq!(page.entries.len(), 32);
          assert!(page.entries.iter().all(Option::is_some));
          assert_eq!(
            page.encoded_size(),
            DependencyRegistrationPage::max_encoded_len()
              - usize::from(page.previous.is_none()) * 8
              - usize::from(page.next.is_none()) * 8
          );
          assert_eq!(page.entries[position.slot as usize], Some(entry.handle));
          (
            entry.source,
            position,
            page,
            DependencyRegistrationHeaders::<T>::get(entry.source),
          )
        })
        .collect::<Vec<_>>()
    } else {
      Vec::new()
    };
    if interior_tick {
      assert_eq!(tick_members.len(), 288);
      for index in [32, 160].into_iter().chain(97..128).chain([192, 224]) {
        let guard = tick_members[index];
        let state = Pallet::<T>::active_actor_state(guard).unwrap();
        let guard_ref = Pallet::<T>::load_actor_ref(guard).unwrap();
        let identity = Pallet::<T>::actor_identity(guard).unwrap();
        let hold = ActorStateHolds::<T>::get(guard);
        let balance = T::AssetOps::balance(&identity.sovereign_account, native);
        Pallet::<T>::pause_actor(RawOrigin::Root.into(), guard)?;
        let paused = Pallet::<T>::active_actor_state(guard).unwrap();
        assert_eq!(paused.contract.encode(), state.contract.encode());
        assert_eq!(
          paused.hot.trigger_runtime_state,
          state.hot.trigger_runtime_state
        );
        assert_eq!(ActorStateHolds::<T>::get(guard), hold);
        assert_eq!(
          T::AssetOps::balance(&identity.sovereign_account, native),
          balance
        );
        assert_eq!(Pallet::<T>::load_actor_ref(guard), Some(guard_ref));
        assert!(!TriggerDeadlineHandles::<T>::contains_key(guard));
      }
      tick_guards.extend(tick_members.into_iter().filter(|id| *id != actor_id));
    }
    let tick_guard_authority = tick_guards
      .into_iter()
      .map(|id| {
        (
          id,
          Pallet::<T>::actor_identity(id).unwrap().encode(),
          parked_close_peer_snapshot::<T>(id),
        )
      })
      .collect::<Vec<_>>();
    let tick = TriggerDeadlineHandles::<T>::get(actor_id);
    assert_eq!(tick.is_some(), shared_temporal);
    let tick_header = tick.map(|handle| DeadlineHeaders::<T>::get(handle.key).unwrap());
    let joined_tick_geometry = if interior_tick {
      let handle = tick.unwrap();
      let header = tick_header.unwrap();
      assert_eq!(
        (header.count, header.page_count, header.first_vacant_page),
        (253, 9, Some(7))
      );
      let page = DeadlinePages::<T>::get(handle.key, handle.page).unwrap();
      assert_eq!((page.previous_page, page.next_page), (Some(2), Some(4)));
      assert_eq!(
        (page.previous_vacant_page, page.next_vacant_page),
        (Some(6), Some(5))
      );
      assert_close_deadline_page_width(&page, 1, 0);
      for neighbor in [2, 4] {
        assert_close_deadline_page_width(
          &DeadlinePages::<T>::get(handle.key, neighbor).unwrap(),
          32,
          2,
        );
      }
      for neighbor in [5, 6] {
        assert_close_deadline_page_width(
          &DeadlinePages::<T>::get(handle.key, neighbor).unwrap(),
          31,
          0,
        );
      }
      let mut expected_header = header;
      let mut pages = DeadlinePages::<T>::iter_prefix(handle.key).collect::<Vec<_>>();
      if !late {
        expected_header.count -= 1;
        expected_header.page_count -= 1;
        pages.retain(|(id, _)| *id != handle.page);
        for (id, page) in &mut pages {
          match *id {
            2 => page.next_page = Some(4),
            4 => page.previous_page = Some(2),
            6 => page.next_vacant_page = Some(5),
            5 => page.previous_vacant_page = Some(6),
            _ => {}
          }
        }
      }
      Some(capture_close_deadline_fixture::<T>(
        CloseDeadlineOwner::Trigger,
        actor,
        Some(expected_header),
        pages,
        close_deadline_index_snapshot::<T>(WakeupClock::Tick),
        Vec::new(),
      ))
    } else {
      None
    };
    let source =
      DeadlineHandles::<T>::get(actor_id).expect("public Cycle enters timed balance Park");
    let WakeupKey::Block(due) = source.key else {
      return Err(BenchmarkError::Stop(
        "balance review must own a Block deadline",
      ));
    };
    let front_snapshot = if retained_front {
      let header = DeadlineHeaders::<T>::get(source.key).unwrap();
      let page = DeadlinePages::<T>::get(source.key, source.page).unwrap();
      assert_eq!(header.first_page, source.page);
      assert!(page.previous_page.is_none());
      assert_eq!(page.entries.iter().find_map(|entry| *entry), Some(actor));
      assert_eq!(page.live_entries, 32);
      assert_close_deadline_page_width(&page, 32, 4 - usize::from(page.next_page.is_some()));
      assert!(page.previous_vacant_page.is_none() && page.next_vacant_page.is_none());
      let vacancy = header
        .first_vacant_page
        .map(|id| (id, DeadlinePages::<T>::get(source.key, id).unwrap()));
      if vacancy_neighbor {
        let (id, neighbor) = vacancy
          .as_ref()
          .expect("named profile retains a distinct vacancy head");
        assert_ne!(*id, source.page);
        assert_eq!(
          (header.count, header.page_count),
          (32 + u32::from(vacancy_live), 2)
        );
        assert_eq!(page.next_page, Some(*id));
        assert_eq!(neighbor.previous_page, Some(source.page));
        assert!(neighbor.next_page.is_none());
        assert!(neighbor.previous_vacant_page.is_none() && neighbor.next_vacant_page.is_none());
        assert_close_deadline_page_width(neighbor, vacancy_live, 3);
      }
      Some((header, page, vacancy))
    } else {
      None
    };
    let now = frame_system::Pallet::<T>::block_number().max(due);
    let mut future = WakeupKey::Block(
      now
        .checked_add(&1u32.into())
        .ok_or(BenchmarkError::Stop("future review requires Block space"))?,
    );
    // Peer completion may span several Q1 rounds; keep real clocks and choose an unused bucket.
    for _ in 0..=ActiveActorCount::<T>::get() {
      if !DeadlineHeaders::<T>::contains_key(future) {
        break;
      }
      future = next_close_deadline_key::<T>(future)?;
    }
    assert!(!DeadlineHeaders::<T>::contains_key(future));
    let peers = (0..32)
      .map(|seed| create_close_deadline_guard::<T>(63_000 + seed, future))
      .collect::<Result<Vec<_>, _>>()?;
    let mut destination_header = DeadlineHeaders::<T>::get(future).unwrap();
    assert_eq!(
      (
        destination_header.count,
        destination_header.page_count,
        destination_header.first_vacant_page
      ),
      (32, 1, None)
    );
    // Synthetic historical endpoint only; public peers and the complete source are not fabricated.
    destination_header.next_page = u64::MAX;
    DeadlineHeaders::<T>::insert(future, destination_header);
    let destination_page = DeadlinePages::<T>::get(future, 0).unwrap();
    let peer_authority = peers
      .iter()
      .map(|id| {
        (
          *id,
          ActorSemanticStates::<T>::get(id).encode(),
          DeadlineHandles::<T>::get(id),
        )
      })
      .collect::<Vec<_>>();
    if causal {
      let delta = T::AssetOps::minimum_balance(causal_asset).max(One::one());
      T::AssetOps::mint(&identity.sovereign_account, causal_asset, delta)
        .map_err(|failure| failure.error)?;
      if !PendingDependencyEvents::<T>::contains_key(actor_id) {
        polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
          let result = <Pallet<T> as BalanceTransitionIngress<T::AssetId>>::note_balance_transition(
            causal_asset,
          );
          polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(result)
        })?;
        let mut scan = polkadot_sdk::sp_weights::WeightMeter::with_limit(Weight::MAX);
        for _ in 0..2 {
          Pallet::<T>::process_next_dependency_scan_unit(&mut scan)
            .map_err(|_| BenchmarkError::Stop("causal source scan must complete"))?;
        }
      }
      assert!(PendingDependencyEvents::<T>::contains_key(actor_id));
    }
    let mut deep_counts = Vec::new();
    if wide_deep {
      if shared_temporal && !interior_tick {
        let room = (Pallet::<T>::effective_active_actor_limit() - ActiveActorCount::<T>::get())
          .min(T::MaxActorIdentities::get() - ActorIdentityCount::<T>::get())
          .min(T::MaxSystemSovereigns::get() - SystemSovereignCount::<T>::get());
        let before = DeadlineIndexLen::<T>::get(WakeupClock::Tick);
        let half = room / 2;
        if half <= 96 {
          return Err(BenchmarkError::Stop(
            "deep joint fixture requires public population room",
          ));
        }
        let guards = half - (before + half - 1) % 32;
        for index in 0..guards {
          Pallet::<T>::create_system_actor(
            RawOrigin::Root.into(),
            account("park-terminal-deep-tick-guard", index, 0),
            Mutability::Mutable,
            system_contract::<T>(
              Schedule {
                trigger: Trigger::cadenced(1_000 + u64::from(index)),
                cooldown_blocks: 0,
              },
              make_inert_contract_steps::<T>(),
            ),
          )?;
        }
        let keys = DeadlineIndexLen::<T>::get(WakeupClock::Tick);
        assert_eq!(DeadlineIndexPositions::<T>::get(tick.unwrap().key), Some(0));
        deep_counts.push((WakeupClock::Tick, keys));
      }
      let keys = populate_canonical_deadline_index_with_tail::<T>(now, true);
      assert_eq!(DeadlineIndexPositions::<T>::get(source.key), Some(0));
      deep_counts.push((WakeupClock::Block, keys));
      for &(clock, keys) in &deep_counts {
        assert!(keys > 64);
        assert_eq!(keys % 32, 1);
        assert_eq!(
          DeadlineIndexPages::<T>::get(clock, u64::from(keys / 32))
            .unwrap()
            .len(),
          1
        );
      }
    }
    let retained_block_index =
      retained_front.then(|| close_deadline_index_snapshot::<T>(WakeupClock::Block));
    let untouched_tick_index =
      address_header.then(|| close_deadline_index_snapshot::<T>(WakeupClock::Tick));
    let deep_handles = if wide_deep {
      (
        DeadlineHandles::<T>::iter()
          .filter(|(id, _)| *id != actor_id)
          .collect::<Vec<_>>(),
        TriggerDeadlineHandles::<T>::iter()
          .filter(|(id, _)| *id != actor_id)
          .collect::<Vec<_>>(),
      )
    } else {
      (Vec::new(), Vec::new())
    };
    frame_system::Pallet::<T>::set_block_number(now);
    assert_eq!(
      Pallet::<T>::classify_next_due_block_deadline(now),
      Ok(DueBlockDeadlineBranch::Review(actor))
    );
    assert_measured_actor_accounts::<T>(&[actor_id]);
    #[cfg(feature = "try-runtime")]
    Pallet::<T>::do_try_state()
      .expect("public prefix, full Contract and Park registrations are canonical");
    let mut assets = watch_assets;
    assets.push(native);
    if full_body {
      assets.push(credit_asset);
    }
    let fixture = CloseDestructionFixture {
      actor_id,
      identity: identity.clone(),
      balances: assets
        .into_iter()
        .map(|asset| {
          (
            asset,
            T::AssetOps::balance(&identity.sovereign_account, asset),
          )
        })
        .collect(),
      owner_hold_after: owner_hold_before,
      owner_slots_after: owner_slots_before,
      active_count_after: ActiveActorCount::<T>::get() - 1,
      identity_count_after: ActorIdentityCount::<T>::get() - 1,
      sink_balance: T::AssetOps::balance(&T::FeeSink::get(), native),
      committed_credit: Some((recipient, credit_asset, credit_after)),
    };
    if late {
      assert!(T::StateHoldCurrency::balance_on_hold(&hold_reason, &owner) > One::one());
      T::StateHoldCurrency::release(&hold_reason, &owner, One::one(), Precision::Exact)?;
      assert!(matches!(
        Pallet::<T>::load_actor_state(actor_id),
        LoadedActorStateOf::Active(_)
      ));
    }
    let original = Pallet::<T>::active_actor_state(actor_id).unwrap().encode();
    let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    let mut meter = polkadot_sdk::sp_weights::WeightMeter::with_limit(
      Pallet::<T>::due_dependency_review_weight_upper(),
    );
    let result;
    #[block]
    {
      result = Pallet::<T>::process_next_due_block_dependency_review(
        &mut meter,
        ServiceResidenceKind::Pending,
        now,
        Some(future),
      );
    }
    assert_eq!(
      meter.consumed(),
      Pallet::<T>::due_dependency_review_weight_upper()
    );
    if late {
      assert_eq!(result, Err(DependencyReviewWorkerError::TerminalCleanup));
      assert_eq!(
        polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
        root
      );
      assert_eq!(
        Pallet::<T>::active_actor_state(actor_id).unwrap().encode(),
        original
      );
      for &(asset, balance) in &fixture.balances {
        assert_eq!(
          T::AssetOps::balance(&identity.sovereign_account, asset),
          balance
        );
      }
      assert_eq!(
        T::AssetOps::balance(&T::FeeSink::get(), native),
        fixture.sink_balance
      );
      let (recipient, asset, balance) = fixture.committed_credit.as_ref().unwrap();
      assert_eq!(T::AssetOps::balance(recipient, *asset), *balance);
    } else {
      assert_eq!(result, Ok((actor, DependencyReviewMutation::Closed)));
      frame_system::Pallet::<T>::assert_last_event(
        Event::<T>::ActorClosed {
          actor_id,
          reason: CloseReason::SchedulerIndexExhausted,
        }
        .into(),
      );
      assert_close_destruction::<T>(&fixture);
      assert!(!ParkedBalanceEpisodes::<T>::contains_key(actor_id));
      assert!(!PendingCheckOwners::<T>::contains_key(actor_id));
      assert!(!PendingDependencyEvents::<T>::contains_key(actor_id));
      assert!(!PendingDependencyReviews::<T>::contains_key(actor_id));
      assert!(DependencyPlans::<T>::get(actor_id).is_empty());
      assert!(!DependencyTimedReviews::<T>::contains_key(actor_id));
      #[cfg(feature = "try-runtime")]
      Pallet::<T>::do_try_state().expect("namespace destructor preserves full peer authority");
    }
    if shared_watches {
      assert_eq!(registrations.len(), watch_count);
      if let Some(handle) = tick {
        if late {
          assert_eq!(TriggerDeadlineHandles::<T>::get(actor_id), Some(handle));
          assert_eq!(DeadlineHeaders::<T>::get(handle.key), tick_header);
        } else if !interior_tick {
          assert!(!TriggerDeadlineHandles::<T>::contains_key(actor_id));
          assert!(!DeadlineHeaders::<T>::contains_key(handle.key));
        }
      } else {
        assert!(!TriggerDeadlineHandles::<T>::contains_key(actor_id));
      }
      for (source, position, mut page, mut header) in registrations {
        if !late {
          page.entries[position.slot as usize] = None;
          assert_eq!(
            DependencyRegistrationFreePositions::<T>::get(source, header.free_count),
            Some(position)
          );
          header.count -= 1;
          header.free_count += 1;
          assert!(!DependencyRegistrations::<T>::contains_key(
            source, actor_id
          ));
          assert!(!DependencyRegistrationPositions::<T>::contains_key(
            source, actor_id
          ));
        }
        assert_eq!(
          DependencyRegistrationPages::<T>::get(source, position.page),
          Some(page)
        );
        assert_eq!(DependencyRegistrationHeaders::<T>::get(source), header);
      }
      for (peer, snapshot) in shared_authority {
        assert_eq!(parked_close_peer_snapshot::<T>(peer), snapshot);
      }
    }
    if wide_deep {
      for (clock, keys) in deep_counts {
        let removed = !late && !(retained_front && clock == WakeupClock::Block);
        assert_eq!(DeadlineIndexLen::<T>::get(clock), keys - u32::from(removed));
        assert_eq!(
          DeadlineIndexPages::<T>::contains_key(clock, u64::from(keys / 32)),
          !removed
        );
        assert_deadline_clock_indices::<T>(clock);
      }
      for (id, handle) in deep_handles.0 {
        assert_eq!(DeadlineHandles::<T>::get(id), Some(handle));
      }
      for (id, handle) in deep_handles.1 {
        assert_eq!(TriggerDeadlineHandles::<T>::get(id), Some(handle));
      }
    }
    if let Some((mut header, mut page, vacancy)) = front_snapshot {
      if !late {
        page.entries[source.slot as usize] = None;
        page.live_entries -= 1;
        page.previous_vacant_page = None;
        page.next_vacant_page = header.first_vacant_page;
        header.first_vacant_page = Some(source.page);
        header.count -= 1;
        assert!(!DeadlineHandles::<T>::contains_key(actor_id));
      }
      assert_eq!(DeadlineHeaders::<T>::get(source.key), Some(header));
      assert_eq!(DeadlinePages::<T>::get(source.key, source.page), Some(page));
      if let Some((id, mut page)) = vacancy {
        if !late {
          page.previous_vacant_page = Some(source.page);
        }
        assert_eq!(DeadlinePages::<T>::get(source.key, id), Some(page));
      }
      assert_eq!(
        close_deadline_index_snapshot::<T>(WakeupClock::Block),
        retained_block_index.unwrap()
      );
      for (id, snapshot) in front_guards {
        assert_eq!(parked_close_peer_snapshot::<T>(id), snapshot);
      }
    }
    if let Some(snapshot) = untouched_tick_index {
      assert_eq!(
        close_deadline_index_snapshot::<T>(WakeupClock::Tick),
        snapshot
      );
    }
    if let Some(joined) = joined_tick_geometry {
      assert_eq!(
        DeadlineHeaders::<T>::get(joined.handle.key),
        joined.expected_header
      );
      assert_eq!(
        DeadlinePages::<T>::iter_prefix(joined.handle.key).count(),
        joined.expected_pages.len()
      );
      for (id, page) in joined.expected_pages {
        assert_eq!(DeadlinePages::<T>::get(joined.handle.key, id), Some(page));
      }
      assert_eq!(
        close_deadline_index_snapshot::<T>(WakeupClock::Tick),
        joined.expected_index
      );
      assert_eq!(
        TriggerDeadlineHandles::<T>::get(actor_id),
        late.then_some(joined.handle)
      );
      for (id, identity, snapshot) in tick_guard_authority {
        assert_eq!(Pallet::<T>::actor_identity(id).unwrap().encode(), identity);
        assert_eq!(parked_close_peer_snapshot::<T>(id), snapshot);
      }
    }
    assert_eq!(DeadlineHeaders::<T>::get(future), Some(destination_header));
    assert_eq!(DeadlinePages::<T>::get(future, 0), Some(destination_page));
    for (id, semantic, handle) in peer_authority {
      assert_eq!(ActorSemanticStates::<T>::get(id).encode(), semantic);
      assert_eq!(DeadlineHandles::<T>::get(id), handle);
    }
    Ok(())
  }

  /// Rearm the unchanged maximum watch plan while deleting a source page with distinct physical
  /// and vacancy neighbors and filling a populated destination vacancy head.
  #[benchmark]
  fn process_due_parked_balance_review() -> Result<(), BenchmarkError> {
    let actor = prepare_due_parked_balance_review::<T>("due-balance-review")?;
    prepare_deadline_removal_neighbors::<T>(actor);
    prepare_deadline_destination_vacancy::<T>(3u32.into());
    frame_system::Pallet::<T>::set_block_number(2u32.into());
    let source = DeadlineHandles::<T>::get(actor.actor_id).unwrap();
    let mut meter = polkadot_sdk::sp_weights::WeightMeter::with_limit(Weight::MAX);

    #[block]
    {
      Pallet::<T>::process_next_due_block_dependency_review(
        &mut meter,
        ServiceResidenceKind::Live,
        2u32.into(),
        Some(WakeupKey::Block(3u32.into())),
      )
      .expect("unchanged maximum balance plan re-arms benchmark Actor");
    }

    assert!(ParkedBalanceEpisodes::<T>::contains_key(actor.actor_id));
    assert!(!DeadlinePages::<T>::contains_key(source.key, source.page));
    assert_eq!(DeadlineHeaders::<T>::get(source.key).unwrap().count, 96);
    let destination = DeadlineHandles::<T>::get(actor.actor_id).unwrap();
    assert_eq!(
      (destination.key, destination.page, destination.slot),
      (WakeupKey::Block(3u32.into()), 0, 31)
    );
    assert_eq!(
      DeadlineHeaders::<T>::get(destination.key).unwrap().count,
      33
    );
    assert_deadline_clock_indices::<T>(WakeupClock::Block);
    Ok(())
  }

  /// Rearm the same maximum watch plan while deleting the minimum singleton key from the fullest
  /// reachable Block index and inserting the new minimum destination key.
  #[benchmark]
  fn process_due_parked_balance_review_deep_index() -> Result<(), BenchmarkError> {
    let actor = prepare_due_parked_balance_review::<T>("due-balance-review-index")?;
    let source = DeadlineHandles::<T>::get(actor.actor_id).unwrap();
    let keys = populate_canonical_deadline_index::<T>(3u32.into());
    frame_system::Pallet::<T>::set_block_number(2u32.into());
    let mut meter = polkadot_sdk::sp_weights::WeightMeter::with_limit(Weight::MAX);

    #[block]
    {
      Pallet::<T>::process_next_due_block_dependency_review(
        &mut meter,
        ServiceResidenceKind::Live,
        2u32.into(),
        Some(WakeupKey::Block(3u32.into())),
      )
      .expect("maximum balance plan replaces the deep-index minimum");
    }

    assert!(ParkedBalanceEpisodes::<T>::contains_key(actor.actor_id));
    assert!(!DeadlineHeaders::<T>::contains_key(source.key));
    let destination = DeadlineHandles::<T>::get(actor.actor_id).unwrap();
    assert_eq!(destination.key, WakeupKey::Block(3u32.into()));
    assert_eq!(DeadlineIndexLen::<T>::get(WakeupClock::Block), keys);
    assert_eq!(DeadlineIndexPositions::<T>::get(source.key), None);
    assert_eq!(DeadlineIndexPositions::<T>::get(destination.key), Some(0));
    assert_deadline_clock_indices::<T>(WakeupClock::Block);
    Ok(())
  }

