  fn register_measured_user_task<T: Config>(
    owner: &T::AccountId,
    task: TaskOf<T>,
  ) -> Result<(ActorId, T::AccountId), BenchmarkError> {
    frame_system::Pallet::<T>::set_block_number(1u32.into());
    ensure_creation_balance::<T>(owner);
    let steps: ContractSteps<T> = vec![Step {
      precondition: None,
      task,
      on_error: StepErrorPolicy::AbortCycle,
    }]
    .try_into()
    .expect("one authored Task fits");
    prefund_user_sovereign::<T>(owner, 0, &steps);
    let contract = user_contract::<T>(
      Schedule {
        trigger: Trigger::cadenced(1),
        cooldown_blocks: 0,
      },
      steps,
    )
    .expect("active User Contract exists");
    Pallet::<T>::create_user_actor_at_slot(
      RawOrigin::Signed(owner.clone()).into(),
      0,
      Mutability::Mutable,
      Some(contract),
    )?;
    let actor_id = NextActorId::<T>::get() - 1;
    let source = Pallet::<T>::sovereign_account_id(owner, 0);
    assert_eq!(
      Pallet::<T>::actor_identity(actor_id)
        .unwrap()
        .sovereign_account,
      source
    );
    assert_measured_actor_accounts::<T>(&[actor_id]);
    Ok((actor_id, source))
  }

