  #[benchmark]
  fn task_mint() -> Result<(), BenchmarkError> {
    if T::MaxContractSteps::get() < 2 {
      return Err(BenchmarkError::Skip);
    }
    frame_system::Pallet::<T>::set_block_number(1u32.into());
    let owner = measured_account::<T>("mint-owner", 0);
    let native = T::FeeNativeAssetId::get();
    let amount = T::MinUserBalance::get()
      .max(T::AssetOps::minimum_balance(native))
      .checked_add(&One::one())
      .expect("funded Mint amount fits");
    let steps: ContractSteps<T> = vec![
      Step {
        precondition: None,
        task: ActorTask::Burn {
          asset: native,
          amount: AmountResolution::Fixed(One::one()),
        },
        on_error: StepErrorPolicy::AbortCycle,
      },
      Step {
        precondition: None,
        task: ActorTask::Mint {
          asset: native,
          amount: AmountResolution::Fixed(amount),
        },
        on_error: StepErrorPolicy::AbortCycle,
      },
    ]
    .try_into()
    .expect("Burn prefix and Mint successor fit");
    Pallet::<T>::create_system_actor(
      RawOrigin::Root.into(),
      owner,
      Mutability::Mutable,
      system_contract::<T>(
        Schedule {
          trigger: Trigger::address_event(SourceFilter::Any, AssetFilter::Any),
          cooldown_blocks: 0,
        },
        steps,
      ),
    )?;
    let actor_id = NextActorId::<T>::get() - 1;
    let source = Pallet::<T>::actor_identity(actor_id)
      .expect("System identity exists")
      .sovereign_account;
    assert_measured_actor_accounts::<T>(&[actor_id]);
    T::BenchmarkHelper::enable_asset_ops_ingress();
    T::AssetOps::mint(&source, native, amount).map_err(|failure| failure.error)?;
    assert_canonical_ingress_readiness::<T>(actor_id);
    frame_system::Pallet::<T>::set_block_number(2u32.into());
    Pallet::<T>::execute_cycle(Weight::MAX);
    let state =
      Pallet::<T>::active_actor_state(actor_id).expect("real System Running state exists");
    let run = state
      .run_state
      .as_ref()
      .expect("real Burn prefix retains Run");
    assert_eq!(state.hot.cycle_state, CycleState::Running);
    assert!(!state.hot.pending_signal);
    assert_eq!(run.cursor, 1);
    assert_eq!(run.last_committed_step_block, Some(2u32.into()));
    let cycle_nonce = run.cycle_nonce;
    let step_index = run.cursor;
    frame_system::Pallet::<T>::set_block_number(run.eligible_at);
    let retained = (
      Pallet::<T>::actor_identity(actor_id),
      ActorRunStateStore::<T>::get(actor_id),
      ActorProcesses::<T>::get(actor_id),
      ServiceNodes::<T>::get(actor_id),
      ServiceHeader::<T>::get(),
    )
      .encode();
    let before = T::AssetOps::total_balance(&source, native);
    let sink_before = T::AssetOps::total_balance(&T::FeeSink::get(), native);
    #[cfg(feature = "try-runtime")]
    Pallet::<T>::do_try_state().expect("real Running Mint setup passes state audit");
    #[block]
    {
      Pallet::<T>::benchmark_prepared_mint(
        actor_id,
        &source,
        native,
        amount,
        cycle_nonce,
        step_index,
      )
      .expect("complete Running System self-Mint Task must succeed");
    }
    assert_eq!(
      T::AssetOps::total_balance(&source, native).checked_sub(&before),
      Some(amount)
    );
    assert_eq!(
      T::AssetOps::total_balance(&T::FeeSink::get(), native),
      sink_before
    );
    assert_eq!(
      (
        Pallet::<T>::actor_identity(actor_id),
        ActorRunStateStore::<T>::get(actor_id),
        ActorProcesses::<T>::get(actor_id),
        ServiceNodes::<T>::get(actor_id),
        ServiceHeader::<T>::get(),
      )
        .encode(),
      retained
    );
    let state = Pallet::<T>::active_actor_state(actor_id).expect("System actor remains Running");
    assert_eq!(state.hot.cycle_state, CycleState::Running);
    assert!(
      !state.hot.pending_signal,
      "busy self-Mint creates no deferred Cycle"
    );
    frame_system::Pallet::<T>::assert_last_event(
      Event::<T>::MintExecuted {
        actor_id,
        cycle_nonce,
        step_index,
        asset: native,
        amount,
      }
      .into(),
    );
    #[cfg(feature = "try-runtime")]
    Pallet::<T>::do_try_state().expect("Task-local Mint preserves canonical progress");
    Ok(())
  }

  #[benchmark]
  fn precondition_all_max() -> Result<(), polkadot_sdk::frame_benchmarking::BenchmarkError> {
    if benchmark_predicate_capacity::<T>() == 0 {
      return Err(polkadot_sdk::frame_benchmarking::BenchmarkError::Stop(
        "host has no representable predicate capacity for this benchmark",
      ));
    }
    let actor: T::AccountId = account("condition-all", 0, 0);
    let max_predicates = benchmark_predicate_capacity::<T>();
    let assets = T::BenchmarkHelper::setup_predicate_assets(&actor, max_predicates)
      .expect("predicate benchmark assets must be available");
    assert!(assets.len() >= max_predicates as usize);
    let predicates = assets
      .into_iter()
      .take(max_predicates as usize)
      .map(|asset| {
        T::AssetOps::mint(&actor, asset, T::MinUserBalance::get())
          .expect("condition benchmark asset must be funded");
        Predicate::BalanceAbove {
          asset,
          threshold: T::Balance::zero(),
        }
      })
      .collect::<alloc::vec::Vec<_>>();
    let precondition = packed_predicate_clauses::<T>(predicates, T::MaxPredicatesPerClause::get());
    #[block]
    {
      assert_eq!(
        Pallet::<T>::evaluate_precondition(&precondition, &actor, T::Balance::zero()),
        Ok(true)
      );
    }
    Ok(())
  }

  #[benchmark]
  fn precondition_observation(
    c: Linear<1, { benchmark_predicate_capacity::<T>().max(1) }>,
  ) -> Result<(), polkadot_sdk::frame_benchmarking::BenchmarkError> {
    if benchmark_predicate_capacity::<T>() == 0 {
      return Err(polkadot_sdk::frame_benchmarking::BenchmarkError::Stop(
        "host has no representable predicate capacity for this benchmark",
      ));
    }
    let actor: T::AccountId = account("condition-observation", 0, 0);
    let bounded = c;
    let feeds = T::BenchmarkHelper::setup_observation_feeds(bounded)
      .expect("observation benchmark feeds must be available");
    assert!(feeds.len() >= bounded as usize);
    let predicates = feeds
      .into_iter()
      .take(bounded as usize)
      .map(|feed| Predicate::ObservationAbove {
        feed,
        threshold: 0,
        max_age_blocks: 100,
      })
      .collect::<alloc::vec::Vec<_>>();
    let precondition = packed_predicate_clauses::<T>(predicates, T::MaxPredicatesPerClause::get());
    #[block]
    {
      let _ = Pallet::<T>::evaluate_precondition(&precondition, &actor, T::Balance::zero());
    }
    Ok(())
  }

  #[benchmark(pov_mode = Measured)]
  fn predicate_set_evaluation(
    c: Linear<1, { benchmark_predicate_capacity::<T>().max(1) }>,
  ) -> Result<(), polkadot_sdk::frame_benchmarking::BenchmarkError> {
    let observations = u32::from(c >= 2);
    let (actor, precondition) =
      prepare_max_encoded_step_precondition::<T>(c - observations, observations, false)?;
    let result;
    #[block]
    {
      result = Pallet::<T>::evaluate_precondition(&precondition, &actor, Zero::zero());
      core::hint::black_box(&result);
    }
    assert_eq!(result, Ok(true));
    Ok(())
  }

