  struct RemoveLiquidityFixture<T: Config> {
    actor_id: ActorId,
    source: T::AccountId,
    lp_asset: T::AssetId,
    asset_a: T::AssetId,
    asset_b: T::AssetId,
    lp_amount: T::Balance,
  }

  fn prepare_user_remove_liquidity<T: Config>(
    consumer_refusal: bool,
  ) -> Result<RemoveLiquidityFixture<T>, BenchmarkError> {
    frame_system::Pallet::<T>::set_block_number(1u32.into());
    let owner = measured_account::<T>("remove-liquidity-owner", 0);
    ensure_creation_balance::<T>(&owner);
    let source = Pallet::<T>::sovereign_account_id(&owner, 0);
    T::AssetOps::mint(
      &source,
      T::FeeNativeAssetId::get(),
      T::MinUserBalance::get().saturating_add(One::one()),
    )
    .map_err(|failure| failure.error)?;
    let (lp_asset, asset_a, asset_b, lp_amount) = if consumer_refusal {
      T::BenchmarkHelper::setup_remove_liquidity_consumer_outputs(&source)?
        .ok_or(BenchmarkError::Skip)?
    } else {
      T::BenchmarkHelper::setup_remove_liquidity(&source)?
    };
    let steps: ContractSteps<T> = vec![Step {
      precondition: None,
      task: ActorTask::RemoveLiquidity {
        lp_asset,
        asset_a,
        asset_b,
        lp_amount: AmountResolution::Fixed(lp_amount),
        min_amount_a: One::one(),
        min_amount_b: One::one(),
      },
      on_error: StepErrorPolicy::AbortCycle,
    }]
    .try_into()
    .expect("one RemoveLiquidity Step fits");
    prefund_user_sovereign::<T>(&owner, 0, &steps);
    let contract = user_contract::<T>(
      Schedule {
        trigger: Trigger::cadenced(1),
        cooldown_blocks: 0,
      },
      steps.clone(),
    )
    .expect("active User Contract exists");
    Pallet::<T>::create_user_actor_at_slot(
      RawOrigin::Signed(owner.clone()).into(),
      0,
      Mutability::Mutable,
      Some(contract),
    )?;
    let actor_id = NextActorId::<T>::get() - 1;
    assert_eq!(
      Pallet::<T>::actor_identity(actor_id)
        .unwrap()
        .sovereign_account,
      source
    );
    assert_measured_actor_accounts::<T>(&[actor_id]);
    if consumer_refusal {
      let required = T::MinUserBalance::get()
        .checked_add(&full_attempt_fee::<T>(&steps))
        .expect("floor and Action fee fit");
      let current = T::AssetOps::balance(&source, T::FeeNativeAssetId::get());
      if current < required {
        T::AssetOps::mint(&source, T::FeeNativeAssetId::get(), required - current)
          .map_err(|failure| failure.error)?;
      } else if current > required {
        T::AssetOps::transfer(
          &source,
          &owner,
          T::FeeNativeAssetId::get(),
          current - required,
        )
        .map_err(|failure| failure.error)?;
      }
      assert_eq!(
        T::AssetOps::balance(&source, T::FeeNativeAssetId::get()),
        required
      );
    }
    Ok(RemoveLiquidityFixture {
      actor_id,
      source,
      lp_asset,
      asset_a,
      asset_b,
      lp_amount,
    })
  }

  #[benchmark]
  fn task_remove_liquidity() -> Result<(), BenchmarkError> {
    let fixture = prepare_user_remove_liquidity::<T>(false)?;
    let lp_before = T::AssetOps::total_balance(&fixture.source, fixture.lp_asset);
    let a_before = T::AssetOps::total_balance(&fixture.source, fixture.asset_a);
    let b_before = T::AssetOps::total_balance(&fixture.source, fixture.asset_b);
    #[block]
    {
      Pallet::<T>::benchmark_prepared_remove_liquidity(
        fixture.actor_id,
        &fixture.source,
        (fixture.lp_asset, fixture.asset_a, fixture.asset_b),
        fixture.lp_amount,
      )
      .expect("complete User RemoveLiquidity Task must succeed");
    }
    assert_eq!(
      lp_before.checked_sub(&T::AssetOps::total_balance(
        &fixture.source,
        fixture.lp_asset
      )),
      Some(fixture.lp_amount)
    );
    let amount_a = T::AssetOps::total_balance(&fixture.source, fixture.asset_a)
      .checked_sub(&a_before)
      .expect("first output is credited");
    let amount_b = T::AssetOps::total_balance(&fixture.source, fixture.asset_b)
      .checked_sub(&b_before)
      .expect("second output is credited");
    assert!(!amount_a.is_zero() && !amount_b.is_zero());
    frame_system::Pallet::<T>::assert_last_event(
      Event::<T>::LiquidityRemoved {
        actor_id: fixture.actor_id,
        cycle_nonce: 1,
        step_index: 0,
        lp_asset: fixture.lp_asset,
        lp_amount: fixture.lp_amount,
        asset_a: fixture.asset_a,
        asset_b: fixture.asset_b,
        amount_a,
        amount_b,
      }
      .into(),
    );
    Ok(())
  }

