  struct StakingFixture<T: Config> {
    actor_id: ActorId,
    source: T::AccountId,
    asset: T::AssetId,
    amount: T::Balance,
  }

  fn prepare_user_staking<T: Config>(
    unstake: bool,
    consumer_refusal: bool,
  ) -> Result<StakingFixture<T>, BenchmarkError> {
    frame_system::Pallet::<T>::set_block_number(1u32.into());
    let owner = measured_account::<T>("staking-owner", 0);
    ensure_creation_balance::<T>(&owner);
    let source = Pallet::<T>::sovereign_account_id(&owner, 0);
    T::AssetOps::mint(
      &source,
      T::FeeNativeAssetId::get(),
      T::MinUserBalance::get().saturating_add(One::one()),
    )
    .map_err(|failure| failure.error)?;
    let (asset, amount) = match (unstake, consumer_refusal) {
      (false, false) => T::BenchmarkHelper::setup_stake(&source)?,
      (true, false) => T::BenchmarkHelper::setup_unstake(&source)?,
      (false, true) => {
        T::BenchmarkHelper::setup_stake_consumer_receipt(&source)?.ok_or(BenchmarkError::Skip)?
      }
      (true, true) => {
        T::BenchmarkHelper::setup_unstake_consumer_output(&source)?.ok_or(BenchmarkError::Skip)?
      }
    };
    let task = if unstake {
      ActorTask::Unstake {
        asset,
        shares: AmountResolution::Fixed(amount),
      }
    } else {
      ActorTask::Stake {
        asset,
        amount: AmountResolution::Fixed(amount),
      }
    };
    let steps: ContractSteps<T> = vec![Step {
      precondition: None,
      task,
      on_error: StepErrorPolicy::AbortCycle,
    }]
    .try_into()
    .expect("one staking Step fits");
    prefund_user_sovereign::<T>(&owner, 0, &steps);
    let contract = user_contract::<T>(
      Schedule {
        trigger: Trigger::cadenced(1),
        cooldown_blocks: 0,
      },
      steps.clone(),
    )
    .expect("active User Contract exists");
    Pallet::<T>::create_user_actor_at_slot(
      RawOrigin::Signed(owner.clone()).into(),
      0,
      Mutability::Mutable,
      Some(contract),
    )?;
    let actor_id = NextActorId::<T>::get() - 1;
    assert_eq!(
      Pallet::<T>::actor_identity(actor_id)
        .unwrap()
        .sovereign_account,
      source
    );
    assert_measured_actor_accounts::<T>(&[actor_id]);
    if consumer_refusal {
      let required = T::MinUserBalance::get()
        .checked_add(&full_attempt_fee::<T>(&steps))
        .expect("floor plus one Action fee fits");
      let excess = T::AssetOps::balance(&source, T::FeeNativeAssetId::get())
        .checked_sub(&required)
        .expect("public creation prefunding covers one Task attempt");
      T::AssetOps::transfer(&source, &owner, T::FeeNativeAssetId::get(), excess)
        .map_err(|failure| failure.error)?;
      assert_eq!(
        T::AssetOps::balance(&source, T::FeeNativeAssetId::get()),
        required
      );
    }
    Ok(StakingFixture {
      actor_id,
      source,
      asset,
      amount,
    })
  }

