  struct SwapFixture<T: Config> {
    actor_id: ActorId,
    source: T::AccountId,
    asset_in: T::AssetId,
    asset_out: T::AssetId,
    input_cap: T::Balance,
    amount_out: T::Balance,
  }

  fn prepare_user_swap<T: Config>(
    exact_out: bool,
    consumer_refusal: bool,
  ) -> Result<SwapFixture<T>, BenchmarkError> {
    frame_system::Pallet::<T>::set_block_number(1u32.into());
    let owner = measured_account::<T>("swap-owner", 0);
    ensure_creation_balance::<T>(&owner);
    let source = Pallet::<T>::sovereign_account_id(&owner, 0);
    T::AssetOps::mint(
      &source,
      T::FeeNativeAssetId::get(),
      T::MinUserBalance::get().saturating_add(One::one()),
    )
    .map_err(|failure| failure.error)?;
    let (asset_in, asset_out, input_cap, amount_out) = if consumer_refusal {
      T::BenchmarkHelper::setup_swap_consumer_output(&source)?.ok_or(BenchmarkError::Skip)?
    } else if exact_out {
      let (asset_in, asset_out, amount_out, input_cap) =
        T::BenchmarkHelper::setup_swap_exact_out(&source)?;
      (asset_in, asset_out, input_cap, amount_out)
    } else {
      let (asset_in, asset_out, input_cap) = T::BenchmarkHelper::setup_swap_exact_in(&source)?;
      (asset_in, asset_out, input_cap, Zero::zero())
    };
    let task = if exact_out {
      ActorTask::SwapOut {
        asset_in,
        asset_out,
        amount_out: AmountResolution::Fixed(amount_out),
        input_limit: InputLimit::Absolute(input_cap),
        slippage_tolerance: Perbill::zero(),
      }
    } else {
      ActorTask::SwapIn {
        asset_in,
        asset_out,
        amount_in: AmountResolution::Fixed(input_cap),
        slippage_tolerance: Perbill::zero(),
      }
    };
    let steps: ContractSteps<T> = vec![Step {
      precondition: None,
      task,
      on_error: StepErrorPolicy::AbortCycle,
    }]
    .try_into()
    .expect("one swap Step fits");
    prefund_user_sovereign::<T>(&owner, 0, &steps);
    let contract = user_contract::<T>(
      Schedule {
        trigger: Trigger::cadenced(1),
        cooldown_blocks: 0,
      },
      steps.clone(),
    )
    .expect("active User Contract exists");
    Pallet::<T>::create_user_actor_at_slot(
      RawOrigin::Signed(owner.clone()).into(),
      0,
      Mutability::Mutable,
      Some(contract),
    )?;
    let actor_id = NextActorId::<T>::get() - 1;
    assert_eq!(
      Pallet::<T>::actor_identity(actor_id)
        .unwrap()
        .sovereign_account,
      source
    );
    assert_measured_actor_accounts::<T>(&[actor_id]);
    if consumer_refusal {
      assert_eq!(asset_in, T::FeeNativeAssetId::get());
      let required = T::MinUserBalance::get()
        .checked_add(&full_attempt_fee::<T>(&steps))
        .and_then(|value| value.checked_add(&input_cap))
        .expect("floor, Action fee and complete input fit");
      let current = T::AssetOps::balance(&source, T::FeeNativeAssetId::get());
      if current < required {
        T::AssetOps::mint(&source, T::FeeNativeAssetId::get(), required - current)
          .map_err(|failure| failure.error)?;
      } else if current > required {
        T::AssetOps::transfer(
          &source,
          &owner,
          T::FeeNativeAssetId::get(),
          current - required,
        )
        .map_err(|failure| failure.error)?;
      }
      assert_eq!(
        T::AssetOps::balance(&source, T::FeeNativeAssetId::get()),
        required
      );
    }
    Ok(SwapFixture {
      actor_id,
      source,
      asset_in,
      asset_out,
      input_cap,
      amount_out,
    })
  }

  fn verify_swap_receipt<T: Config>(
    fixture: &SwapFixture<T>,
    input_before: T::Balance,
    output_before: T::Balance,
  ) {
    let amount_in = input_before
      .checked_sub(&T::AssetOps::total_balance(
        &fixture.source,
        fixture.asset_in,
      ))
      .expect("swap debits input");
    let amount_out = T::AssetOps::total_balance(&fixture.source, fixture.asset_out)
      .checked_sub(&output_before)
      .expect("swap credits output");
    assert!(!amount_in.is_zero() && !amount_out.is_zero());
    frame_system::Pallet::<T>::assert_last_event(
      Event::<T>::SwapExecuted {
        actor_id: fixture.actor_id,
        cycle_nonce: 1,
        step_index: 0,
        asset_in: fixture.asset_in,
        asset_out: fixture.asset_out,
        amount_in,
        amount_out,
      }
      .into(),
    );
  }

