  #[derive(Clone, Copy)]
  enum ServiceDeadlineDestination {
    NewKey,
    AppendPage,
    FillVacancy,
  }

  struct ServiceDeadlinePlacementFixture<T: Config> {
    destination: ServiceDeadlineDestination,
    destination_before: Option<DeadlineHeader>,
    pages_before: Vec<DeadlinePage>,
    actor: ActorRef,
    due: BlockNumberFor<T>,
    keys: u32,
    header: ServiceHeaderRecord<BlockNumberFor<T>>,
    source: ServiceNode<BlockNumberFor<T>>,
    peers: Vec<(ActorRef, ServiceNode<BlockNumberFor<T>>, ActorProcessOf<T>)>,
  }

  fn prepare_service_deadline_placement<T: Config>(
    with_peers: bool,
    destination: ServiceDeadlineDestination,
  ) -> Result<ServiceDeadlinePlacementFixture<T>, BenchmarkError> {
    let now: BlockNumberFor<T> = 1u32.into();
    frame_system::Pallet::<T>::set_block_number(now);
    let owner: T::AccountId = account("service-to-deadline", 0, 0);
    Pallet::<T>::create_system_actor(
      RawOrigin::Root.into(),
      owner.clone(),
      Mutability::Mutable,
      system_contract::<T>(
        Schedule {
          trigger: Trigger::Manual,
          cooldown_blocks: 0,
        },
        make_inert_contract_steps::<T>(),
      ),
    )?;
    let actor_id = NextActorId::<T>::get().saturating_sub(1);
    Pallet::<T>::manual_trigger(RawOrigin::Signed(owner).into(), actor_id)?;
    let actor = Pallet::<T>::load_actor_ref(actor_id).expect("benchmark Actor is active");
    let mut peers = Vec::new();
    if with_peers {
      for seed in 0..2 {
        let peer_owner: T::AccountId = account("service-placement-peer", seed, 0);
        Pallet::<T>::create_system_actor(
          RawOrigin::Root.into(),
          peer_owner.clone(),
          Mutability::Mutable,
          system_contract::<T>(
            Schedule {
              trigger: Trigger::Manual,
              cooldown_blocks: 0,
            },
            make_inert_contract_steps::<T>(),
          ),
        )?;
        let peer_id = NextActorId::<T>::get().saturating_sub(1);
        Pallet::<T>::manual_trigger(RawOrigin::Signed(peer_owner).into(), peer_id)?;
        peers.push(Pallet::<T>::load_actor_ref(peer_id).unwrap());
      }
    }
    let due = now.saturating_add(2u32.into());
    let key = WakeupKey::Block(due);
    match destination {
      ServiceDeadlineDestination::NewKey => assert!(!DeadlineHeaders::<T>::contains_key(key)),
      ServiceDeadlineDestination::AppendPage => {
        for seed in 1_000..1_032 {
          create_canonical_deadline_guard::<T>(seed, due);
        }
        let header = DeadlineHeaders::<T>::get(key).unwrap();
        assert_eq!(
          (header.count, header.page_count, header.first_vacant_page),
          (32, 1, None)
        );
      }
      ServiceDeadlineDestination::FillVacancy => prepare_deadline_destination_vacancy::<T>(due),
    }
    let destination_before = DeadlineHeaders::<T>::get(key);
    let pages_before = (0..destination_before
      .as_ref()
      .map_or(0, |header| header.page_count))
      .map(|page| DeadlinePages::<T>::get(key, u64::from(page)).unwrap())
      .collect();
    let keys = populate_canonical_deadline_index::<T>(due);
    // Placement follows a retained Service consideration, not an unattempted publication.
    // Reach both optional timestamp fields through the canonical round at B+1.
    let eligible = ServiceNodes::<T>::get(actor_id).unwrap().eligible_from;
    assert!(eligible > now && eligible < due);
    frame_system::Pallet::<T>::set_block_number(eligible);
    polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
      Pallet::<T>::begin_service_round(eligible).expect("placement round opens");
      Pallet::<T>::advance_service_head(actor, eligible)
        .expect("placement source is considered once at eligibility");
      polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(())
    });
    let header = ServiceHeader::<T>::get();
    assert_eq!(header.count, if with_peers { 3 } else { 1 });
    assert_eq!(header.round_block, Some(eligible));
    assert_eq!(
      header.encoded_size(),
      ServiceHeaderRecord::<BlockNumberFor<T>>::max_encoded_len()
    );
    let process = ActorProcesses::<T>::get(actor_id).unwrap();
    assert_eq!(process.last_attempted, Some(eligible));
    assert_eq!(process.status, ProcessStatus::Serving);
    assert_eq!(
      process.residence,
      Some(ProcessResidence::Service(ServiceResidenceKind::Pending))
    );

    assert!(
      ActiveActorCount::<T>::get() == Pallet::<T>::effective_active_actor_limit()
        || ActorIdentityCount::<T>::get() == T::MaxActorIdentities::get()
        || SystemSovereignCount::<T>::get() == T::MaxSystemSovereigns::get(),
      "placement fills the unchanged remaining admitted capacity"
    );
    let source = ServiceNodes::<T>::get(actor_id).unwrap();
    if with_peers {
      assert_ne!(source.previous, source.next);
      assert_ne!(source.previous, actor);
      assert_ne!(source.next, actor);
    }
    Ok(ServiceDeadlinePlacementFixture {
      destination,
      destination_before,
      pages_before,
      actor,
      due,
      keys,
      header,
      source,
      peers: peers
        .into_iter()
        .map(|peer| {
          (
            peer,
            ServiceNodes::<T>::get(peer.actor_id).unwrap(),
            ActorProcesses::<T>::get(peer.actor_id).unwrap(),
          )
        })
        .collect(),
    })
  }

  fn assert_service_deadline_placement<T: Config>(fixture: &ServiceDeadlinePlacementFixture<T>) {
    let actor_id = fixture.actor.actor_id;
    let key = WakeupKey::Block(fixture.due);
    assert!(!ServiceNodes::<T>::contains_key(actor_id));
    let handle = DeadlineHandles::<T>::get(actor_id).expect("Actor owns its Deadline residence");
    assert_eq!(handle.actor, fixture.actor);
    assert_eq!(handle.key, key);
    match fixture.destination {
      ServiceDeadlineDestination::NewKey => {
        assert_eq!((handle.page, handle.slot), (0, 0));
        assert_eq!(
          DeadlineIndexLen::<T>::get(WakeupClock::Block),
          fixture.keys + 1
        );
      }
      ServiceDeadlineDestination::AppendPage => {
        assert_eq!((handle.page, handle.slot), (1, 0));
        let mut prior = fixture.pages_before[0].clone();
        prior.next_page = Some(1);
        assert_eq!(DeadlinePages::<T>::get(key, 0), Some(prior));
        let added = DeadlinePages::<T>::get(key, 1).unwrap();
        assert_eq!((added.previous_page, added.next_page), (Some(0), None));
        assert_eq!(
          (added.previous_vacant_page, added.next_vacant_page),
          (None, None)
        );
        assert_eq!(added.live_entries, 1);
        assert_eq!(added.entries.len(), 32);
        assert_eq!(added.entries[0], Some(fixture.actor));
        assert!(added.entries.iter().skip(1).all(Option::is_none));
        let mut header = fixture.destination_before.unwrap();
        header.count += 1;
        header.page_count += 1;
        header.last_page = 1;
        header.next_page = 2;
        header.first_vacant_page = Some(1);
        assert_eq!(DeadlineHeaders::<T>::get(key), Some(header));
        assert_eq!(DeadlineIndexLen::<T>::get(WakeupClock::Block), fixture.keys);
      }
      ServiceDeadlineDestination::FillVacancy => {
        assert_eq!((handle.page, handle.slot), (0, 31));
        let mut filled = fixture.pages_before[0].clone();
        filled.entries[31] = Some(fixture.actor);
        filled.live_entries = 32;
        filled.next_vacant_page = None;
        assert_eq!(DeadlinePages::<T>::get(key, 0), Some(filled));
        let mut successor = fixture.pages_before[1].clone();
        successor.previous_vacant_page = None;
        assert_eq!(DeadlinePages::<T>::get(key, 1), Some(successor));
        let mut header = fixture.destination_before.unwrap();
        header.count += 1;
        header.first_vacant_page = Some(1);
        assert_eq!(DeadlineHeaders::<T>::get(key), Some(header));
        assert_eq!(DeadlineIndexLen::<T>::get(WakeupClock::Block), fixture.keys);
      }
    }
    assert_eq!(DeadlineIndexPositions::<T>::get(key), Some(0));
    let mut expected_header = fixture.header;
    if fixture.peers.is_empty() {
      expected_header = ServiceHeaderRecord::default();
    } else {
      expected_header.count -= 1;
    }
    assert_eq!(ServiceHeader::<T>::get(), expected_header);
    for (peer, before, process) in &fixture.peers {
      let mut expected = *before;
      if expected.previous == fixture.actor {
        expected.previous = fixture.source.previous;
      }
      if expected.next == fixture.actor {
        expected.next = fixture.source.next;
      }
      assert_eq!(ServiceNodes::<T>::get(peer.actor_id), Some(expected));
      assert_eq!(ActorProcesses::<T>::get(peer.actor_id), Some(*process));
    }
    #[cfg(feature = "try-runtime")]
    Pallet::<T>::do_try_state().expect("canonical placement preserves complete state");
  }

