  fn maximum_behavior_expression<T: Config>() -> Result<CloseWhenOf<T>, BenchmarkError> {
    use BehaviorMetric::*;
    if T::MaxBehaviorClauses::get() != 4 || T::MaxBehaviorAtomsPerClause::get() != 4 {
      return Err(BenchmarkError::Stop(
        "policy component requires four-by-four bounds",
      ));
    }
    let clauses = [
      [
        PreconditionPassTotal,
        PreconditionPassStreak,
        PreconditionRejectTotal,
        PreconditionRejectStreak,
      ],
      [
        PreconditionPassTotal,
        ActionSuccessTotal,
        ActionSuccessStreak,
        ActionFailureTotal,
      ],
      [
        PreconditionPassStreak,
        ActionFailureStreak,
        CycleCompletedTotal,
        CycleCleanTotal,
      ],
      [
        PreconditionRejectTotal,
        PreconditionRejectStreak,
        ActionSuccessTotal,
        ActionSuccessStreak,
      ],
    ];
    Ok(CloseWhen {
      clauses: clauses
        .into_iter()
        .map(|clause| {
          clause
            .into_iter()
            .map(|metric| BehaviorAtom {
              metric,
              threshold: u32::MAX,
            })
            .collect::<Vec<_>>()
            .try_into()
            .expect("four atoms fit")
        })
        .collect::<Vec<_>>()
        .try_into()
        .expect("four clauses fit"),
    })
  }

  /// Prepares source-bound component records, without admitting policy service or invoking a Task.
  /// 0=absent, 1=current outcome, 2=sparse accumulated, 3=maximum Idle, 4=Running, 5=Suspended.
  fn prepare_behavior_source_snapshot<T: Config>(
    case: u32,
  ) -> Result<(ActorId, ActorContractHeaderOf<T>, CycleState, u64), BenchmarkError> {
    let source =
      prepare_behavior_source_snapshot_in_domain::<T>(case, false, ActorType::User, false)?;
    Ok((
      source.actor_id,
      source.header,
      source.cycle_state,
      source.cycle_nonce,
    ))
  }

  struct BehaviorSourceSnapshotFixture<T: Config> {
    actor_id: ActorId,
    header: ActorContractHeaderOf<T>,
    cycle_state: CycleState,
    cycle_nonce: u64,
    destruction: Option<CloseDestructionFixture<T>>,
  }

  fn prepare_behavior_source_snapshot_in_domain<T: Config>(
    case: u32,
    detached: bool,
    actor_type: ActorType,
    last_owner_slot: bool,
  ) -> Result<BehaviorSourceSnapshotFixture<T>, BenchmarkError> {
    frame_system::Pallet::<T>::set_block_number(1u32.into());
    let source_cycle = match case {
      4 => CycleState::Running,
      5 => CycleState::Suspended,
      _ => CycleState::Idle,
    };
    let mut destruction = None;
    let actor_id = if case >= 3 {
      // Reuse the legal configured-length temporal witnesses, including actual committed prefix
      // and host failure. Policy authority is staged below; it has no public-admission claim.
      let mut fixture = prepare_temporal_close::<T>(actor_type, false, source_cycle)?;
      if last_owner_slot {
        leave_last_close_owner_slot::<T>(&mut fixture)?;
      }
      let actor_id = fixture.actor_id;
      destruction = Some(fixture);
      actor_id
    } else {
      let owner = measured_account::<T>("behavior-source-owner", 0);
      let recipient = measured_account::<T>("behavior-source-recipient", 0);
      let mut steps = make_contract_steps::<T>(recipient);
      steps[0].precondition = Some(Precondition {
        clauses: vec![
          vec![Predicate::BlockNumberAbove { threshold: 0 }]
            .try_into()
            .expect("one predicate fits"),
        ]
        .try_into()
        .expect("one clause fits"),
      });
      bench_create_user_with_trigger_and_steps::<T>(owner, Trigger::Manual, steps)
    };
    let (mut contract, base) = Pallet::<T>::load_admitted_contract_geometry(actor_id)
      .expect("ordinary component Contract loads");
    if detached {
      // Detach through the ordinary admitted path before staging optional records. This supplies
      // the finalizer's real post-detachment topology without inventing optional resource prices.
      detach_close_destruction::<T>(actor_id)?;
    }
    contract.close_when = match case {
      0 => None,
      1 | 2 => Some(CloseWhen {
        clauses: vec![
          vec![BehaviorAtom {
            metric: BehaviorMetric::ActionSuccessTotal,
            threshold: if case == 1 { 1 } else { u32::MAX },
          }]
          .try_into()
          .expect("one atom fits"),
        ]
        .try_into()
        .expect("one clause fits"),
      }),
      _ => Some(maximum_behavior_expression::<T>()?),
    };
    let (header, cycle_nonce) =
      stage_behavior_source_snapshot::<T>(actor_id, case, source_cycle, contract, base)?;
    Ok(BehaviorSourceSnapshotFixture {
      actor_id,
      header,
      cycle_state: source_cycle,
      cycle_nonce,
      destruction,
    })
  }

  fn stage_behavior_source_snapshot<T: Config>(
    actor_id: ActorId,
    case: u32,
    source_cycle: CycleState,
    contract: ActorContractOf<T>,
    base: ActorAdmissionCertificateOf<T>,
  ) -> Result<(ActorContractHeaderOf<T>, u64), BenchmarkError> {
    let admission: ActorAdmissionCertificateOf<T> = ActorAdmissionCertificate::new(
      contract.semantic_contract_id(),
      contract.body_commitment().expect("bounded component body"),
      contract.trigger.wake_qualification(&contract.window),
      base.runtime_actor_semantics_version,
      base.production_weight_identity,
      base.body_geometry_version,
      base.configured_bounds_commitment,
      base.maximum_lifecycle_weight,
    );
    let ActorSemanticState::Active(mut semantic) =
      ActorSemanticStates::<T>::get(actor_id).expect("component semantic source exists")
    else {
      panic!("active component source")
    };
    semantic.admission = admission.clone();
    assert_eq!(semantic.hot.cycle_state, source_cycle);
    let cycle_nonce = semantic
      .identity
      .cycle_nonce
      .checked_add(1)
      .expect("fresh cycle nonce");
    if case >= 4 {
      let mut run = ActorRunStateStore::<T>::get(actor_id).expect("actual prefix retains Run");
      assert_eq!(run.cycle_nonce, cycle_nonce);
      assert!(run.last_committed_step_block.is_some());
      assert_eq!(run.cumulative_outcomes.committed_effectful_tasks, 1);
      assert!(matches!(
        run.last_step_outcome,
        Some(StepOutcome::Failed(_))
      ));
      run.contract_authority = ActorRunAuthority {
        semantic_contract_id: admission.semantic_contract_id,
        body_commitment: admission.body_commitment,
        admission_identity: admission.admission_identity,
        pipeline_service_identity: pipeline_service_identity(admission.admission_identity),
      };
      assert!(if case == 5 {
        run.suspension_is_coherent()
      } else {
        run.running_is_coherent()
      });
      ActorRunStateStore::<T>::insert(actor_id, run);
    }
    let generation = semantic.generation;
    ActorSemanticStates::<T>::insert(actor_id, ActorSemanticState::Active(semantic));
    let mut head = ActorContractHeads::<T>::get(actor_id).expect("component head exists");
    head.header.has_close_when = contract.close_when.is_some();
    head.header.semantic_contract_id = admission.semantic_contract_id;
    head.header.admission_identity = admission.admission_identity;
    ActorContractHeads::<T>::insert(actor_id, &head);
    for chunk_index in 0..contract
      .steps
      .len()
      .saturating_sub(1)
      .div_ceil(MAX_STEPS_PER_TAIL_CHUNK as usize)
    {
      ActorContractTailChunks::<T>::mutate(actor_id, chunk_index as u32, |chunk| {
        let chunk = chunk
          .as_mut()
          .expect("configured-length source retains its tail");
        chunk.authority.semantic_contract_id = admission.semantic_contract_id;
        chunk.authority.admission_identity = admission.admission_identity;
      });
    }
    let mut expects_monitor = false;
    if let Some(expression) = contract.close_when {
      let binding = BehaviorPolicyBinding {
        semantic_contract_id: admission.semantic_contract_id,
        admission_identity: admission.admission_identity,
      };
      let policy = ActorBehaviorPolicy {
        plan: expression
          .validate()
          .expect("canonical component expression")
          .compile(binding)
          .expect("bounded component plan"),
        expression,
        episode_started_at_generation: generation,
      };
      expects_monitor = policy.plan.mode() == BehaviorTrackingMode::Accumulated
        || policy.plan.requires_clean_cycle();
      if expects_monitor {
        let episode = (
          b"DEOS_ACTOR_BEHAVIOR_EPISODE",
          actor_id,
          generation,
          admission.semantic_contract_id,
        )
          .using_encoded(frame::hashing::blake2_256);
        let bound = policy
          .plan
          .bind(&policy.expression, binding)
          .expect("component policy binds");
        let mut state = bound
          .begin_episode(episode)
          .expect("component monitor exists");
        if case >= 3 {
          // Match the already executed prefix: Transfer, then StopCycle or Temporary failure.
          for observation in [
            BehaviorObservation {
              precondition: None,
              action: Some(true),
              completion: None,
            },
            if case == 3 {
              BehaviorObservation {
                precondition: None,
                action: None,
                completion: Some(false),
              }
            } else {
              BehaviorObservation {
                precondition: Some(true),
                action: Some(false),
                completion: None,
              }
            },
          ] {
            state = bound
              .reduce(&state, episode, observation)
              .expect("prefix observations reduce")
              .candidate;
          }
        }
        let monitor = ActorBehaviorMonitor {
          state,
          clean_cycle: if case >= 4 {
            Some(BehaviorCleanCycle {
              cycle_nonce,
              candidate: CleanCycleCandidate::default()
                .observe(CleanCycleStep::EconomicSuccess)
                .observe(CleanCycleStep::Disqualified),
            })
          } else {
            None
          },
        };
        if case >= 3 {
          assert_eq!(
            policy.encoded_size(),
            ActorBehaviorPolicyOf::<T>::max_encoded_len()
          );
          assert_eq!(policy.plan.metrics().len(), 10);
          if case >= 4 {
            assert_eq!(
              monitor.encoded_size(),
              ActorBehaviorMonitor::max_encoded_len()
            );
          }
        }
        ActorBehaviorMonitors::<T>::insert(actor_id, monitor);
      }
      ActorBehaviorPolicies::<T>::insert(actor_id, policy);
    }
    assert_eq!(
      ActorBehaviorPolicies::<T>::contains_key(actor_id),
      case != 0
    );
    assert_eq!(
      ActorBehaviorMonitors::<T>::contains_key(actor_id),
      expects_monitor
    );
    Ok((head.header, cycle_nonce))
  }

  /// Reuses component bindings, not public policy admission or policy-priced service.
  /// P0/P1/P2/P3 are Idle; P4 retains the real temporal Transfer/failure prefix.
  fn prepare_behavior_policy_cleanup<T: Config>(
    case: u32,
  ) -> Result<BehaviorSourceSnapshotFixture<T>, BenchmarkError> {
    let source_case = match case {
      0 | 2 => 0,
      1 => 1,
      3 => 2,
      4 => 4,
      _ => return Err(BenchmarkError::Stop("unknown policy cleanup class")),
    };
    let zero_clean: Option<CloseWhenOf<T>> = (case == 2).then(|| CloseWhen {
      clauses: vec![
        vec![BehaviorAtom {
          metric: BehaviorMetric::CycleCleanTotal,
          threshold: 1,
        }]
        .try_into()
        .expect("one atom fits"),
      ]
      .try_into()
      .expect("one clause fits"),
    });
    let mut source =
      prepare_behavior_source_snapshot_in_domain::<T>(source_case, false, ActorType::User, false)?;
    if let Some(expression) = zero_clean {
      let (mut contract, admission) = Pallet::<T>::load_admitted_contract_geometry(source.actor_id)
        .expect("ordinary component source reconstructs");
      contract.close_when = Some(expression);
      (source.header, source.cycle_nonce) = stage_behavior_source_snapshot::<T>(
        source.actor_id,
        2,
        CycleState::Idle,
        contract,
        admission,
      )?;
    }
    assert_eq!(source.header.has_close_when, case != 0);
    assert_eq!(
      ActorBehaviorMonitors::<T>::contains_key(source.actor_id),
      case >= 2
    );
    if case != 0 {
      let policy =
        ActorBehaviorPolicies::<T>::get(source.actor_id).expect("policy component exists");
      assert_eq!(
        policy.plan.mode() == BehaviorTrackingMode::CurrentOutcome,
        case <= 2
      );
      assert_eq!(policy.plan.requires_clean_cycle(), case == 2 || case == 4);
      if case == 2 {
        assert_eq!(
          Pallet::<T>::behavior_control_weight_context(&policy)
            .unwrap()
            .counter_slots,
          0
        );
      }
      if case == 4 {
        assert_eq!(
          policy.encoded_size(),
          ActorBehaviorPolicyOf::<T>::max_encoded_len()
        );
        assert_eq!(
          ActorBehaviorMonitors::<T>::get(source.actor_id)
            .unwrap()
            .encoded_size(),
          ActorBehaviorMonitor::max_encoded_len()
        );
      }
    }
    Ok(source)
  }

  // Independent key-delta oracle. Both this root and verification use FRAME depth one;
  // its transaction is setup/verification only, never part of the recorded fragment.
  fn expected_behavior_cleanup_root<T: Config>(actor_id: ActorId, case: u32) -> Vec<u8> {
    polkadot_sdk::frame_support::storage::with_transaction(|| {
      if case != 0 {
        ActorBehaviorPolicies::<T>::remove(actor_id);
      }
      if case >= 2 {
        ActorBehaviorMonitors::<T>::remove(actor_id);
      }
      polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(Ok::<_, DispatchError>(
        polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
      ))
    })
    .expect("setup oracle rolls back")
  }

  /// Additional policy read/delete/drop only. Ordinary geometry and the caller transaction
  /// remain excluded; the selector is categorical and cannot generate a Weight coefficient.
  #[benchmark(extra, pov_mode = Measured)]
  fn behavior_policy_cleanup(c: Linear<0, 4>) -> Result<(), BenchmarkError> {
    let source = prepare_behavior_policy_cleanup::<T>(c)?;
    let actor_id = source.actor_id;
    let has_policy = source.header.has_close_when;
    let expected = expected_behavior_cleanup_root::<T>(actor_id, c);
    #[block]
    {
      Pallet::<T>::benchmark_remove_behavior_state(actor_id, has_policy)
        .expect("prepared optional cleanup source exists");
    }
    polkadot_sdk::frame_support::storage::with_transaction(|| {
      assert_eq!(
        polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
        expected
      );
      polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(Ok::<_, DispatchError>(()))
    })
    .expect("verification uses the oracle FRAME depth");
    Ok(())
  }

  /// Complete bound snapshot loader, with the caller's already-loaded header.
  /// Admission/pricing and the ordinary Actor probe retain separate owners.
  #[benchmark(pov_mode = Measured)]
  fn behavior_source_snapshot(c: Linear<0, 5>) -> Result<(), BenchmarkError> {
    let (actor_id, header, _, _) = prepare_behavior_source_snapshot::<T>(c)?;
    let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    #[block]
    {
      let source = Pallet::<T>::load_step_behavior_policy(actor_id, &header)
        .expect("component source authenticates");
      assert_eq!(source.is_some(), c != 0);
      if let Some(source) = source {
        assert_eq!(source.monitor.is_some(), c >= 2);
        core::hint::black_box(source);
      }
    }
    assert_eq!(
      polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
      root
    );
    Ok(())
  }

  /// Maximum-policy Service inspection: the complete policy and monitor source load that Service
  /// performs once per round, measured on the same live maximum-geometry fixture as the
  /// policy-bearing Close owner so both owners describe the same Contract shape. This is the host
  /// price behind `maximum_behavior_service_inspection_weight`.
  #[benchmark(pov_mode = Measured)]
  fn behavior_service_inspection() -> Result<(), BenchmarkError> {
    let source = prepare_behavior_source_snapshot_in_domain::<T>(4, false, ActorType::User, false)?;
    let actor_id = source.actor_id;
    let header = source.header;
    let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    #[block]
    {
      let policy = Pallet::<T>::load_step_behavior_policy(actor_id, &header)
        .expect("maximum policy source authenticates")
        .expect("maximum policy source exists");
      assert!(policy.monitor.is_some());
      core::hint::black_box(policy);
    }
    assert_eq!(
      polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
      root
    );
    Ok(())
  }

  /// Cold policy authentication and context used by Service, without monitor/Run inspection.
  /// The caller's header, host prices and complete Service admission remain separate owners.
  #[benchmark(pov_mode = Measured)]
  fn behavior_service_policy_context(c: Linear<0, 5>) -> Result<(), BenchmarkError> {
    let (actor_id, header, _, _) = prepare_behavior_source_snapshot::<T>(c)?;
    let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    #[block]
    {
      let context = Pallet::<T>::benchmark_behavior_service_policy_context(actor_id, &header)
        .expect("component policy authenticates");
      assert_eq!(context.is_some(), c != 0);
      core::hint::black_box(context);
    }
    assert_eq!(
      polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
      root
    );
    Ok(())
  }

  /// First policy installation: absent, current-outcome, accumulated, configured-maximum policy.
  /// Includes compile/binding/episode/publication, not caller admission, ordinary geometry or holds.
  #[benchmark(extra, pov_mode = Measured)]
  fn behavior_policy_installation(c: Linear<0, 3>, r: Linear<0, 1>) -> Result<(), BenchmarkError> {
    let (actor_id, _, _, _) = prepare_behavior_source_snapshot::<T>(c)?;
    let (contract, admission) = Pallet::<T>::load_admitted_contract_geometry(actor_id)
      .expect("prepared installation geometry reconstructs");
    let semantic = ActorSemanticStates::<T>::get(actor_id);
    let head = ActorContractHeads::<T>::get(actor_id);
    let expected_policy = ActorBehaviorPolicies::<T>::take(actor_id);
    ActorBehaviorMonitors::<T>::remove(actor_id);
    let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    #[block]
    {
      polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
        Pallet::<T>::benchmark_install_contract_behavior_state(actor_id, &contract, &admission)
          .expect("first installation compiles and binds");
        if r == 1 {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(())
        } else {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(())
        }
      });
    }
    assert_eq!(ActorSemanticStates::<T>::get(actor_id), semantic);
    assert_eq!(ActorContractHeads::<T>::get(actor_id), head);
    if r == 1 {
      assert!(!ActorBehaviorPolicies::<T>::contains_key(actor_id));
      assert!(!ActorBehaviorMonitors::<T>::contains_key(actor_id));
      assert_eq!(
        polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
        root
      );
    } else {
      assert_eq!(ActorBehaviorPolicies::<T>::get(actor_id), expected_policy);
      assert_eq!(ActorBehaviorMonitors::<T>::contains_key(actor_id), c >= 2);
      if let Some(policy) = expected_policy {
        let binding = BehaviorPolicyBinding {
          semantic_contract_id: admission.semantic_contract_id,
          admission_identity: admission.admission_identity,
        };
        let episode = (
          b"DEOS_ACTOR_BEHAVIOR_EPISODE",
          actor_id,
          policy.episode_started_at_generation,
          admission.semantic_contract_id,
        )
          .using_encoded(frame::hashing::blake2_256);
        let expected = if c >= 2 {
          Some(ActorBehaviorMonitor {
            state: policy
              .plan
              .bind(&policy.expression, binding)
              .unwrap()
              .begin_episode(episode)
              .expect("accumulated installation starts an episode"),
            clean_cycle: None,
          })
        } else {
          None
        };
        assert_eq!(ActorBehaviorMonitors::<T>::get(actor_id), expected);
      } else {
        assert_eq!(
          polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
          root
        );
      }
    }
    Ok(())
  }

  struct RetainedServiceFinalizerSource<T: Config> {
    actor: ActorRef,
    state: ActiveActorStateOf<T>,
    admission: ActorAdmissionCertificateOf<T>,
    destruction: CloseDestructionFixture<T>,
  }

  fn prepare_retained_service_finalizer<T: Config>()
  -> Result<RetainedServiceFinalizerSource<T>, BenchmarkError> {
    let (actor_id, _, _) = prepare_geometry_behavior_authentication::<T>(5)?;
    let ActorSemanticState::Active(semantic) = ActorSemanticStates::<T>::get(actor_id).unwrap()
    else {
      panic!("paid prefix keeps Active authority")
    };
    let (contract, admission) = Pallet::<T>::load_admitted_contract_geometry(actor_id).unwrap();
    let actor = ActorRef {
      actor_id,
      generation: semantic.generation,
    };
    let state = ActiveActorState {
      identity: semantic.identity,
      hot: semantic.hot,
      contract,
      run_state: ActorRunStateStore::<T>::get(actor_id),
    };
    assert_eq!(state.hot.cycle_state, CycleState::Running);
    assert_eq!(state.run_state.as_ref().unwrap().cursor, 1);
    assert!(
      ActorBehaviorMonitors::<T>::get(actor_id)
        .unwrap()
        .clean_cycle
        .is_some()
    );
    assert!(ActorProcesses::<T>::contains_key(actor_id));
    assert!(ServiceNodes::<T>::contains_key(actor_id));
    let mut destruction = prepare_step_close_expectation::<T>(
      actor_id,
      &state,
      &state.contract,
      Zero::zero(),
      Zero::zero(),
      None,
    );
    let ActorTask::Transfer { to, asset, .. } = &state.contract.steps[0].task else {
      panic!("real prefix is the authored Transfer")
    };
    destruction.committed_credit = Some((to.clone(), *asset, T::AssetOps::balance(to, *asset)));
    Ok(RetainedServiceFinalizerSource {
      actor,
      state,
      admission,
      destruction,
    })
  }

  /// c0..8 keep detached User/System phases. c9 is the retained-Service intrinsic+retirement
  /// joint: retirement must remain in the same caller transaction, not after an intermediate commit.
  /// Resource qualification, source loading and ordinary detachment stay excluded.
  #[benchmark(extra, pov_mode = Measured)]
  fn close_finalize_policy(c: Linear<0, 9>, r: Linear<0, 1>) -> Result<(), BenchmarkError> {
    let (actor_id, state, admission, fixture, retirement) = if c == 9 {
      let source = prepare_retained_service_finalizer::<T>()?;
      (
        source.actor.actor_id,
        source.state,
        source.admission,
        source.destruction,
        Some(source.actor),
      )
    } else {
      let actor_type = if c < 6 {
        ActorType::User
      } else {
        ActorType::System
      };
      let source = prepare_behavior_source_snapshot_in_domain::<T>(
        c % 3 + 3,
        true,
        actor_type,
        (3..6).contains(&c),
      )?;
      let actor_id = source.actor_id;
      let fixture = source.destruction.expect("temporal destruction witness");
      Pallet::<T>::reconcile_actor_state_hold_with_authority(actor_id)?;
      let ActorSemanticState::Active(semantic) = ActorSemanticStates::<T>::get(actor_id).unwrap()
      else {
        panic!("active detached finalizer source")
      };
      let contract =
        Pallet::<T>::load_contract_geometry_with_admission(actor_id, &semantic.admission)
          .expect("detached policy geometry authenticates");
      let state = ActiveActorState {
        identity: semantic.identity.clone(),
        hot: semantic.hot,
        contract,
        run_state: ActorRunStateStore::<T>::get(actor_id),
      };
      assert!(!ActorProcesses::<T>::contains_key(actor_id));
      assert!(!ServiceNodes::<T>::contains_key(actor_id));
      assert!(!DeadlineHandles::<T>::contains_key(actor_id));
      assert!(!TriggerDeadlineHandles::<T>::contains_key(actor_id));
      assert_eq!(
        ActorStateHolds::<T>::contains_key(actor_id),
        actor_type == ActorType::User
      );
      (actor_id, state, semantic.admission, fixture, None)
    };
    let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    #[block]
    {
      polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
        if let Some(actor) = retirement {
          Pallet::<T>::benchmark_finalize_actor_from_consumed_state(
            actor_id,
            state,
            admission,
            CloseReason::OwnerInitiated,
          )
          .expect("retained paid-source intrinsic finalization completes");
          Pallet::<T>::retire_service_member(actor)
            .expect("caller retirement stays atomic with finalization");
        } else {
          Pallet::<T>::benchmark_finalize_actor_loaded_state(actor_id, state, admission)
            .expect("loaded policy finalizer completes without an optional price proxy");
        }
        if r == 1 {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(())
        } else {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(())
        }
      });
    }
    if r == 1 {
      assert_eq!(
        polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
        root
      );
    } else {
      assert_close_destruction::<T>(&fixture);
      assert!(!ActorBehaviorPolicies::<T>::contains_key(actor_id));
      assert!(!ActorBehaviorMonitors::<T>::contains_key(actor_id));
    }
    Ok(())
  }

  fn cycle_completion_behavior_expression<T: Config>() -> Result<CloseWhenOf<T>, BenchmarkError> {
    let mut expression = maximum_behavior_expression::<T>()?;
    // Keep the late completion clause independent: it must not subsume another clause.
    expression.clauses[2] = [
      BehaviorMetric::PreconditionPassStreak,
      BehaviorMetric::ActionFailureTotal,
      BehaviorMetric::ActionFailureStreak,
      BehaviorMetric::CycleCleanTotal,
    ]
    .into_iter()
    .map(|metric| BehaviorAtom {
      metric,
      threshold: u32::MAX,
    })
    .collect::<Vec<_>>()
    .try_into()
    .expect("four canonical atoms fit");
    // Empty cycles can complete, but cannot invent Action or clean-economic observations.
    expression.clauses[3] = vec![BehaviorAtom {
      metric: BehaviorMetric::CycleCompletedTotal,
      threshold: 1,
    }]
    .try_into()
    .expect("one completion atom fits");
    Ok(expression)
  }

  fn zero_step_policy_expression<T: Config>(q: u32) -> Result<CloseWhenOf<T>, BenchmarkError> {
    if q == 0 {
      return maximum_behavior_expression::<T>();
    }
    if q == 1 {
      return cycle_completion_behavior_expression::<T>();
    }
    let atom = |metric, threshold| BehaviorAtom { metric, threshold };
    let clauses = match q {
      2 => vec![vec![atom(BehaviorMetric::ActionSuccessTotal, 1)]],
      3 => vec![vec![atom(BehaviorMetric::CycleCompletedTotal, 1)]],
      4 => vec![vec![atom(BehaviorMetric::CycleCleanTotal, 1)]],
      5 => vec![
        vec![atom(BehaviorMetric::CycleCompletedTotal, 1)],
        vec![atom(BehaviorMetric::CycleCleanTotal, 1)],
      ],
      6 => vec![vec![atom(BehaviorMetric::CycleCompletedTotal, 2)]],
      7 => vec![
        vec![atom(BehaviorMetric::ActionSuccessTotal, 2)],
        vec![atom(BehaviorMetric::CycleCompletedTotal, 1)],
      ],
      _ => return Err(BenchmarkError::Stop("unknown zero-Step policy category")),
    };
    let expression = CloseWhen {
      clauses: clauses
        .into_iter()
        .map(|clause| clause.try_into())
        .collect::<Result<Vec<_>, _>>()
        .map_err(|_| BenchmarkError::Stop("policy atoms exceed host bounds"))?
        .try_into()
        .map_err(|_| BenchmarkError::Stop("policy clauses exceed host bounds"))?,
    };
    expression
      .validate()
      .map_err(|_| BenchmarkError::Stop("policy category must be canonical"))?;
    Ok(expression)
  }

  fn prepare_zero_step_policy_source<T: Config>(
    c: u32,
    closes: bool,
  ) -> Result<
    (
      ZeroStepHeaderFixture<T>,
      ActiveActorStateOf<T>,
      ActorAdmissionCertificateOf<T>,
    ),
    BenchmarkError,
  > {
    prepare_zero_step_policy_source_with_expression::<T>(
      c,
      zero_step_policy_expression::<T>(u32::from(closes))?,
    )
  }

  fn prepare_zero_step_policy_source_with_expression<T: Config>(
    c: u32,
    expression: CloseWhenOf<T>,
  ) -> Result<
    (
      ZeroStepHeaderFixture<T>,
      ActiveActorStateOf<T>,
      ActorAdmissionCertificateOf<T>,
    ),
    BenchmarkError,
  > {
    prepare_zero_step_policy_source_with_peers::<T>(c, expression, 2)
  }

  fn prepare_zero_step_policy_source_with_peers<T: Config>(
    c: u32,
    expression: CloseWhenOf<T>,
    retained_peers: u32,
  ) -> Result<
    (
      ZeroStepHeaderFixture<T>,
      ActiveActorStateOf<T>,
      ActorAdmissionCertificateOf<T>,
    ),
    BenchmarkError,
  > {
    let actor_type = if c < 4 {
      ActorType::User
    } else {
      ActorType::System
    };
    let source = match c % 4 {
      0 => ZeroStepHeaderSource::Manual,
      1 => ZeroStepHeaderSource::AddressEvent,
      2 => ZeroStepHeaderSource::AtTimeDue,
      _ => ZeroStepHeaderSource::CadencedDue,
    };
    if retained_peers > 2 {
      return Err(BenchmarkError::Stop(
        "zero-Step topology supports zero to two peers",
      ));
    }
    let mut fixture = prepare_zero_step_header::<T>(actor_type, source, false);
    let actor_id = fixture.actor.actor_id;
    let kind = ServiceNodes::<T>::get(actor_id).unwrap().kind;
    let semantic = Pallet::<T>::load_service_actor_semantic_state(fixture.actor, kind).unwrap();
    // Shrink only ordinary followers before policy staging, through the public lifecycle owner.
    for (peer, _) in fixture.peers.iter().skip(retained_peers as usize) {
      Pallet::<T>::close_actor(RawOrigin::Root.into(), peer.actor_id)?;
      assert!(!ActorSemanticStates::<T>::contains_key(peer.actor_id));
      assert!(!ServiceNodes::<T>::contains_key(peer.actor_id));
    }
    assert_eq!(
      Pallet::<T>::load_service_actor_semantic_state(fixture.actor, kind).unwrap(),
      semantic
    );
    assert_eq!(ServiceHeader::<T>::get().count, retained_peers + 1);
    assert_eq!(ServiceHeader::<T>::get().cursor, Some(fixture.actor));
    let node = ServiceNodes::<T>::get(actor_id).unwrap();
    match retained_peers {
      0 => {
        assert_eq!(node.previous, fixture.actor);
        assert_eq!(node.next, fixture.actor);
      }
      1 => {
        assert_eq!(node.previous, node.next);
        assert_ne!(node.next, fixture.actor);
      }
      _ => {
        assert_ne!(node.previous, node.next);
        assert_ne!(node.next, fixture.actor);
      }
    }
    fixture.successor = node.next;
    fixture.peers = zero_step_peers_after_removal::<T>(fixture.actor);
    fixture.identity_count = ActorIdentityCount::<T>::get();
    fixture.active_count = ActiveActorCount::<T>::get();
    let (mut state, base) = consume_zero_step_opening::<T>(actor_id);
    state.contract.close_when = Some(expression);
    stage_behavior_source_snapshot::<T>(
      actor_id,
      2,
      CycleState::Idle,
      state.contract.clone(),
      base,
    )?;
    Pallet::<T>::reconcile_actor_state_hold_with_authority(actor_id)?;
    let ActorSemanticState::Active(semantic) = ActorSemanticStates::<T>::get(actor_id).unwrap()
    else {
      panic!("active zero-Step source")
    };
    let admission = semantic.admission;
    let fee = Pallet::<T>::pipeline_fee_for_actor(actor_id, actor_type)
      .map_err(|_| BenchmarkError::Stop("stored pipeline quote missing"))?
      .total_fee;
    assert_eq!(fee, fixture.pipeline_fee);
    assert_eq!(fee.is_zero(), actor_type == ActorType::System);
    Ok((fixture, state, admission))
  }

  /// Read-only caller prelude on family-relative full headers with the wide policy source.
  /// Shape/price qualification, transition, publication and transaction completion are separate.
  #[benchmark(extra, pov_mode = Measured)]
  fn zero_step_policy_source_authentication(c: Linear<0, 7>) -> Result<(), BenchmarkError> {
    let (fixture, state, admission) = prepare_zero_step_policy_source::<T>(c, false)?;
    let actor_id = fixture.actor.actor_id;
    assert_maximum_zero_step_header::<T>(actor_id, state.contract.trigger.family());
    let kind = ServiceNodes::<T>::get(actor_id)
      .expect("source has canonical Service residence")
      .kind;
    let expected = Pallet::<T>::load_service_actor_semantic_state(fixture.actor, kind)
      .expect("source semantic authority is coherent");
    let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    let semantic;
    #[block]
    {
      semantic =
        Pallet::<T>::authenticate_zero_step_service_source(fixture.actor, kind, &state, &admission)
          .expect("read-only caller authentication needs no optional price proxy");
    }
    assert_eq!(semantic, expected);
    assert_eq!(
      polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
      root,
    );
    let native = T::FeeNativeAssetId::get();
    assert_eq!(
      T::AssetOps::balance(&fixture.payer, native),
      fixture.payer_native_before
    );
    assert_eq!(
      T::AssetOps::balance(&T::FeeSink::get(), native),
      fixture.sink_native_before
    );
    assert_eq!(
      T::AssetOps::balance(&fixture.payer, fixture.asset),
      fixture.custody
    );
    Ok(())
  }

  /// Semantic publication on a prepared post-control image, not a committed Cycle boundary.
  /// Includes input clones and the writer's own transaction; no enclosing attempt transaction.
  #[benchmark(extra, pov_mode = Measured)]
  fn zero_step_policy_semantic_publication(c: Linear<0, 7>) -> Result<(), BenchmarkError> {
    use polkadot_sdk::frame_support::storage::{TransactionOutcome, with_transaction_unchecked};
    let (fixture, state, admission) = prepare_zero_step_policy_source::<T>(c, false)?;
    let actor = fixture.actor;
    assert_maximum_zero_step_header::<T>(actor.actor_id, state.contract.trigger.family());
    let kind = ServiceNodes::<T>::get(actor.actor_id).unwrap().kind;
    let now = frame_system::Pallet::<T>::block_number();
    // FRAME flushes this transient setup image before timing. No production prefix is committed.
    let (next, reason) = with_transaction_unchecked(|| {
      TransactionOutcome::Commit(
        Pallet::<T>::benchmark_zero_step_control(actor.actor_id, state, &admission, now)
          .expect("real intrinsic control supplies the replacement"),
      )
    });
    assert!(reason.is_none());
    assert!(!polkadot_sdk::frame_support::storage::transactional::is_transactional());
    let phase = Pallet::<T>::load_service_actor_semantic_state(actor, kind).unwrap();
    assert_eq!(next.identity.cycle_nonce, phase.identity.cycle_nonce + 1);
    assert_eq!(next.hot.cycle_state, CycleState::Idle);
    assert!(!next.hot.pending_signal);
    assert!(next.run_state.is_none());
    let root = || polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    let phase_root = root();
    let mut expected = phase;
    expected.identity = next.identity.clone();
    expected.hot = next.hot.clone();
    // Oracle and verification both use depth one; neither envelope is timed.
    let expected_root = with_transaction_unchecked(|| {
      ActorSemanticStates::<T>::insert(
        actor.actor_id,
        ActorSemanticState::Active(expected.clone()),
      );
      TransactionOutcome::Rollback(root())
    });
    assert_eq!(root(), phase_root);
    let hold_reason: T::RuntimeHoldReason = HoldReason::ActorState.into();
    let owner_hold = T::StateHoldCurrency::balance_on_hold(&hold_reason, &fixture.owner);
    #[block]
    {
      Pallet::<T>::try_store_service_control_state(
        actor,
        kind,
        next.identity.clone(),
        next.hot.clone(),
      )
      .expect("prepared semantic publication needs no price proxy");
    }
    assert!(!polkadot_sdk::frame_support::storage::transactional::is_transactional());
    with_transaction_unchecked(|| {
      assert_eq!(root(), expected_root);
      TransactionOutcome::Rollback(())
    });
    assert_eq!(
      Pallet::<T>::load_service_actor_semantic_state(actor, kind).unwrap(),
      expected
    );
    let native = T::FeeNativeAssetId::get();
    assert_eq!(
      T::AssetOps::balance(&fixture.payer, native),
      fixture.payer_native_before - fixture.pipeline_fee
    );
    assert_eq!(
      T::AssetOps::balance(&T::FeeSink::get(), native),
      fixture.sink_native_before + fixture.pipeline_fee
    );
    assert_eq!(
      T::AssetOps::balance(&fixture.payer, fixture.asset),
      fixture.custody
    );
    assert_eq!(
      T::StateHoldCurrency::balance_on_hold(&hold_reason, &fixture.owner),
      owner_hold
    );
    Ok(())
  }

  /// Read-only preparation on a setup-flushed post-control/publication image.
  /// The production wrapper's transaction guard and all physical placement remain separate.
  #[benchmark(extra, pov_mode = Measured)]
  fn zero_step_policy_placement_preparation(c: Linear<0, 7>) -> Result<(), BenchmarkError> {
    use crate::scheduler::PreparedIdleServicePlacement;
    use polkadot_sdk::frame_support::storage::{TransactionOutcome, with_transaction_unchecked};
    let (fixture, state, admission) = prepare_zero_step_policy_source::<T>(c, false)?;
    let actor = fixture.actor;
    assert_maximum_zero_step_header::<T>(actor.actor_id, state.contract.trigger.family());
    let kind = ServiceNodes::<T>::get(actor.actor_id).unwrap().kind;
    let now = frame_system::Pallet::<T>::block_number();
    let next = with_transaction_unchecked(|| {
      let (next, reason) =
        Pallet::<T>::benchmark_zero_step_control(actor.actor_id, state, &admission, now)
          .expect("genuine control supplies unlatched Idle");
      assert!(reason.is_none());
      Pallet::<T>::try_store_service_control_state(
        actor,
        kind,
        next.identity.clone(),
        next.hot.clone(),
      )
      .expect("semantic publication prepares the placement phase");
      TransactionOutcome::Commit(next)
    });
    assert!(!polkadot_sdk::frame_support::storage::transactional::is_transactional());
    let process = ActorProcesses::<T>::get(actor.actor_id).unwrap();
    let semantic = Pallet::<T>::load_service_actor_semantic_state(actor, kind).unwrap();
    assert_eq!(semantic.identity, next.identity);
    assert_eq!(semantic.hot, next.hot);
    assert_eq!(semantic.admission, admission);
    let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    let prepared;
    #[block]
    {
      prepared = Pallet::<T>::prepare_idle_service_placement(actor, &next, now)
        .expect("read-only preparation needs no optional prices");
    }
    match prepared {
      PreparedIdleServicePlacement::Disabled {
        process: cached,
        disablement,
      } => {
        assert!(next.contract.window.is_none());
        assert_eq!(cached, process);
        assert_eq!(disablement.cause, ProcessDisableCause::Protocol);
        assert_eq!(
          disablement.revival_authority,
          ProcessRevivalAuthority::Protocol
        );
        assert_eq!(disablement.basis, SuspendedProcessBasis::Idle);
      }
      PreparedIdleServicePlacement::Deadline { at } => {
        assert_eq!(
          Some(at),
          next.contract.window.map(|window| window.end + One::one())
        );
      }
      PreparedIdleServicePlacement::Parked { .. } => panic!("zero-Step cannot author Park"),
    }
    assert_eq!(
      polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
      root
    );
    assert!(!polkadot_sdk::frame_support::storage::transactional::is_transactional());
    let native = T::FeeNativeAssetId::get();
    assert_eq!(
      T::AssetOps::balance(&fixture.payer, native),
      fixture.payer_native_before - fixture.pipeline_fee
    );
    assert_eq!(
      T::AssetOps::balance(&T::FeeSink::get(), native),
      fixture.sink_native_before + fixture.pipeline_fee
    );
    assert_eq!(
      T::AssetOps::balance(&fixture.payer, fixture.asset),
      fixture.custody
    );
    Ok(())
  }

  /// Finishing plus an explicit caller FRAME transaction on a setup-flushed phase image.
  /// Deadline placement is already durable in setup; Disabled finishing owns its own unlink.
  #[benchmark(extra, pov_mode = Measured)]
  fn zero_step_policy_placement_finish(
    c: Linear<0, 7>,
    r: Linear<0, 1>,
    t: Linear<0, 2>,
  ) -> Result<(), BenchmarkError> {
    use crate::scheduler::PreparedIdleServicePlacement;
    use polkadot_sdk::frame_support::storage::{TransactionOutcome, with_transaction_unchecked};
    let (fixture, state, admission) =
      prepare_zero_step_policy_source_with_peers::<T>(c, zero_step_policy_expression::<T>(0)?, t)?;
    let actor = fixture.actor;
    assert_maximum_zero_step_header::<T>(actor.actor_id, state.contract.trigger.family());
    let kind = ServiceNodes::<T>::get(actor.actor_id).unwrap().kind;
    let now = frame_system::Pallet::<T>::block_number();
    let disabled = with_transaction_unchecked(|| {
      let (next, reason) =
        Pallet::<T>::benchmark_zero_step_control(actor.actor_id, state, &admission, now).unwrap();
      assert!(reason.is_none());
      Pallet::<T>::try_store_service_control_state(
        actor,
        kind,
        next.identity.clone(),
        next.hot.clone(),
      )
      .unwrap();
      let disabled = match Pallet::<T>::prepare_idle_service_placement(actor, &next, now).unwrap() {
        PreparedIdleServicePlacement::Disabled {
          process,
          disablement,
        } => Some((process, disablement)),
        PreparedIdleServicePlacement::Deadline { at } => {
          let destination =
            Pallet::<T>::plan_deadline_destination(actor, WakeupKey::Block(at)).unwrap();
          Pallet::<T>::transfer_service_member_to_deadline(actor, destination).unwrap();
          None
        }
        PreparedIdleServicePlacement::Parked { .. } => panic!("zero-Step cannot author Park"),
      };
      TransactionOutcome::Commit(disabled)
    });
    assert!(!polkadot_sdk::frame_support::storage::transactional::is_transactional());
    let phase_process = ActorProcesses::<T>::get(actor.actor_id).unwrap();
    assert_ne!(phase_process.last_attempted, Some(now));
    let phase_semantic = ActorSemanticStates::<T>::get(actor.actor_id);
    let phase_node = ServiceNodes::<T>::get(actor.actor_id);
    let phase_header = ServiceHeader::<T>::get();
    let root = || polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    let phase_root = root();
    let rollback_root = with_transaction_unchecked(|| TransactionOutcome::Rollback(root()));
    let mut expected_process = phase_process;
    expected_process.last_attempted = Some(now);
    if let Some((_, disablement)) = disabled {
      expected_process.status = ProcessStatus::Disabled(disablement);
      expected_process.residence = None;
    } else {
      assert!(matches!(
        phase_process.residence,
        Some(ProcessResidence::Deadline { .. })
      ));
    }
    let mut expected_header = phase_header;
    if disabled.is_some() {
      assert_eq!(phase_header.count, t + 1);
      assert_eq!(phase_header.cursor, Some(actor));
      expected_header = if t == 0 {
        ServiceHeaderRecord::default()
      } else {
        let mut header = phase_header;
        header.count -= 1;
        header.cursor = Some(fixture.successor);
        header
      };
    }
    // Independent bounded ring/process oracle, at the same FRAME depth as the measured caller.
    let expected_root = with_transaction_unchecked(|| {
      if disabled.is_some() {
        let node = phase_node.expect("Disabled phase still owns Service");
        match t {
          0 => {
            assert_eq!(node.previous, actor);
            assert_eq!(node.next, actor);
          }
          1 => {
            assert_eq!(node.previous, node.next);
            let mut peer = ServiceNodes::<T>::get(node.next.actor_id).unwrap();
            peer.previous = node.next;
            peer.next = node.next;
            ServiceNodes::<T>::insert(node.next.actor_id, peer);
          }
          _ => {
            assert_ne!(node.previous, node.next);
            let mut previous = ServiceNodes::<T>::get(node.previous.actor_id).unwrap();
            let mut next = ServiceNodes::<T>::get(node.next.actor_id).unwrap();
            previous.next = node.next;
            next.previous = node.previous;
            ServiceNodes::<T>::insert(node.previous.actor_id, previous);
            ServiceNodes::<T>::insert(node.next.actor_id, next);
          }
        }
        ServiceNodes::<T>::remove(actor.actor_id);
        ServiceHeader::<T>::put(expected_header);
      }
      ActorProcesses::<T>::insert(actor.actor_id, expected_process);
      TransactionOutcome::Rollback(root())
    });
    assert_eq!(root(), phase_root);
    let hold_reason: T::RuntimeHoldReason = HoldReason::ActorState.into();
    let owner_hold = T::StateHoldCurrency::balance_on_hold(&hold_reason, &fixture.owner);
    let result;
    #[block]
    {
      result = with_transaction_unchecked(|| {
        let result = Pallet::<T>::finish_idle_service_placement(actor, now, disabled);
        if r == 1 {
          TransactionOutcome::Rollback(result)
        } else {
          TransactionOutcome::Commit(result)
        }
      });
    }
    result.expect("prepared finishing needs no optional prices");
    assert!(!polkadot_sdk::frame_support::storage::transactional::is_transactional());
    // Matching the oracle depth accounts for FRAME transaction-level bookkeeping in roots.
    with_transaction_unchecked(|| {
      assert_eq!(root(), if r == 1 { rollback_root } else { expected_root });
      TransactionOutcome::Rollback(())
    });
    assert_eq!(
      ActorProcesses::<T>::get(actor.actor_id),
      Some(if r == 1 {
        phase_process
      } else {
        expected_process
      })
    );
    assert_eq!(
      ActorSemanticStates::<T>::get(actor.actor_id),
      phase_semantic
    );
    if r == 0 || disabled.is_none() {
      assert!(!ServiceNodes::<T>::contains_key(actor.actor_id));
      assert_eq!(ServiceHeader::<T>::get(), expected_header);
      assert_eq!(expected_header.count, t);
      assert_eq!(expected_header.cursor, (t > 0).then_some(fixture.successor));
      for (peer, expected) in &fixture.peers {
        assert_eq!(
          (
            ServiceNodes::<T>::get(peer.actor_id),
            ActorProcesses::<T>::get(peer.actor_id),
            ActorSemanticStates::<T>::get(peer.actor_id)
          )
            .encode(),
          *expected
        );
      }
    } else {
      assert_eq!(ServiceNodes::<T>::get(actor.actor_id), phase_node);
      assert_eq!(ServiceHeader::<T>::get(), phase_header);
    }
    let native = T::FeeNativeAssetId::get();
    assert_eq!(
      T::AssetOps::balance(&fixture.payer, native),
      fixture.payer_native_before - fixture.pipeline_fee
    );
    assert_eq!(
      T::AssetOps::balance(&T::FeeSink::get(), native),
      fixture.sink_native_before + fixture.pipeline_fee
    );
    assert_eq!(
      T::AssetOps::balance(&fixture.payer, fixture.asset),
      fixture.custody
    );
    assert_eq!(
      T::StateHoldCurrency::balance_on_hold(&hold_reason, &fixture.owner),
      owner_hold
    );
    Ok(())
  }

  // Component-only source: policy is staged while Idle, never rebound after the paid prefix.
  // 0=absent Idle, 1=current/no monitor Idle, 2=clean/zero counters Idle,
  // 3=clean/zero counters Running, 4=accumulated/no clean Running, 5=maximum clean Running.
  fn prepare_geometry_behavior_authentication<T: Config>(
    case: u32,
  ) -> Result<(ActorId, ActorContractHeaderOf<T>, Option<CloseWhenOf<T>>), BenchmarkError> {
    let count = T::MaxContractSteps::get();
    if case > 5 || count < 3 {
      return Err(BenchmarkError::Stop(
        "authentication source needs a known class and successor",
      ));
    }
    let profile = ReachableOpeningProfile::UserTransferHeaderMax;
    if case == 0 {
      let (id, actual_count) = prepare_reachable_opening_with_successor::<T>(
        count.saturating_sub(1).div_ceil(MAX_STEPS_PER_TAIL_CHUNK),
        profile,
        false,
      )?;
      assert_eq!(actual_count, count);
      let header = ActorContractHeads::<T>::get(id).unwrap().header;
      assert!(!header.has_close_when);
      assert!(!ActorRunStateStore::<T>::contains_key(id));
      return Ok((id, header, None));
    }
    let expression = if case == 5 {
      maximum_behavior_expression::<T>()?
    } else {
      CloseWhen {
        clauses: vec![
          vec![BehaviorAtom {
            metric: if matches!(case, 2 | 3) {
              BehaviorMetric::CycleCleanTotal
            } else {
              BehaviorMetric::ActionSuccessTotal
            },
            threshold: if case == 4 { u32::MAX } else { 1 },
          }]
          .try_into()
          .expect("one atom fits"),
        ]
        .try_into()
        .expect("one clause fits"),
      }
    };
    let source = prepare_step_policy_source::<T>(profile, ActorType::User, expression)?;
    let id = source.actor.actor_id;
    assert_eq!(source.state.hot.cycle_state, CycleState::Idle);
    assert_eq!(source.state.identity.cycle_nonce, 0);
    assert!(!ActorRunStateStore::<T>::contains_key(id));
    let head = ActorContractHeads::<T>::get(id).unwrap();
    let tails = ActorContractTailChunks::<T>::iter_prefix(id).collect::<Vec<_>>();
    let policy = ActorBehaviorPolicies::<T>::get(id).unwrap();
    if case >= 3 {
      let ActorTask::Transfer { to, asset, .. } = source.plan.loaded_step.step.clone().task else {
        panic!("authored first Step is a Transfer")
      };
      let payer = &source.state.identity.sovereign_account;
      let native = T::FeeNativeAssetId::get();
      assert_ne!(asset, native);
      let credit_before = T::AssetOps::balance(&to, asset);
      let custody_before = T::AssetOps::balance(payer, asset);
      let payer_before = T::AssetOps::balance(payer, native);
      let sink_before = T::AssetOps::balance(&T::FeeSink::get(), native);
      let pipeline = Pallet::<T>::pipeline_fee_for_actor(id, ActorType::User)
        .unwrap()
        .total_fee;
      let Some(ProcessResidence::Service(kind)) = ActorProcesses::<T>::get(id).unwrap().residence
      else {
        panic!("Idle source has Service residence")
      };
      let step = source.plan.loaded_step.step.clone();
      let now = frame_system::Pallet::<T>::block_number();
      let effect = polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
        let effect = execute_transfer_policy_progression::<T>(
          source.actor,
          kind,
          source.state.clone(),
          source.plan,
          &source.admission,
          now,
        );
        polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(effect)
      });
      let action = Pallet::<T>::maximum_current_action_fee(
        ActorType::User,
        &step,
        ActorStepResourceEnvelope {
          control: Weight::zero(),
          effect,
        },
      )
      .unwrap()
      .total_fee;
      let paid = pipeline.checked_add(&action).unwrap();
      assert!(!paid.is_zero());
      assert_eq!(payer_before - T::AssetOps::balance(payer, native), paid);
      assert_eq!(
        T::AssetOps::balance(&T::FeeSink::get(), native) - sink_before,
        paid
      );
      let credited = T::AssetOps::balance(&to, asset) - credit_before;
      assert!(!credited.is_zero());
      assert_eq!(
        custody_before - T::AssetOps::balance(payer, asset),
        credited
      );
      let run = ActorRunStateStore::<T>::get(id).unwrap();
      assert_eq!(run.cursor, 1);
      assert_eq!(run.cumulative_outcomes.committed_effectful_tasks, 1);
      assert_eq!(
        Pallet::<T>::actor_hot(id).unwrap().cycle_state,
        CycleState::Running
      );
    }
    assert_eq!(ActorContractHeads::<T>::get(id).as_ref(), Some(&head));
    assert_eq!(
      ActorContractTailChunks::<T>::iter_prefix(id).collect::<Vec<_>>(),
      tails
    );
    assert_eq!(ActorBehaviorPolicies::<T>::get(id).as_ref(), Some(&policy));
    assert_eq!(
      Pallet::<T>::load_admitted_contract_geometry(id).unwrap().0,
      source.contract
    );
    let context = Pallet::<T>::behavior_control_weight_context(&policy).unwrap();
    assert_eq!(context.requires_clean_cycle, matches!(case, 2 | 3 | 5));
    if matches!(case, 2 | 3) {
      assert_eq!(context.counter_slots, 0);
    }
    if case == 5 {
      assert_eq!(
        policy.encoded_size(),
        ActorBehaviorPolicyOf::<T>::max_encoded_len()
      );
      assert_eq!(
        ActorBehaviorMonitors::<T>::get(id).unwrap().encoded_size(),
        ActorBehaviorMonitor::max_encoded_len()
      );
    }
    Ok((id, head.header, source.contract.close_when))
  }

  /// Only conditional geometry policy/monitor authentication. Header load, returned-expression
  /// destruction and the caller transaction are outside; staged sources do not prove admission.
  #[benchmark(extra, pov_mode = Measured)]
  fn geometry_behavior_authentication(c: Linear<0, 5>) -> Result<(), BenchmarkError> {
    let (id, header, expected) = prepare_geometry_behavior_authentication::<T>(c)?;
    let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    let actual;
    #[block]
    {
      actual = Pallet::<T>::benchmark_geometry_behavior_authentication(id, &header);
    }
    assert_eq!(actual, Some(expected));
    assert_eq!(
      polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
      root
    );
    Ok(())
  }

  struct BehaviorClosingResetSource<T: Config> {
    actor_id: ActorId,
    admission: ActorAdmissionCertificateOf<T>,
    successor: ActorSemanticRecordOf<T>,
    monitor: Option<ActorBehaviorMonitor>,
    clean: bool,
  }

  // Derive the caller's clean successor from real inner cancellation, then restore the paid
  // source. This trial is not detached-finalizer admission and never rebinds Run authority.
  fn prepare_behavior_closing_reset<T: Config>(
    case: u32,
  ) -> Result<BehaviorClosingResetSource<T>, BenchmarkError> {
    let source_case = match case {
      0 => 4,
      1 => 3,
      2 => 5,
      _ => return Err(BenchmarkError::Stop("unknown Closing-reset source")),
    };
    let (actor_id, _, _) = prepare_geometry_behavior_authentication::<T>(source_case)?;
    let ActorSemanticState::Active(semantic) = ActorSemanticStates::<T>::get(actor_id).unwrap()
    else {
      panic!("paid source remains Active")
    };
    let (contract, admission) = Pallet::<T>::load_admitted_contract_geometry(actor_id).unwrap();
    let state = ActiveActorState {
      identity: semantic.identity.clone(),
      hot: semantic.hot.clone(),
      contract,
      run_state: ActorRunStateStore::<T>::get(actor_id),
    };
    assert_eq!(state.hot.cycle_state, CycleState::Running);
    let clean = ActorBehaviorPolicies::<T>::get(actor_id)
      .unwrap()
      .plan
      .requires_clean_cycle();
    let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    let (successor, monitor) = polkadot_sdk::frame_support::storage::with_transaction(|| {
      let result = Pallet::<T>::cancel_run_internal_loaded(
        actor_id,
        &state.identity,
        CancellationReason::Closing(CloseReason::OwnerInitiated),
        None,
        crate::execution::LoadedCancellationContext::ConsumedFrame {
          state: state.clone(),
          admission: admission.clone(),
        },
      )
      .map(|cancelled| {
        assert!(cancelled);
        let ActorSemanticState::Active(successor) =
          ActorSemanticStates::<T>::get(actor_id).unwrap()
        else {
          panic!("inner Closing cancellation retains Active semantics until retirement")
        };
        (successor, ActorBehaviorMonitors::<T>::get(actor_id))
      });
      polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(result)
    })?;
    assert_eq!(
      polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
      root
    );
    assert_eq!(ActorRunStateStore::<T>::get(actor_id), state.run_state);
    assert!(ActorProcesses::<T>::contains_key(actor_id));
    assert_eq!(successor.admission, admission);
    if clean {
      assert_eq!(successor.hot.cycle_state, CycleState::Idle);
      assert_eq!(
        successor.identity.cycle_nonce,
        state.run_state.unwrap().cycle_nonce
      );
      assert!(monitor.as_ref().unwrap().clean_cycle.is_none());
    } else {
      // The early-return branch does not use the supplied successor identity/Hot.
      assert_eq!(successor, semantic);
      assert_eq!(monitor, ActorBehaviorMonitors::<T>::get(actor_id));
    }
    Ok(BehaviorClosingResetSource {
      actor_id,
      admission,
      successor,
      monitor,
      clean,
    })
  }

  // Expected intermediate phase only: matching FRAME depth, no Run removal or caller events.
  fn expected_behavior_closing_reset_root<T: Config>(
    source: &BehaviorClosingResetSource<T>,
  ) -> Vec<u8> {
    polkadot_sdk::frame_support::storage::with_transaction(|| {
      if source.clean {
        ActorBehaviorMonitors::<T>::insert(source.actor_id, source.monitor.as_ref().unwrap());
        ActorSemanticStates::<T>::insert(
          source.actor_id,
          ActorSemanticState::Active(source.successor.clone()),
        );
      }
      polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(Ok::<_, DispatchError>(
        polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
      ))
    })
    .unwrap()
  }

  /// Closing clean-reset occurrence only, including its own head/policy/monitor authentication.
  /// Run removal, events, caller transaction, ordinary detachment and finalizer remain excluded.
  #[benchmark(extra, pov_mode = Measured)]
  fn behavior_closing_reset(c: Linear<0, 2>) -> Result<(), BenchmarkError> {
    let source = prepare_behavior_closing_reset::<T>(c)?;
    let expected = expected_behavior_closing_reset_root::<T>(&source);
    #[block]
    {
      Pallet::<T>::clear_behavior_cycle_for_cancellation(
        source.actor_id,
        &source.admission,
        &source.successor.identity,
        &source.successor.hot,
        true,
      )?;
    }
    polkadot_sdk::frame_support::storage::with_transaction(|| {
      assert_eq!(
        polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
        expected
      );
      polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(Ok::<_, DispatchError>(()))
    })?;
    Ok(())
  }

  // Supplied Contract values only: maximum body/Task/predicate input, never published authority.
  fn prepare_full_body_behavior_context<T: Config>(
    policy: u32,
  ) -> Result<(ActorContractOf<T>, Option<BehaviorControlWeightContext>), BenchmarkError> {
    if policy > 2 || T::MaxContractSteps::get() == 0 || T::MaxRetryAttempts::get() == 0 {
      return Err(BenchmarkError::Stop(
        "full body needs supported policy and nonempty bounds",
      ));
    }
    let (_, asset, trigger, funding) = large_header_fields::<T>();
    let (_, precondition) =
      prepare_max_encoded_step_precondition::<T>(0, benchmark_predicate_capacity::<T>(), false)?;
    assert_eq!(
      precondition.predicate_count(),
      benchmark_predicate_capacity::<T>()
    );
    let step = Step {
      precondition: Some(precondition),
      task: maximum_encoded_control_task::<T>(asset),
      on_error: StepErrorPolicy::RetryLater {
        max_attempts: T::MaxRetryAttempts::get(),
      },
    };
    assert_eq!(step.task.encoded_size(), TaskOf::<T>::max_encoded_len());
    let start = frame_system::Pallet::<T>::block_number()
      .checked_add(&T::MaxExecutionDelayBlocks::get())
      .ok_or(BenchmarkError::Stop("full-body window start overflows"))?;
    let end = start
      .checked_add(&T::MinWindowLength::get())
      .ok_or(BenchmarkError::Stop("full-body window end overflows"))?;
    let contract = ActorContract {
      trigger,
      cooldown_blocks: T::MaxExecutionDelayBlocks::get().saturated_into(),
      window: Some(ScheduleWindow { start, end }),
      steps: vec![step; T::MaxContractSteps::get() as usize]
        .try_into()
        .map_err(|_| BenchmarkError::Stop("full body must fit configured bound"))?,
      funding,
      on_unfunded: OnUnfunded::Close,
      close_when: match policy {
        0 => None,
        1 => Some(zero_step_policy_expression::<T>(4)?),
        _ => Some(maximum_behavior_expression::<T>()?),
      },
      parked_balance_activation: None,
      auto_close_at_cycle_nonce: Some(T::MaxAutoCloseNonceHorizon::get()),
    };
    let expected = match &contract.close_when {
      None => None,
      Some(expression) => {
        let plan = expression
          .validate()
          .expect("canonical supplied expression")
          .compile(BehaviorPolicyBinding {
            semantic_contract_id: contract.semantic_contract_id(),
            admission_identity: [0; 32],
          })
          .expect("configured supplied policy compiles");
        Some(
          Pallet::<T>::behavior_control_weight_context(&ActorBehaviorPolicy {
            expression: expression.clone(),
            plan,
            episode_started_at_generation: 1,
          })
          .expect("supplied policy context exists"),
        )
      }
    };
    Ok((contract, expected))
  }

  /// One pure Contract-side compiler invocation. c0..7 retain zero-Step sources; c8 supplies
  /// the configured full body. No host price selection, stored policy load or public admission.
  #[benchmark(extra, pov_mode = Measured)]
  fn contract_behavior_context(c: Linear<0, 8>, p: Linear<0, 2>) -> Result<(), BenchmarkError> {
    let (fixture, contract, expected) = if c == 8 {
      let (contract, expected) = prepare_full_body_behavior_context::<T>(p)?;
      (None, contract, expected)
    } else {
      let (fixture, state, expected) = if p == 0 {
        let actor_type = if c < 4 {
          ActorType::User
        } else {
          ActorType::System
        };
        let family = match c % 4 {
          0 => ZeroStepHeaderSource::Manual,
          1 => ZeroStepHeaderSource::AddressEvent,
          2 => ZeroStepHeaderSource::AtTimeDue,
          _ => ZeroStepHeaderSource::CadencedDue,
        };
        let fixture = prepare_zero_step_header::<T>(actor_type, family, false);
        let (state, _) = consume_zero_step_opening::<T>(fixture.actor.actor_id);
        assert!(state.contract.close_when.is_none());
        (fixture, state, None)
      } else {
        let (fixture, state, _) = prepare_zero_step_policy_source::<T>(c, p == 2)?;
        let head = ActorContractHeads::<T>::get(fixture.actor.actor_id).unwrap();
        let source = Pallet::<T>::load_step_behavior_policy(fixture.actor.actor_id, &head.header)
          .unwrap()
          .unwrap();
        let expected = Pallet::<T>::behavior_control_weight_context(&source.policy).unwrap();
        (fixture, state, Some(expected))
      };
      assert_maximum_zero_step_header::<T>(fixture.actor.actor_id, state.contract.trigger.family());
      (Some(fixture), state.contract, expected)
    };
    let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    let context;
    #[block]
    {
      context = Pallet::<T>::benchmark_contract_behavior_control_weight_context(&contract);
    }
    assert_eq!(context, Some(expected));
    assert_eq!(
      polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
      root
    );
    if let Some(fixture) = fixture {
      let native = T::FeeNativeAssetId::get();
      assert_eq!(
        T::AssetOps::balance(&fixture.payer, native),
        fixture.payer_native_before
      );
      assert_eq!(
        T::AssetOps::balance(&T::FeeSink::get(), native),
        fixture.sink_native_before
      );
      assert_eq!(
        T::AssetOps::balance(&fixture.payer, fixture.asset),
        fixture.custody
      );
    }
    Ok(())
  }

  /// Authenticated zero-Step Opening/completion and candidate publication, with real collection
  /// from the retained envelope. This is not pricing, placement, destruction or late settlement.
  #[benchmark(extra, pov_mode = Measured)]
  fn zero_step_policy_control(
    c: Linear<0, 7>,
    q: Linear<0, 7>,
    r: Linear<0, 1>,
  ) -> Result<(), BenchmarkError> {
    let (fixture, state, admission) = prepare_zero_step_policy_source_with_expression::<T>(
      c,
      zero_step_policy_expression::<T>(q)?,
    )?;
    let actor_id = fixture.actor.actor_id;
    assert_maximum_zero_step_header::<T>(actor_id, state.contract.trigger.family());
    let header = ActorContractHeads::<T>::get(actor_id).unwrap().header;
    let source = Pallet::<T>::load_step_behavior_policy(actor_id, &header)
      .unwrap()
      .unwrap();
    assert_eq!(
      source.binding.admission_identity,
      admission.admission_identity
    );
    assert_eq!(
      source.binding.semantic_contract_id,
      state.contract.semantic_contract_id()
    );
    assert_eq!(
      source.policy.expression,
      state.contract.close_when.clone().unwrap()
    );
    let accumulated = matches!(q, 0 | 1 | 6 | 7);
    let clean = matches!(q, 0 | 1 | 4 | 5);
    assert_eq!(
      source.policy.plan.mode(),
      if accumulated {
        BehaviorTrackingMode::Accumulated
      } else {
        BehaviorTrackingMode::CurrentOutcome
      }
    );
    assert_eq!(source.policy.plan.requires_clean_cycle(), clean);
    assert_eq!(source.monitor.is_some(), accumulated || clean);
    assert!(
      source
        .monitor
        .as_ref()
        .is_none_or(|monitor| monitor.clean_cycle.is_none())
    );
    let original_state = state.clone();
    let now = frame_system::Pallet::<T>::block_number();
    let fee = fixture.pipeline_fee;
    let hold = ActorStateHolds::<T>::get(actor_id).map(|record| record.encode());
    let hold_reason: T::RuntimeHoldReason = HoldReason::ActorState.into();
    let owner_hold = T::StateHoldCurrency::balance_on_hold(&hold_reason, &fixture.owner);
    let source_ring = (
      ServiceHeader::<T>::get(),
      ServiceNodes::<T>::get(actor_id),
      ActorProcesses::<T>::get(actor_id),
      fixture
        .peers
        .iter()
        .map(|(peer, _)| {
          (
            ServiceNodes::<T>::get(peer.actor_id),
            ActorProcesses::<T>::get(peer.actor_id),
            ActorSemanticStates::<T>::get(peer.actor_id),
          )
        })
        .collect::<Vec<_>>(),
    )
      .encode();
    let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    let outcome;
    #[block]
    {
      outcome = polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
        let outcome = Pallet::<T>::benchmark_zero_step_control(actor_id, state, &admission, now)
          .expect("intrinsic zero-Step control needs no optional price proxy");
        if r == 1 {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(outcome)
        } else {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(outcome)
        }
      });
    }
    assert_eq!(
      outcome.1,
      (q % 2 == 1).then_some(CloseReason::BehaviorPolicySatisfied)
    );
    assert_eq!(
      outcome.0.identity.cycle_nonce,
      original_state.identity.cycle_nonce + 1
    );
    assert!(!outcome.0.hot.pending_signal);
    assert!(outcome.0.run_state.is_none());
    let paid = if r == 0 { fee } else { Zero::zero() };
    let native = T::FeeNativeAssetId::get();
    assert_eq!(
      T::AssetOps::balance(&fixture.payer, native),
      fixture.payer_native_before - paid
    );
    assert_eq!(
      T::AssetOps::balance(&T::FeeSink::get(), native),
      fixture.sink_native_before + paid
    );
    assert_eq!(
      T::AssetOps::balance(&fixture.payer, fixture.asset),
      fixture.custody
    );
    if r == 1 {
      assert_eq!(
        polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
        root
      );
    } else {
      let policy = ActorBehaviorPolicies::<T>::get(actor_id).unwrap();
      let monitor = ActorBehaviorMonitors::<T>::get(actor_id);
      assert_eq!(policy, source.policy);
      assert_eq!(
        policy.plan.metrics().len(),
        if q <= 1 {
          10
        } else if q == 5 || q == 7 {
          2
        } else {
          1
        }
      );
      assert_eq!(monitor.is_some(), accumulated || clean);
      let binding = BehaviorPolicyBinding {
        semantic_contract_id: admission.semantic_contract_id,
        admission_identity: admission.admission_identity,
      };
      let bound = policy
        .plan
        .bind(&policy.expression, binding)
        .expect("candidate binding remains valid");
      let episode = (
        b"DEOS_ACTOR_BEHAVIOR_EPISODE",
        actor_id,
        policy.episode_started_at_generation,
        admission.semantic_contract_id,
      )
        .using_encoded(frame::hashing::blake2_256);
      if let Some(monitor) = &monitor {
        for cap in policy.plan.metrics() {
          assert_eq!(
            bound
              .value(&monitor.state, episode, cap.metric)
              .expect("authenticated candidate value"),
            accumulated.then_some(u32::from(cap.metric == BehaviorMetric::CycleCompletedTotal)),
          );
        }
        assert!(monitor.clean_cycle.is_none());
        if !accumulated {
          assert_eq!(
            monitor.state,
            bound.begin_episode(episode).expect("zero-slot state")
          );
          assert_eq!(Some(monitor), source.monitor.as_ref());
        }
      }
      frame_system::Pallet::<T>::assert_has_event(
        Event::<T>::CycleSummary {
          actor_id,
          cycle_nonce: outcome.0.identity.cycle_nonce,
          result: CycleResult::Completed,
          outcomes: OutcomeTotals::default(),
        }
        .into(),
      );
    }
    assert_eq!(
      ActorStateHolds::<T>::get(actor_id).map(|record| record.encode()),
      hold
    );
    assert_eq!(
      T::StateHoldCurrency::balance_on_hold(&hold_reason, &fixture.owner),
      owner_hold
    );
    assert_eq!(
      ActorContractHeads::<T>::get(actor_id).unwrap().header,
      header
    );
    assert_eq!(
      Pallet::<T>::load_control_admission(actor_id),
      Some(admission.clone())
    );
    assert_eq!(
      (
        ServiceHeader::<T>::get(),
        ServiceNodes::<T>::get(actor_id),
        ActorProcesses::<T>::get(actor_id),
        fixture
          .peers
          .iter()
          .map(|(peer, _)| (
            ServiceNodes::<T>::get(peer.actor_id),
            ActorProcesses::<T>::get(peer.actor_id),
            ActorSemanticStates::<T>::get(peer.actor_id),
          ))
          .collect::<Vec<_>>(),
      )
        .encode(),
      source_ring
    );
    let pipeline_event: <T as frame_system::Config>::RuntimeEvent =
      Event::<T>::PipelineFeeCharged { actor_id, fee }.into();
    assert_eq!(
      frame_system::Pallet::<T>::events()
        .iter()
        .filter(|record| record.event == pipeline_event)
        .count(),
      usize::from(r == 0 && fixture.class.actor_type() == ActorType::User)
    );
    // Finish the prepared residence outside measurement; cleanup is not a Pipeline cost.
    let cleanup = if r == 1 { original_state } else { outcome.0 };
    Pallet::<T>::benchmark_finalize_actor_loaded_state(actor_id, cleanup, admission)?;
    Pallet::<T>::retire_service_member(fixture.actor).expect("prepared Service member retires");
    assert!(!ActorBehaviorPolicies::<T>::contains_key(actor_id));
    assert!(!ActorBehaviorMonitors::<T>::contains_key(actor_id));
    #[cfg(feature = "try-runtime")]
    Pallet::<T>::do_try_state().expect("prepared zero-Step control leaves coherent peers");
    Ok(())
  }

  struct StepPolicySource<T: Config> {
    actor: ActorRef,
    state: ActiveActorStateOf<T>,
    admission: ActorAdmissionCertificateOf<T>,
    plan: CurrentStepPlanOf<T>,
    contract: ActorContractOf<T>,
  }

  fn prepare_step_policy_source<T: Config>(
    profile: ReachableOpeningProfile,
    actor_type: ActorType,
    expression: CloseWhenOf<T>,
  ) -> Result<StepPolicySource<T>, BenchmarkError> {
    prepare_step_policy_source_with_successor::<T>(profile, actor_type, expression, false)
  }

  fn prepare_step_policy_source_with_successor<T: Config>(
    profile: ReachableOpeningProfile,
    actor_type: ActorType,
    expression: CloseWhenOf<T>,
    preserve_successor: bool,
  ) -> Result<StepPolicySource<T>, BenchmarkError> {
    let tails = T::MaxContractSteps::get()
      .saturating_sub(1)
      .div_ceil(MAX_STEPS_PER_TAIL_CHUNK);
    let (actor_id, count) =
      prepare_reachable_opening_with_successor::<T>(tails, profile, preserve_successor)?;
    assert_eq!(count, T::MaxContractSteps::get());
    let (contract, base) = Pallet::<T>::load_admitted_contract_geometry(actor_id).unwrap();
    install_step_policy_source::<T>(actor_id, actor_type, contract, base, expression)
  }

  fn install_step_policy_source<T: Config>(
    actor_id: ActorId,
    actor_type: ActorType,
    mut contract: ActorContractOf<T>,
    base: ActorAdmissionCertificateOf<T>,
    expression: CloseWhenOf<T>,
  ) -> Result<StepPolicySource<T>, BenchmarkError> {
    let (mut state, _, _) =
      benchmark_fixture_consume_frame_current_step_service_state::<T>(actor_id);
    assert_eq!(state.identity.cycle_nonce, 0);
    assert_eq!(
      Some(base.body_commitment),
      contract.body_commitment(),
      "policy source installation must not rewrite an admitted body"
    );
    assert!(
      contract
        .auto_close_at_cycle_nonce
        .is_none_or(|nonce| nonce > 1)
    );
    contract.close_when = Some(expression);
    state.contract.close_when = contract.close_when.clone();
    stage_behavior_source_snapshot::<T>(actor_id, 2, CycleState::Idle, contract.clone(), base)?;
    Pallet::<T>::reconcile_actor_state_hold_with_authority(actor_id)?;
    let ActorSemanticState::Active(record) = ActorSemanticStates::<T>::get(actor_id).unwrap()
    else {
      panic!("prepared Step has Active authority")
    };
    state.identity = record.identity;
    state.hot = record.hot;
    let admission = record.admission;
    let actor = ActorRef {
      actor_id,
      generation: record.generation,
    };
    let head = ActorContractHeads::<T>::get(actor_id).unwrap();
    let loaded = LoadedActorStep {
      cursor: 0,
      step: head.first_step.unwrap(),
      resources: head.first_step_resources.unwrap(),
    };
    assert_eq!(state.identity.actor_class.actor_type(), actor_type);
    let fee = Pallet::<T>::maximum_current_action_fee(actor_type, &loaded.step, loaded.resources)
      .expect("real Step fee owner exists");
    let plan = Pallet::<T>::build_canonical_current_step_plan(
      actor_id,
      state.identity.clone(),
      state.hot.clone(),
      state.run_state.clone(),
      admission.clone(),
      loaded,
      fee,
    )
    .expect("canonical Step plan exists");
    Ok(StepPolicySource {
      actor,
      state,
      admission,
      plan,
      contract,
    })
  }

  fn execute_opening_policy_pre_effect<T: Config>(
    actor: ActorRef,
    kind: ServiceResidenceKind,
    state: ActiveActorStateOf<T>,
    plan: CurrentStepPlanOf<T>,
    admission: &ActorAdmissionCertificateOf<T>,
    now: BlockNumberFor<T>,
  ) {
    let next = Pallet::<T>::benchmark_opening_pre_effect_failure_control(
      actor.actor_id,
      state,
      plan,
      admission,
      now,
    )
    .unwrap();
    assert_eq!(next.identity.cycle_nonce, 1);
    assert_eq!(next.hot.unsuccessful_attempt_streak, 1);
    assert_eq!(
      Pallet::<T>::publish_idle_cycle_completion(actor, kind, &next, now).unwrap(),
      StepControlPlacement::None
    );
  }

  fn execute_opening_policy_pre_effect_continue<T: Config>(
    actor: ActorRef,
    kind: ServiceResidenceKind,
    state: ActiveActorStateOf<T>,
    plan: CurrentStepPlanOf<T>,
    admission: &ActorAdmissionCertificateOf<T>,
    now: BlockNumberFor<T>,
  ) {
    let next = Pallet::<T>::benchmark_opening_pre_effect_failure_control(
      actor.actor_id,
      state,
      plan,
      admission,
      now,
    )
    .unwrap();
    assert_eq!(next.hot.cycle_state, CycleState::Running);
    Pallet::<T>::try_store_service_control_state(actor, kind, next.identity, next.hot).unwrap();
    Pallet::<T>::advance_service_head(actor, now).unwrap();
  }

  /// Minimal-header preparation failure; User includes Pipeline fees, never Task/destruction.
  #[benchmark(extra, pov_mode = Measured)]
  fn opening_policy_pre_effect_control(
    r: Linear<0, 1>,
    c: Linear<0, 1>,
  ) -> Result<(), BenchmarkError> {
    let actor_type = if c == 0 {
      ActorType::User
    } else {
      ActorType::System
    };
    let StepPolicySource {
      actor,
      state,
      admission,
      plan,
      contract,
    } = prepare_step_policy_source::<T>(
      if c == 0 {
        ReachableOpeningProfile::UserFailedMin { continuing: false }
      } else {
        ReachableOpeningProfile::FailedMin
      },
      actor_type,
      maximum_behavior_expression::<T>()?,
    )?;
    let id = actor.actor_id;
    assert_eq!(contract.steps.len() as u32, T::MaxContractSteps::get());
    assert_eq!(Some(admission.body_commitment), contract.body_commitment());
    assert_eq!(state.identity.cycle_nonce, 0);
    assert!(!ActorRunStateStore::<T>::contains_key(id));
    let ActorTask::Unstake { asset, .. } = plan.loaded_step.step.task else {
      panic!("Unstake source")
    };
    assert!(T::StakingOps::share_asset(asset).is_none());
    let payer = state.identity.sovereign_account.clone();
    let balances = expected_step_balances::<T>(&payer, &contract, Zero::zero(), None);
    let pipeline = Pallet::<T>::pipeline_fee_for_actor(id, actor_type)
      .unwrap()
      .total_fee;
    if actor_type == ActorType::User {
      assert!(!pipeline.is_zero());
    }
    let native = T::FeeNativeAssetId::get();
    let native_before = T::AssetOps::balance(&payer, native);
    let sink_before = T::AssetOps::total_balance(&T::FeeSink::get(), native);
    let position = T::AssetOps::balance(&payer, asset);
    let shares = T::StakingOps::share_balance(&payer, asset);
    let held = ActorStateHolds::<T>::get(id);
    let before = ActorSemanticStates::<T>::get(id);
    let Some(ProcessResidence::Service(kind)) = ActorProcesses::<T>::get(id).unwrap().residence
    else {
      panic!("Service source")
    };
    let now = frame_system::Pallet::<T>::block_number();
    let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    #[block]
    {
      polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
        execute_opening_policy_pre_effect::<T>(actor, kind, state, plan, &admission, now);
        if r == 1 {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(())
        } else {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(())
        }
      });
    }
    assert_eq!(ActorStateHolds::<T>::get(id), held);
    let charged = if r == 0 && actor_type == ActorType::User {
      pipeline
    } else {
      Zero::zero()
    };
    assert_eq!(
      T::AssetOps::balance(&payer, native),
      native_before.checked_sub(&charged).unwrap()
    );
    assert_eq!(
      T::AssetOps::total_balance(&T::FeeSink::get(), native),
      sink_before.checked_add(&charged).unwrap()
    );
    assert_eq!(
      T::AssetOps::balance(&payer, asset),
      position
        .checked_sub(&if asset == native {
          charged
        } else {
          Zero::zero()
        })
        .unwrap()
    );
    assert_eq!(T::StakingOps::share_balance(&payer, asset), shares);
    for (asset, amount) in balances {
      let delta = if asset == native {
        charged
      } else {
        Zero::zero()
      };
      assert_eq!(
        T::AssetOps::balance(&payer, asset),
        amount.checked_sub(&delta).unwrap()
      );
    }
    let receipt: <T as frame_system::Config>::RuntimeEvent = Event::<T>::PipelineFeeCharged {
      actor_id: id,
      fee: pipeline,
    }
    .into();
    assert_eq!(
      frame_system::Pallet::<T>::events()
        .iter()
        .filter(|event| event.event == receipt)
        .count(),
      usize::from(r == 0 && actor_type == ActorType::User)
    );
    let (retained, certificate) = Pallet::<T>::load_admitted_contract_geometry(id).unwrap();
    assert_eq!(retained, contract);
    assert_eq!(certificate, admission);
    assert!(!ActorRunStateStore::<T>::contains_key(id));
    assert!(!DeadlineHandles::<T>::contains_key(id));
    if r == 1 {
      assert_eq!(ActorSemanticStates::<T>::get(id), before);
      assert!(ServiceNodes::<T>::contains_key(id));
      assert_eq!(
        polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
        root
      );
    } else {
      assert!(ActorSemanticStates::<T>::contains_key(id));
      assert!(!ServiceNodes::<T>::contains_key(id));
    }
    Ok(())
  }

  /// Permanent preparation failure advances a Run; User includes Pipeline, never Action/destruction.
  #[benchmark(extra, pov_mode = Measured)]
  fn opening_policy_pre_effect_continue(
    r: Linear<0, 1>,
    c: Linear<0, 1>,
  ) -> Result<(), BenchmarkError> {
    let actor_type = if c == 0 {
      ActorType::User
    } else {
      ActorType::System
    };
    let StepPolicySource {
      actor,
      state,
      admission,
      plan,
      contract,
    } = prepare_step_policy_source::<T>(
      if c == 0 {
        ReachableOpeningProfile::UserFailedMin { continuing: true }
      } else {
        ReachableOpeningProfile::FailedContinueMin
      },
      actor_type,
      maximum_behavior_expression::<T>()?,
    )?;
    let id = actor.actor_id;
    assert_eq!(contract.steps.len() as u32, T::MaxContractSteps::get());
    assert_eq!(Some(admission.body_commitment), contract.body_commitment());
    assert_eq!(state.identity.cycle_nonce, 0);
    assert!(!ActorRunStateStore::<T>::contains_key(id));
    let ActorTask::Unstake { asset, .. } = plan.loaded_step.step.task else {
      panic!("Unstake source")
    };
    assert!(T::StakingOps::share_asset(asset).is_none());
    let payer = state.identity.sovereign_account.clone();
    let balances = expected_step_balances::<T>(&payer, &contract, Zero::zero(), None);
    let pipeline = Pallet::<T>::pipeline_fee_for_actor(id, actor_type)
      .unwrap()
      .total_fee;
    if actor_type == ActorType::User {
      assert!(!pipeline.is_zero());
    }
    let native = T::FeeNativeAssetId::get();
    let native_before = T::AssetOps::balance(&payer, native);
    let sink_before = T::AssetOps::total_balance(&T::FeeSink::get(), native);
    let position = T::AssetOps::balance(&payer, asset);
    let shares = T::StakingOps::share_balance(&payer, asset);
    let held = ActorStateHolds::<T>::get(id);
    let before = ActorSemanticStates::<T>::get(id);
    let Some(ProcessResidence::Service(kind)) = ActorProcesses::<T>::get(id).unwrap().residence
    else {
      panic!("Service source")
    };
    let now = frame_system::Pallet::<T>::block_number();
    let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    #[block]
    {
      polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
        execute_opening_policy_pre_effect_continue::<T>(actor, kind, state, plan, &admission, now);
        if r == 1 {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(())
        } else {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(())
        }
      });
    }
    assert_eq!(ActorStateHolds::<T>::get(id), held);
    let charged = if r == 0 && actor_type == ActorType::User {
      pipeline
    } else {
      Zero::zero()
    };
    assert_eq!(
      T::AssetOps::balance(&payer, native),
      native_before.checked_sub(&charged).unwrap()
    );
    assert_eq!(
      T::AssetOps::total_balance(&T::FeeSink::get(), native),
      sink_before.checked_add(&charged).unwrap()
    );
    assert_eq!(
      T::AssetOps::balance(&payer, asset),
      position
        .checked_sub(&if asset == native {
          charged
        } else {
          Zero::zero()
        })
        .unwrap()
    );
    assert_eq!(T::StakingOps::share_balance(&payer, asset), shares);
    for (asset, amount) in balances {
      let delta = if asset == native {
        charged
      } else {
        Zero::zero()
      };
      assert_eq!(
        T::AssetOps::balance(&payer, asset),
        amount.checked_sub(&delta).unwrap()
      );
    }
    let receipt: <T as frame_system::Config>::RuntimeEvent = Event::<T>::PipelineFeeCharged {
      actor_id: id,
      fee: pipeline,
    }
    .into();
    assert_eq!(
      frame_system::Pallet::<T>::events()
        .iter()
        .filter(|event| event.event == receipt)
        .count(),
      usize::from(r == 0 && actor_type == ActorType::User)
    );
    let (retained, certificate) = Pallet::<T>::load_admitted_contract_geometry(id).unwrap();
    assert_eq!(retained, contract);
    assert_eq!(certificate, admission);
    assert!(!DeadlineHandles::<T>::contains_key(id));
    if r == 1 {
      assert!(!ActorRunStateStore::<T>::contains_key(id));
      assert_eq!(ActorSemanticStates::<T>::get(id), before);
      assert!(ServiceNodes::<T>::contains_key(id));
      assert_eq!(
        polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
        root
      );
    } else {
      assert!(ActorSemanticStates::<T>::contains_key(id));
      assert!(ServiceNodes::<T>::contains_key(id));
      let ActorSemanticState::Active(record) = ActorSemanticStates::<T>::get(id).unwrap() else {
        panic!("Active successor")
      };
      assert_eq!(record.identity.cycle_nonce, 0);
      assert_eq!(record.hot.cycle_state, CycleState::Running);
      assert_eq!(record.hot.unsuccessful_attempt_streak, 0);
      let run = ActorRunStateStore::<T>::get(id).unwrap();
      assert_eq!(run.cycle_nonce, 1);
      assert_eq!(run.cursor, 1);
      assert_eq!(run.eligible_at, now.checked_add(&One::one()).unwrap());
      assert_eq!(run.cumulative_outcomes.failed_steps, 1);
      assert_eq!(run.cumulative_outcomes.committed_effectful_tasks, 0);
      assert_eq!(
        run.last_step_outcome,
        Some(StepOutcome::Failed(crate::TaskFailure::permanent(
          Error::<T>::InvalidAmountResolution
        )))
      );
    }
    Ok(())
  }

  #[cfg(test)]
  #[test]
  fn opening_policy_pre_effect_failure_preserves_custody_and_rollback() {
    for actor_type in [ActorType::User, ActorType::System] {
      for continuing in [false, true] {
        for rollback in [false, true] {
          new_test_ext().execute_with(|| {
        crate::mock::set_missing_behavior_control_weight(true);
        crate::mock::set_missing_behavior_close_weight(true);
        crate::mock::set_missing_behavior_inspection_weight(true);
        let StepPolicySource { actor, state, admission, plan, contract } = prepare_step_policy_source::<Test>(
          if actor_type == ActorType::User { ReachableOpeningProfile::UserFailedMin { continuing } }
          else if continuing { ReachableOpeningProfile::FailedContinueMin } else { ReachableOpeningProfile::FailedMin }, actor_type, maximum_behavior_expression::<Test>().unwrap()
        ).unwrap();
        let id = actor.actor_id;
        assert_eq!(contract.steps.len() as u32, <<Test as Config>::MaxContractSteps as Get<u32>>::get());
        assert_eq!(Some(admission.body_commitment), contract.body_commitment());
        assert_eq!(state.identity.cycle_nonce, 0);
        assert!(!ActorRunStateStore::<Test>::contains_key(id));
        assert!(Pallet::<Test>::load_frame_actor_service_state(id).is_none());
        let ActorTask::Unstake { asset, .. } = plan.loaded_step.step.task else { panic!("Unstake source") };
        assert!(<Test as Config>::StakingOps::share_asset(asset).is_none());
        let payer = state.identity.sovereign_account;
        let balances = expected_step_balances::<Test>(&payer, &contract, 0, None);
        let pipeline = Pallet::<Test>::pipeline_fee_for_actor(id, actor_type).unwrap().total_fee;
        if actor_type == ActorType::User { assert!(pipeline > 0); }
        let native = <Test as Config>::FeeNativeAssetId::get();
        let native_before = <Test as Config>::AssetOps::balance(&payer, native);
        let sink_before = <Test as Config>::AssetOps::total_balance(&<Test as Config>::FeeSink::get(), native);
        let position = <Test as Config>::AssetOps::balance(&payer, asset);
        let held = ActorStateHolds::<Test>::get(id);
        let before = ActorSemanticStates::<Test>::get(id);
        let Some(ProcessResidence::Service(kind)) = ActorProcesses::<Test>::get(id).unwrap().residence else { panic!("Service source") };
        let now = frame_system::Pallet::<Test>::block_number();
        let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
        polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
          if continuing {
            assert_eq!(contract.steps[0].on_error, StepErrorPolicy::ContinueNextStep);
            execute_opening_policy_pre_effect_continue::<Test>(actor, kind, state, plan, &admission, now);
            let ActorSemanticState::Active(next) = ActorSemanticStates::<Test>::get(id).unwrap() else { panic!("Active successor") };
            assert_eq!(next.identity.cycle_nonce, 0);
            assert_eq!(next.hot.unsuccessful_attempt_streak, 0);
            let run = ActorRunStateStore::<Test>::get(id).unwrap();
            assert_eq!(run.cycle_nonce, 1);
            assert_eq!(run.cursor, 1);
            assert_eq!(run.eligible_at, now + 1);
            assert_eq!(run.cumulative_outcomes.failed_steps, 1);
            assert_eq!(run.cumulative_outcomes.committed_effectful_tasks, 0);
            assert_eq!(run.last_step_outcome, Some(StepOutcome::Failed(crate::TaskFailure::permanent(Error::<Test>::InvalidAmountResolution))));
          } else {
            execute_opening_policy_pre_effect::<Test>(actor, kind, state, plan, &admission, now);
          }
          let pipeline_receipts: Vec<_> = frame_system::Pallet::<Test>::events().iter().filter_map(|event| match event.event {
            crate::mock::RuntimeEvent::Actors(Event::PipelineFeeCharged { actor_id, fee }) if actor_id == id => Some(fee),
            _ => None,
          }).collect();
          assert_eq!(pipeline_receipts, if actor_type == ActorType::User { vec![pipeline] } else { vec![] });
          assert!(ActorSemanticStates::<Test>::contains_key(id));
          assert_eq!(ActorRunStateStore::<Test>::contains_key(id), continuing);
          assert_eq!(ServiceNodes::<Test>::contains_key(id), continuing);
          assert!(!DeadlineHandles::<Test>::contains_key(id));
          assert!(frame_system::Pallet::<Test>::events().iter().all(|event| !matches!(event.event,
            crate::mock::RuntimeEvent::Actors(Event::ActionFeeCharged { actor_id, .. } | Event::ActorClosed { actor_id, .. }) if actor_id == id)));
          if rollback { polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(()) }
          else { polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(()) }
        });
        assert_eq!(ActorStateHolds::<Test>::get(id), held);
        assert_eq!(<Test as Config>::AssetOps::balance(&payer, asset), position);
        let charged = if !rollback && actor_type == ActorType::User { pipeline } else { 0 };
        assert_eq!(<Test as Config>::AssetOps::balance(&payer, native), native_before - charged);
        assert_eq!(<Test as Config>::AssetOps::total_balance(&<Test as Config>::FeeSink::get(), native), sink_before + charged);
        for (asset, amount) in balances { assert_eq!(<Test as Config>::AssetOps::balance(&payer, asset), amount - if asset == native { charged } else { 0 }); }
        let (retained, certificate) = Pallet::<Test>::load_admitted_contract_geometry(id).unwrap();
        assert_eq!(retained, contract);
        assert_eq!(certificate, admission);
        if rollback {
          assert_eq!(ActorSemanticStates::<Test>::get(id), before);
          assert!(ServiceNodes::<Test>::contains_key(id));
          assert_eq!(polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1), root);
        }
      });
        }
      }
    }
  }

  fn execute_opening_policy_no_action<T: Config>(
    actor: ActorRef,
    kind: ServiceResidenceKind,
    state: ActiveActorStateOf<T>,
    plan: CurrentStepPlanOf<T>,
    admission: &ActorAdmissionCertificateOf<T>,
    now: BlockNumberFor<T>,
    retry: bool,
  ) {
    let next = Pallet::<T>::benchmark_opening_no_action_control(
      actor.actor_id,
      state,
      plan,
      admission,
      now,
      retry,
    )
    .unwrap();
    let destination = if retry {
      Some(
        Pallet::<T>::plan_deadline_destination(
          actor,
          WakeupKey::Block(next.run_state.as_ref().unwrap().eligible_at),
        )
        .unwrap(),
      )
    } else {
      None
    };
    Pallet::<T>::try_store_service_control_state(actor, kind, next.identity, next.hot).unwrap();
    if let Some(destination) = destination {
      Pallet::<T>::transfer_service_member_to_deadline(actor, destination).unwrap();
    } else {
      Pallet::<T>::advance_service_head(actor, now).unwrap();
    }
  }

  /// Minimal-header resolution skip or Task-input retry; User pays Pipeline, never Action.
  #[benchmark(extra, pov_mode = Measured)]
  fn opening_policy_no_action_control(
    f: Linear<0, 1>,
    r: Linear<0, 1>,
    c: Linear<0, 1>,
  ) -> Result<(), BenchmarkError> {
    let retry = f == 1;
    let actor_type = if c == 0 {
      ActorType::User
    } else {
      ActorType::System
    };
    let profile = if c == 0 {
      ReachableOpeningProfile::UserNoActionMin { retry }
    } else if retry {
      ReachableOpeningProfile::RetryMin
    } else {
      ReachableOpeningProfile::Minimal
    };
    let StepPolicySource {
      actor,
      state,
      admission,
      plan,
      contract,
    } = prepare_step_policy_source::<T>(profile, actor_type, maximum_behavior_expression::<T>()?)?;
    let id = actor.actor_id;
    assert_eq!(contract.steps.len() as u32, T::MaxContractSteps::get());
    assert_eq!(Some(admission.body_commitment), contract.body_commitment());
    assert_eq!(state.identity.cycle_nonce, 0);
    assert!(!ActorRunStateStore::<T>::contains_key(id));
    let ActorTask::Transfer { asset, ref to, .. } = plan.loaded_step.step.task else {
      panic!("Transfer source")
    };
    let recipient = to.clone();
    let payer = state.identity.sovereign_account.clone();
    let recipient_before = T::AssetOps::balance(&recipient, asset);
    let input = T::AssetOps::balance(&payer, asset);
    let native = T::FeeNativeAssetId::get();
    assert_ne!(asset, native);
    assert!(input.is_zero());
    let pipeline = Pallet::<T>::pipeline_fee_for_actor(id, actor_type)
      .unwrap()
      .total_fee;
    if actor_type == ActorType::User {
      assert!(!pipeline.is_zero());
    }
    let native_before = T::AssetOps::balance(&payer, native);
    let sink_before = T::AssetOps::total_balance(&T::FeeSink::get(), native);
    let custody = expected_step_balances::<T>(&payer, &contract, Zero::zero(), None);
    let held = ActorStateHolds::<T>::get(id);
    let before = ActorSemanticStates::<T>::get(id);
    let Some(ProcessResidence::Service(kind)) = ActorProcesses::<T>::get(id).unwrap().residence
    else {
      panic!("Service source")
    };
    let now = frame_system::Pallet::<T>::block_number();
    let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    #[block]
    {
      polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
        execute_opening_policy_no_action::<T>(actor, kind, state, plan, &admission, now, retry);
        if r == 1 {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(())
        } else {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(())
        }
      });
    }
    assert_eq!(ActorStateHolds::<T>::get(id), held);
    assert_eq!(T::AssetOps::balance(&payer, asset), input);
    assert_eq!(T::AssetOps::balance(&recipient, asset), recipient_before);
    let charged = if r == 0 && actor_type == ActorType::User {
      pipeline
    } else {
      Zero::zero()
    };
    assert_eq!(
      T::AssetOps::balance(&payer, native),
      native_before.checked_sub(&charged).unwrap()
    );
    assert_eq!(
      T::AssetOps::total_balance(&T::FeeSink::get(), native),
      sink_before.checked_add(&charged).unwrap()
    );
    for (asset, amount) in custody {
      let delta = if asset == native {
        charged
      } else {
        Zero::zero()
      };
      assert_eq!(
        T::AssetOps::balance(&payer, asset),
        amount.checked_sub(&delta).unwrap()
      );
    }
    let receipt: <T as frame_system::Config>::RuntimeEvent = Event::<T>::PipelineFeeCharged {
      actor_id: id,
      fee: pipeline,
    }
    .into();
    assert_eq!(
      frame_system::Pallet::<T>::events()
        .iter()
        .filter(|event| event.event == receipt)
        .count(),
      usize::from(r == 0 && actor_type == ActorType::User)
    );
    let (retained, certificate) = Pallet::<T>::load_admitted_contract_geometry(id).unwrap();
    assert_eq!(retained, contract);
    assert_eq!(certificate, admission);
    if r == 1 {
      assert_eq!(ActorSemanticStates::<T>::get(id), before);
      assert!(!ActorRunStateStore::<T>::contains_key(id));
      assert!(ServiceNodes::<T>::contains_key(id));
      assert!(!DeadlineHandles::<T>::contains_key(id));
      assert_eq!(
        polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
        root
      );
    } else {
      let ActorSemanticState::Active(record) = ActorSemanticStates::<T>::get(id).unwrap() else {
        panic!("Active successor")
      };
      assert_eq!(record.identity.cycle_nonce, 0);
      assert_eq!(
        record.hot.cycle_state,
        if retry {
          CycleState::Suspended
        } else {
          CycleState::Running
        }
      );
      assert_eq!(record.hot.unsuccessful_attempt_streak, u32::from(retry));
      let run = ActorRunStateStore::<T>::get(id).unwrap();
      assert_eq!(run.cycle_nonce, 1);
      assert_eq!(run.cursor, u32::from(!retry));
      assert_eq!(run.unsuccessful_attempts_at_cursor, u32::from(retry));
      assert_eq!(run.cumulative_outcomes.committed_effectful_tasks, 0);
      assert_eq!(run.cumulative_outcomes.failed_steps, 0);
      assert_eq!(
        run.cumulative_outcomes.skipped_resolution,
        u32::from(!retry)
      );
      assert_eq!(
        run.eligible_at,
        now
          .checked_add(&(if retry { 2u32 } else { 1u32 }).into())
          .unwrap()
      );
      assert_eq!(DeadlineHandles::<T>::contains_key(id), retry);
      assert_eq!(ServiceNodes::<T>::contains_key(id), !retry);
    }
    Ok(())
  }

