  fn execute_funding_policy_attempt<T: Config>(
    actor: ActorRef,
    kind: ServiceResidenceKind,
    state: ActiveActorStateOf<T>,
    plan: CurrentStepPlanOf<T>,
    admission: &ActorAdmissionCertificateOf<T>,
    now: BlockNumberFor<T>,
    expected: AttemptDisposition,
  ) -> Option<CloseReason> {
    let (next, reason, publish_clean) =
      Pallet::<T>::benchmark_funding_control(actor.actor_id, state, plan, admission, now, expected)
        .unwrap();
    if let Some(reason) = reason {
      if publish_clean {
        Pallet::<T>::try_store_service_control_state(
          actor,
          kind,
          next.identity.clone(),
          next.hot.clone(),
        )
        .unwrap();
      }
      Pallet::<T>::benchmark_finalize_actor_from_consumed_state(
        actor.actor_id,
        next,
        admission.clone(),
        reason,
      )
      .unwrap();
      Pallet::<T>::retire_service_member(actor).unwrap();
    } else {
      let due = next.run_state.as_ref().unwrap().eligible_at;
      let destination = if expected == AttemptDisposition::Suspended
        && due != now.checked_add(&One::one()).unwrap()
      {
        Some(Pallet::<T>::plan_deadline_destination(actor, WakeupKey::Block(due)).unwrap())
      } else {
        None
      };
      Pallet::<T>::try_store_service_control_state(actor, kind, next.identity, next.hot).unwrap();
      if let Some(destination) = destination {
        Pallet::<T>::transfer_service_member_to_deadline(actor, destination).unwrap();
      } else {
        Pallet::<T>::advance_service_head(actor, now).unwrap();
      }
    }
    reason
  }

  /// Task-input skip or configured-bound Close; terminal prior retries/Pipeline payment are setup.
  #[benchmark(extra, pov_mode = Measured)]
  fn funding_policy_control(
    t: Linear<0, 1>,
    r: Linear<0, 1>,
    c: Linear<0, 1>,
  ) -> Result<(), BenchmarkError> {
    use polkadot_sdk::frame_support::traits::fungible::Inspect;
    let terminal = t == 1;
    let actor_type = if c == 0 {
      ActorType::User
    } else {
      ActorType::System
    };
    let profile = if c == 0 {
      if terminal {
        ReachableOpeningProfile::UserNoActionMin { retry: true }
      } else {
        ReachableOpeningProfile::UserFundingSkipMin
      }
    } else if terminal {
      ReachableOpeningProfile::RetryMin
    } else {
      ReachableOpeningProfile::FundingSkipMin
    };
    let StepPolicySource {
      actor,
      state,
      admission,
      plan,
      contract,
    } = prepare_step_policy_source::<T>(profile, actor_type, maximum_behavior_expression::<T>()?)?;
    let id = actor.actor_id;
    assert_eq!(contract.steps.len() as u32, T::MaxContractSteps::get());
    assert_eq!(Some(admission.body_commitment), contract.body_commitment());
    let ActorTask::Transfer {
      asset,
      ref to,
      amount: AmountResolution::Fixed(amount),
    } = plan.loaded_step.step.task
    else {
      panic!("fixed Transfer")
    };
    assert_eq!(amount, One::one());
    let recipient = to.clone();
    let payer = state.identity.sovereign_account.clone();
    let owner = state.identity.owner.clone();
    let native = T::FeeNativeAssetId::get();
    assert_ne!(asset, native);
    let pipeline = Pallet::<T>::pipeline_fee_for_actor(id, actor_type)
      .unwrap()
      .total_fee;
    if actor_type == ActorType::User {
      assert!(!pipeline.is_zero());
    }
    let native_before = T::AssetOps::balance(&payer, native);
    let sink_before = T::AssetOps::total_balance(&T::FeeSink::get(), native);
    let input = T::AssetOps::balance(&payer, asset);
    assert!(input.is_zero());
    let recipient_before = T::AssetOps::balance(&recipient, asset);
    let custody = expected_step_balances::<T>(&payer, &contract, Zero::zero(), None);
    let local_limit = T::MaxRetryAttempts::get();
    let terminal_attempt = (1..=local_limit)
      .find(|attempt| *attempt == local_limit || Pallet::<T>::failure_limit_reached(*attempt))
      .unwrap();
    assert!(terminal_attempt > 1);
    let terminal_reason = if terminal_attempt == local_limit {
      CloseReason::RetryAttemptsExhausted
    } else {
      CloseReason::ConsecutiveFailures
    };
    let Some(ProcessResidence::Service(kind)) = ActorProcesses::<T>::get(id).unwrap().residence
    else {
      panic!("Service source")
    };
    let now = frame_system::Pallet::<T>::block_number();
    let (state, admission, plan, kind, now) = if terminal {
      assert_eq!(
        contract.steps[0].on_error.retry_max_attempts(),
        Some(local_limit)
      );
      polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
        execute_opening_policy_no_action::<T>(actor, kind, state, plan, &admission, now, true);
        polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(())
      });
      for _ in 1..terminal_attempt - 1 {
        let (state, admission, plan, kind, now) = prepare_policy_step_attempt::<T>(actor);
        assert_eq!(plan.loaded_step.cursor, 0);
        assert_eq!(plan.loaded_step.step, contract.steps[0]);
        polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
          assert_eq!(
            execute_funding_policy_attempt::<T>(
              actor,
              kind,
              state,
              plan,
              &admission,
              now,
              AttemptDisposition::Suspended
            ),
            None
          );
          polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(())
        });
      }
      prepare_policy_step_attempt::<T>(actor)
    } else {
      (state, admission, plan, kind, now)
    };
    assert_eq!(plan.loaded_step.cursor, 0);
    assert_eq!(plan.loaded_step.step, contract.steps[0]);
    let before = ActorSemanticStates::<T>::get(id);
    let prefix = ActorRunStateStore::<T>::get(id);
    if terminal {
      let run = prefix.as_ref().unwrap();
      assert_eq!(run.cycle_nonce, 1);
      assert_eq!(run.unsuccessful_attempts_at_cursor, terminal_attempt - 1);
      assert_eq!(run.cumulative_outcomes.committed_effectful_tasks, 0);
      assert!(ServiceNodes::<T>::contains_key(id));
      assert!(!DeadlineHandles::<T>::contains_key(id));
    }
    let held = ActorStateHolds::<T>::get(id);
    let hold_reason: <T as Config>::RuntimeHoldReason = crate::HoldReason::ActorState.into();
    let owner_held = T::StateHoldCurrency::balance_on_hold(&hold_reason, &owner);
    let owner_free = T::StateHoldCurrency::balance(&owner);
    let owner_slots = OwnerSlotBitmaps::<T>::get(&owner);
    if actor_type == ActorType::User {
      assert_eq!(held.as_ref().unwrap().owner, owner);
      assert!(!owner_held.is_zero());
      assert_ne!(owner, payer);
      assert_eq!(
        owner_slots
          .iter()
          .map(|byte| byte.count_ones())
          .sum::<u32>(),
        1
      );
    }
    let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    let reason;
    #[block]
    {
      reason = polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
        let result = execute_funding_policy_attempt::<T>(
          actor,
          kind,
          state,
          plan,
          &admission,
          now,
          if terminal {
            AttemptDisposition::Failed
          } else {
            AttemptDisposition::Continued
          },
        );
        if r == 1 {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(result)
        } else {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(result)
        }
      });
    }
    assert_eq!(reason, terminal.then_some(terminal_reason));
    assert_eq!(T::AssetOps::balance(&payer, asset), input);
    assert_eq!(T::AssetOps::balance(&recipient, asset), recipient_before);
    let charged = if actor_type == ActorType::User && (terminal || r == 0) {
      pipeline
    } else {
      Zero::zero()
    };
    assert_eq!(
      T::AssetOps::balance(&payer, native),
      native_before.checked_sub(&charged).unwrap()
    );
    assert_eq!(
      T::AssetOps::total_balance(&T::FeeSink::get(), native),
      sink_before.checked_add(&charged).unwrap()
    );
    for (asset, amount) in custody {
      let delta = if asset == native {
        charged
      } else {
        Zero::zero()
      };
      assert_eq!(
        T::AssetOps::balance(&payer, asset),
        amount.checked_sub(&delta).unwrap()
      );
    }
    if actor_type == ActorType::User {
      let released = terminal && r == 0;
      assert_eq!(
        T::StateHoldCurrency::balance_on_hold(&hold_reason, &owner),
        if released { Zero::zero() } else { owner_held }
      );
      assert_eq!(
        T::StateHoldCurrency::balance(&owner),
        owner_free
          .checked_add(&if released { owner_held } else { Zero::zero() })
          .unwrap()
      );
      assert_eq!(
        OwnerSlotBitmaps::<T>::get(&owner),
        if released { [0; 32] } else { owner_slots }
      );
      if released {
        assert!(!OwnerSlotBitmaps::<T>::contains_key(&owner));
      }
    }
    if !terminal || r == 1 {
      assert_eq!(ActorStateHolds::<T>::get(id), held);
      let (retained, certificate) = Pallet::<T>::load_admitted_contract_geometry(id).unwrap();
      assert_eq!(retained, contract);
      assert_eq!(certificate, admission);
    }
    let started: <T as frame_system::Config>::RuntimeEvent = Event::<T>::CycleStarted {
      actor_id: id,
      cycle_nonce: 1,
    }
    .into();
    let closed: <T as frame_system::Config>::RuntimeEvent = Event::<T>::ActorClosed {
      actor_id: id,
      reason: terminal_reason,
    }
    .into();
    let events = frame_system::Pallet::<T>::events();
    let receipt: <T as frame_system::Config>::RuntimeEvent = Event::<T>::PipelineFeeCharged {
      actor_id: id,
      fee: pipeline,
    }
    .into();
    assert_eq!(
      events.iter().filter(|event| event.event == receipt).count(),
      usize::from(actor_type == ActorType::User && (terminal || r == 0))
    );
    assert_eq!(
      events.iter().filter(|event| event.event == started).count(),
      usize::from(terminal || r == 0)
    );
    assert_eq!(
      events.iter().filter(|event| event.event == closed).count(),
      usize::from(terminal && r == 0)
    );
    if r == 1 {
      assert_eq!(ActorSemanticStates::<T>::get(id), before);
      assert_eq!(ActorRunStateStore::<T>::get(id), prefix);
      assert!(ServiceNodes::<T>::contains_key(id));
      assert!(!DeadlineHandles::<T>::contains_key(id));
      assert_eq!(
        polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
        root
      );
    } else if terminal {
      assert!(!ActorSemanticStates::<T>::contains_key(id));
      assert!(!ActorRunStateStore::<T>::contains_key(id));
      assert!(!ActorStateHolds::<T>::contains_key(id));
      assert!(!ServiceNodes::<T>::contains_key(id));
      assert!(!DeadlineHandles::<T>::contains_key(id));
      assert!(
        ActorContractTailChunks::<T>::iter_prefix(id)
          .next()
          .is_none()
      );
    } else {
      let run = ActorRunStateStore::<T>::get(id).unwrap();
      assert_eq!(run.cursor, 1);
      assert_eq!(run.cycle_nonce, 1);
      assert_eq!(run.cumulative_outcomes.skipped_funding_unavailable, 1);
      assert_eq!(run.cumulative_outcomes.failed_steps, 0);
      assert_eq!(run.cumulative_outcomes.committed_effectful_tasks, 0);
      assert_eq!(run.eligible_at, now.checked_add(&One::one()).unwrap());
      assert!(ServiceNodes::<T>::contains_key(id));
      assert!(!DeadlineHandles::<T>::contains_key(id));
    }
    Ok(())
  }

  #[cfg(test)]
  #[test]
  fn funding_policy_skip_and_terminal_preserve_real_limits_and_rollback() {
    use polkadot_sdk::frame_support::traits::fungible::InspectHold;
    for actor_type in [ActorType::User, ActorType::System] {
      for terminal in [false, true] {
        for rollback in [false, true] {
          new_test_ext().execute_with(|| {
            crate::mock::set_missing_behavior_control_weight(true);
            crate::mock::set_missing_behavior_close_weight(true);
            crate::mock::set_missing_behavior_inspection_weight(true);
            let profile = if actor_type == ActorType::User {
              if terminal {
                ReachableOpeningProfile::UserNoActionMin { retry: true }
              } else {
                ReachableOpeningProfile::UserFundingSkipMin
              }
            } else if terminal {
              ReachableOpeningProfile::RetryMin
            } else {
              ReachableOpeningProfile::FundingSkipMin
            };
            let StepPolicySource {
              actor,
              state,
              admission,
              plan,
              contract,
            } = prepare_step_policy_source::<Test>(
              profile,
              actor_type,
              maximum_behavior_expression::<Test>().unwrap(),
            )
            .unwrap();
            let id = actor.actor_id;
            assert_eq!(
              contract.steps.len() as u32,
              <<Test as Config>::MaxContractSteps as Get<u32>>::get()
            );
            assert_eq!(Some(admission.body_commitment), contract.body_commitment());
            let ActorTask::Transfer {
              asset,
              ref to,
              amount: AmountResolution::Fixed(amount),
            } = plan.loaded_step.step.task
            else {
              panic!("fixed Transfer")
            };
            assert_eq!(amount, 1);
            let recipient = *to;
            let payer = state.identity.sovereign_account;
            let owner = state.identity.owner;
            let native = <Test as Config>::FeeNativeAssetId::get();
            assert_ne!(asset, native);
            let pipeline = Pallet::<Test>::pipeline_fee_for_actor(id, actor_type)
              .unwrap()
              .total_fee;
            if actor_type == ActorType::User {
              assert!(pipeline > 0);
            }
            let native_before = <Test as Config>::AssetOps::balance(&payer, native);
            let sink_before =
              <Test as Config>::AssetOps::total_balance(&<Test as Config>::FeeSink::get(), native);
            let input = <Test as Config>::AssetOps::balance(&payer, asset);
            assert_eq!(input, 0);
            let recipient_before = <Test as Config>::AssetOps::balance(&recipient, asset);
            let custody = expected_step_balances::<Test>(&payer, &contract, 0, None);
            let local_limit = <<Test as Config>::MaxRetryAttempts as Get<u32>>::get();
            let terminal_attempt = (1..=local_limit)
              .find(|attempt| {
                *attempt == local_limit || Pallet::<Test>::failure_limit_reached(*attempt)
              })
              .unwrap();
            assert!(terminal_attempt > 1);
            assert!(
              terminal_attempt < local_limit,
              "fixture requires the global bound before the local retry ceiling"
            );
            let terminal_reason = if terminal_attempt == local_limit {
              CloseReason::RetryAttemptsExhausted
            } else {
              CloseReason::ConsecutiveFailures
            };
            let Some(ProcessResidence::Service(kind)) =
              ActorProcesses::<Test>::get(id).unwrap().residence
            else {
              panic!("Service source")
            };
            let now = frame_system::Pallet::<Test>::block_number();
            let (state, admission, plan, kind, now) = if terminal {
              assert_eq!(
                contract.steps[0].on_error.retry_max_attempts(),
                Some(local_limit)
              );
              polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
                execute_opening_policy_no_action::<Test>(
                  actor, kind, state, plan, &admission, now, true,
                );
                polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(())
              });
              for _ in 1..terminal_attempt - 1 {
                let (state, admission, plan, kind, now) =
                  prepare_policy_step_attempt::<Test>(actor);
                assert_eq!(plan.loaded_step.cursor, 0);
                assert_eq!(plan.loaded_step.step, contract.steps[0]);
                polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
                  assert_eq!(
                    execute_funding_policy_attempt::<Test>(
                      actor,
                      kind,
                      state,
                      plan,
                      &admission,
                      now,
                      AttemptDisposition::Suspended
                    ),
                    None
                  );
                  polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(())
                });
              }
              prepare_policy_step_attempt::<Test>(actor)
            } else {
              assert_eq!(contract.steps[0].on_error, StepErrorPolicy::AbortCycle);
              (state, admission, plan, kind, now)
            };
            assert!(Pallet::<Test>::load_frame_actor_service_state(id).is_none());
            let before = ActorSemanticStates::<Test>::get(id);
            let prefix = ActorRunStateStore::<Test>::get(id);
            if terminal {
              let run = prefix.as_ref().unwrap();
              assert_eq!(run.cursor, 0);
              assert_eq!(run.cycle_nonce, 1);
              assert_eq!(run.unsuccessful_attempts_at_cursor, terminal_attempt - 1);
              assert_eq!(run.cumulative_outcomes.committed_effectful_tasks, 0);
            }
            let held = ActorStateHolds::<Test>::get(id);
            let reason: crate::mock::RuntimeHoldReason = crate::HoldReason::ActorState.into();
            let owner_held = crate::mock::Balances::balance_on_hold(&reason, &owner);
            let owner_free = crate::mock::Balances::free_balance(owner);
            let owner_slots = OwnerSlotBitmaps::<Test>::get(owner);
            if actor_type == ActorType::User {
              assert_eq!(held.as_ref().unwrap().owner, owner);
              assert!(owner_held > 0);
              assert_ne!(owner, payer);
              assert_eq!(
                owner_slots
                  .iter()
                  .map(|byte| byte.count_ones())
                  .sum::<u32>(),
                1
              );
            }
            let root =
              polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
            polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
              let reason = execute_funding_policy_attempt::<Test>(
                actor,
                kind,
                state,
                plan,
                &admission,
                now,
                if terminal {
                  AttemptDisposition::Failed
                } else {
                  AttemptDisposition::Continued
                },
              );
              assert_eq!(reason, terminal.then_some(terminal_reason));
              if terminal {
                assert!(!ActorSemanticStates::<Test>::contains_key(id));
                assert!(!ActorRunStateStore::<Test>::contains_key(id));
                assert!(!ActorStateHolds::<Test>::contains_key(id));
                assert!(!ServiceNodes::<Test>::contains_key(id));
                assert!(!DeadlineHandles::<Test>::contains_key(id));
              } else {
                let run = ActorRunStateStore::<Test>::get(id).unwrap();
                assert_eq!(run.cursor, 1);
                assert_eq!(run.cycle_nonce, 1);
                assert_eq!(run.cumulative_outcomes.skipped_funding_unavailable, 1);
                assert_eq!(run.cumulative_outcomes.failed_steps, 0);
                assert_eq!(run.cumulative_outcomes.committed_effectful_tasks, 0);
                assert_eq!(run.eligible_at, now + 1);
              }
              let mut starts = 0;
              let mut closes = 0;
              let mut pipelines = 0;
              for event in frame_system::Pallet::<Test>::events() {
                match event.event {
                  crate::mock::RuntimeEvent::Actors(Event::PipelineFeeCharged {
                    actor_id,
                    fee,
                  }) if actor_id == id => {
                    assert_eq!(fee, pipeline);
                    pipelines += 1;
                  }
                  crate::mock::RuntimeEvent::Actors(Event::ActionFeeCharged {
                    actor_id, ..
                  }) if actor_id == id => {
                    panic!("no Action invocation")
                  }
                  crate::mock::RuntimeEvent::Actors(Event::CycleStarted {
                    actor_id,
                    cycle_nonce,
                  }) if actor_id == id => {
                    assert_eq!(cycle_nonce, 1);
                    starts += 1;
                  }
                  crate::mock::RuntimeEvent::Actors(Event::ActorClosed { actor_id, reason })
                    if actor_id == id =>
                  {
                    assert_eq!(reason, terminal_reason);
                    closes += 1;
                  }
                  _ => {}
                }
              }
              assert_eq!(starts, 1);
              assert_eq!(closes, usize::from(terminal));
              assert_eq!(pipelines, usize::from(actor_type == ActorType::User));
              if rollback {
                polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(())
              } else {
                polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(())
              }
            });
            assert_eq!(<Test as Config>::AssetOps::balance(&payer, asset), input);
            assert_eq!(
              <Test as Config>::AssetOps::balance(&recipient, asset),
              recipient_before
            );
            let charged = if actor_type == ActorType::User && (terminal || !rollback) {
              pipeline
            } else {
              0
            };
            assert_eq!(
              <Test as Config>::AssetOps::balance(&payer, native),
              native_before - charged
            );
            assert_eq!(
              <Test as Config>::AssetOps::total_balance(&<Test as Config>::FeeSink::get(), native),
              sink_before + charged
            );
            for (asset, amount) in custody {
              assert_eq!(
                <Test as Config>::AssetOps::balance(&payer, asset),
                amount - if asset == native { charged } else { 0 }
              );
            }
            if actor_type == ActorType::User {
              let released = terminal && !rollback;
              assert_eq!(
                crate::mock::Balances::balance_on_hold(&reason, &owner),
                if released { 0 } else { owner_held }
              );
              assert_eq!(
                crate::mock::Balances::free_balance(owner),
                owner_free + if released { owner_held } else { 0 }
              );
              assert_eq!(
                OwnerSlotBitmaps::<Test>::get(owner),
                if released { [0; 32] } else { owner_slots }
              );
              if released {
                assert!(!OwnerSlotBitmaps::<Test>::contains_key(owner));
              }
            }
            if !terminal || rollback {
              assert_eq!(ActorStateHolds::<Test>::get(id), held);
              let (retained, certificate) =
                Pallet::<Test>::load_admitted_contract_geometry(id).unwrap();
              assert_eq!(retained, contract);
              assert_eq!(certificate, admission);
            }
            if rollback {
              assert_eq!(ActorSemanticStates::<Test>::get(id), before);
              assert_eq!(ActorRunStateStore::<Test>::get(id), prefix);
              assert!(ServiceNodes::<Test>::contains_key(id));
              assert!(!DeadlineHandles::<Test>::contains_key(id));
              assert_eq!(
                polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
                root
              );
            }
          });
        }
      }
    }
  }

  fn prepare_liquidity_retry_policy_source<T: Config>(
    actor_type: ActorType,
  ) -> Result<StepPolicySource<T>, BenchmarkError> {
    prepare_liquidity_retry_policy_source_with_limit::<T>(actor_type, T::MaxRetryAttempts::get())
  }

  fn prepare_liquidity_retry_policy_source_with_limit<T: Config>(
    actor_type: ActorType,
    max_attempts: u32,
  ) -> Result<StepPolicySource<T>, BenchmarkError> {
    prepare_liquidity_policy_source::<T>(actor_type, StepErrorPolicy::RetryLater { max_attempts })
  }

  fn prepare_liquidity_policy_source<T: Config>(
    actor_type: ActorType,
    on_error: StepErrorPolicy,
  ) -> Result<StepPolicySource<T>, BenchmarkError> {
    prepare_liquidity_policy_source_with_inputs::<T>(actor_type, on_error, false)
  }

  fn prepare_liquidity_policy_source_with_inputs<T: Config>(
    actor_type: ActorType,
    on_error: StepErrorPolicy,
    small_inputs: bool,
  ) -> Result<StepPolicySource<T>, BenchmarkError> {
    if on_error
      .retry_max_attempts()
      .is_some_and(|limit| limit < 2 || limit > T::MaxRetryAttempts::get())
    {
      return Err(BenchmarkError::Stop(
        "liquidity recovery needs a permitted retry",
      ));
    }
    let (retry_steps, (asset_a, asset_b, _, _)) = retry_contract_with_opening_partition::<T>(
      T::MaxContractSteps::get() * benchmark_predicate_capacity::<T>(),
    )?;
    let profile = if actor_type == ActorType::User {
      ReachableOpeningProfile::UserTransferHeaderMax
    } else {
      ReachableOpeningProfile::SystemTransferHeaderMax
    };
    let tails = T::MaxContractSteps::get()
      .saturating_sub(1)
      .div_ceil(MAX_STEPS_PER_TAIL_CHUNK);
    let mut successor = retry_steps[0].clone();
    successor.on_error = on_error;
    if small_inputs {
      let ActorTask::AddLiquidity {
        amount_a,
        amount_b,
        min_lp_out,
        ..
      } = &mut successor.task
      else {
        panic!("liquidity source")
      };
      *amount_a = AmountResolution::Fixed(One::one());
      *amount_b = AmountResolution::Fixed(One::one());
      *min_lp_out = One::one();
    }
    let (actor_id, count) = prepare_reachable_opening_with_authored_successor::<T>(
      tails,
      profile,
      true,
      Some(successor),
      !small_inputs,
      None,
      false,
    )?;
    assert_eq!(count, T::MaxContractSteps::get());
    let (contract, base) = Pallet::<T>::load_admitted_contract_geometry(actor_id).unwrap();
    let payer = Pallet::<T>::actor_identity(actor_id)
      .unwrap()
      .sovereign_account;
    let a = T::AssetOps::balance(&payer, asset_a);
    let b = T::AssetOps::balance(&payer, asset_b);
    assert!(!a.is_zero() && !b.is_zero());
    let ActorTask::AddLiquidity { min_lp_out, .. } = contract.steps[1].task else {
      panic!("retry fixture supplies AddLiquidity")
    };
    if small_inputs {
      assert_eq!(min_lp_out, One::one());
    } else {
      assert!(min_lp_out >= a.max(b));
    }
    install_step_policy_source::<T>(
      actor_id,
      actor_type,
      contract,
      base,
      maximum_behavior_expression::<T>()?,
    )
  }

  fn prepare_service_fee_policy_source<T: Config>(
    retry: bool,
  ) -> Result<StepPolicySource<T>, BenchmarkError> {
    let owner = account("service-fee-source-owner", 0, 0);
    ensure_creation_balance::<T>(&owner);
    let asset = T::BenchmarkHelper::setup_predicate_assets(&owner, 2)?
      .into_iter()
      .find(|asset| *asset != T::FeeNativeAssetId::get())
      .ok_or(BenchmarkError::Stop("non-native input required"))?;
    let successor = Step {
      precondition: None,
      task: ActorTask::Transfer {
        to: account("service-fee-target", 0, 0),
        asset,
        amount: AmountResolution::Fixed(One::one()),
      },
      on_error: if retry {
        StepErrorPolicy::RetryLater {
          max_attempts: T::MaxRetryAttempts::get(),
        }
      } else {
        StepErrorPolicy::ContinueNextStep
      },
    };
    let prefix = ActorTask::Transfer {
      to: account("native-fee-prefix-recipient", 0, 0),
      asset: T::FeeNativeAssetId::get(),
      amount: AmountResolution::Percent(Perbill::one()),
    };
    let tails = T::MaxContractSteps::get()
      .saturating_sub(1)
      .div_ceil(MAX_STEPS_PER_TAIL_CHUNK);
    let (id, count) = prepare_reachable_opening_with_authored_successor::<T>(
      tails,
      ReachableOpeningProfile::UserTransferHeaderMax,
      true,
      Some(successor),
      false,
      Some(prefix),
      false,
    )?;
    assert_eq!(count, T::MaxContractSteps::get());
    let (contract, admission) = Pallet::<T>::load_admitted_contract_geometry(id).unwrap();
    assert_eq!(contract.on_unfunded, OnUnfunded::Close);
    assert_eq!(contract.cooldown_blocks, 0);
    install_step_policy_source::<T>(
      id,
      ActorType::User,
      contract,
      admission,
      maximum_behavior_expression::<T>()?,
    )
  }

  fn execute_running_service_fee_policy_attempt<T: Config>(
    actor: ActorRef,
    kind: ServiceResidenceKind,
    state: ActiveActorStateOf<T>,
    plan: CurrentStepPlanOf<T>,
    admission: &ActorAdmissionCertificateOf<T>,
    now: BlockNumberFor<T>,
    retry: bool,
  ) {
    let next = Pallet::<T>::benchmark_running_service_fee_control(
      actor.actor_id,
      state,
      plan,
      admission,
      now,
      retry,
    )
    .unwrap();
    Pallet::<T>::try_store_service_control_state(actor, kind, next.identity, next.hot).unwrap();
    Pallet::<T>::advance_service_head(actor, now).unwrap();
  }

  /// First Running ServiceFee shortage under Close, never a Suspended retry admission.
  #[benchmark(extra, pov_mode = Measured)]
  fn running_policy_service_fee(f: Linear<0, 1>, r: Linear<0, 1>) -> Result<(), BenchmarkError> {
    let retry = f == 1;
    let StepPolicySource {
      actor,
      state,
      admission,
      plan,
      contract,
    } = prepare_service_fee_policy_source::<T>(retry)?;
    let id = actor.actor_id;
    let payer = state.identity.sovereign_account.clone();
    let native = T::FeeNativeAssetId::get();
    assert_eq!(contract.steps.len() as u32, T::MaxContractSteps::get());
    assert!(matches!(contract.trigger, Trigger::Manual));
    assert!(
      contract.window.is_none()
        && contract.parked_balance_activation.is_none()
        && contract.auto_close_at_cycle_nonce.is_none()
    );
    let first = plan.loaded_step.step.clone();
    let ActorTask::Transfer {
      to,
      asset,
      amount: AmountResolution::Percent(ratio),
    } = first.task.clone()
    else {
      panic!("native prefix")
    };
    assert_eq!(asset, native);
    assert_eq!(ratio, Perbill::one());
    assert_eq!(Some(admission.body_commitment), contract.body_commitment());
    let native_before = T::AssetOps::balance(&payer, native);
    let recipient_before = T::AssetOps::balance(&to, native);
    let sink_before = T::AssetOps::total_balance(&T::FeeSink::get(), native);
    let pipeline = Pallet::<T>::pipeline_fee_for_actor(id, ActorType::User)
      .unwrap()
      .total_fee;
    assert!(!pipeline.is_zero());
    let Some(ProcessResidence::Service(kind)) = ActorProcesses::<T>::get(id).unwrap().residence
    else {
      panic!("Service source")
    };
    let opening = frame_system::Pallet::<T>::block_number();
    let held = ActorStateHolds::<T>::get(id);
    let (opening_effect, opening_fee, action_fee) =
      polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
        let nonce = plan.ticket.cycle_nonce;
        let (next, reason, effect, _) =
          Pallet::<T>::benchmark_transfer_control(id, state, plan, &admission, opening).unwrap();
        assert!(reason.is_none());
        Pallet::<T>::try_store_service_control_state(actor, kind, next.identity, next.hot).unwrap();
        Pallet::<T>::advance_service_head(actor, opening).unwrap();
        let fee = Pallet::<T>::maximum_current_action_fee(
          ActorType::User,
          &first,
          ActorStepResourceEnvelope {
            control: Weight::zero(),
            effect,
          },
        )
        .unwrap();
        assert!(!fee.total_fee.is_zero());
        Pallet::<T>::collect_user_step_fee(&payer, fee.total_fee).unwrap();
        Pallet::<T>::deposit_action_fee_receipt(id, nonce, 0, effect, fee.effect_fee);
        polkadot_sdk::frame_support::storage::TransactionOutcome::Commit((
          effect,
          fee.effect_fee,
          fee.total_fee,
        ))
      });
    let floor = T::MinUserBalance::get();
    let credit = native_before
      .checked_sub(&pipeline)
      .and_then(|x| x.checked_sub(&action_fee))
      .and_then(|x| x.checked_sub(&floor))
      .unwrap();
    assert!(!credit.is_zero());
    assert_eq!(T::AssetOps::balance(&payer, native), floor);
    assert_eq!(
      T::AssetOps::balance(&to, native),
      recipient_before.checked_add(&credit).unwrap()
    );
    let sink = sink_before
      .checked_add(&pipeline)
      .and_then(|x| x.checked_add(&action_fee))
      .unwrap();
    assert_eq!(T::AssetOps::total_balance(&T::FeeSink::get(), native), sink);
    let (state, certificate, plan, kind, now) = prepare_policy_step_attempt::<T>(actor);
    assert_eq!(certificate, admission);
    assert_eq!(plan.loaded_step.step, contract.steps[1]);
    assert_eq!(state.hot.cycle_state, CycleState::Running);
    assert!(!plan.maximum_fee.total_fee.is_zero());
    let ActorTask::Transfer {
      asset,
      to: target,
      amount: AmountResolution::Fixed(amount),
    } = plan.loaded_step.step.task.clone()
    else {
      panic!("funded successor")
    };
    assert_ne!(asset, native);
    assert_eq!(amount, One::one());
    assert!(T::AssetOps::balance(&payer, asset) > amount);
    let target_before = T::AssetOps::balance(&target, asset);
    let custody = expected_step_balances::<T>(&payer, &contract, Zero::zero(), None);
    let before = ActorSemanticStates::<T>::get(id);
    let prefix = ActorRunStateStore::<T>::get(id).unwrap();
    assert_eq!(prefix.cursor, 1);
    assert_eq!(prefix.cumulative_outcomes.committed_effectful_tasks, 1);
    let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    #[block]
    {
      polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
        execute_running_service_fee_policy_attempt::<T>(
          actor, kind, state, plan, &admission, now, retry,
        );
        if r == 1 {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(())
        } else {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(())
        }
      });
    }
    assert_eq!(ActorStateHolds::<T>::get(id), held);
    assert!(!crate::ActorFinancialWaits::<T>::contains_key(id));
    assert!(!DeadlineHandles::<T>::contains_key(id));
    assert!(ServiceNodes::<T>::contains_key(id));
    for (asset, amount) in custody {
      assert_eq!(T::AssetOps::balance(&payer, asset), amount);
    }
    assert_eq!(T::AssetOps::balance(&target, asset), target_before);
    assert_eq!(
      T::AssetOps::balance(&to, native),
      recipient_before.checked_add(&credit).unwrap()
    );
    assert_eq!(T::AssetOps::total_balance(&T::FeeSink::get(), native), sink);
    let (retained, certificate) = Pallet::<T>::load_admitted_contract_geometry(id).unwrap();
    assert_eq!(retained, contract);
    assert_eq!(certificate, admission);
    for receipt in [
      Event::<T>::PipelineFeeCharged {
        actor_id: id,
        fee: pipeline,
      },
      Event::<T>::ActionFeeCharged {
        actor_id: id,
        cycle_nonce: 1,
        step_index: 0,
        actual_effect_weight: opening_effect,
        fee: opening_fee,
      },
    ] {
      let receipt: <T as frame_system::Config>::RuntimeEvent = receipt.into();
      assert_eq!(
        frame_system::Pallet::<T>::events()
          .iter()
          .filter(|event| event.event == receipt)
          .count(),
        1
      );
    }
    if r == 1 {
      assert_eq!(ActorSemanticStates::<T>::get(id), before);
      assert_eq!(ActorRunStateStore::<T>::get(id), Some(prefix));
      assert_eq!(
        polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
        root
      );
    } else {
      let ActorSemanticState::Active(next) = ActorSemanticStates::<T>::get(id).unwrap() else {
        panic!("Active successor")
      };
      assert_eq!(next.identity.cycle_nonce, 0);
      assert_eq!(
        next.hot.cycle_state,
        if retry {
          CycleState::Suspended
        } else {
          CycleState::Running
        }
      );
      assert_eq!(next.hot.unsuccessful_attempt_streak, u32::from(retry));
      let run = ActorRunStateStore::<T>::get(id).unwrap();
      assert_eq!(run.cycle_nonce, 1);
      assert_eq!(run.cursor, if retry { 1 } else { 2 });
      assert_eq!(run.eligible_at, now.checked_add(&One::one()).unwrap());
      assert_eq!(run.unsuccessful_attempts_at_cursor, u32::from(retry));
      assert_eq!(run.cumulative_outcomes.committed_effectful_tasks, 1);
      assert_eq!(run.cumulative_outcomes.failed_steps, 0);
      assert_eq!(
        run.cumulative_outcomes.skipped_funding_unavailable,
        u32::from(!retry)
      );
      assert_eq!(
        run.last_step_outcome,
        Some(StepOutcome::FundingUnavailable(
          crate::FundingUnavailableReason::ServiceFee
        ))
      );
    }
    Ok(())
  }

  #[cfg(test)]
  #[test]
  fn service_fee_policy_uses_authored_native_spend_and_preserves_paid_prefix() {
    for retry in [false, true] {
      for rollback in [false, true] {
        new_test_ext().execute_with(|| {
          crate::mock::set_missing_behavior_control_weight(true);
          crate::mock::set_missing_behavior_close_weight(true);
          crate::mock::set_missing_behavior_inspection_weight(true);
          let StepPolicySource {
            actor,
            state,
            admission,
            plan,
            contract,
          } = prepare_service_fee_policy_source::<Test>(retry).unwrap();
          let id = actor.actor_id;
          let payer = state.identity.sovereign_account;
          let native = <Test as Config>::FeeNativeAssetId::get();
          let first = plan.loaded_step.step.clone();
          let ActorTask::Transfer {
            to,
            asset,
            amount: AmountResolution::Percent(ratio),
          } = first.task
          else {
            panic!("native prefix")
          };
          assert_eq!(asset, native);
          assert_eq!(ratio, Perbill::one());
          assert_eq!(Some(admission.body_commitment), contract.body_commitment());
          let native_before = <Test as Config>::AssetOps::balance(&payer, native);
          let recipient_before = <Test as Config>::AssetOps::balance(&to, native);
          let sink_before =
            <Test as Config>::AssetOps::total_balance(&<Test as Config>::FeeSink::get(), native);
          let pipeline = Pallet::<Test>::pipeline_fee_for_actor(id, ActorType::User)
            .unwrap()
            .total_fee;
          assert!(pipeline > 0);
          let Some(ProcessResidence::Service(kind)) =
            ActorProcesses::<Test>::get(id).unwrap().residence
          else {
            panic!("Service source")
          };
          let now = frame_system::Pallet::<Test>::block_number();
          let held = ActorStateHolds::<Test>::get(id);
          let action_fee = polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
            let nonce = plan.ticket.cycle_nonce;
            let (next, reason, effect, _) =
              Pallet::<Test>::benchmark_transfer_control(id, state, plan, &admission, now).unwrap();
            assert!(reason.is_none());
            Pallet::<Test>::try_store_service_control_state(actor, kind, next.identity, next.hot)
              .unwrap();
            Pallet::<Test>::advance_service_head(actor, now).unwrap();
            let fee = Pallet::<Test>::maximum_current_action_fee(
              ActorType::User,
              &first,
              ActorStepResourceEnvelope {
                control: Weight::zero(),
                effect,
              },
            )
            .unwrap();
            assert!(fee.total_fee > 0);
            Pallet::<Test>::collect_user_step_fee(&payer, fee.total_fee).unwrap();
            Pallet::<Test>::deposit_action_fee_receipt(id, nonce, 0, effect, fee.effect_fee);
            polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(fee.total_fee)
          });
          let floor = <Test as Config>::MinUserBalance::get();
          assert_eq!(<Test as Config>::AssetOps::balance(&payer, native), floor);
          assert_eq!(
            <Test as Config>::AssetOps::balance(&to, native),
            recipient_before + native_before - pipeline - action_fee - floor
          );
          assert_eq!(
            <Test as Config>::AssetOps::total_balance(&<Test as Config>::FeeSink::get(), native),
            sink_before + pipeline + action_fee
          );
          let (state, certificate, plan, kind, now) = prepare_policy_step_attempt::<Test>(actor);
          assert_eq!(certificate, admission);
          assert_eq!(plan.loaded_step.step, contract.steps[1]);
          assert!(plan.maximum_fee.total_fee > 0);
          let ActorTask::Transfer {
            asset,
            to: target,
            amount: AmountResolution::Fixed(amount),
          } = plan.loaded_step.step.task
          else {
            panic!("funded successor")
          };
          assert_ne!(asset, native);
          assert_eq!(amount, 1);
          assert!(<Test as Config>::AssetOps::balance(&payer, asset) > amount);
          let target_before = <Test as Config>::AssetOps::balance(&target, asset);
          let custody = expected_step_balances::<Test>(&payer, &contract, 0, None);
          let before = ActorSemanticStates::<Test>::get(id);
          let prefix = ActorRunStateStore::<Test>::get(id).unwrap();
          assert_eq!(prefix.cursor, 1);
          assert_eq!(prefix.cumulative_outcomes.committed_effectful_tasks, 1);
          let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
          polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
            execute_running_service_fee_policy_attempt::<Test>(
              actor, kind, state, plan, &admission, now, retry,
            );
            let ActorSemanticState::Active(next) = ActorSemanticStates::<Test>::get(id).unwrap()
            else {
              panic!("Active successor")
            };
            assert_eq!(
              next.hot.cycle_state,
              if retry {
                CycleState::Suspended
              } else {
                CycleState::Running
              }
            );
            assert_eq!(next.identity.cycle_nonce, 0);
            assert_eq!(next.hot.unsuccessful_attempt_streak, u32::from(retry));
            let run = ActorRunStateStore::<Test>::get(id).unwrap();
            assert_eq!(run.cycle_nonce, 1);
            assert_eq!(run.cursor, if retry { 1 } else { 2 });
            assert_eq!(run.eligible_at, now + 1);
            assert_eq!(run.unsuccessful_attempts_at_cursor, u32::from(retry));
            assert_eq!(run.cumulative_outcomes.committed_effectful_tasks, 1);
            assert_eq!(run.cumulative_outcomes.failed_steps, 0);
            assert_eq!(
              run.cumulative_outcomes.skipped_funding_unavailable,
              u32::from(!retry)
            );
            assert_eq!(
              run.last_step_outcome,
              Some(StepOutcome::FundingUnavailable(
                crate::FundingUnavailableReason::ServiceFee
              ))
            );
            if rollback {
              polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(())
            } else {
              polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(())
            }
          });
          assert_eq!(ActorStateHolds::<Test>::get(id), held);
          assert!(!crate::ActorFinancialWaits::<Test>::contains_key(id));
          assert!(!DeadlineHandles::<Test>::contains_key(id));
          assert!(ServiceNodes::<Test>::contains_key(id));
          for (asset, amount) in custody {
            assert_eq!(<Test as Config>::AssetOps::balance(&payer, asset), amount);
          }
          assert_eq!(
            <Test as Config>::AssetOps::balance(&target, asset),
            target_before
          );
          assert_eq!(
            <Test as Config>::AssetOps::balance(&to, native),
            recipient_before + native_before - pipeline - action_fee - floor
          );
          assert_eq!(
            <Test as Config>::AssetOps::total_balance(&<Test as Config>::FeeSink::get(), native),
            sink_before + pipeline + action_fee
          );
          let (retained, certificate) =
            Pallet::<Test>::load_admitted_contract_geometry(id).unwrap();
          assert_eq!(retained, contract);
          assert_eq!(certificate, admission);
          let mut pipelines = 0;
          let mut actions = 0;
          for event in frame_system::Pallet::<Test>::events() {
            match event.event {
              crate::mock::RuntimeEvent::Actors(Event::PipelineFeeCharged { actor_id, fee })
                if actor_id == id =>
              {
                assert_eq!(fee, pipeline);
                pipelines += 1;
              }
              crate::mock::RuntimeEvent::Actors(Event::ActionFeeCharged {
                actor_id,
                step_index,
                ..
              }) if actor_id == id => {
                assert_eq!(step_index, 0);
                actions += 1;
              }
              crate::mock::RuntimeEvent::Actors(Event::ActorClosed { actor_id, .. })
                if actor_id == id =>
              {
                panic!("no close")
              }
              _ => {}
            }
          }
          assert_eq!((pipelines, actions), (1, 1));
          if rollback {
            assert_eq!(ActorSemanticStates::<Test>::get(id), before);
            assert_eq!(ActorRunStateStore::<Test>::get(id), Some(prefix));
            assert_eq!(
              polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
              root
            );
          }
        });
      }
    }
  }

  #[cfg(test)]
  #[test]
  fn service_fee_suspended_component_source_preserves_outer_price_refusals() {
    use polkadot_sdk::frame_support::traits::fungible::InspectHold;
    for mode in 0..4 {
      new_test_ext().execute_with(|| {
        // Existing mock ports model availability, not qualified reference coefficients.
        crate::mock::set_missing_behavior_inspection_weight(mode == 0);
        crate::mock::set_missing_behavior_control_weight(mode == 1);
        crate::mock::set_missing_behavior_close_weight(mode == 2);
        let id = NextActorId::<Test>::get();
        _running_policy_service_fee::<Test>(1, 0, true).unwrap();
        assert_eq!(NextActorId::<Test>::get(), id + 1);
        let ActorSemanticState::Active(record) = ActorSemanticStates::<Test>::get(id).unwrap()
        else {
          panic!("Suspended source")
        };
        assert_eq!(record.hot.cycle_state, CycleState::Suspended);
        let run = ActorRunStateStore::<Test>::get(id).unwrap();
        assert_eq!(run.cursor, 1);
        assert_eq!(run.unsuccessful_attempts_at_cursor, 1);
        assert_eq!(run.cumulative_outcomes.committed_effectful_tasks, 1);
        assert_eq!(
          run.last_step_outcome,
          Some(StepOutcome::FundingUnavailable(
            crate::FundingUnavailableReason::ServiceFee
          ))
        );
        let now = run.eligible_at;
        assert_eq!(now, frame_system::Pallet::<Test>::block_number() + 1);
        frame_system::Pallet::<Test>::set_block_number(now);
        let (contract, certificate) = Pallet::<Test>::load_admitted_contract_geometry(id).unwrap();
        assert_eq!(contract.on_unfunded, OnUnfunded::Close);
        let payer = record.identity.sovereign_account;
        let owner = record.identity.owner;
        assert_ne!(payer, owner);
        let native = <Test as Config>::FeeNativeAssetId::get();
        assert_eq!(
          <Test as Config>::AssetOps::balance(&payer, native),
          <Test as Config>::MinUserBalance::get()
        );
        let custody = expected_step_balances::<Test>(&payer, &contract, 0, None);
        let ActorTask::Transfer { to, .. } = contract.steps[0].task else {
          panic!("paid prefix")
        };
        let recipient = <Test as Config>::AssetOps::balance(&to, native);
        let sink =
          <Test as Config>::AssetOps::total_balance(&<Test as Config>::FeeSink::get(), native);
        let held = ActorStateHolds::<Test>::get(id).unwrap();
        assert_eq!(held.owner, owner);
        let hold_reason: crate::mock::RuntimeHoldReason = crate::HoldReason::ActorState.into();
        let owner_held = crate::mock::Balances::balance_on_hold(&hold_reason, &owner);
        let owner_free = crate::mock::Balances::free_balance(owner);
        assert!(owner_held > 0);
        let slots = OwnerSlotBitmaps::<Test>::get(owner);
        assert_eq!(slots.iter().map(|x| x.count_ones()).sum::<u32>(), 1);
        let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
        let mut meter = polkadot_sdk::sp_weights::WeightMeter::with_limit(Weight::MAX);
        if mode == 3 {
          let (_, _, loaded) = Pallet::<Test>::benchmark_policy_step_source(id).unwrap();
          let policy = ActorBehaviorPolicies::<Test>::get(id).unwrap();
          let behavior = Pallet::<Test>::behavior_control_weight_context(&policy).unwrap();
          let context = Pallet::<Test>::step_control_weight_context(
            contract.steps.len() as u32,
            loaded.cursor,
            0,
          )
          .unwrap();
          let required = <Test as Config>::StepControlWeight::maximum_behavior_control_weight(
            context,
            &loaded.step,
            behavior,
          )
          .unwrap();
          assert!(
            !required.all_lte(loaded.resources.control),
            "component source is not a policy-priced declaration"
          );
        }
        let result = Pallet::<Test>::service_canonical_round_head(&mut meter, now);
        assert!(
          result.is_err(),
          "unqualified component source must refuse: {result:?}"
        );
        assert!(!meter.consumed().is_zero());
        for (asset, balance) in custody {
          assert_eq!(<Test as Config>::AssetOps::balance(&payer, asset), balance);
        }
        assert_eq!(<Test as Config>::AssetOps::balance(&to, native), recipient);
        assert_eq!(
          <Test as Config>::AssetOps::total_balance(&<Test as Config>::FeeSink::get(), native),
          sink
        );
        assert!(!crate::ActorFinancialWaits::<Test>::contains_key(id));
        assert_eq!(
          ActorSemanticStates::<Test>::get(id),
          Some(ActorSemanticState::Active(record))
        );
        assert_eq!(ActorRunStateStore::<Test>::get(id), Some(run));
        assert_eq!(ActorStateHolds::<Test>::get(id), Some(held));
        assert_eq!(OwnerSlotBitmaps::<Test>::get(owner), slots);
        assert_eq!(
          crate::mock::Balances::balance_on_hold(&hold_reason, &owner),
          owner_held
        );
        assert_eq!(crate::mock::Balances::free_balance(owner), owner_free);
        assert_eq!(
          Pallet::<Test>::load_admitted_contract_geometry(id).unwrap(),
          (contract, certificate)
        );
        assert_eq!(
          polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
          root
        );
      });
    }
  }

