  fn prepare_stop_cycle_policy_source<T: Config>(
    c: u32,
    closes: bool,
  ) -> Result<StepPolicySource<T>, BenchmarkError> {
    let profile = if c == 0 {
      ReachableOpeningProfile::UserCompleteHeaderMax
    } else {
      ReachableOpeningProfile::CompleteMax
    };
    let expression = if closes {
      cycle_completion_behavior_expression::<T>()?
    } else {
      maximum_behavior_expression::<T>()?
    };
    let source = prepare_step_policy_source::<T>(
      profile,
      if c == 0 {
        ActorType::User
      } else {
        ActorType::System
      },
      expression,
    )?;
    assert!(matches!(
      source.plan.loaded_step.step.task,
      ActorTask::StopCycle
    ));
    assert!(source.plan.maximum_fee.total_fee.is_zero());
    Ok(source)
  }

  fn action_success_behavior_expression<T: Config>() -> Result<CloseWhenOf<T>, BenchmarkError> {
    use BehaviorMetric::*;
    let mut expression = maximum_behavior_expression::<T>()?;
    expression.clauses[1] = expression.clauses[2].clone();
    expression.clauses[2] = [
      PreconditionRejectTotal,
      ActionFailureTotal,
      ActionFailureStreak,
      CycleCompletedTotal,
    ]
    .into_iter()
    .map(|metric| BehaviorAtom {
      metric,
      threshold: u32::MAX,
    })
    .collect::<Vec<_>>()
    .try_into()
    .expect("four atoms fit");
    expression.clauses[3] = vec![BehaviorAtom {
      metric: ActionSuccessTotal,
      threshold: 1,
    }]
    .try_into()
    .expect("one success atom fits");
    Ok(expression)
  }

  /// Joined nonterminal StopCycle control/publication, excluding host price settlement.
  #[benchmark(extra, pov_mode = Measured)]
  fn stop_cycle_policy_publication(c: Linear<0, 1>, r: Linear<0, 1>) -> Result<(), BenchmarkError> {
    let StepPolicySource {
      actor,
      state,
      admission,
      plan,
      contract,
    } = prepare_stop_cycle_policy_source::<T>(c, false)?;
    let actor_id = actor.actor_id;
    let identity = state.identity.clone();
    let actor_type = identity.actor_class.actor_type();
    let Some(ProcessResidence::Service(kind)) =
      ActorProcesses::<T>::get(actor_id).unwrap().residence
    else {
      panic!("prepared source has Service residence")
    };
    assert_eq!(ServiceHeader::<T>::get().count, 1);
    let head = ActorContractHeads::<T>::get(actor_id);
    let tails = ActorContractTailChunks::<T>::iter_prefix(actor_id).collect::<Vec<_>>();
    let policy = ActorBehaviorPolicies::<T>::get(actor_id);
    let monitor = ActorBehaviorMonitors::<T>::get(actor_id);
    let hold = ActorStateHolds::<T>::get(actor_id);
    let hold_reason: T::RuntimeHoldReason = HoldReason::ActorState.into();
    let owner_hold = T::StateHoldCurrency::balance_on_hold(&hold_reason, &identity.owner);
    let slots = OwnerSlotBitmaps::<T>::get(&identity.owner);
    let active_count = ActiveActorCount::<T>::get();
    let identity_count = ActorIdentityCount::<T>::get();
    let native = T::FeeNativeAssetId::get();
    let pipeline = Pallet::<T>::pipeline_fee_for_actor(actor_id, actor_type)
      .unwrap()
      .total_fee;
    assert_eq!(pipeline.is_zero(), actor_type == ActorType::System);
    let payer = &identity.sovereign_account;
    let mut balances = vec![(
      native,
      T::AssetOps::balance(payer, native)
        .checked_sub(&pipeline)
        .unwrap(),
    )];
    for step in contract.steps.iter().skip(1) {
      if let ActorTask::AddLiquidity {
        asset_a, asset_b, ..
      } = step.task
      {
        for asset in [asset_a, asset_b] {
          if asset != native {
            balances.push((asset, T::AssetOps::balance(payer, asset)));
          }
        }
      }
    }
    let sink = T::AssetOps::balance(&T::FeeSink::get(), native)
      .checked_add(&pipeline)
      .unwrap();
    let expected_effect = T::TaskEffectWeight::actual_effect_weight(
      &ActorTask::StopCycle,
      TaskEffectExecution::Invoked,
    )
    .expect("real StopCycle effect owner exists");
    let now = frame_system::Pallet::<T>::block_number();
    let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    let observed;
    #[block]
    {
      observed = polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
        let (state, reason, effect) =
          Pallet::<T>::benchmark_stop_cycle_control(actor_id, state, plan, &admission, now)
            .expect("real StopCycle control completes without optional price proxies");
        assert!(reason.is_none());
        let placement = Pallet::<T>::publish_idle_cycle_completion(actor, kind, &state, now)
          .expect("surviving Idle authority and passive placement publish together");
        if r == 1 {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback((effect, placement))
        } else {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Commit((effect, placement))
        }
      });
    }
    assert_eq!(observed.0, expected_effect);
    if r == 1 {
      assert_eq!(
        polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
        root
      );
    } else {
      let ActorSemanticState::Active(record) = ActorSemanticStates::<T>::get(actor_id).unwrap()
      else {
        panic!("nonterminal StopCycle retains Active authority")
      };
      let mut expected_identity = identity.clone();
      expected_identity.cycle_nonce += 1;
      assert_eq!(record.identity, expected_identity);
      assert_eq!(record.hot.cycle_state, CycleState::Idle);
      assert!(!record.hot.pending_signal);
      assert!(!ActorRunStateStore::<T>::contains_key(actor_id));
      assert!(!ServiceNodes::<T>::contains_key(actor_id));
      assert_eq!(ServiceHeader::<T>::get(), ServiceHeaderRecord::default());
      let process = ActorProcesses::<T>::get(actor_id).unwrap();
      assert_eq!(process.generation, actor.generation);
      assert!(matches!(process.status, ProcessStatus::Disabled(_)));
      assert!(process.residence.is_none());
      assert_eq!(ActorContractHeads::<T>::get(actor_id), head);
      assert_eq!(
        ActorContractTailChunks::<T>::iter_prefix(actor_id).collect::<Vec<_>>(),
        tails
      );
      assert_eq!(ActorBehaviorPolicies::<T>::get(actor_id), policy);
      assert_ne!(ActorBehaviorMonitors::<T>::get(actor_id), monitor);
      assert_eq!(ActorStateHolds::<T>::get(actor_id), hold);
      assert_eq!(
        T::StateHoldCurrency::balance_on_hold(&hold_reason, &identity.owner),
        owner_hold
      );
      assert_eq!(OwnerSlotBitmaps::<T>::get(&identity.owner), slots);
      assert_eq!(ActiveActorCount::<T>::get(), active_count);
      assert_eq!(ActorIdentityCount::<T>::get(), identity_count);
      for (asset, amount) in balances {
        assert_eq!(T::AssetOps::balance(payer, asset), amount);
      }
      assert_eq!(T::AssetOps::balance(&T::FeeSink::get(), native), sink);
      let receipt: <T as frame_system::Config>::RuntimeEvent = Event::<T>::PipelineFeeCharged {
        actor_id,
        fee: pipeline,
      }
      .into();
      assert_eq!(
        frame_system::Pallet::<T>::events()
          .iter()
          .filter(|record| record.event == receipt)
          .count(),
        usize::from(actor_type == ActorType::User)
      );
    }
    Ok(())
  }

