  fn expected_step_balances<T: Config>(
    payer: &T::AccountId,
    contract: &ActorContractOf<T>,
    fees: T::Balance,
    transfer: Option<(T::AssetId, T::Balance)>,
  ) -> Vec<(T::AssetId, T::Balance)> {
    let native = T::FeeNativeAssetId::get();
    let mut balances = vec![(
      native,
      T::AssetOps::balance(payer, native)
        .checked_sub(&fees)
        .unwrap(),
    )];
    for step in contract.steps.iter().skip(1) {
      if let ActorTask::AddLiquidity {
        asset_a, asset_b, ..
      } = step.task
      {
        for asset in [asset_a, asset_b] {
          if asset != native {
            balances.push((asset, T::AssetOps::balance(payer, asset)));
          }
        }
      }
    }
    if let Some((asset, amount)) = &transfer {
      if let Some((_, balance)) = balances
        .iter_mut()
        .find(|(candidate, _)| candidate == asset)
      {
        *balance = balance.checked_sub(amount).unwrap();
      } else {
        balances.push((
          *asset,
          T::AssetOps::balance(payer, *asset)
            .checked_sub(amount)
            .unwrap(),
        ));
      }
    }
    balances
  }

  fn prepare_step_close_expectation<T: Config>(
    actor_id: ActorId,
    state: &ActiveActorStateOf<T>,
    contract: &ActorContractOf<T>,
    pipeline: T::Balance,
    action: T::Balance,
    transfer: Option<(T::AccountId, T::AssetId, T::Balance)>,
  ) -> CloseDestructionFixture<T> {
    let native = T::FeeNativeAssetId::get();
    let balances = expected_step_balances::<T>(
      &state.identity.sovereign_account,
      contract,
      pipeline.checked_add(&action).unwrap(),
      transfer
        .as_ref()
        .map(|(_, asset, amount)| (*asset, *amount)),
    );
    let held = ActorStateHolds::<T>::get(actor_id).map_or(Zero::zero(), |record| {
      let b = record.breakdown;
      [
        b.identity,
        b.contract_head,
        b.contract_body,
        b.detector,
        b.run,
      ]
      .into_iter()
      .try_fold(T::Balance::zero(), |total, amount| {
        total.checked_add(&amount)
      })
      .unwrap()
    });
    let hold_reason: T::RuntimeHoldReason = HoldReason::ActorState.into();
    let owner_hold_after =
      T::StateHoldCurrency::balance_on_hold(&hold_reason, &state.identity.owner)
        .checked_sub(&held)
        .unwrap();
    let mut owner_slots_after = OwnerSlotBitmaps::<T>::get(&state.identity.owner);
    if let ActorClass::User { owner_slot } = state.identity.actor_class {
      owner_slots_after[usize::from(owner_slot) / 8] &= !(1 << (owner_slot % 8));
    }
    CloseDestructionFixture {
      actor_id,
      identity: state.identity.clone(),
      balances,
      owner_hold_after,
      owner_slots_after,
      active_count_after: ActiveActorCount::<T>::get() - 1,
      identity_count_after: ActorIdentityCount::<T>::get() - 1,
      sink_balance: T::AssetOps::balance(&T::FeeSink::get(), native)
        .checked_add(&pipeline)
        .and_then(|balance| balance.checked_add(&action))
        .unwrap(),
      committed_credit: transfer.map(|(recipient, asset, amount)| {
        let after = T::AssetOps::balance(&recipient, asset)
          .checked_add(&amount)
          .unwrap();
        (recipient, asset, after)
      }),
    }
  }

  fn execute_transfer_policy_progression<T: Config>(
    actor: ActorRef,
    kind: ServiceResidenceKind,
    state: ActiveActorStateOf<T>,
    plan: CurrentStepPlanOf<T>,
    admission: &ActorAdmissionCertificateOf<T>,
    now: BlockNumberFor<T>,
  ) -> Weight {
    let actor_type = state.identity.actor_class.actor_type();
    let payer = state.identity.sovereign_account.clone();
    let step = plan.loaded_step.step.clone();
    let cursor = plan.loaded_step.cursor;
    let nonce = plan.ticket.cycle_nonce;
    let (next, reason, effect, _) =
      Pallet::<T>::benchmark_transfer_control(actor.actor_id, state, plan, admission, now)
        .expect("real Transfer and false policy reduce without optional control prices");
    assert!(reason.is_none());
    Pallet::<T>::try_store_service_control_state(actor, kind, next.identity, next.hot)
      .expect("surviving Run authority publishes");
    Pallet::<T>::advance_service_head(actor, now).expect("Q1 advances to captured successor");
    let fee = Pallet::<T>::maximum_current_action_fee(
      actor_type,
      &step,
      ActorStepResourceEnvelope {
        control: Weight::zero(),
        effect,
      },
    )
    .unwrap();
    if actor_type == ActorType::User && !fee.total_fee.is_zero() {
      Pallet::<T>::collect_user_step_fee(&payer, fee.total_fee).expect("real Action fee collected");
    }
    Pallet::<T>::deposit_action_fee_receipt(actor.actor_id, nonce, cursor, effect, fee.effect_fee);
    effect
  }

  /// Successful current Transfer, retained Run/Service and Action fee; no host control pricing.
  #[benchmark(extra, pov_mode = Measured)]
  fn transfer_policy_progression(
    c: Linear<0, 1>,
    r: Linear<0, 1>,
    h: Linear<0, 1>,
  ) -> Result<(), BenchmarkError> {
    if T::MaxContractSteps::get() < 2 {
      return Err(BenchmarkError::Stop(
        "progression requires an authored successor",
      ));
    }
    let actor_type = if c == 0 {
      ActorType::User
    } else {
      ActorType::System
    };
    let profile = if c == 0 {
      ReachableOpeningProfile::UserTransferHeaderMax
    } else {
      ReachableOpeningProfile::SystemTransferHeaderMax
    };
    let StepPolicySource {
      actor,
      state,
      admission,
      plan,
      contract,
    } = if h == 0 {
      prepare_step_policy_source::<T>(profile, actor_type, maximum_behavior_expression::<T>()?)?
    } else {
      let tails = T::MaxContractSteps::get()
        .saturating_sub(1)
        .div_ceil(MAX_STEPS_PER_TAIL_CHUNK);
      let (id, count) = prepare_reachable_opening_with_authored_successor::<T>(
        tails, profile, false, None, false, None, true,
      )?;
      assert_eq!(count, T::MaxContractSteps::get());
      let (contract, base) = Pallet::<T>::load_admitted_contract_geometry(id).unwrap();
      install_step_policy_source::<T>(
        id,
        actor_type,
        contract,
        base,
        maximum_behavior_expression::<T>()?,
      )?
    };
    let actor_id = actor.actor_id;
    let identity = state.identity.clone();
    let step = plan.loaded_step.step.clone();
    let ActorTask::Transfer {
      to,
      asset,
      amount: AmountResolution::Percent(ratio),
    } = step.task.clone()
    else {
      panic!("positive header fixture retains a percentage Transfer")
    };
    let native = T::FeeNativeAssetId::get();
    assert_ne!(asset, native);
    let payer = &identity.sovereign_account;
    let asset_before = T::AssetOps::balance(payer, asset);
    let recipient_before = T::AssetOps::balance(&to, asset);
    let amount = ratio.mul_floor(asset_before.saturating_sub(T::AssetOps::minimum_balance(asset)));
    assert!(!amount.is_zero());
    let Some(ProcessResidence::Service(kind)) =
      ActorProcesses::<T>::get(actor_id).unwrap().residence
    else {
      panic!("prepared source has Service residence")
    };
    assert_eq!(ServiceHeader::<T>::get().count, 1);
    let head = ActorContractHeads::<T>::get(actor_id);
    let tails = ActorContractTailChunks::<T>::iter_prefix(actor_id).collect::<Vec<_>>();
    let policy = ActorBehaviorPolicies::<T>::get(actor_id);
    let monitor = ActorBehaviorMonitors::<T>::get(actor_id);
    let hold = ActorStateHolds::<T>::get(actor_id);
    let hold_reason: T::RuntimeHoldReason = HoldReason::ActorState.into();
    let owner_hold = T::StateHoldCurrency::balance_on_hold(&hold_reason, &identity.owner);
    let slots = OwnerSlotBitmaps::<T>::get(&identity.owner);
    let active_count = ActiveActorCount::<T>::get();
    let identity_count = ActorIdentityCount::<T>::get();
    let sovereign_binding = SovereignIndex::<T>::get(payer);
    let expected_effect =
      T::TaskEffectWeight::actual_effect_weight(&step.task, TaskEffectExecution::Invoked)
        .expect("real Transfer effect owner exists");
    let expected_fee = Pallet::<T>::maximum_current_action_fee(
      actor_type,
      &step,
      ActorStepResourceEnvelope {
        control: Weight::zero(),
        effect: expected_effect,
      },
    )
    .unwrap();
    assert_eq!(
      expected_fee.total_fee.is_zero(),
      actor_type == ActorType::System
    );
    let pipeline = Pallet::<T>::pipeline_fee_for_actor(actor_id, actor_type)
      .unwrap()
      .total_fee;
    let fees = pipeline.checked_add(&expected_fee.total_fee).unwrap();
    let balances = expected_step_balances::<T>(payer, &contract, fees, Some((asset, amount)));
    let sink = T::AssetOps::balance(&T::FeeSink::get(), native)
      .checked_add(&fees)
      .unwrap();
    let now = frame_system::Pallet::<T>::block_number();
    let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    let effect;
    #[block]
    {
      effect = polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
        let cycle_nonce = plan.ticket.cycle_nonce;
        let (state, reason, actual_effect, _) =
          Pallet::<T>::benchmark_transfer_control(actor_id, state, plan, &admission, now)
            .expect("real Transfer and false policy reduce without optional control prices");
        assert!(reason.is_none());
        Pallet::<T>::try_store_service_control_state(
          actor,
          kind,
          state.identity.clone(),
          state.hot.clone(),
        )
        .expect("surviving Run authority publishes");
        Pallet::<T>::advance_service_head(actor, now).expect("Q1 advances to captured successor");
        let fee = Pallet::<T>::maximum_current_action_fee(
          actor_type,
          &step,
          ActorStepResourceEnvelope {
            control: Weight::zero(),
            effect: actual_effect,
          },
        )
        .unwrap();
        if actor_type == ActorType::User && !fee.total_fee.is_zero() {
          Pallet::<T>::collect_user_step_fee(payer, fee.total_fee)
            .expect("real Action fee collected");
        }
        Pallet::<T>::deposit_action_fee_receipt(
          actor_id,
          cycle_nonce,
          0,
          actual_effect,
          fee.effect_fee,
        );
        if r == 1 {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(actual_effect)
        } else {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(actual_effect)
        }
      });
    }
    assert_eq!(effect, expected_effect);
    if r == 1 {
      assert_eq!(T::AssetOps::balance(payer, asset), asset_before);
      assert_eq!(T::AssetOps::balance(&to, asset), recipient_before);
      assert_eq!(
        polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
        root
      );
    } else {
      let ActorSemanticState::Active(record) = ActorSemanticStates::<T>::get(actor_id).unwrap()
      else {
        panic!("continuation retains Active authority")
      };
      assert_eq!(record.identity, identity);
      assert_eq!(record.hot.cycle_state, CycleState::Running);
      assert!(!record.hot.pending_signal);
      let run = ActorRunStateStore::<T>::get(actor_id).unwrap();
      assert_eq!(run.cursor, 1);
      assert_eq!(run.cycle_nonce, 1);
      assert_eq!(run.eligible_at, now.checked_add(&One::one()).unwrap());
      assert_eq!(run.last_committed_step_block, Some(now));
      assert_eq!(run.cumulative_outcomes.committed_effectful_tasks, 1);
      assert_eq!(ActorContractHeads::<T>::get(actor_id), head);
      assert_eq!(
        ActorContractTailChunks::<T>::iter_prefix(actor_id).collect::<Vec<_>>(),
        tails
      );
      assert_eq!(ActorBehaviorPolicies::<T>::get(actor_id), policy);
      assert_ne!(ActorBehaviorMonitors::<T>::get(actor_id), monitor);
      assert_eq!(ActorStateHolds::<T>::get(actor_id), hold);
      assert_eq!(
        T::StateHoldCurrency::balance_on_hold(&hold_reason, &identity.owner),
        owner_hold
      );
      assert_eq!(OwnerSlotBitmaps::<T>::get(&identity.owner), slots);
      assert_eq!(SovereignIndex::<T>::get(payer), sovereign_binding);
      assert_eq!(ActiveActorCount::<T>::get(), active_count);
      assert_eq!(ActorIdentityCount::<T>::get(), identity_count);
      assert_eq!(
        ServiceNodes::<T>::get(actor_id).unwrap().last_considered,
        now
      );
      assert_eq!(
        ActorProcesses::<T>::get(actor_id).unwrap().last_attempted,
        Some(now)
      );
      let encounter = polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
        polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(
          Pallet::<T>::consider_service_head(now),
        )
      });
      assert_eq!(encounter, Ok(ServiceRoundEncounter::Closed));
      for (asset, amount) in balances {
        assert_eq!(T::AssetOps::balance(payer, asset), amount);
      }
      assert_eq!(
        T::AssetOps::balance(&to, asset),
        recipient_before.checked_add(&amount).unwrap()
      );
      assert_eq!(T::AssetOps::balance(&T::FeeSink::get(), native), sink);
      for (receipt, count) in [
        (
          Event::<T>::PipelineFeeCharged {
            actor_id,
            fee: pipeline,
          },
          usize::from(actor_type == ActorType::User),
        ),
        (
          Event::<T>::ActionFeeCharged {
            actor_id,
            cycle_nonce: 1,
            step_index: 0,
            actual_effect_weight: effect,
            fee: expected_fee.effect_fee,
          },
          1,
        ),
      ] {
        let receipt: <T as frame_system::Config>::RuntimeEvent = receipt.into();
        assert_eq!(
          frame_system::Pallet::<T>::events()
            .iter()
            .filter(|event| event.event == receipt)
            .count(),
          count
        );
      }
    }
    Ok(())
  }

  /// A successful Running Transfer after a committed paid prefix; no host control pricing.
  #[benchmark(extra, pov_mode = Measured)]
  fn running_policy_transfer(c: Linear<0, 1>, r: Linear<0, 1>) -> Result<(), BenchmarkError> {
    let rollback = r == 1;
    let actor_type = if c == 0 {
      ActorType::User
    } else {
      ActorType::System
    };
    let profile = if c == 0 {
      ReachableOpeningProfile::UserTransferHeaderMax
    } else {
      ReachableOpeningProfile::SystemTransferHeaderMax
    };
    let count = T::MaxContractSteps::get();
    if count < 3 {
      return Err(BenchmarkError::Stop(
        "Running Transfer requires a further authored successor",
      ));
    }
    let draft = make_reachable_opening_steps::<T>(count)?;
    let ActorTask::AddLiquidity { asset_a: asset, .. } = draft[1].task else {
      panic!("successor asset source")
    };
    let recipient: T::AccountId = account("running-transfer-recipient", 0, 0);
    let ratio = Perbill::from_percent(50);
    let successor = Step {
      precondition: None,
      task: ActorTask::Transfer {
        to: recipient.clone(),
        asset,
        amount: AmountResolution::Percent(ratio),
      },
      on_error: StepErrorPolicy::AbortCycle,
    };
    let (id, actual_count) = prepare_reachable_opening_with_authored_successor::<T>(
      count.saturating_sub(1).div_ceil(MAX_STEPS_PER_TAIL_CHUNK),
      profile,
      true,
      Some(successor.clone()),
      false,
      None,
      true,
    )?;
    assert_eq!(actual_count, count);
    let (contract, admission) = Pallet::<T>::load_admitted_contract_geometry(id).unwrap();
    assert_eq!(contract.steps[1], successor);
    let source = install_step_policy_source::<T>(
      id,
      actor_type,
      contract,
      admission,
      maximum_behavior_expression::<T>()?,
    )?;
    let actor = source.actor;
    let payer = source.state.identity.sovereign_account.clone();
    let owner = source.state.identity.owner.clone();
    let prefix_step = source.plan.loaded_step.step.clone();
    let ActorTask::Transfer {
      to: prefix_recipient,
      asset: prefix_asset,
      ..
    } = prefix_step.task.clone()
    else {
      panic!("prefix Transfer")
    };
    assert_ne!(prefix_recipient, recipient);
    assert_ne!(prefix_asset, asset);
    let credit_before = T::AssetOps::balance(&prefix_recipient, prefix_asset);
    let Some(ProcessResidence::Service(kind)) = ActorProcesses::<T>::get(id).unwrap().residence
    else {
      panic!("Opening source")
    };
    let opening = frame_system::Pallet::<T>::block_number();
    let pipeline = Pallet::<T>::pipeline_fee_for_actor(id, actor_type)
      .unwrap()
      .total_fee;
    assert_eq!(pipeline.is_zero(), actor_type == ActorType::System);
    let opening_effect = polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
      let effect = execute_transfer_policy_progression::<T>(
        actor,
        kind,
        source.state,
        source.plan,
        &source.admission,
        opening,
      );
      polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(effect)
    });
    let opening_action = Pallet::<T>::maximum_current_action_fee(
      actor_type,
      &prefix_step,
      ActorStepResourceEnvelope {
        control: Weight::zero(),
        effect: opening_effect,
      },
    )
    .unwrap();
    assert_eq!(
      opening_action.total_fee.is_zero(),
      actor_type == ActorType::System
    );
    let credit = T::AssetOps::balance(&prefix_recipient, prefix_asset);
    assert!(credit > credit_before);
    let (state, admission, plan, kind, now) = prepare_policy_step_attempt::<T>(actor);
    assert_eq!(now, opening.checked_add(&One::one()).unwrap());
    assert_eq!(state.hot.cycle_state, CycleState::Running);
    assert_eq!(plan.loaded_step.cursor, 1);
    assert_eq!(plan.loaded_step.step, successor);
    let prefix = ActorRunStateStore::<T>::get(id).unwrap();
    assert_eq!(prefix.cursor, 1);
    assert_eq!(prefix.cumulative_outcomes.committed_effectful_tasks, 1);
    let effect =
      T::TaskEffectWeight::actual_effect_weight(&successor.task, TaskEffectExecution::Invoked)
        .unwrap();
    let action = Pallet::<T>::maximum_current_action_fee(
      actor_type,
      &successor,
      ActorStepResourceEnvelope {
        control: Weight::zero(),
        effect,
      },
    )
    .unwrap();
    assert_eq!(action.total_fee.is_zero(), actor_type == ActorType::System);
    let available = T::AssetOps::balance(&payer, asset);
    let amount = ratio.mul_floor(
      available
        .checked_sub(&T::AssetOps::minimum_balance(asset))
        .unwrap(),
    );
    assert!(!amount.is_zero());
    let balances = expected_step_balances::<T>(
      &payer,
      &source.contract,
      action.total_fee,
      Some((asset, amount)),
    );
    let receiver_before = T::AssetOps::balance(&recipient, asset);
    let native = T::FeeNativeAssetId::get();
    let sink_before = T::AssetOps::balance(&T::FeeSink::get(), native);
    let stored = Pallet::<T>::load_admitted_contract_geometry(id).unwrap();
    let head = ActorContractHeads::<T>::get(id);
    let tails = ActorContractTailChunks::<T>::iter_prefix(id).collect::<Vec<_>>();
    let hold = ActorStateHolds::<T>::get(id);
    let slots = OwnerSlotBitmaps::<T>::get(&owner);
    let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    let actual;
    #[block]
    {
      actual = polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
        let actual =
          execute_transfer_policy_progression::<T>(actor, kind, state, plan, &admission, now);
        if rollback {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(actual)
        } else {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(actual)
        }
      });
    }
    assert_eq!(actual, effect);
    assert_eq!(
      T::AssetOps::balance(&prefix_recipient, prefix_asset),
      credit
    );
    assert_eq!(ActorContractHeads::<T>::get(id), head);
    assert_eq!(
      ActorContractTailChunks::<T>::iter_prefix(id).collect::<Vec<_>>(),
      tails
    );
    assert_eq!(ActorStateHolds::<T>::get(id), hold);
    assert_eq!(
      Pallet::<T>::load_admitted_contract_geometry(id).unwrap(),
      stored
    );
    assert_eq!(OwnerSlotBitmaps::<T>::get(&owner), slots);
    assert_eq!(
      Pallet::<T>::actor_hot(id).unwrap().cycle_state,
      CycleState::Running
    );
    if rollback {
      assert_eq!(ActorRunStateStore::<T>::get(id), Some(prefix.clone()));
      assert_eq!(T::AssetOps::balance(&payer, asset), available);
      assert_eq!(T::AssetOps::balance(&recipient, asset), receiver_before);
      assert_eq!(
        T::AssetOps::balance(&T::FeeSink::get(), native),
        sink_before
      );
      assert_eq!(
        polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
        root
      );
    } else {
      let run = ActorRunStateStore::<T>::get(id).unwrap();
      assert_eq!(run.cursor, 2);
      assert_eq!(run.cycle_nonce, prefix.cycle_nonce);
      assert_eq!(run.cumulative_outcomes.committed_effectful_tasks, 2);
      assert_eq!(run.last_committed_step_block, Some(now));
      assert_eq!(run.eligible_at, now.checked_add(&One::one()).unwrap());
      for (asset, balance) in balances {
        assert_eq!(T::AssetOps::balance(&payer, asset), balance);
      }
      assert_eq!(
        T::AssetOps::balance(&recipient, asset),
        receiver_before.checked_add(&amount).unwrap()
      );
      assert_eq!(
        T::AssetOps::balance(&T::FeeSink::get(), native),
        sink_before.checked_add(&action.total_fee).unwrap()
      );
    }
    for (event, expected) in [
      (
        Event::<T>::PipelineFeeCharged {
          actor_id: id,
          fee: pipeline,
        },
        usize::from(actor_type == ActorType::User),
      ),
      (
        Event::<T>::ActionFeeCharged {
          actor_id: id,
          cycle_nonce: prefix.cycle_nonce,
          step_index: 0,
          actual_effect_weight: opening_effect,
          fee: opening_action.effect_fee,
        },
        1,
      ),
      (
        Event::<T>::ActionFeeCharged {
          actor_id: id,
          cycle_nonce: prefix.cycle_nonce,
          step_index: 1,
          actual_effect_weight: effect,
          fee: action.effect_fee,
        },
        usize::from(!rollback),
      ),
    ] {
      let event: <T as frame_system::Config>::RuntimeEvent = event.into();
      assert_eq!(
        frame_system::Pallet::<T>::events()
          .iter()
          .filter(|record| record.event == event)
          .count(),
        expected
      );
    }
    Ok(())
  }

  #[cfg(test)]
  #[test]
  fn running_transfer_policy_preserves_paid_prefix_and_rollback() {
    for source in 0..=1 {
      for rollback in 0..=1 {
        for verify in [false, true] {
          new_test_ext().execute_with(|| {
            crate::mock::set_missing_behavior_control_weight(true);
            crate::mock::set_missing_behavior_close_weight(true);
            crate::mock::set_missing_behavior_inspection_weight(true);
            _running_policy_transfer::<Test>(source, rollback, verify).unwrap();
          });
        }
      }
    }
  }

  #[cfg(test)]
  #[test]
  fn transfer_policy_progression_preserves_full_sources_fees_and_rollback() {
    for source in 0..=1 {
      for rollback in 0..=1 {
        for header in 0..=1 {
          for verify in [false, true] {
            new_test_ext().execute_with(|| {
              crate::mock::set_missing_behavior_control_weight(true);
              crate::mock::set_missing_behavior_close_weight(true);
              crate::mock::set_missing_behavior_inspection_weight(true);
              _transfer_policy_progression::<Test>(source, rollback, header, verify).unwrap();
            });
          }
        }
      }
    }
  }

  /// Running predicate rejection with explicit predicate-account presence; raw only.
  #[benchmark(extra, pov_mode = Measured)]
  fn running_policy_predicate(
    c: Linear<0, 1>,
    p: Linear<0, 1>,
    r: Linear<0, 1>,
  ) -> Result<(), BenchmarkError> {
    let source = c;
    let populated = p == 1;
    let rollback = r == 1;
    let actor_type = if source == 0 {
      ActorType::User
    } else {
      ActorType::System
    };
    let profile = if source == 0 {
      ReachableOpeningProfile::UserTransferHeaderMax
    } else {
      ReachableOpeningProfile::SystemTransferHeaderMax
    };
    let StepPolicySource {
      actor,
      state,
      admission,
      plan,
      ..
    } = prepare_step_policy_source_with_successor::<T>(
      profile,
      actor_type,
      maximum_behavior_expression::<T>().unwrap(),
      true,
    )
    .unwrap();
    let actor_id = actor.actor_id;
    let Some(ProcessResidence::Service(kind)) =
      ActorProcesses::<T>::get(actor_id).unwrap().residence
    else {
      panic!("Opening source is on Service")
    };
    let first = plan.loaded_step.step.clone();
    let ActorTask::Transfer {
      to,
      asset,
      amount: AmountResolution::Percent(ratio),
    } = first.task.clone()
    else {
      panic!("source begins with real percentage Transfer")
    };
    let payer = state.identity.sovereign_account.clone();
    let before = <T as Config>::AssetOps::balance(&payer, asset);
    let recipient_before = <T as Config>::AssetOps::balance(&to, asset);
    let amount =
      ratio.mul_floor(before.saturating_sub(<T as Config>::AssetOps::minimum_balance(asset)));
    assert!(!amount.is_zero());
    let opening_now = frame_system::Pallet::<T>::block_number();
    let pipeline_fee = Pallet::<T>::pipeline_fee_for_actor(actor_id, actor_type)
      .unwrap()
      .total_fee;
    let (opening_effect, opening_fee) =
      polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
        let nonce = plan.ticket.cycle_nonce;
        let (next, reason, effect, _) =
          Pallet::<T>::benchmark_transfer_control(actor_id, state, plan, &admission, opening_now)
            .unwrap();
        assert!(reason.is_none());
        Pallet::<T>::try_store_service_control_state(actor, kind, next.identity, next.hot).unwrap();
        Pallet::<T>::advance_service_head(actor, opening_now).unwrap();
        let fee = Pallet::<T>::maximum_current_action_fee(
          actor_type,
          &first,
          ActorStepResourceEnvelope {
            control: Weight::zero(),
            effect,
          },
        )
        .unwrap();
        if actor_type == ActorType::User && !fee.total_fee.is_zero() {
          Pallet::<T>::collect_user_step_fee(&payer, fee.total_fee).unwrap();
        }
        Pallet::<T>::deposit_action_fee_receipt(actor_id, nonce, 0, effect, fee.effect_fee);
        polkadot_sdk::frame_support::storage::TransactionOutcome::Commit((effect, fee.effect_fee))
      });
    assert_eq!(
      <T as Config>::AssetOps::balance(&payer, asset),
      before.checked_sub(&amount).unwrap()
    );
    assert_eq!(
      <T as Config>::AssetOps::balance(&to, asset),
      recipient_before.checked_add(&amount).unwrap()
    );
    let now = frame_system::Pallet::<T>::block_number()
      .checked_add(&One::one())
      .unwrap();
    frame_system::Pallet::<T>::set_block_number(now);
    polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
      Pallet::<T>::begin_service_round(now).unwrap();
      polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(())
    });
    let (state, admission, loaded) = Pallet::<T>::benchmark_policy_step_source(actor_id).unwrap();
    assert_eq!(state.hot.cycle_state, CycleState::Running);
    assert_eq!(loaded.cursor, 1);
    assert!(matches!(loaded.step.task, ActorTask::AddLiquidity { .. }));
    assert_eq!(
      loaded
        .step
        .precondition
        .as_ref()
        .unwrap()
        .evaluation_units(),
      benchmark_predicate_capacity::<T>()
    );
    let predicate_balances = loaded
      .step
      .precondition
      .as_ref()
      .unwrap()
      .clauses
      .iter()
      .flatten()
      .map(|predicate| {
        let Predicate::BalanceAbove { asset, threshold } = predicate else {
          panic!("protected successor uses balance predicates")
        };
        assert_ne!(*asset, <T as Config>::FeeNativeAssetId::get());
        assert!(*threshold >= <T as Config>::AssetOps::minimum_balance(*asset));
        assert_eq!(
          <T as Config>::AssetOps::balance(&payer, *asset),
          Zero::zero()
        );
        assert_eq!(
          <T as Config>::BenchmarkHelper::asset_account_exists(&payer, *asset),
          Some(false)
        );
        if populated {
          <T as Config>::AssetOps::mint(&payer, *asset, *threshold).unwrap();
        }
        assert_eq!(
          <T as Config>::BenchmarkHelper::asset_account_exists(&payer, *asset),
          Some(populated)
        );
        let expected = if populated { *threshold } else { Zero::zero() };
        assert_eq!(<T as Config>::AssetOps::balance(&payer, *asset), expected);
        (*asset, expected)
      })
      .collect::<Vec<_>>();
    assert!(
      !Pallet::<T>::evaluate_precondition(
        loaded.step.precondition.as_ref().unwrap(),
        &payer,
        Zero::zero()
      )
      .unwrap()
    );
    let contract = Pallet::<T>::load_contract_geometry_with_admission(actor_id, &admission)
      .expect("verification retains the full authored custody domain outside measurement");
    assert_eq!(
      contract.steps.len() as u32,
      <<T as Config>::MaxContractSteps as Get<u32>>::get()
    );
    let payer = state.identity.sovereign_account.clone();
    let balances = expected_step_balances::<T>(&payer, &contract, Zero::zero(), None);
    let sink = <T as Config>::AssetOps::balance(
      &<T as Config>::FeeSink::get(),
      <T as Config>::FeeNativeAssetId::get(),
    );
    let holds = ActorStateHolds::<T>::get(actor_id);
    let prefix = ActorRunStateStore::<T>::get(actor_id).unwrap();
    assert_eq!(prefix.cumulative_outcomes.committed_effectful_tasks, 1);
    let receipts = [
      (
        Event::<T>::PipelineFeeCharged {
          actor_id,
          fee: pipeline_fee,
        },
        usize::from(actor_type == ActorType::User),
      ),
      (
        Event::<T>::ActionFeeCharged {
          actor_id,
          cycle_nonce: 1,
          step_index: 0,
          actual_effect_weight: opening_effect,
          fee: opening_fee,
        },
        1,
      ),
    ];
    for (receipt, count) in &receipts {
      let receipt: <T as frame_system::Config>::RuntimeEvent = receipt.clone().into();
      assert_eq!(
        frame_system::Pallet::<T>::events()
          .iter()
          .filter(|e| e.event == receipt)
          .count(),
        *count
      );
    }
    let ActorSemanticState::Active(record) = ActorSemanticStates::<T>::get(actor_id).unwrap()
    else {
      panic!("Running source retains Active authority")
    };
    let actor = ActorRef {
      actor_id,
      generation: record.generation,
    };
    let Some(ProcessResidence::Service(kind)) =
      ActorProcesses::<T>::get(actor_id).unwrap().residence
    else {
      panic!("Running source retains Service")
    };
    let fee = Pallet::<T>::maximum_current_action_fee(
      state.identity.actor_class.actor_type(),
      &loaded.step,
      loaded.resources,
    )
    .unwrap();
    let plan = Pallet::<T>::build_canonical_current_step_plan(
      actor_id,
      state.identity.clone(),
      state.hot.clone(),
      state.run_state.clone(),
      admission.clone(),
      loaded,
      fee,
    )
    .unwrap();
    let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    #[block]
    {
      polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
        let next =
          Pallet::<T>::benchmark_running_predicate_control(actor_id, state, plan, &admission, now)
            .unwrap();
        Pallet::<T>::try_store_service_control_state(actor, kind, next.identity, next.hot).unwrap();
        Pallet::<T>::advance_service_head(actor, now).unwrap();
        if rollback {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(())
        } else {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(())
        }
      });
    }
    if !rollback {
      let run = ActorRunStateStore::<T>::get(actor_id).unwrap();
      assert_eq!(run.cursor, 2);
      assert_eq!(run.cycle_nonce, prefix.cycle_nonce);
      assert_eq!(run.eligible_at, now.checked_add(&One::one()).unwrap());
      assert_eq!(run.cumulative_outcomes.committed_effectful_tasks, 1);
    }
    for (asset, expected) in predicate_balances {
      assert_eq!(<T as Config>::AssetOps::balance(&payer, asset), expected);
      assert_eq!(
        <T as Config>::BenchmarkHelper::asset_account_exists(&payer, asset),
        Some(populated)
      );
    }
    assert_eq!(ActorStateHolds::<T>::get(actor_id), holds);
    for (asset, balance) in balances {
      assert_eq!(<T as Config>::AssetOps::balance(&payer, asset), balance);
    }
    assert_eq!(
      <T as Config>::AssetOps::balance(
        &<T as Config>::FeeSink::get(),
        <T as Config>::FeeNativeAssetId::get()
      ),
      sink
    );
    for (receipt, count) in receipts {
      let receipt: <T as frame_system::Config>::RuntimeEvent = receipt.into();
      assert_eq!(
        frame_system::Pallet::<T>::events()
          .iter()
          .filter(|e| e.event == receipt)
          .count(),
        count
      );
    }
    assert_eq!(
      <T as Config>::AssetOps::balance(&payer, asset),
      before.checked_sub(&amount).unwrap()
    );
    assert_eq!(
      <T as Config>::AssetOps::balance(&to, asset),
      recipient_before.checked_add(&amount).unwrap()
    );
    if rollback {
      assert_eq!(ActorRunStateStore::<T>::get(actor_id), Some(prefix));
      assert_eq!(
        polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
        root
      );
    }

    Ok(())
  }

  #[cfg(test)]
  #[test]
  fn policy_benchmark_source_materializes_only_current_step_geometry() {
    for c in 0..=1 {
      new_test_ext().execute_with(|| {
        crate::mock::set_missing_behavior_control_weight(true);
        crate::mock::set_missing_behavior_close_weight(true);
        crate::mock::set_missing_behavior_inspection_weight(true);
        _running_policy_predicate::<Test>(c, 0, 0, true).unwrap();
        let id = NextActorId::<Test>::get() - 1;
        let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
        let tail = ActorContractTailChunks::<Test>::take(id, 1)
          .expect("configured source has an unreachable tail");
        let missing =
          polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
        let (state, _, loaded) = Pallet::<Test>::benchmark_policy_step_source(id)
          .expect("current chunk and policy suffice");
        assert_eq!(loaded.cursor, 2);
        assert_eq!(
          state.contract.steps.len() as u32,
          <<Test as Config>::MaxContractSteps as Get<u32>>::get()
        );
        assert!(state.contract.steps.iter().all(|step| step == &loaded.step));
        assert_eq!(
          polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
          missing
        );
        ActorContractTailChunks::<Test>::insert(id, 1, tail);
        assert_eq!(
          polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
          root
        );
      });
    }
  }

