  /// Joined terminal control/destruction/retirement, not a sum of intrinsic component prices.
  #[benchmark(extra, pov_mode = Measured)]
  fn zero_step_policy_terminal(c: Linear<0, 7>, r: Linear<0, 1>) -> Result<(), BenchmarkError> {
    let (fixture, state, admission) = prepare_zero_step_policy_source::<T>(c, true)?;
    let actor = fixture.actor;
    let actor_id = actor.actor_id;
    let now = frame_system::Pallet::<T>::block_number();
    let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    #[block]
    {
      polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
        let (state, reason) =
          Pallet::<T>::benchmark_zero_step_control(actor_id, state, &admission, now)
            .expect("intrinsic zero-Step control reaches its authored terminal outcome");
        assert_eq!(reason, Some(CloseReason::BehaviorPolicySatisfied));
        Pallet::<T>::benchmark_finalize_actor_from_consumed_state(
          actor_id,
          state,
          admission,
          reason.unwrap(),
        )
        .expect("consumed policy state is destroyed without a synthetic resource port");
        Pallet::<T>::retire_service_member(actor)
          .expect("semantic cleanup precedes exact Service retirement");
        if r == 1 {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(())
        } else {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(())
        }
      });
    }
    if r == 1 {
      assert_eq!(
        polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
        root,
      );
    } else {
      assert!(!ActorBehaviorPolicies::<T>::contains_key(actor_id));
      assert!(!ActorBehaviorMonitors::<T>::contains_key(actor_id));
      assert!(!ActorIdentities::<T>::contains_key(actor_id));
      assert!(!ActorControlLocators::<T>::contains_key(actor_id));
      assert!(!ActorUnsignaledControlCells::<T>::contains_key(actor_id));
      assert!(
        ActorContractTailChunks::<T>::iter_prefix(actor_id)
          .next()
          .is_none()
      );
      assert_zero_step_header_reason::<T>(fixture, true, CloseReason::BehaviorPolicySatisfied);
      #[cfg(feature = "try-runtime")]
      Pallet::<T>::do_try_state().expect("terminal policy leaves coherent peers and custody");
    }
    Ok(())
  }

  /// Joined intrinsic control plus nonterminal Service publication/placement. This includes the
  /// intrinsic owner, so its samples are not an additive publication surcharge. Prices remain absent.
  #[benchmark(extra, pov_mode = Measured)]
  fn zero_step_policy_publication(c: Linear<0, 7>, r: Linear<0, 1>) -> Result<(), BenchmarkError> {
    let (fixture, state, admission) = prepare_zero_step_policy_source::<T>(c, false)?;
    let actor = fixture.actor;
    let actor_id = actor.actor_id;
    let kind = ServiceNodes::<T>::get(actor_id).unwrap().kind;
    let now = frame_system::Pallet::<T>::block_number();
    let expected_nonce = state.identity.cycle_nonce + 1;
    let window = state.contract.window;
    let head = ActorContractHeads::<T>::get(actor_id).unwrap().encode();
    let hold = ActorStateHolds::<T>::get(actor_id).map(|h| h.encode());
    let hold_reason: T::RuntimeHoldReason = HoldReason::ActorState.into();
    let owner_hold = T::StateHoldCurrency::balance_on_hold(&hold_reason, &fixture.owner);
    let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    #[block]
    {
      polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
        let (state, reason) =
          Pallet::<T>::benchmark_zero_step_control(actor_id, state, &admission, now)
            .expect("intrinsic control completes with real retained-envelope payment");
        assert!(reason.is_none());
        let placement = Pallet::<T>::publish_idle_cycle_completion(actor, kind, &state, now)
          .expect("canonical publication/placement needs no optional price proxy");
        assert_eq!(
          placement,
          if window.is_some() {
            StepControlPlacement::Wakeup
          } else {
            StepControlPlacement::None
          }
        );
        if r == 1 {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(())
        } else {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(())
        }
      });
    }
    if r == 1 {
      assert_eq!(
        polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
        root
      );
    } else {
      let (record, process) = Pallet::<T>::load_canonical_actor_semantic_state(actor)
        .expect("published semantic owner and residence agree");
      assert_eq!(record.identity.cycle_nonce, expected_nonce);
      assert_eq!(record.hot.cycle_state, CycleState::Idle);
      assert!(!record.hot.pending_signal);
      assert_eq!(process.last_attempted, Some(now));
      assert!(!ServiceNodes::<T>::contains_key(actor_id));
      assert!(!ActorRunStateStore::<T>::contains_key(actor_id));
      assert_eq!(ServiceHeader::<T>::get().count, 2);
      assert_eq!(ServiceHeader::<T>::get().cursor, Some(fixture.successor));
      for (peer, expected) in &fixture.peers {
        assert_eq!(
          (
            ServiceNodes::<T>::get(peer.actor_id),
            ActorProcesses::<T>::get(peer.actor_id),
            ActorSemanticStates::<T>::get(peer.actor_id)
          )
            .encode(),
          *expected
        );
      }
      assert_eq!(
        DeadlineHandles::<T>::get(actor_id).map(|h| h.key),
        window.map(|w| WakeupKey::Block(w.end + One::one()))
      );
      assert_eq!(
        TriggerDeadlineHandles::<T>::contains_key(actor_id),
        c % 4 == 3
      );
      if c % 4 == 3 {
        let handle = TriggerDeadlineHandles::<T>::get(actor_id).unwrap();
        assert_eq!(handle.actor, actor);
        assert!(
          matches!(handle.key, WakeupKey::Tick(tick) if tick > Pallet::<T>::current_scheduler_tick().unwrap())
        );
        assert_eq!(
          DeadlinePages::<T>::get(handle.key, handle.page)
            .unwrap()
            .entries[handle.slot as usize],
          Some(actor)
        );
      }
      assert_eq!(
        ActorContractHeads::<T>::get(actor_id).unwrap().encode(),
        head
      );
      assert_eq!(
        ActorStateHolds::<T>::get(actor_id).map(|h| h.encode()),
        hold
      );
      assert_eq!(
        T::StateHoldCurrency::balance_on_hold(&hold_reason, &fixture.owner),
        owner_hold
      );
      assert_eq!(ActorIdentityCount::<T>::get(), fixture.identity_count);
      assert_eq!(ActiveActorCount::<T>::get(), fixture.active_count);
    }
    let paid = if r == 0 {
      fixture.pipeline_fee
    } else {
      Zero::zero()
    };
    let native = T::FeeNativeAssetId::get();
    assert_eq!(
      T::AssetOps::balance(&fixture.payer, native),
      fixture.payer_native_before - paid
    );
    assert_eq!(
      T::AssetOps::balance(&T::FeeSink::get(), native),
      fixture.sink_native_before + paid
    );
    assert_eq!(
      T::AssetOps::balance(&fixture.payer, fixture.asset),
      fixture.custody
    );
    Ok(())
  }

  /// Candidate reduction and authenticated publication, excluding source loading and Step effects.
  /// Rollback retains the original records; a satisfied candidate does not invoke Close here.
  #[benchmark(pov_mode = Measured)]
  fn behavior_candidate_publish(c: Linear<0, 5>, r: Linear<0, 1>) -> Result<(), BenchmarkError> {
    let (actor_id, header, source_cycle, cycle_nonce) = prepare_behavior_source_snapshot::<T>(c)?;
    let source = Pallet::<T>::load_step_behavior_policy(actor_id, &header)
      .expect("component source authenticates");
    let before = ActorBehaviorMonitors::<T>::get(actor_id);
    let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    #[block]
    {
      polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
        if let Some(source) = source {
          let candidate = Pallet::<T>::reduce_step_behavior_policy(
            source,
            source_cycle,
            CycleState::Idle,
            cycle_nonce,
            BehaviorObservation {
              precondition: Some(true),
              action: Some(true),
              completion: None,
            },
            CleanCycleStep::EconomicSuccess,
            Some(NormalCycleCompletion::PlanEnd),
          )
          .expect("qualified component observations reduce");
          assert!(Pallet::<T>::commit_step_behavior_candidate(&candidate));
          assert_eq!(candidate.satisfied, c == 1);
          core::hint::black_box(candidate);
        }
        if r == 1 {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(())
        } else {
          polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(())
        }
      });
    }
    if r == 1 || c < 2 {
      assert_eq!(ActorBehaviorMonitors::<T>::get(actor_id), before);
      assert_eq!(
        polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
        root
      );
    } else {
      let after = ActorBehaviorMonitors::<T>::get(actor_id).expect("accumulated monitor survives");
      assert_ne!(Some(&after), before.as_ref());
      assert!(after.clean_cycle.is_none());
    }
    Ok(())
  }

  /// Stale Running/Suspended repark refusal when financial geometry is unqualified.
  /// Financial authority is staged; public entry, backing and successful repark are separate.
  #[benchmark(extra, pov_mode = Measured)]
  fn financial_service_repark_unqualified(c: Linear<0, 1>) -> Result<(), BenchmarkError> {
    frame_system::Pallet::<T>::set_block_number(1u32.into());
    let bytes = u32::try_from(FinancialWaitEpisode::<T::Balance>::max_encoded_len())
      .map_err(|_| BenchmarkError::Stop("financial episode size must fit the host port"))?;
    if T::AdmissionCertificateAuthority::financial_wait_entry_weight(bytes).is_some()
      && T::AdmissionCertificateAuthority::financial_wait_close_additional_weight(bytes).is_some()
    {
      return Err(BenchmarkError::Skip);
    }
    let phase = if c == 0 {
      CycleState::Running
    } else {
      CycleState::Suspended
    };
    let fixture = prepare_temporal_close::<T>(ActorType::User, false, phase)?;
    let actor_id = fixture.actor_id;
    let (mut contract, base) = Pallet::<T>::load_admitted_contract_geometry(actor_id)
      .expect("ordinary retained Contract loads before component staging");
    let actor = ActorRef {
      actor_id,
      generation: benchmark_fixture_semantic_record::<T>(actor_id)
        .unwrap()
        .generation,
    };
    polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
      Pallet::<T>::remove_trigger_deadline_member(actor)
        .expect("ordinary independent Trigger Deadline is removed before staging");
      polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(())
    });
    contract.on_unfunded = OnUnfunded::AwaitFunding;
    // Different from current authority, with no claim of a historical runtime upgrade.
    let admission: ActorAdmissionCertificateOf<T> = ActorAdmissionCertificate::new(
      contract.semantic_contract_id(),
      contract
        .body_commitment()
        .expect("complete configured-length body"),
      contract.trigger.wake_qualification(&contract.window),
      base
        .runtime_actor_semantics_version
        .checked_add(1)
        .ok_or(BenchmarkError::Stop(
          "stale semantic authority must be representable",
        ))?,
      base.production_weight_identity,
      base.body_geometry_version,
      base.configured_bounds_commitment,
      base.maximum_lifecycle_weight,
    );
    let authority = ActorRunAuthority {
      semantic_contract_id: admission.semantic_contract_id,
      body_commitment: admission.body_commitment,
      admission_identity: admission.admission_identity,
      pipeline_service_identity: pipeline_service_identity(admission.admission_identity),
    };
    let ActorSemanticState::Active(mut semantic) = ActorSemanticStates::<T>::get(actor_id).unwrap()
    else {
      panic!("component retains an active source")
    };
    semantic.admission = admission.clone();
    semantic.hot.trigger_wakeup_pointer = None;
    ActorSemanticStates::<T>::insert(actor_id, ActorSemanticState::Active(semantic));
    let mut head = ActorContractHeads::<T>::get(actor_id).unwrap();
    head.header.on_unfunded = OnUnfunded::AwaitFunding;
    head.header.semantic_contract_id = admission.semantic_contract_id;
    head.header.body_commitment = admission.body_commitment;
    head.header.admission_identity = admission.admission_identity;
    ActorContractHeads::<T>::insert(actor_id, &head);
    let tail_count = contract
      .steps
      .len()
      .saturating_sub(1)
      .div_ceil(MAX_STEPS_PER_TAIL_CHUNK as usize);
    for chunk_index in 0..tail_count {
      ActorContractTailChunks::<T>::mutate(actor_id, chunk_index as u32, |chunk| {
        let chunk = chunk.as_mut().expect("every unvisited wide tail survives");
        chunk.authority.semantic_contract_id = admission.semantic_contract_id;
        chunk.authority.body_commitment = admission.body_commitment;
        chunk.authority.admission_identity = admission.admission_identity;
      });
    }
    let mut run = ActorRunStateStore::<T>::get(actor_id).unwrap();
    run.contract_authority = authority;
    let unpaid = if c == 0 {
      UnpaidActorService::RunningAction {
        cycle_nonce: run.cycle_nonce,
        cursor: run.cursor,
      }
    } else {
      UnpaidActorService::SuspendedAction {
        cycle_nonce: run.cycle_nonce,
        cursor: run.cursor,
        unsuccessful_attempts_at_cursor: run.unsuccessful_attempts_at_cursor,
      }
    };
    ActorRunStateStore::<T>::insert(actor_id, &run);
    let record = FinancialWaitRecord::new(
      FinancialWaitScope {
        actor,
        actor_type: ActorType::User,
        contract_authority: authority,
        behavior_episode: None,
      },
      unpaid,
      T::Balance::one(),
      T::Time::now(),
      T::CadenceTickMillis::get(),
      T::MaxTemporalDelayTicks::get(),
    )
    .map_err(|_| BenchmarkError::Stop("stale source requires an original grace clock"))?;
    let episode = FinancialWaitEpisode::new(record);
    ActorFinancialWaits::<T>::insert(actor_id, episode);
    let mut process = ActorProcesses::<T>::get(actor_id).unwrap();
    process.status = ProcessStatus::AwaitingFunding;
    assert_eq!(
      process.residence,
      Some(ProcessResidence::Service(ServiceResidenceKind::Live))
    );
    ActorProcesses::<T>::insert(actor_id, &process);
    let semantic = ActorSemanticStates::<T>::get(actor_id).unwrap();
    let tails = (0..tail_count)
      .map(|chunk| ActorContractTailChunks::<T>::get(actor_id, chunk as u32).unwrap())
      .collect::<Vec<_>>();
    let service_count = ServiceHeader::<T>::get().count;
    let events = frame_system::Pallet::<T>::event_count();
    let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    #[block]
    {
      polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
        let result = Pallet::<T>::benchmark_repark_financial_service(actor, &episode);
        assert_eq!(
          result,
          Err(FinancialWaitDueError::Service(
            ServiceRingMutationError::ProcessResidenceMismatch
          ))
        );
        let _ = core::hint::black_box(result);
        polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(())
      });
    }
    assert_eq!(ActorFinancialWaits::<T>::get(actor_id), Some(episode));
    assert_eq!(ActorSemanticStates::<T>::get(actor_id), Some(semantic));
    assert_eq!(ActorContractHeads::<T>::get(actor_id), Some(head));
    assert_eq!(ActorRunStateStore::<T>::get(actor_id), Some(run));
    for (index, tail) in tails.into_iter().enumerate() {
      assert_eq!(
        ActorContractTailChunks::<T>::get(actor_id, index as u32),
        Some(tail)
      );
    }
    for (asset, balance) in fixture.balances {
      assert_eq!(
        T::AssetOps::balance(&fixture.identity.sovereign_account, asset),
        balance
      );
    }
    assert_eq!(
      T::AssetOps::balance(&T::FeeSink::get(), T::FeeNativeAssetId::get()),
      fixture.sink_balance
    );
    assert_eq!(frame_system::Pallet::<T>::event_count(), events);
    assert!(!TriggerDeadlineHandles::<T>::contains_key(actor_id));
    assert_eq!(ActorProcesses::<T>::get(actor_id), Some(process));
    assert!(ServiceNodes::<T>::contains_key(actor_id));
    assert!(!DeadlineHandles::<T>::contains_key(actor_id));
    assert_eq!(ServiceHeader::<T>::get().count, service_count);
    assert_eq!(
      polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
      root
    );
    Ok(())
  }

  /// Maximum-width financial lookup, origin/clock binding and expired-insolvency classification.
  /// Canonical source authentication, current time/balance, admission and cleanup are separate.
  #[benchmark(extra, pov_mode = Measured)]
  fn financial_wait_record_binding() -> Result<(), BenchmarkError> {
    // Match FRAME's pre-measurement initialization before capturing the root.
    if frame_system::Pallet::<T>::block_number().is_zero() {
      frame_system::Pallet::<T>::set_block_number(1u32.into());
    }
    let actor_id = 2_973;
    let scope = FinancialWaitScope {
      actor: ActorRef {
        actor_id,
        generation: 1,
      },
      actor_type: ActorType::User,
      contract_authority: ActorRunAuthority {
        semantic_contract_id: [1; 32],
        body_commitment: [2; 32],
        admission_identity: [3; 32],
        pipeline_service_identity: [4; 32],
      },
      behavior_episode: Some([5; 32]),
    };
    let unpaid = UnpaidActorService::SuspendedAction {
      cycle_nonce: 1,
      cursor: 0,
      unsuccessful_attempts_at_cursor: 1,
    };
    let liability = T::Balance::one();
    let tick_millis = T::CadenceTickMillis::get();
    let max_delay = T::MaxTemporalDelayTicks::get();
    let record = FinancialWaitRecord::new(scope, unpaid, liability, 0, tick_millis, max_delay)
      .map_err(|_| BenchmarkError::Stop("financial binding requires a valid grace clock"))?;
    let due_millis = record
      .expiry_tick()
      .checked_mul(tick_millis)
      .ok_or(BenchmarkError::Stop(
        "financial expiry must fit consensus time",
      ))?;
    let episode = FinancialWaitEpisode::new(record);
    if episode.encoded_size() != FinancialWaitEpisode::<T::Balance>::max_encoded_len() {
      return Err(BenchmarkError::Stop(
        "financial binding requires a full-width Balance codec",
      ));
    }
    ensure!(
      !ActorSemanticStates::<T>::contains_key(actor_id)
        && !ActorContractHeads::<T>::contains_key(actor_id)
        && !ActorProcesses::<T>::contains_key(actor_id),
      BenchmarkError::Stop("financial component key must have no Actor source")
    );
    ActorFinancialWaits::<T>::insert(actor_id, episode);
    let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    #[block]
    {
      let loaded = ActorFinancialWaits::<T>::get(actor_id).expect("financial component exists");
      let bound = loaded
        .bind(scope, unpaid, liability, tick_millis, max_delay)
        .expect("original origin and source clock bind");
      let decision = bound
        .classify(Zero::zero(), due_millis)
        .expect("current time is not before entry");
      assert_eq!(decision, FinancialWaitDecision::GraceExpired);
      core::hint::black_box((loaded, decision));
    }
    assert_eq!(ActorFinancialWaits::<T>::get(actor_id), Some(episode));
    assert_eq!(
      polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
      root
    );
    Ok(())
  }

  /// Loaded geometry removal only: 0=ordinary, 1=policy, 2=financial, 3=both.
  /// The categorical selector requires raw samples, not a regression coefficient.
  /// These component fixtures install no Actor/process and do not qualify complete Close.
  #[benchmark(pov_mode = Measured)]
  fn contract_optional_cleanup(c: Linear<0, 3>) -> Result<(), BenchmarkError> {
    let actor_id = 2_972;
    let policy_present = c == 1 || c == 3;
    let financial_present = c >= 2;
    let (_, asset, trigger, funding) = large_header_fields::<T>();
    let steps = maximum_temporal_control_steps::<T>(asset)?;
    let first = steps.first().expect("maximum Contract has a Step");
    assert!(
      steps.iter().all(|step| step == first),
      "cleanup retains every wide Step"
    );
    let precondition = first
      .precondition
      .as_ref()
      .expect("wide Step has predicates");
    assert_eq!(
      precondition.predicate_count(),
      benchmark_predicate_capacity::<T>()
    );
    assert_eq!(
      precondition.clauses.len(),
      T::MaxPreconditionClauses::get() as usize
    );
    for clause in &precondition.clauses {
      assert_eq!(
        clause.len(),
        1,
        "maximum canonical width uses singleton clauses"
      );
      assert_eq!(
        clause[0].encoded_size(),
        Predicate::<T::AssetId, T::Balance, u32, T::ObservationFeedId>::max_encoded_len()
      );
    }
    let mut contract = user_contract::<T>(
      Schedule {
        trigger,
        cooldown_blocks: T::MaxExecutionDelayBlocks::get().saturated_into(),
      },
      steps,
    )
    .expect("component Contract exists");
    contract.funding = funding;
    contract.window = Some(ScheduleWindow {
      start: 1u32.into(),
      end: T::MinWindowLength::get().saturating_add(1_000u32.into()),
    });
    contract.auto_close_at_cycle_nonce = Some(2);
    // This benchmark-only geometry certificate is not public optional-policy admission.
    let (base, mut head, mut chunks) = admitted_contract_geometry::<T>(actor_id, &contract);
    assert_eq!(
      head.header.encoded_size(),
      ActorContractHeaderOf::<T>::max_encoded_len()
        - ParkedBalanceActivationOf::<T>::max_encoded_len()
    );
    if policy_present {
      contract.close_when = Some(maximum_behavior_expression::<T>()?);
    }
    if financial_present {
      contract.on_unfunded = OnUnfunded::AwaitFunding;
    }
    let admission: ActorAdmissionCertificateOf<T> = ActorAdmissionCertificate::new(
      contract.semantic_contract_id(),
      contract.body_commitment().expect("bounded component body"),
      contract.trigger.wake_qualification(&contract.window),
      base.runtime_actor_semantics_version,
      base.production_weight_identity,
      base.body_geometry_version,
      base.configured_bounds_commitment,
      base.maximum_lifecycle_weight,
    );
    let actor = ActorRef {
      actor_id,
      generation: 1,
    };
    let mut behavior_episode = None;
    if let Some(expression) = &contract.close_when {
      let binding = BehaviorPolicyBinding {
        semantic_contract_id: admission.semantic_contract_id,
        admission_identity: admission.admission_identity,
      };
      let plan = expression
        .validate()
        .expect("canonical maximum expression")
        .compile(binding)
        .expect("bounded maximum plan");
      let policy = ActorBehaviorPolicy {
        expression: expression.clone(),
        plan,
        episode_started_at_generation: actor.generation,
      };
      let episode = (
        b"DEOS_ACTOR_BEHAVIOR_EPISODE",
        actor_id,
        actor.generation,
        admission.semantic_contract_id,
      )
        .using_encoded(frame::hashing::blake2_256);
      let monitor = ActorBehaviorMonitor {
        state: policy
          .plan
          .bind(expression, binding)
          .expect("component policy binds")
          .begin_episode(episode)
          .expect("component monitor exists"),
        clean_cycle: Some(BehaviorCleanCycle {
          cycle_nonce: 1,
          candidate: CleanCycleCandidate::default(),
        }),
      };
      assert_eq!(policy.plan.metrics().len(), 10);
      assert_eq!(
        policy.encoded_size(),
        ActorBehaviorPolicyOf::<T>::max_encoded_len()
      );
      assert_eq!(
        monitor.encoded_size(),
        ActorBehaviorMonitor::max_encoded_len()
      );
      ActorBehaviorPolicies::<T>::insert(actor_id, policy);
      ActorBehaviorMonitors::<T>::insert(actor_id, monitor);
      behavior_episode = Some(episode);
    }
    if financial_present {
      let record = FinancialWaitRecord::new(
        FinancialWaitScope {
          actor,
          actor_type: ActorType::User,
          contract_authority: ActorRunAuthority {
            semantic_contract_id: admission.semantic_contract_id,
            body_commitment: admission.body_commitment,
            admission_identity: admission.admission_identity,
            pipeline_service_identity: pipeline_service_identity(admission.admission_identity),
          },
          behavior_episode,
        },
        UnpaidActorService::SuspendedAction {
          cycle_nonce: 1,
          cursor: 0,
          unsuccessful_attempts_at_cursor: 1,
        },
        T::Balance::max_value(),
        0,
        T::CadenceTickMillis::get(),
        T::MaxTemporalDelayTicks::get(),
      )
      .expect("component financial record has a valid bounded clock");
      let episode = FinancialWaitEpisode::new(record);
      if policy_present {
        assert_eq!(
          episode.encoded_size(),
          FinancialWaitEpisode::<T::Balance>::max_encoded_len()
        );
      }
      ActorFinancialWaits::<T>::insert(actor_id, episode);
    }
    head.header.has_close_when = policy_present;
    head.header.on_unfunded = contract.on_unfunded;
    head.header.semantic_contract_id = admission.semantic_contract_id;
    head.header.admission_identity = admission.admission_identity;
    ActorContractHeads::<T>::insert(actor_id, head);
    let chunk_count = chunks.len();
    for (chunk_index, chunk) in &mut chunks {
      chunk.authority.semantic_contract_id = admission.semantic_contract_id;
      chunk.authority.admission_identity = admission.admission_identity;
      ActorContractTailChunks::<T>::insert(actor_id, *chunk_index, chunk);
    }
    assert!(!ActorSemanticStates::<T>::contains_key(actor_id));
    assert!(!ActorProcesses::<T>::contains_key(actor_id));
    assert_eq!(
      ActorBehaviorPolicies::<T>::contains_key(actor_id),
      policy_present
    );
    assert_eq!(
      ActorBehaviorMonitors::<T>::contains_key(actor_id),
      policy_present
    );
    assert_eq!(
      ActorFinancialWaits::<T>::contains_key(actor_id),
      financial_present
    );
    #[block]
    {
      assert!(Pallet::<T>::benchmark_remove_loaded_contract_geometry(actor_id, contract).is_some());
    }
    assert!(!ActorContractHeads::<T>::contains_key(actor_id));
    assert!(!ActorBehaviorPolicies::<T>::contains_key(actor_id));
    assert!(!ActorBehaviorMonitors::<T>::contains_key(actor_id));
    assert!(!ActorFinancialWaits::<T>::contains_key(actor_id));
    for chunk_index in 0..chunk_count {
      assert!(!ActorContractTailChunks::<T>::contains_key(
        actor_id,
        chunk_index as u32
      ));
    }
    Ok(())
  }

