  #[cfg(test)]
  fn assert_wide_idle_interior_caller(
    prepared: WideIdleInteriorCloseFixture<Test>,
    rollback: bool,
  ) {
    let fixture = &prepared.close;
    let actor_id = fixture.actor_id;
    let source = prepared.source;
    let plan = DependencyPlans::<Test>::get(actor_id);
    let contract = Pallet::<Test>::load_actor_contract(actor_id)
      .unwrap()
      .encode();
    let header = DependencyRegistrationHeaders::<Test>::get(source);
    let page = DependencyRegistrationPages::<Test>::get(source, 1).unwrap();
    let position = DependencyRegistrationPositions::<Test>::get(source, actor_id).unwrap();
    let mut successor = (0..header.free_count)
      .map(|index| DependencyRegistrationFreePositions::<Test>::get(source, index).unwrap())
      .collect::<Vec<_>>();
    successor.push(position);
    let mut non_tail = 0;
    for slot in 0..32u8 {
      let hole = DependencyRegistrationPosition { page: 1, slot };
      let index = successor.iter().position(|entry| *entry == hole).unwrap();
      non_tail += usize::from(index != successor.len() - 1);
      successor.swap_remove(index);
    }
    assert_eq!(non_tail, if position.slot == 0 { 31 } else { 32 });
    let before = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
      Pallet::<Test>::close_actor(RawOrigin::Signed(fixture.identity.owner).into(), actor_id)
        .unwrap();
      assert_close_destruction::<Test>(fixture);
      assert_wide_idle_interior_close::<Test>(source, &prepared.peers);
      assert_eq!(
        (0..32u64)
          .map(|index| DependencyRegistrationFreePositions::<Test>::get(source, index).unwrap())
          .collect::<Vec<_>>(),
        successor,
      );
      if rollback {
        polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(())
      } else {
        polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(())
      }
    });
    if rollback {
      assert_eq!(
        polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
        before
      );
      assert_eq!(DependencyRegistrationHeaders::<Test>::get(source), header);
      assert_eq!(
        DependencyRegistrationPages::<Test>::get(source, 1),
        Some(page)
      );
      assert_eq!(DependencyPlans::<Test>::get(actor_id), plan);
      assert_eq!(
        Pallet::<Test>::load_actor_contract(actor_id)
          .unwrap()
          .encode(),
        contract
      );
    }
    Pallet::<Test>::do_try_state().unwrap();
  }

