  #[cfg(test)]
  #[test]
  fn running_close_body_and_run_widths_obey_committed_outcome() {
    let policy_gap =
      StepErrorPolicy::max_encoded_len() - StepErrorPolicy::ContinueNextStep.encoded_size();
    let outcome_maximum = StepOutcome::max_encoded_len();
    let nonfailure_maximum = StepOutcome::Skipped(StepSkippedReason::FundingUnavailable(
      FundingUnavailableReason::TaskInput,
    ))
    .encoded_size();
    assert_eq!(policy_gap, 4);
    assert!(outcome_maximum - nonfailure_maximum > policy_gap);
    for actor_type in [ActorType::User, ActorType::System] {
      let (failed_joint, running_body, running_maximum) = new_test_ext().execute_with(|| {
        let fixture =
          prepare_temporal_close_with_prefix::<Test>(actor_type, false, CycleState::Running, true)
            .unwrap();
        let contract = Pallet::<Test>::actor_contract(fixture.actor_id).unwrap();
        let run = ActorRunStateStore::<Test>::get(fixture.actor_id).unwrap();
        let body: usize = contract.steps.iter().map(Encode::encoded_size).sum();
        let running_maximum =
            ActorRunStateOf::<Test>::max_encoded_len()
              - (Option::<SuspensionReason>::max_encoded_len()
                - None::<SuspensionReason>.encoded_size())
              - (Option::<
                CycleBalanceSnapshot<<Test as Config>::AssetId, <Test as Config>::Balance>,
              >::max_encoded_len()
                - run.balance_snapshot.encoded_size());
        assert_eq!(run.encoded_size(), running_maximum);
        assert_eq!(
          contract.steps[(run.cursor - 1) as usize].on_error,
          StepErrorPolicy::ContinueNextStep
        );
        assert!(matches!(
          run.last_step_outcome,
          Some(StepOutcome::Failed(_))
        ));
        let failed_joint = body + run.encoded_size();
        assert_eq!(failed_joint, body + running_maximum);
        Pallet::<Test>::close_actor(
          RawOrigin::Signed(fixture.identity.owner).into(),
          fixture.actor_id,
        )
        .unwrap();
        assert_close_destruction::<Test>(&fixture);
        (failed_joint, body, running_maximum)
      });
      new_test_ext().execute_with(|| {
        let mut fixture = prepare_temporal_close_with_prefix::<Test>(
          actor_type,
          false,
          CycleState::Suspended,
          true,
        )
        .unwrap();
        let contract = Pallet::<Test>::actor_contract(fixture.actor_id).unwrap();
        let before = ActorRunStateStore::<Test>::get(fixture.actor_id).unwrap();
        let body: usize = contract.steps.iter().map(Encode::encoded_size).sum();
        assert_eq!(body, running_body + policy_gap);
        assert_eq!(
          before.encoded_size(),
          ActorRunStateOf::<Test>::max_encoded_len()
            - (Option::<CycleBalanceSnapshot<<Test as Config>::AssetId, <Test as Config>::Balance>>::max_encoded_len()
              - before.balance_snapshot.encoded_size())
        );
        frame_system::Pallet::<Test>::set_block_number(before.eligible_at);
        Pallet::<Test>::execute_cycle(Weight::zero());
        assert_eq!(
          Pallet::<Test>::active_actor_view(fixture.actor_id)
            .unwrap()
            .cycle_state,
          CycleState::Suspended
        );
        assert_eq!(
          ActorRunStateStore::<Test>::get(fixture.actor_id)
            .unwrap()
            .encode(),
          before.encode()
        );
        let ActorTask::Transfer { asset, to, .. } = &contract.steps[before.cursor as usize].task
        else {
          panic!("wide retry uses Transfer")
        };
        <Test as Config>::AssetOps::mint(
          to,
          *asset,
          <Test as Config>::AssetOps::minimum_balance(*asset),
        )
        .unwrap();
        frame_system::Pallet::<Test>::set_block_number(before.eligible_at + 1);
        Pallet::<Test>::execute_cycle(Weight::MAX);
        let after = ActorRunStateStore::<Test>::get(fixture.actor_id).unwrap();
        assert_eq!(
          Pallet::<Test>::active_actor_view(fixture.actor_id)
            .unwrap()
            .cycle_state,
          CycleState::Running
        );
        assert_eq!(after.contract_authority, before.contract_authority);
        assert_eq!(after.cursor, before.cursor + 1);
        assert_eq!(after.unsuccessful_attempts_at_cursor, 0);
        assert!(after.suspension.is_none());
        assert_eq!(after.last_step_outcome, Some(StepOutcome::Executed));
        assert_eq!(after.cumulative_outcomes.committed_effectful_tasks, 2);
        assert_eq!(after.cumulative_outcomes.failed_steps, 1);
        assert_eq!(
          after.encoded_size(),
          running_maximum - (outcome_maximum - StepOutcome::Executed.encoded_size())
        );
        assert_eq!(
          Pallet::<Test>::actor_contract(fixture.actor_id)
            .unwrap()
            .encode(),
          contract.encode()
        );
        assert!(body + after.encoded_size() < failed_joint);
        assert!(body + running_maximum - (outcome_maximum - nonfailure_maximum) < failed_joint);
        for (asset, balance) in &mut fixture.balances {
          *balance =
            <Test as Config>::AssetOps::balance(&fixture.identity.sovereign_account, *asset);
        }
        fixture.sink_balance = <Test as Config>::AssetOps::balance(
          &<Test as Config>::FeeSink::get(),
          <Test as Config>::FeeNativeAssetId::get(),
        );
        Pallet::<Test>::do_try_state().unwrap();
        Pallet::<Test>::close_actor(
          RawOrigin::Signed(fixture.identity.owner).into(),
          fixture.actor_id,
        )
        .unwrap();
        assert_close_destruction::<Test>(&fixture);
      });
    }
  }

