  #[cfg(test)]
  fn assert_close_test_events(
    fixture: &CloseDestructionFixture<Test>,
    prefix: &[polkadot_sdk::frame_system::EventRecord<
      crate::mock::RuntimeEvent,
      <Test as polkadot_sdk::frame_system::Config>::Hash,
    >],
    run: Option<&ActorRunStateOf<Test>>,
    released: Option<<Test as Config>::Balance>,
  ) {
    use crate::mock::{RuntimeEvent, System};
    assert!(!prefix.is_empty(), "Close retains prior block events");
    let actor_id = fixture.actor_id;
    let mut expected = Vec::new();
    if let Some(run) = run {
      expected.push(RuntimeEvent::Actors(Event::CycleCancelled {
        actor_id,
        cycle_nonce: run.cycle_nonce,
        reason: CancellationReason::Closing(CloseReason::OwnerInitiated),
      }));
      expected.push(RuntimeEvent::Actors(Event::CycleSummary {
        actor_id,
        cycle_nonce: run.cycle_nonce,
        result: CycleResult::Cancelled,
        outcomes: run.cumulative_outcomes,
      }));
    }
    if let Some(amount) = released {
      assert!(amount > 0);
      expected.push(RuntimeEvent::Balances(
        polkadot_sdk::pallet_balances::Event::Released {
          reason: HoldReason::ActorState.into(),
          who: fixture.identity.owner,
          amount,
        },
      ));
    }
    expected.push(RuntimeEvent::Actors(Event::ActorClosed {
      actor_id,
      reason: CloseReason::OwnerInitiated,
    }));
    let actual = System::events();
    assert_eq!(&actual[..prefix.len()], prefix);
    assert_eq!(actual.len(), prefix.len() + expected.len());
    assert_eq!(System::event_count() as usize, actual.len());
    for (record, event) in actual[prefix.len()..].iter().zip(expected) {
      assert_eq!(record.event, event);
      assert_eq!(
        record.phase,
        polkadot_sdk::frame_system::Phase::ApplyExtrinsic(0)
      );
      assert!(record.topics.is_empty());
    }
  }

  #[cfg(test)]
  #[test]
  fn close_destruction_late_hold_failure_restores_public_and_consumed_state() {
    use crate::mock::take_admission_authority_calls;
    use polkadot_sdk::frame_support::storage::{TransactionOutcome, with_transaction};
    use polkadot_sdk::frame_support::traits::{fungible::MutateHold, tokens::Precision};
    type Currency = <Test as Config>::StateHoldCurrency;
    for (consumed, last_slot, shape, dormant) in [
      (false, false, 0, false),
      (false, true, 0, false),
      (true, false, 0, false),
      (true, true, 0, false),
      (false, true, 2, false),
      (false, true, 3, false),
      (false, true, 4, false),
      (false, true, 5, false),
      (false, false, 0, true),
      (false, true, 0, true),
    ] {
      new_test_ext().execute_with(|| {
        let mut fixture = if dormant {
          prepare_dormant_close::<Test>(ActorType::User).unwrap()
        } else {
          prepare_close_shape::<Test>(ActorType::User, shape).unwrap()
        };
        let host_calls = u32::from(!consumed && !dormant);
        if last_slot {
          leave_last_close_owner_slot::<Test>(&mut fixture).unwrap();
        }
        let terminal =
          consumed.then(|| detach_close_destruction::<Test>(fixture.actor_id).unwrap());
        let reason = HoldReason::ActorState.into();
        let held = Currency::balance_on_hold(&reason, &fixture.identity.owner);
        assert!(held > fixture.owner_hold_after);
        // The last fallible owner runs after semantic/identity deletion, counters and
        // slot release, plus Run/body deletion when closing an Active Actor.
        Currency::release(&reason, &fixture.identity.owner, held, Precision::Exact).unwrap();
        crate::mock::System::note_finished_initialize();
        let event_prefix = crate::mock::System::events();
        let close = || match &terminal {
          Some((state, admission)) => Pallet::<Test>::finalize_actor_from_consumed_state(
            fixture.actor_id,
            state.clone(),
            admission,
            CloseReason::OwnerInitiated,
          ),
          None => Pallet::<Test>::close_actor(
            RawOrigin::Signed(fixture.identity.owner).into(),
            fixture.actor_id,
          ),
        };
        take_admission_authority_calls();
        with_transaction(|| -> TransactionOutcome<DispatchResult> {
          // A failed inner Close preserves work owned by the enclosing caller.
          polkadot_sdk::sp_io::storage::set(b":actors_close_parent_test:", b"retained");
          let before =
            polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
          assert_eq!(close(), Err(Error::<Test>::StateHoldInvariant.into()));
          assert_eq!(
            polkadot_sdk::frame_support::storage::unhashed::get::<u32>(
              polkadot_sdk::frame_support::storage::transactional::TRANSACTION_LEVEL_KEY,
            ),
            Some(1)
          );
          assert_eq!(
            polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
            before
          );
          assert_eq!(crate::mock::System::events(), event_prefix);
          assert_eq!(
            crate::mock::System::event_count() as usize,
            event_prefix.len()
          );
          TransactionOutcome::Commit(Ok(()))
        })
        .unwrap();
        assert_eq!(take_admission_authority_calls(), host_calls);
        assert!(!polkadot_sdk::frame_support::storage::transactional::is_transactional());
        assert_eq!(
          polkadot_sdk::sp_io::storage::get(b":actors_close_parent_test:").as_deref(),
          Some(&b"retained"[..])
        );
        Currency::hold(&reason, &fixture.identity.owner, held).unwrap();
        let run = ActorRunStateStore::<Test>::get(fixture.actor_id);
        let event_prefix = crate::mock::System::events();
        let before = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
        with_transaction(|| -> TransactionOutcome<DispatchResult> {
          close().unwrap();
          assert_close_test_events(
            &fixture,
            &event_prefix,
            run.as_ref(),
            Some(held - fixture.owner_hold_after),
          );
          assert_close_destruction::<Test>(&fixture);
          TransactionOutcome::Rollback(Ok(()))
        })
        .unwrap();
        assert_eq!(take_admission_authority_calls(), host_calls);
        assert!(!polkadot_sdk::frame_support::storage::transactional::is_transactional());
        assert_eq!(
          polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
          before
        );
        assert_eq!(crate::mock::System::events(), event_prefix);
        close().unwrap();
        assert_eq!(take_admission_authority_calls(), host_calls);
        assert_close_test_events(
          &fixture,
          &event_prefix,
          run.as_ref(),
          Some(held - fixture.owner_hold_after),
        );
        assert_close_destruction::<Test>(&fixture);
      });
    }
  }

