  #[cfg(test)]
  #[test]
  fn pure_parked_release_late_refusal_rolls_back_deadline_and_registration_prefix() {
    use polkadot_sdk::frame_support::storage::{TransactionOutcome, with_transaction_unchecked};
    new_test_ext().execute_with(|| {
      let fixture = prepare_parked_dependency_release::<Test>().unwrap();
      let source = fixture.registrations[1].0;
      let header = DependencyRegistrationHeaders::<Test>::get(source);
      DependencyRegistrationHeaders::<Test>::mutate(source, |header| {
        header.free_count = u64::from(<<Test as Config>::MaxActiveActors as Get<u32>>::get()) * 32;
      });
      let before = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
      let result = with_transaction_unchecked(|| {
        match Pallet::<Test>::release_parked_dependency_authority(
          fixture.parked.actor,
          fixture.evidence,
        ) {
          Ok(()) => TransactionOutcome::Commit(Ok(())),
          Err(error) => TransactionOutcome::Rollback(Err(error)),
        }
      });
      assert_eq!(result, Err(DependencyRegistrationError::CorruptTopology));
      assert_eq!(
        polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
        before
      );
      DependencyRegistrationHeaders::<Test>::insert(source, header);
      with_transaction_unchecked(|| {
        let result = Pallet::<Test>::release_parked_dependency_authority(
          fixture.parked.actor,
          fixture.evidence,
        );
        assert_eq!(result, Ok(()));
        TransactionOutcome::Commit(())
      });
      assert_parked_dependency_release::<Test>(fixture).unwrap();
    });
  }

  #[cfg(test)]
  fn assert_wide_idle_deep_temporal_caller(
    shape: u32,
    rollback: bool,
    fixture: CloseDestructionFixture<Test>,
    checks: WideIdleCloseChecks<Test>,
  ) {
    let WideIdleCloseChecks::DeepTemporalInterior(_, deep) = &checks else {
      unreachable!("deep temporal preparation returns deep checks")
    };
    let actor_id = fixture.actor_id;
    let trigger = TriggerDeadlineHandles::<Test>::get(actor_id).unwrap();
    let review = DeadlineHandles::<Test>::get(actor_id).unwrap();
    let positions = [
      DeadlineIndexPositions::<Test>::get(trigger.key).unwrap(),
      DeadlineIndexPositions::<Test>::get(review.key).unwrap(),
    ];
    let plan = DependencyPlans::<Test>::get(actor_id);
    let source = plan[0].source;
    let header = DependencyRegistrationHeaders::<Test>::get(source);
    let position = DependencyRegistrationPositions::<Test>::get(source, actor_id).unwrap();
    let mut successor = (0..header.free_count)
      .map(|index| DependencyRegistrationFreePositions::<Test>::get(source, index).unwrap())
      .collect::<Vec<_>>();
    successor.push(position);
    let mut non_tail = 0;
    for slot in 0..32u8 {
      let hole = DependencyRegistrationPosition { page: 1, slot };
      let index = successor.iter().position(|entry| *entry == hole).unwrap();
      non_tail += usize::from(index != successor.len() - 1);
      successor.swap_remove(index);
    }
    assert_eq!(non_tail, if position.slot == 0 { 31 } else { 32 });
    let contract = Pallet::<Test>::load_actor_contract(actor_id).unwrap();
    eprintln!(
      "deep-history shape={shape} rollback={rollback} room={} guards={} Tick={}@{} Block={}@{} now={} tick={:?} trigger={:?}",
      deep.room,
      deep.guards.len(),
      deep.lengths[0],
      positions[0],
      deep.lengths[1],
      positions[1],
      frame_system::Pallet::<Test>::block_number(),
      Pallet::<Test>::current_scheduler_tick(),
      trigger.key,
    );
    let before = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
      Pallet::<Test>::close_actor(RawOrigin::Signed(fixture.identity.owner).into(), actor_id)
        .unwrap();
      assert_close_destruction::<Test>(&fixture);
      assert_wide_idle_close_checks::<Test>(actor_id, &checks);
      assert_eq!(
        (0..32u64)
          .map(|index| DependencyRegistrationFreePositions::<Test>::get(source, index).unwrap())
          .collect::<Vec<_>>(),
        successor,
      );
      if rollback {
        polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(())
      } else {
        polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(())
      }
    });
    if rollback {
      assert_eq!(
        polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
        before
      );
      assert_eq!(DependencyRegistrationHeaders::<Test>::get(source), header);
      assert_eq!(DependencyPlans::<Test>::get(actor_id), plan);
      assert_eq!(
        Pallet::<Test>::load_actor_contract(actor_id).unwrap(),
        contract
      );
      assert_eq!(TriggerDeadlineHandles::<Test>::get(actor_id), Some(trigger));
      assert_eq!(DeadlineHandles::<Test>::get(actor_id), Some(review));
      assert_eq!(
        DeadlineIndexPositions::<Test>::get(trigger.key),
        Some(positions[0])
      );
      assert_eq!(
        DeadlineIndexPositions::<Test>::get(review.key),
        Some(positions[1])
      );
    }
    Pallet::<Test>::do_try_state().unwrap();
  }

