  #[cfg(test)]
  fn assert_slot31_temporal_birth_source(separate_births: bool, handoff: bool) {
    assert!(!handoff || separate_births);
    for visit_target in [false, true] {
      for rollback in [false, true] {
        unanchored_root_genesis_ext(120).execute_with(|| {
          let bootstrap = Pallet::<Test>::load_actor_ref(0).unwrap();
          let genesis_before = Pallet::<Test>::active_actor_state(0).unwrap();
          <Test as Config>::AssetOps::mint(
            &genesis_before.identity.sovereign_account,
            <Test as Config>::FeeNativeAssetId::get(),
            77,
          ).unwrap();
          let prepared = prepare_wide_idle_interior_close_with_birth_boundary::<Test>(0, Some(80), 31, separate_births).unwrap();
          let actor_id = prepared.close.actor_id;
          let actor = Pallet::<Test>::load_actor_ref(actor_id).unwrap();
          let source = prepared.source;
          let review = DeadlineHandles::<Test>::get(actor_id).unwrap();
          let tick = TriggerDeadlineHandles::<Test>::get(actor_id).unwrap();
          assert_eq!(DependencyRegistrationPositions::<Test>::get(source, actor_id).unwrap(),
            DependencyRegistrationPosition { page: 1, slot: 31 });
          assert_eq!(TriggerDeadlineHandles::<Test>::get(0).unwrap().key, WakeupKey::Tick(0));
          assert_eq!(genesis_before.hot.trigger_runtime_state.temporal_anchor_tick(), None);
          let anchored_at = prepare_wide_idle_root_review_prefix::<Test>(&prepared, Some(bootstrap)).unwrap().unwrap();
          let genesis_after = Pallet::<Test>::active_actor_state(0).unwrap();
          assert_eq!(genesis_after.identity, genesis_before.identity);
          assert_eq!(genesis_after.contract, genesis_before.contract);
          assert_eq!(genesis_after.hot.trigger_runtime_state.temporal_anchor_tick(), Some(anchored_at));
          assert!(!genesis_after.hot.pending_signal);
          assert!(ActorRunStateStore::<Test>::get(0).is_none());
          assert_eq!(<Test as Config>::AssetOps::balance(&genesis_after.identity.sovereign_account,
            <Test as Config>::FeeNativeAssetId::get()), 77);
          assert_eq!(DeadlineIndexPositions::<Test>::get(review.key), Some(0));
          assert_eq!(DeadlineIndexPositions::<Test>::get(tick.key), Some(0));
          let WakeupKey::Tick(due) = tick.key else { unreachable!() };
          assert!(Pallet::<Test>::current_scheduler_tick().unwrap() < due);
          let bucket = DeadlineHeaders::<Test>::get(review.key).unwrap();
          if separate_births {
            assert_eq!(bucket.count, 1);
          } else {
            assert!(bucket.count > 1, "same-block following births share the review key");
          }
          assert_eq!(DeadlinePages::<Test>::get(review.key, bucket.first_page).unwrap()
            .entries.iter().flatten().next().copied(), Some(actor));
          assert!(matches!(Pallet::<Test>::classify_next_due_block_deadline(
            frame_system::Pallet::<Test>::block_number()).unwrap(),
            DueBlockDeadlineBranch::Review(next) if next == actor));
          let bootstrap_authority = wide_idle_tick_peer_authority::<Test>(0);
          let bootstrap_custody = wide_idle_deep_clock_guard_snapshot::<Test>(0);

          let asset = DependencySourceBalances::<Test>::get(source).unwrap();
          assert!(DependencyRevisions::<Test>::get(source).scan_target.is_none());
          assert!(!PendingDependencyEvents::<Test>::contains_key(actor_id));
          let contract_before_scan = Pallet::<Test>::load_actor_contract(actor_id).unwrap().encode();
          let acknowledged_before = DependencyRegistrations::<Test>::get(source, actor_id).unwrap().acknowledged_revision;
          publish_close_scan_balance_transition::<Test>(asset).unwrap();
          let first_epoch = DependencyRevisions::<Test>::get(source).scan_target.unwrap();
          let mut meter = polkadot_sdk::sp_weights::WeightMeter::with_limit(Weight::MAX);
          let carried = if handoff {
            Some(prepare_wide_idle_scan_handoff::<Test>(source, actor_id, &mut meter).unwrap())
          } else { None };
          let epoch = DependencyRevisions::<Test>::get(source).scan_target.unwrap();
          let frontier = if visit_target { 64 } else { 63 };
          for _ in 0..frontier {
            assert!(Pallet::<Test>::process_next_dependency_scan_unit(&mut meter).unwrap().is_some());
          }
          publish_close_scan_balance_transition::<Test>(asset).unwrap();
          let state = DependencyRevisions::<Test>::get(source);
          assert_eq!(state.scan_target, Some(epoch));
          assert_eq!(state.scan_cursor, frontier);
          assert_eq!(state.revision, epoch + 1);
          assert_eq!(
            PendingDependencyEvents::<Test>::get(actor_id).map(|event| event.revision),
            if handoff { Some(first_epoch) } else { visit_target.then_some(epoch) }
          );
          if handoff {
            assert_eq!(PendingDependencyEvents::<Test>::get(actor_id), carried);
          }
          assert_eq!(DependencyRegistrations::<Test>::get(source, actor_id).unwrap().acknowledged_revision,
            if visit_target { epoch } else if handoff { first_epoch } else { acknowledged_before });
          assert_eq!(Pallet::<Test>::load_actor_contract(actor_id).unwrap().encode(), contract_before_scan);
          assert_eq!(DeadlineHandles::<Test>::get(actor_id), Some(review));
          assert_eq!(TriggerDeadlineHandles::<Test>::get(actor_id), Some(tick));
          assert!(Pallet::<Test>::current_scheduler_tick().unwrap() < due);
          let peers = prepared.peers.iter()
            .map(|(peer, _)| (*peer, parked_close_peer_snapshot::<Test>(*peer))).collect::<Vec<_>>();
          let peer_pending = peers.iter().map(|(peer, _)| (*peer,
            PendingDependencyEvents::<Test>::get(peer), PendingDependencyReviews::<Test>::get(peer)))
            .collect();
          // Acknowledged peer handles belong to the committed scan prefix, not the earlier snapshot.
          let checks = WideIdleActiveInteriorChecks {
            source, state, list: DependencyScanSourceListState::<Test>::get(),
            node: DependencyScanSourceNodes::<Test>::get(source).unwrap(), peers,
            pending: peer_pending,
          };
          let mut successor = (0..63u64).map(|index|
            DependencyRegistrationFreePositions::<Test>::get(source, index).unwrap()).collect::<Vec<_>>();
          successor.push(DependencyRegistrationPosition { page: 1, slot: 31 });
          let mut non_tail = 0;
          for slot in 0..32u8 {
            let hole = DependencyRegistrationPosition { page: 1, slot };
            let index = successor.iter().position(|entry| *entry == hole).unwrap();
            non_tail += usize::from(index != successor.len() - 1);
            successor.swap_remove(index);
          }
          assert_eq!(non_tail, 32);
          Pallet::<Test>::do_try_state().unwrap();
          let before = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
          polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
            Pallet::<Test>::close_actor(RawOrigin::Signed(prepared.close.identity.owner).into(), actor_id).unwrap();
            assert_close_destruction::<Test>(&prepared.close);
            assert_wide_idle_active_interior_close::<Test>(actor_id, &checks);
            assert_eq!((0..32u64).map(|index|
              DependencyRegistrationFreePositions::<Test>::get(source, index).unwrap()).collect::<Vec<_>>(), successor);
            if separate_births {
              assert!(!DeadlineHeaders::<Test>::contains_key(review.key));
              assert!(!DeadlineIndexPositions::<Test>::contains_key(review.key));
            } else {
              assert_eq!(DeadlineHeaders::<Test>::get(review.key).unwrap().count, bucket.count - 1);
              assert_eq!(DeadlineIndexPositions::<Test>::get(review.key), Some(0));
            }
            assert!(!TriggerDeadlineHandles::<Test>::contains_key(actor_id));
            assert!(!DeadlineIndexPositions::<Test>::contains_key(tick.key));
            assert_eq!(wide_idle_tick_peer_authority::<Test>(0), bootstrap_authority);
            assert_eq!(wide_idle_deep_clock_guard_snapshot::<Test>(0), bootstrap_custody);
            Pallet::<Test>::do_try_state().unwrap();
            if rollback {
              polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(())
            } else {
              polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(())
            }
          });
          if rollback {
            assert_eq!(polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1), before);
          }
          Pallet::<Test>::do_try_state().unwrap();
          eprintln!("slot31 temporal source: separate_births={separate_births} handoff={handoff} visit_target={visit_target} frontier={frontier} first_epoch={first_epoch} epoch={epoch} review_count={} anchored_at={anchored_at} now={:?} due={due} rollback={rollback}",
            bucket.count, frame_system::Pallet::<Test>::block_number());
        });
      }
    }
  }
