  #[cfg(test)]
  #[test]
  fn parked_close_write_witness_survives_root_and_caller_rollback() {
    use polkadot_sdk::{
      sp_core::{Blake2Hasher, H256},
      sp_runtime::StateVersion,
      sp_trie::{LayoutV1, delta_trie_root, recorder::Recorder},
    };
    use std::collections::BTreeSet;

    for rollback in [false, true] {
      let mut ext = unanchored_root_genesis_ext(120);
      let (fixture, checks, genesis) = ext.execute_with(|| {
        let genesis = Pallet::<Test>::active_actor_state(0).unwrap();
        <Test as Config>::AssetOps::mint(
          &genesis.identity.sovereign_account,
          <Test as Config>::FeeNativeAssetId::get(),
          77,
        )
        .unwrap();
        let (fixture, checks) =
          prepare_wide_idle_root_temporal_close_with_carry::<Test>(0, 31, false, true).unwrap();
        let event = PendingDependencyEvents::<Test>::get(fixture.actor_id).unwrap();
        let source = DependencyPlans::<Test>::get(fixture.actor_id)[0].source;
        let revision = DependencyRevisions::<Test>::get(source);
        assert_eq!(revision.scan_cursor, 63);
        assert_eq!(revision.scan_target, Some(event.revision + 1));
        assert_eq!(revision.revision, event.revision + 2);
        assert!(!PendingDependencyReviews::<Test>::contains_key(
          fixture.actor_id
        ));
        Pallet::<Test>::do_try_state().unwrap();
        (
          fixture,
          checks,
          Pallet::<Test>::active_actor_state(0).unwrap(),
        )
      });
      ext.commit_all().unwrap();
      assert_eq!(ext.overlayed_changes().changes().count(), 0);
      let prefix_root = *ext.backend.root();
      let pending_keys = [
        PendingDependencyEvents::<Test>::hashed_key_for(fixture.actor_id),
        PendingDependencyReviews::<Test>::hashed_key_for(fixture.actor_id),
      ];
      // This host-owned caller layer adds no FRAME transaction-level storage key.
      ext.execute_with(polkadot_sdk::sp_io::storage::start_transaction);
      let recorder = Recorder::<Blake2Hasher>::default();
      let (body_proof, full_proof, post_root) = ext.execute_with_recorder(recorder.clone(), || {
        Pallet::<Test>::close_actor(
          RawOrigin::Signed(fixture.identity.owner).into(),
          fixture.actor_id,
        )
        .unwrap();
        let body_proof = recorder.to_storage_proof();
        let body_keys = recorder
          .recorded_keys()
          .into_values()
          .flat_map(|keys| keys.into_keys().map(|key| key.as_ref().to_vec()))
          .collect::<BTreeSet<_>>();
        assert!(pending_keys.iter().all(|key| !body_keys.contains(key)));
        let post_root = H256::from_slice(&polkadot_sdk::sp_io::storage::root(StateVersion::V1));
        (body_proof, recorder.to_storage_proof(), post_root)
      });
      assert_eq!(*ext.backend.root(), prefix_root);
      let delta = ext
        .overlayed_changes()
        .changes()
        .map(|(key, entry)| (key.clone(), entry.clone().value().cloned()))
        .collect::<Vec<_>>();
      assert!(
        pending_keys
          .iter()
          .all(|key| delta.contains(&(key.clone(), None)))
      );
      let body_nodes = body_proof.iter_nodes().cloned().collect::<BTreeSet<_>>();
      let full_nodes = full_proof.iter_nodes().cloned().collect::<BTreeSet<_>>();
      assert!(full_nodes.is_superset(&body_nodes));
      let mut full_database = full_proof.to_memory_db::<Blake2Hasher>();
      assert_eq!(
        delta_trie_root::<LayoutV1<Blake2Hasher>, _, _, _, _, _>(
          &mut full_database,
          prefix_root,
          delta.clone(),
          None,
          None,
        )
        .unwrap(),
        post_root,
      );
      let mut body_database = body_proof.to_memory_db::<Blake2Hasher>();
      let body_replay = delta_trie_root::<LayoutV1<Blake2Hasher>, _, _, _, _, _>(
        &mut body_database,
        prefix_root,
        delta,
        None,
        None,
      );
      assert!(
        body_replay.is_err(),
        "body proof omits required write witness"
      );
      let mut pending_body_complete = Vec::new();
      for key in &pending_keys {
        let removal = vec![(key.clone(), None::<Vec<u8>>)];
        let mut database = full_proof.to_memory_db::<Blake2Hasher>();
        assert!(
          delta_trie_root::<LayoutV1<Blake2Hasher>, _, _, _, _, _>(
            &mut database,
            prefix_root,
            removal.clone(),
            None,
            None,
          )
          .is_ok()
        );
        let mut database = body_proof.to_memory_db::<Blake2Hasher>();
        pending_body_complete.push(
          delta_trie_root::<LayoutV1<Blake2Hasher>, _, _, _, _, _>(
            &mut database,
            prefix_root,
            removal,
            None,
            None,
          )
          .is_ok(),
        );
      }
      assert_eq!(pending_body_complete, [false, true]);
      eprintln!(
        "carry63 write witness: rollback={rollback} body_nodes={} root_nodes={} extra_nodes={} body_delta_complete={} pending_body_complete={pending_body_complete:?}",
        body_nodes.len(),
        full_nodes.len(),
        full_nodes.len() - body_nodes.len(),
        body_replay.is_ok(),
      );
      ext.execute_with(|| {
        assert_close_destruction::<Test>(&fixture);
        assert_wide_idle_close_checks::<Test>(fixture.actor_id, &checks);
        assert_eq!(Pallet::<Test>::active_actor_state(0).unwrap(), genesis);
        assert_eq!(
          <Test as Config>::AssetOps::balance(
            &genesis.identity.sovereign_account,
            <Test as Config>::FeeNativeAssetId::get(),
          ),
          77,
        );
        if rollback {
          polkadot_sdk::sp_io::storage::rollback_transaction();
        } else {
          polkadot_sdk::sp_io::storage::commit_transaction();
        }
        assert_eq!(
          polkadot_sdk::sp_io::storage::root(StateVersion::V1),
          if rollback {
            prefix_root.as_bytes()
          } else {
            post_root.as_bytes()
          },
        );
        Pallet::<Test>::do_try_state().unwrap();
      });
    }
  }

