  #[cfg(test)]
  #[test]
  fn wide_idle_two_clock_scan_close_uses_legal_conditional_header() {
    for shape in 0..=2 {
      for rollback in [false, true] {
        new_test_ext().execute_with(|| {
          let fixture = prepare_wide_idle_hole_history_close::<Test>(shape).unwrap();
          let actor_id = fixture.actor_id;
          let original = Pallet::<Test>::load_actor_contract(actor_id).unwrap();
          let actor_before = Pallet::<Test>::load_actor_ref(actor_id).unwrap();
          assert!(matches!(original.trigger, Trigger::AddressEvent { .. }));
          assert!(original.window.is_some());
          let old_plan = DependencyPlans::<Test>::get(actor_id);
          assert_eq!(old_plan.len(), 1);
          let old_source = old_plan[0].source;
          assert_eq!(
            DependencyRegistrationHeaders::<Test>::get(old_source).free_count,
            31
          );
          let next = frame_system::Pallet::<Test>::block_number()
            .checked_add(1)
            .unwrap();
          frame_system::Pallet::<Test>::set_block_number(next);
          if !rollback {
            let mut invalid = original.clone();
            invalid.trigger = Trigger::at_time(12);
            invalid.window = None;
            let before =
              polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
            assert_eq!(
              Pallet::<Test>::update_contract(
                RawOrigin::Signed(fixture.identity.owner).into(),
                actor_id,
                invalid
              ),
              Err(Error::<Test>::InvalidTriggerConfiguration.into())
            );
            assert_eq!(
              polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
              before
            );
            let mut invalid = original.clone();
            invalid.trigger = Trigger::at_time(12);
            invalid.cooldown_blocks = 0;
            assert_eq!(
              Pallet::<Test>::update_contract(
                RawOrigin::Signed(fixture.identity.owner).into(),
                actor_id,
                invalid
              ),
              Err(Error::<Test>::InvalidScheduleWindow.into())
            );
            assert_eq!(
              polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
              before
            );
            let mut invalid = original.clone();
            invalid.trigger = Trigger::cadenced(12);
            invalid.cooldown_blocks = 0;
            invalid.window = None;
            assert_eq!(
              Pallet::<Test>::update_contract(
                RawOrigin::Signed(fixture.identity.owner).into(),
                actor_id,
                invalid
              ),
              Err(Error::<Test>::InvalidParkedBalanceActivation.into())
            );
            assert_eq!(
              polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
              before
            );
          }
          let mut temporal = original.clone();
          temporal.trigger = Trigger::at_time(12);
          temporal.cooldown_blocks = 0;
          temporal.window = None;
          Pallet::<Test>::update_contract(
            RawOrigin::Signed(fixture.identity.owner).into(),
            actor_id,
            temporal.clone(),
          )
          .unwrap();
          let current = Pallet::<Test>::load_actor_contract(actor_id).unwrap();
          assert_eq!(current, temporal);
          assert_eq!(current.steps, original.steps);
          assert_max_contract_geometry::<Test>(actor_id);
          let actor = Pallet::<Test>::load_actor_ref(actor_id).unwrap();
          assert_ne!(actor.generation, actor_before.generation);
          assert!(ActorRunStateStore::<Test>::get(actor_id).is_none());
          let plan = DependencyPlans::<Test>::get(actor_id);
          assert_eq!(plan.len(), 1);
          let source = plan[0].source;
          assert_ne!(source, old_source);
          assert!(!DependencyRegistrationHeaders::<Test>::contains_key(
            old_source
          ));
          let header = DependencyRegistrationHeaders::<Test>::get(source);
          assert_eq!((header.count, header.free_count), (1, 0));
          let review = DeadlineHandles::<Test>::get(actor_id).unwrap();
          let trigger = TriggerDeadlineHandles::<Test>::get(actor_id).unwrap();
          assert!(matches!(review.key, WakeupKey::Block(_)));
          assert!(matches!(trigger.key, WakeupKey::Tick(_)));
          let asset = DependencySourceBalances::<Test>::get(source).unwrap();
          publish_close_scan_balance_transition::<Test>(asset).unwrap();
          let mut meter = polkadot_sdk::sp_weights::WeightMeter::with_limit(Weight::MAX);
          assert_eq!(
            Pallet::<Test>::process_next_dependency_scan_unit(&mut meter).unwrap(),
            Some(DependencyScanMutation::Advanced(1))
          );
          assert!(PendingDependencyEvents::<Test>::contains_key(actor_id));
          assert!(
            DependencyRevisions::<Test>::get(source)
              .scan_target
              .is_some()
          );
          assert!(DependencyScanSourceNodes::<Test>::contains_key(source));
          Pallet::<Test>::do_try_state().unwrap();
          let before =
            polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
          polkadot_sdk::frame_support::storage::with_transaction_unchecked(|| {
            Pallet::<Test>::close_actor(RawOrigin::Signed(fixture.identity.owner).into(), actor_id)
              .unwrap();
            assert_close_destruction::<Test>(&fixture);
            assert!(!TriggerDeadlineHandles::<Test>::contains_key(actor_id));
            assert!(!DeadlineIndexPositions::<Test>::contains_key(review.key));
            assert!(!DeadlineIndexPositions::<Test>::contains_key(trigger.key));
            assert!(!PendingDependencyEvents::<Test>::contains_key(actor_id));
            assert!(!DependencyRevisions::<Test>::contains_key(source));
            assert!(!DependencyScanSourceNodes::<Test>::contains_key(source));
            assert!(!BalanceDependencySources::<Test>::contains_key(asset));
            assert!(DependencyPlans::<Test>::get(actor_id).is_empty());
            assert_eq!(DependencyScanSourceListState::<Test>::get().count, 0);
            if rollback {
              polkadot_sdk::frame_support::storage::TransactionOutcome::Rollback(())
            } else {
              polkadot_sdk::frame_support::storage::TransactionOutcome::Commit(())
            }
          });
          if rollback {
            assert_eq!(
              polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
              before
            );
            assert_eq!(TriggerDeadlineHandles::<Test>::get(actor_id), Some(trigger));
            assert_eq!(DeadlineHandles::<Test>::get(actor_id), Some(review));
            assert!(PendingDependencyEvents::<Test>::contains_key(actor_id));
          }
          Pallet::<Test>::do_try_state().unwrap();
        });
      }
    }
  }

