  #[cfg(test)]
  #[test]
  fn zero_step_idle_placement_parts_preserve_destinations_and_rollback() {
    use crate::scheduler::{AttemptTransactionError, PreparedIdleServicePlacement};
    use polkadot_sdk::frame_support::storage::{TransactionOutcome, with_transaction_unchecked};
    for source in 0..=7 {
      new_test_ext().execute_with(|| {
        crate::mock::set_missing_behavior_control_weight(true);
        crate::mock::set_missing_behavior_close_weight(true);
        crate::mock::set_missing_behavior_inspection_weight(true);
        let (fixture, state, admission) =
          prepare_zero_step_policy_source::<Test>(source, false).unwrap();
        let actor = fixture.actor;
        let kind = ServiceNodes::<Test>::get(actor.actor_id).unwrap().kind;
        let now = frame_system::Pallet::<Test>::block_number();
        let root =
          || polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
        let source_root = root();
        with_transaction_unchecked(|| {
          let (next, reason) =
            Pallet::<Test>::benchmark_zero_step_control(actor.actor_id, state, &admission, now)
              .unwrap();
          assert!(reason.is_none());
          Pallet::<Test>::try_store_service_control_state(
            actor,
            kind,
            next.identity.clone(),
            next.hot.clone(),
          )
          .unwrap();
          let prepared_root = root();
          let prepared = Pallet::<Test>::prepare_idle_service_placement(actor, &next, now).unwrap();
          assert_eq!(root(), prepared_root);
          let mut latched = next.clone();
          latched.hot.pending_signal = true;
          assert!(matches!(
            Pallet::<Test>::prepare_idle_service_placement(actor, &latched, now),
            Err(AttemptTransactionError::Invariant)
          ));
          assert!(matches!(
            Pallet::<Test>::prepare_idle_service_placement(
              ActorRef {
                generation: actor.generation + 1,
                ..actor
              },
              &next,
              now
            ),
            Err(AttemptTransactionError::Invariant)
          ));
          assert_eq!(root(), prepared_root);
          let disabled = match prepared {
            PreparedIdleServicePlacement::Disabled {
              process,
              disablement,
            } => {
              assert!(next.contract.window.is_none());
              assert_eq!(disablement.cause, ProcessDisableCause::Protocol);
              Some((process, disablement))
            }
            PreparedIdleServicePlacement::Deadline { at } => {
              assert_eq!(Some(at), next.contract.window.map(|window| window.end + 1));
              let destination =
                Pallet::<Test>::plan_deadline_destination(actor, WakeupKey::Block(at)).unwrap();
              Pallet::<Test>::transfer_service_member_to_deadline(actor, destination).unwrap();
              None
            }
            PreparedIdleServicePlacement::Parked { .. } => panic!("zero-Step cannot author Park"),
          };
          let before_finish = root();
          with_transaction_unchecked(|| {
            ActorProcesses::<Test>::remove(actor.actor_id);
            let refused_root = root();
            assert_eq!(
              Pallet::<Test>::finish_idle_service_placement(actor, now, disabled),
              Err(AttemptTransactionError::Invariant)
            );
            assert_eq!(root(), refused_root);
            TransactionOutcome::Rollback(())
          });
          assert_eq!(root(), before_finish);
          let placed = ActorProcesses::<Test>::get(actor.actor_id).unwrap();
          Pallet::<Test>::finish_idle_service_placement(actor, now, disabled).unwrap();
          let process = ActorProcesses::<Test>::get(actor.actor_id).unwrap();
          assert_eq!(process.last_attempted, Some(now));
          if let Some((_, disablement)) = disabled {
            assert_eq!(process.status, ProcessStatus::Disabled(disablement));
            assert!(process.residence.is_none());
          } else {
            assert_eq!(process.residence, placed.residence);
            assert_eq!(process.status, placed.status);
          }
          assert!(!ServiceNodes::<Test>::contains_key(actor.actor_id));
          assert_eq!(ServiceHeader::<Test>::get().count, 2);
          assert_eq!(ServiceHeader::<Test>::get().cursor, Some(fixture.successor));
          for (peer, expected) in &fixture.peers {
            assert_eq!(
              (
                ServiceNodes::<Test>::get(peer.actor_id),
                ActorProcesses::<Test>::get(peer.actor_id),
                ActorSemanticStates::<Test>::get(peer.actor_id)
              )
                .encode(),
              *expected
            );
          }
          let native = <Test as Config>::FeeNativeAssetId::get();
          assert_eq!(
            <Test as Config>::AssetOps::balance(&fixture.payer, native),
            fixture.payer_native_before - fixture.pipeline_fee
          );
          assert_eq!(
            <Test as Config>::AssetOps::balance(&<Test as Config>::FeeSink::get(), native),
            fixture.sink_native_before + fixture.pipeline_fee
          );
          TransactionOutcome::Rollback(())
        });
        assert_eq!(root(), source_root);
      });
    }
  }

  #[cfg(test)]
  #[test]
  fn zero_step_semantic_publication_preserves_phase_and_outer_rollback() {
    use polkadot_sdk::frame_support::storage::{TransactionOutcome, with_transaction_unchecked};
    for source in 0..=7 {
      new_test_ext().execute_with(|| {
        crate::mock::set_missing_behavior_control_weight(true);
        crate::mock::set_missing_behavior_close_weight(true);
        crate::mock::set_missing_behavior_inspection_weight(true);
        let (fixture, state, admission) =
          prepare_zero_step_policy_source::<Test>(source, false).unwrap();
        let actor = fixture.actor;
        let kind = ServiceNodes::<Test>::get(actor.actor_id).unwrap().kind;
        let original = Pallet::<Test>::load_service_actor_semantic_state(actor, kind).unwrap();
        let now = frame_system::Pallet::<Test>::block_number();
        let root =
          || polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
        let native = <Test as Config>::FeeNativeAssetId::get();
        let sink = <Test as Config>::FeeSink::get();
        let hold_reason: <Test as Config>::RuntimeHoldReason = HoldReason::ActorState.into();
        let ledger = || {
          (
            <Test as Config>::AssetOps::balance(&fixture.payer, native),
            <Test as Config>::AssetOps::balance(&sink, native),
            <Test as Config>::AssetOps::balance(&fixture.payer, fixture.asset),
            <Test as Config>::StateHoldCurrency::balance_on_hold(&hold_reason, &fixture.owner),
          )
        };
        let readiness_root = root();
        let readiness_ledger = ledger();
        with_transaction_unchecked(|| {
          let (next, reason) =
            Pallet::<Test>::benchmark_zero_step_control(actor.actor_id, state, &admission, now)
              .unwrap();
          assert!(reason.is_none());
          assert_eq!(next.identity.cycle_nonce, original.identity.cycle_nonce + 1);
          assert_eq!(next.hot.cycle_state, CycleState::Idle);
          assert!(!next.hot.pending_signal);
          assert!(next.run_state.is_none());
          assert_eq!(
            ledger(),
            (
              readiness_ledger.0 - fixture.pipeline_fee,
              readiness_ledger.1 + fixture.pipeline_fee,
              readiness_ledger.2,
              readiness_ledger.3,
            )
          );
          let phase_root = root();
          let phase_ledger = ledger();
          let phase_semantic =
            Pallet::<Test>::load_service_actor_semantic_state(actor, kind).unwrap();
          let mut rearmed = original.clone();
          if source % 4 == 3 {
            assert!(original.hot.trigger_wakeup_pointer.is_none());
            assert!(phase_semantic.hot.trigger_wakeup_pointer.is_some());
            rearmed.hot.trigger_wakeup_pointer = phase_semantic.hot.trigger_wakeup_pointer;
          }
          assert_eq!(
            phase_semantic, rearmed,
            "only Cadenced rearm precedes semantic publication"
          );
          let mut expected = phase_semantic.clone();
          expected.identity = next.identity.clone();
          expected.hot = next.hot.clone();
          // Independent one-key oracle at the same transaction depth as each phase witness.
          // Exact roots therefore cover holds, policy/monitor, peers, process and both deadlines.
          let expected_root = with_transaction_unchecked(|| {
            ActorSemanticStates::<Test>::insert(
              actor.actor_id,
              ActorSemanticState::Active(expected.clone()),
            );
            TransactionOutcome::Rollback(root())
          });
          assert_eq!(root(), phase_root);
          let publish = || {
            Pallet::<Test>::try_store_service_control_state(
              actor,
              kind,
              next.identity.clone(),
              next.hot.clone(),
            )
          };
          with_transaction_unchecked(|| {
            publish().unwrap();
            assert_eq!(root(), expected_root);
            assert_eq!(ledger(), phase_ledger);
            TransactionOutcome::Rollback(())
          });
          assert_eq!(root(), phase_root);
          assert_eq!(ledger(), phase_ledger);
          if source < 4 {
            with_transaction_unchecked(|| {
              let hold = ActorStateHolds::<Test>::get(actor.actor_id).unwrap();
              let mut invalid = hold.clone();
              invalid.owner = invalid.owner.checked_add(1).unwrap();
              ActorStateHolds::<Test>::insert(actor.actor_id, invalid);
              let refused_root = root();
              // This synthetic hold defect is invisible to entry authentication and rejects
              // after semantic replacement; it is a native rollback witness, not a raw source.
              assert_eq!(
                Pallet::<Test>::load_service_actor_semantic_state(actor, kind).unwrap(),
                phase_semantic
              );
              assert_eq!(
                publish(),
                Err(crate::scheduler::EnqueueOutcome::CorruptedTopology)
              );
              assert_eq!(root(), refused_root);
              assert_eq!(ledger(), phase_ledger);
              ActorStateHolds::<Test>::insert(actor.actor_id, hold);
              publish().unwrap();
              assert_eq!(root(), expected_root);
              assert_eq!(ledger(), phase_ledger);
              TransactionOutcome::Rollback(())
            });
            assert_eq!(root(), phase_root);
          }
          // Retry only publication, never Opening or its already observed Pipeline payment.
          with_transaction_unchecked(|| {
            publish().unwrap();
            assert_eq!(root(), expected_root);
            assert_eq!(ledger(), phase_ledger);
            TransactionOutcome::Commit(())
          });
          assert_eq!(
            Pallet::<Test>::load_service_actor_semantic_state(actor, kind).unwrap(),
            expected
          );
          let events = frame_system::Pallet::<Test>::events();
          assert_eq!(
            events
              .iter()
              .filter(|record| matches!(record.event,
                crate::mock::RuntimeEvent::Actors(Event::PipelineFeeCharged { actor_id, .. })
                  if actor_id == actor.actor_id
              ))
              .count(),
            usize::from(source < 4)
          );
          assert!(!events.iter().any(|record| matches!(record.event,
            crate::mock::RuntimeEvent::Actors(Event::ActionFeeCharged { actor_id, .. })
              if actor_id == actor.actor_id
          )));
          // Semantic publication is not final placement. No partial paid zero-Step prefix
          // becomes committed consensus state when the enclosing attempt refuses.
          TransactionOutcome::Rollback(())
        });
        assert_eq!(root(), readiness_root);
        assert_eq!(ledger(), readiness_ledger);
        assert_eq!(
          Pallet::<Test>::load_service_actor_semantic_state(actor, kind).unwrap(),
          original
        );
      });
    }
  }

