  #[cfg(test)]
  #[test]
  fn full_header_policy_source_preserves_readiness_authority_and_refusals() {
    for (profile, actor_type) in [
      (
        ReachableOpeningProfile::UserTransferHeaderMax,
        ActorType::User,
      ),
      (
        ReachableOpeningProfile::SystemTransferHeaderMax,
        ActorType::System,
      ),
    ] {
      for missing in 0..4 {
        new_test_ext().execute_with(|| {
          crate::mock::set_missing_behavior_inspection_weight(missing == 0);
          crate::mock::set_missing_behavior_control_weight(missing == 1);
          crate::mock::set_missing_behavior_close_weight(missing == 2);
          let count = <<Test as Config>::MaxContractSteps as Get<u32>>::get();
          let tails = count.saturating_sub(1).div_ceil(MAX_STEPS_PER_TAIL_CHUNK);
          let (id, actual_count) = prepare_reachable_opening_with_authored_successor::<Test>(
            tails, profile, false, None, false, None, true,
          )
          .unwrap();
          assert_eq!(actual_count, count);
          let (contract, admission) = Pallet::<Test>::load_admitted_contract_geometry(id).unwrap();
          let original_header = ActorContractHeads::<Test>::get(id).unwrap();
          let chunks = ActorContractTailChunks::<Test>::iter_prefix(id).collect::<Vec<_>>();
          let identity = Pallet::<Test>::actor_identity(id).unwrap();
          let payer = identity.sovereign_account;
          let custody = expected_step_balances::<Test>(&payer, &contract, 0, None);
          let native = <Test as Config>::FeeNativeAssetId::get();
          let sink = <Test as Config>::AssetOps::balance(&<Test as Config>::FeeSink::get(), native);
          let source = install_step_policy_source::<Test>(
            id,
            actor_type,
            contract.clone(),
            admission,
            maximum_behavior_expression::<Test>().unwrap(),
          )
          .unwrap();
          let head = ActorContractHeads::<Test>::get(id).unwrap();
          assert_eq!(
            head.header.encoded_size(),
            ActorContractHeaderOf::<Test>::max_encoded_len()
              - ParkedBalanceActivationOf::<Test>::max_encoded_len()
          );
          assert!(head.header.has_close_when);
          assert_eq!(head.header.on_unfunded, OnUnfunded::Close);
          assert_eq!(head.header.trigger.family(), TriggerFamily::AddressEvent);
          assert_eq!(head.header.step_count, count);
          assert_eq!(
            head.header.body_commitment,
            original_header.header.body_commitment
          );
          assert_eq!(
            head.first_step_resources,
            original_header.first_step_resources
          );
          assert_eq!(source.contract.steps, contract.steps);
          assert_eq!(source.state.hot.cycle_state, CycleState::Idle);
          assert!(source.state.hot.pending_signal);
          assert!(source.state.run_state.is_none());
          // Policy staging rebinds chunk authority, never the authored Tasks or their resources.
          let current = ActorContractTailChunks::<Test>::iter_prefix(id).collect::<Vec<_>>();
          assert_eq!(current.len(), chunks.len());
          for ((key, chunk), (old_key, old_chunk)) in current.iter().zip(&chunks) {
            assert_eq!(key, old_key);
            assert_eq!(chunk.steps, old_chunk.steps);
            assert_eq!(chunk.step_resources, old_chunk.step_resources);
          }
          for (asset, balance) in &custody {
            assert_eq!(
              <Test as Config>::AssetOps::balance(&payer, *asset),
              *balance
            );
          }
          assert_eq!(
            <Test as Config>::AssetOps::balance(&<Test as Config>::FeeSink::get(), native),
            sink
          );
          let stored = Pallet::<Test>::load_admitted_contract_geometry(id).unwrap();
          assert_eq!(stored.0, source.contract);
          assert_eq!(stored.1, source.admission);
          let hold = ActorStateHolds::<Test>::get(id);
          assert_eq!(hold.is_some(), actor_type == ActorType::User);
          let slots = OwnerSlotBitmaps::<Test>::get(identity.owner);
          let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
          let mut meter = polkadot_sdk::sp_weights::WeightMeter::with_limit(Weight::MAX);
          if missing == 3 {
            let policy = ActorBehaviorPolicies::<Test>::get(id).unwrap();
            let behavior = Pallet::<Test>::behavior_control_weight_context(&policy).unwrap();
            let context = Pallet::<Test>::step_control_weight_context(count, 0, 0).unwrap();
            let required = <Test as Config>::StepControlWeight::maximum_behavior_control_weight(
              context,
              head.first_step.as_ref().unwrap(),
              behavior,
            )
            .unwrap();
            assert!(!required.all_lte(head.first_step_resources.unwrap().control));
          }
          assert_eq!(
            Pallet::<Test>::service_canonical_round_head(
              &mut meter,
              frame_system::Pallet::<Test>::block_number(),
            ),
            Err(if missing == 0 {
              ServiceRoundError::ResourceUnavailable
            } else {
              ServiceRoundError::ProcessResidenceMismatch
            })
          );
          assert!(!meter.consumed().is_zero());
          assert_eq!(ActorStateHolds::<Test>::get(id), hold);
          assert_eq!(OwnerSlotBitmaps::<Test>::get(identity.owner), slots);
          assert_eq!(
            Pallet::<Test>::load_admitted_contract_geometry(id).unwrap(),
            stored
          );
          assert_eq!(
            polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
            root
          );
        });
      }
    }
  }

  #[cfg(test)]
  #[test]
  fn contract_behavior_context_matches_installed_policy_without_prices() {
    for source in 0..=7 {
      new_test_ext().execute_with(|| {
        let actor_type = if source < 4 {
          ActorType::User
        } else {
          ActorType::System
        };
        let family = match source % 4 {
          0 => ZeroStepHeaderSource::Manual,
          1 => ZeroStepHeaderSource::AddressEvent,
          2 => ZeroStepHeaderSource::AtTimeDue,
          _ => ZeroStepHeaderSource::CadencedDue,
        };
        let fixture = prepare_zero_step_header::<Test>(actor_type, family, false);
        let (state, _) = consume_zero_step_opening::<Test>(fixture.actor.actor_id);
        assert!(state.contract.close_when.is_none());
        crate::mock::set_missing_behavior_control_weight(true);
        crate::mock::set_missing_behavior_close_weight(true);
        crate::mock::set_missing_behavior_inspection_weight(true);
        let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
        assert_eq!(
          Pallet::<Test>::benchmark_contract_behavior_control_weight_context(&state.contract),
          Some(None)
        );
        assert_eq!(
          polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
          root
        );
      });
      for closes in [false, true] {
        new_test_ext().execute_with(|| {
          let (fixture, state, _) =
            prepare_zero_step_policy_source::<Test>(source, closes).unwrap();
          let actor_id = fixture.actor.actor_id;
          let header =
            assert_maximum_zero_step_header::<Test>(actor_id, state.contract.trigger.family())
              .header;
          let policy = Pallet::<Test>::load_step_behavior_policy(actor_id, &header)
            .unwrap()
            .unwrap()
            .policy;
          let expected = Pallet::<Test>::behavior_control_weight_context(&policy).unwrap();
          assert_eq!(expected.policy_bytes as usize, policy.encoded_size());
          assert_eq!(expected.clauses as usize, policy.expression.clauses.len());
          assert_eq!(
            expected.atoms as usize,
            policy
              .expression
              .clauses
              .iter()
              .map(|clause| clause.len())
              .sum::<usize>()
          );
          assert_eq!(expected.metrics as usize, policy.plan.metrics().len());
          assert_eq!(expected.counter_slots, expected.metrics);
          assert!(expected.requires_clean_cycle);
          assert!(expected.monitor_bytes > 0);
          crate::mock::set_missing_behavior_control_weight(true);
          crate::mock::set_missing_behavior_close_weight(true);
          crate::mock::set_missing_behavior_inspection_weight(true);
          let native = <Test as Config>::FeeNativeAssetId::get();
          let reason: <Test as Config>::RuntimeHoldReason = HoldReason::ActorState.into();
          let ledger = || {
            (
              <Test as Config>::AssetOps::balance(&fixture.payer, native),
              <Test as Config>::AssetOps::balance(&<Test as Config>::FeeSink::get(), native),
              <Test as Config>::AssetOps::balance(&fixture.payer, fixture.asset),
              <Test as Config>::StateHoldCurrency::balance_on_hold(&reason, &fixture.owner),
            )
          };
          let before = ledger();
          let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
          assert_eq!(
            Pallet::<Test>::benchmark_contract_behavior_control_weight_context(&state.contract),
            Some(Some(expected))
          );
          // Refuse malformed supplied values only; never write them into consensus authority.
          for malformed in 0..4 {
            let mut supplied = state.contract.clone();
            let expression = supplied.close_when.as_mut().unwrap();
            match malformed {
              0 => expression.clauses.clear(),
              1 => expression.clauses[0].clear(),
              2 => expression.clauses[0][0].threshold = 0,
              _ => expression.clauses[0][1] = expression.clauses[0][0],
            }
            assert!(expression.validate().is_err());
            assert_eq!(
              Pallet::<Test>::benchmark_contract_behavior_control_weight_context(&supplied),
              None
            );
            assert_eq!(ledger(), before);
            assert_eq!(
              polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
              root
            );
          }
          assert_eq!(ledger(), before);
          assert_eq!(
            polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
            root
          );
        });
      }
    }

    new_test_ext().execute_with(|| {
      crate::mock::set_missing_behavior_control_weight(true);
      crate::mock::set_missing_behavior_close_weight(true);
      crate::mock::set_missing_behavior_inspection_weight(true);
      let (owner, asset, trigger, funding) = large_header_fields::<Test>();
      // Reuse the width constructors, not admission/geometry retention: these are supplied
      // values only. No Actor is installed and no bound may be thinned to obtain a context.
      let (_, precondition) = prepare_max_encoded_step_precondition::<Test>(
        0,
        benchmark_predicate_capacity::<Test>(),
        false,
      )
      .unwrap();
      assert_eq!(
        precondition.predicate_count(),
        benchmark_predicate_capacity::<Test>()
      );
      assert_eq!(
        precondition.clauses.len(),
        <<Test as Config>::MaxPreconditionClauses as Get<u32>>::get() as usize
      );
      // The whole-Step cap is four here, not the 4x4 clause-grid product. Retain
      // every configured predicate and clause without asserting an unreachable grid.
      let width = benchmark_predicate_capacity::<Test>()
        .div_ceil(<<Test as Config>::MaxPreconditionClauses as Get<u32>>::get());
      assert!(
        precondition
          .clauses
          .iter()
          .all(|clause| clause.len() == width as usize)
      );
      let wide_step = Step {
        precondition: Some(precondition),
        task: maximum_encoded_control_task::<Test>(asset),
        on_error: StepErrorPolicy::RetryLater { max_attempts: 2 },
      };
      assert_eq!(
        wide_step.task.encoded_size(),
        TaskOf::<Test>::max_encoded_len()
      );
      let maximum = <<Test as Config>::MaxContractSteps as Get<u32>>::get();
      assert!(maximum > 0);
      let full_body: ContractSteps<Test> = vec![wide_step.clone(); maximum as usize]
        .try_into()
        .unwrap();
      let mut empty = user_contract::<Test>(
        Schedule {
          trigger,
          cooldown_blocks: <Test as Config>::MaxExecutionDelayBlocks::get().saturated_into(),
        },
        ContractSteps::<Test>::default(),
      )
      .unwrap();
      empty.funding = funding;
      empty.window = Some(ScheduleWindow {
        start: 1,
        end: <<Test as Config>::MinWindowLength as Get<BlockNumberFor<Test>>>::get()
          .saturating_add(1_000),
      });
      empty.auto_close_at_cycle_nonce = Some(u64::MAX);
      let native = <Test as Config>::FeeNativeAssetId::get();
      let reason: <Test as Config>::RuntimeHoldReason = HoldReason::ActorState.into();
      let ledger = || {
        (
          <Test as Config>::AssetOps::balance(&owner, native),
          <Test as Config>::AssetOps::balance(&owner, asset),
          <Test as Config>::AssetOps::balance(&<Test as Config>::FeeSink::get(), native),
          <Test as Config>::StateHoldCurrency::balance_on_hold(&reason, &owner),
        )
      };
      let before = ledger();
      let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
      for (expression, clauses, atoms, slots) in [
        (zero_step_policy_expression::<Test>(4).unwrap(), 1, 1, 0),
        (maximum_behavior_expression::<Test>().unwrap(), 4, 16, 10),
      ] {
        empty.close_when = Some(expression);
        let mut full = empty.clone();
        full.steps = full_body.clone();
        assert_eq!(full.steps.len(), maximum as usize);
        let zero_context =
          Pallet::<Test>::benchmark_contract_behavior_control_weight_context(&empty)
            .expect("canonical supplied empty-body expression")
            .unwrap();
        let full_context =
          Pallet::<Test>::benchmark_contract_behavior_control_weight_context(&full)
            .expect("canonical supplied full-body expression")
            .unwrap();
        assert_eq!(
          full_context, zero_context,
          "policy geometry does not carry body length"
        );
        assert_eq!(
          (
            full_context.clauses,
            full_context.atoms,
            full_context.counter_slots
          ),
          (clauses, atoms, slots)
        );
        assert!(full_context.requires_clean_cycle && full_context.monitor_bytes > 0);
        assert_eq!(empty.close_when, full.close_when);
        assert_ne!(empty.semantic_contract_id(), full.semantic_contract_id());
        assert_ne!(empty.body_commitment(), full.body_commitment());
        // This is encoded input geometry, not optimized CPU/Weight. The independent counted
        // codec witness proves one Step visit per hash; no proof-byte price is inferred here.
        let extra_bytes = maximum as usize * wide_step.encoded_size()
          + codec::Compact(maximum).encoded_size()
          - codec::Compact(0u32).encoded_size();
        assert!(extra_bytes > 0);
        assert_eq!(
          full.steps.encoded_size() - empty.steps.encoded_size(),
          extra_bytes
        );
        assert_eq!(full.encoded_size() - empty.encoded_size(), extra_bytes);
        assert_eq!(ledger(), before);
        assert_eq!(
          polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
          root
        );
      }
    });
  }

