  #[cfg(test)]
  #[test]
  fn contract_behavior_context_full_body_has_no_storage_io() {
    use polkadot_sdk::{sp_core::Blake2Hasher, sp_trie::recorder::Recorder};
    for policy in 0..=2 {
      let mut ext = new_test_ext();
      let (contract, expected) = ext.execute_with(|| {
        crate::mock::set_missing_behavior_control_weight(true);
        crate::mock::set_missing_behavior_close_weight(true);
        crate::mock::set_missing_behavior_inspection_weight(true);
        let identities = ActorIdentityCount::<Test>::get();
        let (contract, expected) = prepare_full_body_behavior_context::<Test>(policy).unwrap();
        assert_eq!(ActorIdentityCount::<Test>::get(), identities);
        assert_eq!(
          contract.steps.len(),
          <<Test as Config>::MaxContractSteps as Get<u32>>::get() as usize
        );
        for step in &contract.steps {
          assert_eq!(step.task.encoded_size(), TaskOf::<Test>::max_encoded_len());
          assert_eq!(
            step.precondition.as_ref().unwrap().predicate_count(),
            benchmark_predicate_capacity::<Test>()
          );
        }
        let mut empty = contract.clone();
        empty.steps.clear();
        assert_ne!(
          contract.semantic_contract_id(),
          empty.semantic_contract_id()
        );
        assert_ne!(contract.body_commitment(), empty.body_commitment());
        assert_eq!(
          Pallet::<Test>::benchmark_contract_behavior_control_weight_context(&empty),
          Some(expected)
        );
        if let Some(context) = expected {
          assert!(context.requires_clean_cycle);
          assert_eq!(context.counter_slots, if policy == 1 { 0 } else { 10 });
          let mut malformed = contract.clone();
          malformed.close_when.as_mut().unwrap().clauses[0][0].threshold = 0;
          let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
          assert!(
            Pallet::<Test>::benchmark_contract_behavior_control_weight_context(&malformed)
              .is_none()
          );
          assert_eq!(
            polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
            root
          );
        }
        (contract, expected)
      });
      ext.commit_all().unwrap();
      let recorder = Recorder::<Blake2Hasher>::default();
      assert_eq!(
        ext.execute_with_recorder(recorder.clone(), || {
          Pallet::<Test>::benchmark_contract_behavior_control_weight_context(&contract)
        }),
        Some(expected)
      );
      assert!(
        recorder
          .recorded_keys()
          .into_values()
          .all(|keys| keys.is_empty())
      );
      assert_eq!(ext.overlayed_changes().changes().count(), 0);
    }
  }

