  #[cfg(test)]
  #[test]
  fn policy_source_header_geometry_is_family_bounded() {
    for source in 0..=7 {
      for closes in [false, true] {
        new_test_ext().execute_with(|| {
          let (fixture, state, admission) =
            prepare_zero_step_policy_source::<Test>(source, closes).unwrap();
          crate::mock::set_missing_behavior_control_weight(true);
          crate::mock::set_missing_behavior_close_weight(true);
          crate::mock::set_missing_behavior_inspection_weight(true);
          let kind = ServiceNodes::<Test>::get(fixture.actor.actor_id)
            .unwrap()
            .kind;
          let root = polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
          let semantic = Pallet::<Test>::authenticate_zero_step_service_source(
            fixture.actor,
            kind,
            &state,
            &admission,
          )
          .expect("full-header component source authenticates without policy prices");
          assert_eq!(semantic.identity, state.identity);
          assert_eq!(semantic.hot, state.hot);
          assert_eq!(semantic.admission, admission);
          assert_eq!(
            polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1),
            root,
          );
          let head = assert_maximum_zero_step_header::<Test>(
            fixture.actor.actor_id,
            state.contract.trigger.family(),
          );
          assert!(head.header.has_close_when);
          assert_eq!(head.header.on_unfunded, OnUnfunded::Close);
          assert_eq!(
            head.header.funding.encoded_size(),
            FundingSourcePolicyOf::<Test>::max_encoded_len()
          );
        });
      }
    }
    for (profile, actor_type) in [
      (
        ReachableOpeningProfile::UserTransferHeaderMax,
        ActorType::User,
      ),
      (
        ReachableOpeningProfile::SystemTransferHeaderMax,
        ActorType::System,
      ),
    ] {
      new_test_ext().execute_with(|| {
        let source = prepare_step_policy_source::<Test>(
          profile,
          actor_type,
          maximum_behavior_expression::<Test>().unwrap(),
        )
        .unwrap();
        let header = ActorContractHeads::<Test>::get(source.actor.actor_id)
          .unwrap()
          .header;
        assert!(header.has_close_when);
        assert_eq!(header.on_unfunded, OnUnfunded::Close);
        assert_eq!(header.trigger, Trigger::Manual);
        assert!(header.window.is_none());
        assert!(header.auto_close_at_cycle_nonce.is_none());
        assert!(header.parked_balance_activation.is_none());
        assert_eq!(
          header.funding.encoded_size(),
          FundingSourcePolicyOf::<Test>::max_encoded_len()
        );
        // HeaderMax here fills funding only; it is not the full feasible header union.
        assert_eq!(
          header.encoded_size(),
          ActorContractHeaderOf::<Test>::max_encoded_len()
            - ParkedBalanceActivationOf::<Test>::max_encoded_len()
            - TriggerOf::<Test>::max_encoded_len()
            + TriggerOf::<Test>::manual().encoded_size()
            - ScheduleWindow::<BlockNumberFor<Test>>::max_encoded_len()
            - u64::max_encoded_len()
        );
      });
    }
  }

