  #[cfg(test)]
  #[test]
  fn retained_service_finalizer_preserves_paid_prefix_and_closes_after_reset() {
    use polkadot_sdk::frame_support::storage::{TransactionOutcome, with_transaction_unchecked};
    let root = || polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    for rollback in [true, false] {
      new_test_ext().execute_with(|| {
        crate::mock::set_missing_behavior_control_weight(true);
        crate::mock::set_missing_behavior_close_weight(true);
        crate::mock::set_missing_behavior_inspection_weight(true);
        let source = prepare_retained_service_finalizer::<Test>().unwrap();
        let id = source.actor.actor_id;
        let before = root();
        with_transaction_unchecked(|| {
          assert!(
            Pallet::<Test>::cancel_run_internal_loaded(
              id,
              &source.state.identity,
              CancellationReason::Closing(CloseReason::OwnerInitiated),
              None,
              crate::execution::LoadedCancellationContext::ConsumedFrame {
                state: source.state.clone(),
                admission: source.admission.clone(),
              },
            )
            .unwrap()
          );
          assert!(!ActorRunStateStore::<Test>::contains_key(id));
          let monitor = ActorBehaviorMonitors::<Test>::get(id).unwrap();
          assert!(monitor.clean_cycle.is_none());
          let ActorSemanticState::Active(semantic) = ActorSemanticStates::<Test>::get(id).unwrap()
          else {
            panic!("Closing phase stays Active")
          };
          assert_eq!(semantic.hot.cycle_state, CycleState::Idle);
          let phase = root();
          assert_eq!(
            Pallet::<Test>::load_contract_geometry_with_admission(id, &source.admission),
            Some(source.state.contract.clone())
          );
          assert_eq!(
            root(),
            phase,
            "post-reset full geometry authentication is read-only"
          );
          TransactionOutcome::Rollback(())
        });
        assert_eq!(root(), before);
        with_transaction_unchecked(|| {
          Pallet::<Test>::benchmark_finalize_actor_from_consumed_state(
            id,
            source.state,
            source.admission,
            CloseReason::OwnerInitiated,
          )
          .expect("intrinsic policy finalization uses real paid source without a price proxy");
          assert!(!ActorSemanticStates::<Test>::contains_key(id));
          assert!(!ActorBehaviorPolicies::<Test>::contains_key(id));
          assert!(!ActorBehaviorMonitors::<Test>::contains_key(id));
          assert!(ActorProcesses::<Test>::contains_key(id));
          assert!(ServiceNodes::<Test>::contains_key(id));
          Pallet::<Test>::retire_service_member(source.actor)
            .expect("ordinary caller retires Service after finalization");
          assert_close_destruction::<Test>(&source.destruction);
          if rollback {
            TransactionOutcome::Rollback(())
          } else {
            TransactionOutcome::Commit(())
          }
        });
        if rollback {
          assert_eq!(
            root(),
            before,
            "outer refusal restores the whole paid source"
          );
        } else {
          assert_close_destruction::<Test>(&source.destruction);
        }
      });
    }
  }

