  #[cfg(test)]
  #[test]
  fn behavior_closing_reset_profile_preserves_phase_and_refusals() {
    use polkadot_sdk::frame_support::storage::{TransactionOutcome, with_transaction};
    use polkadot_sdk::{sp_core::Blake2Hasher, sp_trie::recorder::Recorder};
    use std::collections::BTreeSet;
    let root = || polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    for case in 0..=2 {
      for verify in [false, true] {
        new_test_ext().execute_with(|| {
          crate::mock::set_missing_behavior_control_weight(true);
          crate::mock::set_missing_behavior_close_weight(true);
          crate::mock::set_missing_behavior_inspection_weight(true);
          _behavior_closing_reset::<Test>(case, verify).unwrap();
        });
      }
      let mut ext = new_test_ext();
      let (source, expected) = ext.execute_with(|| {
        crate::mock::set_missing_behavior_control_weight(true);
        crate::mock::set_missing_behavior_close_weight(true);
        crate::mock::set_missing_behavior_inspection_weight(true);
        let source = prepare_behavior_closing_reset::<Test>(case).unwrap();
        let expected = expected_behavior_closing_reset_root::<Test>(&source);
        let before = root();
        let mut mismatch = source.admission.clone();
        mismatch.admission_identity[0] ^= 1;
        assert!(
          Pallet::<Test>::clear_behavior_cycle_for_cancellation(
            source.actor_id,
            &mismatch,
            &source.successor.identity,
            &source.successor.hot,
            true,
          )
          .is_err()
        );
        assert_eq!(root(), before);
        for fault in 0..=2 {
          if fault != 0 && !source.clean {
            continue;
          }
          with_transaction(|| {
            match fault {
              0 => ActorBehaviorPolicies::<Test>::remove(source.actor_id),
              1 => ActorBehaviorMonitors::<Test>::remove(source.actor_id),
              _ => ActorRunStateStore::<Test>::mutate(source.actor_id, |run| {
                run.as_mut().unwrap().contract_authority.admission_identity[0] ^= 1;
              }),
            }
            let refused = root();
            assert!(
              Pallet::<Test>::clear_behavior_cycle_for_cancellation(
                source.actor_id,
                &source.admission,
                &source.successor.identity,
                &source.successor.hot,
                true,
              )
              .is_err()
            );
            assert_eq!(root(), refused, "refusal precedes phase writes");
            TransactionOutcome::Rollback(Ok::<_, DispatchError>(()))
          })
          .unwrap();
          assert_eq!(root(), before, "fault rollback restores the paid source");
        }
        with_transaction(|| {
          Pallet::<Test>::clear_behavior_cycle_for_cancellation(
            source.actor_id,
            &source.admission,
            &source.successor.identity,
            &source.successor.hot,
            true,
          )
          .unwrap();
          assert_eq!(root(), expected);
          TransactionOutcome::Rollback(Ok::<_, DispatchError>(()))
        })
        .unwrap();
        assert_eq!(
          root(),
          before,
          "outer refusal restores the paid prefix and its fees"
        );
        (source, expected)
      });
      ext.commit_all().unwrap();
      let recorder = Recorder::<Blake2Hasher>::default();
      ext.execute_with_recorder(recorder.clone(), || {
        Pallet::<Test>::clear_behavior_cycle_for_cancellation(
          source.actor_id,
          &source.admission,
          &source.successor.identity,
          &source.successor.hot,
          true,
        )
        .unwrap();
      });
      let keys = recorder
        .recorded_keys()
        .into_values()
        .flat_map(|keys| keys.into_keys().map(|key| key.as_ref().to_vec()))
        .collect::<BTreeSet<_>>();
      let mut expected_keys = BTreeSet::from([
        ActorContractHeads::<Test>::hashed_key_for(source.actor_id),
        ActorBehaviorPolicies::<Test>::hashed_key_for(source.actor_id),
        ActorSemanticStates::<Test>::hashed_key_for(source.actor_id),
      ]);
      let mut writes = BTreeSet::new();
      if source.clean {
        expected_keys.insert(ActorBehaviorMonitors::<Test>::hashed_key_for(
          source.actor_id,
        ));
        expected_keys.insert(ActorRunStateStore::<Test>::hashed_key_for(source.actor_id));
        writes.insert(ActorBehaviorMonitors::<Test>::hashed_key_for(
          source.actor_id,
        ));
        writes.insert(ActorSemanticStates::<Test>::hashed_key_for(source.actor_id));
      }
      assert_eq!(keys, expected_keys);
      assert_eq!(
        ext
          .overlayed_changes()
          .changes()
          .map(|(key, _)| key.clone())
          .collect::<BTreeSet<_>>(),
        writes
      );
      ext.execute_with(|| {
        with_transaction(|| {
          assert_eq!(root(), expected, "only the owned reset records changed");
          TransactionOutcome::Rollback(Ok::<_, DispatchError>(()))
        })
        .unwrap();
      });
    }
  }

