  #[cfg(test)]
  #[test]
  fn geometry_behavior_authentication_profile_preserves_sources_and_refusals() {
    use polkadot_sdk::frame_support::storage::{TransactionOutcome, with_transaction};
    use polkadot_sdk::{sp_core::Blake2Hasher, sp_trie::recorder::Recorder};
    use std::collections::BTreeSet;
    let root = || polkadot_sdk::sp_io::storage::root(polkadot_sdk::sp_runtime::StateVersion::V1);
    for case in 0..=5 {
      for verify in [false, true] {
        new_test_ext().execute_with(|| {
          crate::mock::set_missing_behavior_inspection_weight(true);
          crate::mock::set_missing_behavior_control_weight(true);
          crate::mock::set_missing_behavior_close_weight(true);
          _geometry_behavior_authentication::<Test>(case, verify).unwrap();
        });
      }
      let mut ext = new_test_ext();
      let (id, header, expected) = ext.execute_with(|| {
        crate::mock::set_missing_behavior_inspection_weight(true);
        crate::mock::set_missing_behavior_control_weight(true);
        crate::mock::set_missing_behavior_close_weight(true);
        prepare_geometry_behavior_authentication::<Test>(case).unwrap()
      });
      ext.execute_with(|| {
        let healthy = root();
        assert_eq!(
          Pallet::<Test>::benchmark_geometry_behavior_authentication(id, &header),
          Some(expected.clone())
        );
        if case != 0 {
          let mut mismatched = header.clone();
          mismatched.admission_identity[0] ^= 1;
          assert!(
            Pallet::<Test>::benchmark_geometry_behavior_authentication(id, &mismatched).is_none()
          );
          assert_eq!(root(), healthy);
          for missing_monitor in [false, true] {
            if missing_monitor && case == 1 {
              continue;
            }
            with_transaction(|| {
              if missing_monitor {
                ActorBehaviorMonitors::<Test>::remove(id);
              } else {
                ActorBehaviorPolicies::<Test>::remove(id);
              }
              let refused = root();
              assert!(
                Pallet::<Test>::benchmark_geometry_behavior_authentication(id, &header).is_none()
              );
              assert_eq!(root(), refused);
              TransactionOutcome::Rollback(Ok::<_, DispatchError>(()))
            })
            .unwrap();
            assert_eq!(
              root(),
              healthy,
              "refusal rollback retains the entire paid source"
            );
          }
        }
        assert_eq!(root(), healthy);
      });
      ext.commit_all().unwrap();
      let recorder = Recorder::<Blake2Hasher>::default();
      assert_eq!(
        ext.execute_with_recorder(recorder.clone(), || {
          Pallet::<Test>::benchmark_geometry_behavior_authentication(id, &header)
        }),
        Some(expected)
      );
      let reads = recorder
        .recorded_keys()
        .into_values()
        .flat_map(|keys| keys.into_keys().map(|key| key.as_ref().to_vec()))
        .collect::<BTreeSet<_>>();
      let mut keys = BTreeSet::new();
      if case != 0 {
        keys.insert(ActorBehaviorPolicies::<Test>::hashed_key_for(id));
        keys.insert(ActorSemanticStates::<Test>::hashed_key_for(id));
      }
      if case >= 2 {
        keys.insert(ActorBehaviorMonitors::<Test>::hashed_key_for(id));
      }
      if matches!(case, 3 | 5) {
        keys.insert(ActorRunStateStore::<Test>::hashed_key_for(id));
      }
      assert_eq!(reads, keys, "finite source class {case}");
      assert_eq!(
        ext.overlayed_changes().changes().count(),
        0,
        "authentication performs no writes"
      );
    }
  }

